// Pickups (HP-pack, ammo-pack, gold)
function spawnPickup(x, y, type) {
  if (!state.pickups) state.pickups = [];
  state.pickups.push({ x, y, type, life: 25, vx: 0, vy: 0, magnetized: false });
}
