// TRUCK CONVOY MODE
// ============================================================
// Truck = stort fordon som rör sig framåt. Spelare står på det och försvarar.
// Truck har 7 turret-positions med olika vapen. När en spelare står på en turret,
// får de det vapnet automatiskt (deras egna vapen återgår när de kliver av).

const TRUCK_TURRETS = [
  { id: 't_rocket',  offsetX: -90, offsetY: -32, weaponId: 'rocket',   icon: '🚀', label: 'Raketgevär' },
  { id: 't_minigun', offsetX:  60, offsetY: -32, weaponId: 'minigun',  icon: '🔫', label: 'Minigun' },
  { id: 't_sniper',  offsetX: -90, offsetY:   0, weaponId: 'sniper',   icon: '🎯', label: 'Prickskyttegevär' },
  { id: 't_flame',   offsetX:  60, offsetY:   0, weaponId: 'flame',    icon: '🔥', label: 'Eldkastare' },
  { id: 't_repair',  offsetX: -90, offsetY:  32, weaponId: 'repair',   icon: '🔧', label: 'REPARERA — spamma för att laga trucken' },
  { id: 't_grenade', offsetX:  60, offsetY:  32, weaponId: 'grenade',  icon: '💣', label: 'Granatkastare' },
  { id: 't_railgun', offsetX:   0, offsetY:   0, weaponId: 'railgun',  icon: '🌟', label: 'Railgun (förar-plats)' },
];

// Försök claima en turret (host-validerad)
function tryMountTurret(turretId) {
  if (!state.truck) return;
  const tr = state.truck.turrets.find(x => x.id === turretId);
  if (!tr) return;
  // Toggle dismount om redan på samma
  if (state.player._mountedTurretId === turretId) {
    state.player._mountedTurretId = null;
    if (Coop.active && Coop.isHost) tr.occupiedBy = null;
    if (Coop.active && !Coop.isHost) Coop.sendToHost({ type: 'mount_req', tid: null });
    return;
  }
  // Kolla om turret är tagen av någon annan
  const myId = Coop.active ? (Coop.isHost ? 'host' : Coop.myId) : null;
  if (Coop.active && tr.occupiedBy && tr.occupiedBy !== myId) {
    showToast('Upptagen av annan spelare!');
    Audio.uiClick();
    return;
  }
  if (Coop.active && Coop.isHost) {
    // Frigör tidigare turret
    for (const t of state.truck.turrets) if (t.occupiedBy === 'host') t.occupiedBy = null;
    tr.occupiedBy = 'host';
    state.player._mountedTurretId = turretId;
  } else if (Coop.active && !Coop.isHost) {
    // Klient: skicka request, vänta på host's bekräftelse
    Coop.sendToHost({ type: 'mount_req', tid: turretId });
    state.player._mountedTurretId = turretId; // optimistic
  } else {
    // Single-player
    state.player._mountedTurretId = turretId;
  }
}

// Bygg turret-väljare UI (visas bara i konvoj-mode)
const truckTurretBarEl = document.getElementById('truck-turret-bar');
function buildTruckTurretBar() {
  if (!truckTurretBarEl) return;
  truckTurretBarEl.innerHTML = '';
  for (const tr of TRUCK_TURRETS) {
    const btn = document.createElement('button');
    btn.style.cssText = 'background:rgba(40,40,50,0.95);border:1px solid rgba(170,58,255,0.5);border-radius:8px;width:46px;height:46px;font-size:18px;cursor:pointer;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;';
    btn.dataset.turretId = tr.id;
    btn.innerHTML = `<div>${tr.icon}</div><div style="font-size:7px;opacity:0.6;">${tr.label.split(' ')[0]}</div>`;
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!state.player) return;
      tryMountTurret(tr.id);
      Audio.uiClick();
      renderTruckTurretBar();
    });
    truckTurretBarEl.appendChild(btn);
  }
  // Leave-knapp
  const leaveBtn = document.createElement('button');
  leaveBtn.style.cssText = 'background:rgba(80,30,30,0.95);border:1px solid rgba(255,90,90,0.5);border-radius:8px;width:46px;height:46px;font-size:14px;cursor:pointer;padding:0;color:#fff;font-weight:bold;';
  leaveBtn.textContent = '✕';
  leaveBtn.title = 'Lämna turret';
  leaveBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!state.player) return;
    if (state.player._mountedTurretId) tryMountTurret(state.player._mountedTurretId);
    Audio.uiClick();
    renderTruckTurretBar();
  });
  truckTurretBarEl.appendChild(leaveBtn);
}
function renderTruckTurretBar() {
  if (!truckTurretBarEl) return;
  const myId = Coop.active ? (Coop.isHost ? 'host' : Coop.myId) : null;
  for (const btn of truckTurretBarEl.querySelectorAll('button')) {
    const tid = btn.dataset.turretId;
    if (!tid) continue;
    const tr = state.truck ? state.truck.turrets.find(t => t.id === tid) : null;
    const isMine = state.player && tid === state.player._mountedTurretId;
    const isTaken = tr && tr.occupiedBy && tr.occupiedBy !== myId && tr.occupiedBy !== 'host';
    if (isMine) {
      btn.style.background = 'rgba(170,58,255,0.9)';
      btn.style.borderColor = '#fff';
      btn.style.opacity = '1';
    } else if (isTaken) {
      btn.style.background = 'rgba(80,80,80,0.5)';
      btn.style.borderColor = '#666';
      btn.style.opacity = '0.5';
    } else {
      btn.style.background = 'rgba(40,40,50,0.95)';
      btn.style.borderColor = 'rgba(170,58,255,0.5)';
      btn.style.opacity = '1';
    }
  }
}
buildTruckTurretBar();

function setupTruck(stage) {
  state.truck = {
    x: stage.spawnPos.x + 300,
    y: stage.spawnPos.y,
    w: 220, h: 90,
    hp: 2500, maxHp: 2500,
    speed: 50, // px/s framåt
    alive: true,
    angle: 0, // riktning (mot goal)
    turrets: TRUCK_TURRETS.map(t => ({ ...t, occupiedBy: null, lastShot: 0 })),
    wheelPhase: 0,
  };
  // Spelare börjar PÅ trucken
  if (state.player) {
    state.player.x = state.truck.x;
    state.player.y = state.truck.y - 8;
  }
}

function isTruckMode() {
  const stage = getStage(state.wave);
  return !!(stage && stage.isTruckMode);
}

function updateTruck(dt, now) {
  const t = state.truck;
  if (!t || !t.alive) return;
  const stage = getStage(state.wave);
  // Beräkna riktning mot goal
  const dx = stage.goalPos.x - t.x;
  const dy = stage.goalPos.y - t.y;
  const d = Math.hypot(dx, dy) || 1;
  t.angle = Math.atan2(dy, dx);
  // Bromsa när nästan framme
  const speedMul = d < 200 ? 0.3 : 1;
  t.x += (dx/d) * t.speed * speedMul * dt;
  t.y += (dy/d) * t.speed * speedMul * dt;
  t.wheelPhase += dt * 8;
  // MOUNT-system: lokal spelare som är "fastlåst" på en turret
  const p = state.player;
  if (p && p._mountedTurretId) {
    const tr = t.turrets.find(x => x.id === p._mountedTurretId);
    if (tr) {
      // Lås position till turret
      p.x = t.x + tr.offsetX;
      p.y = t.y + tr.offsetY;
      // Vapen = turret-vapen
      p._turretWeapon = tr.weaponId;
      p._turretId = tr.id;
      tr.occupiedBy = 'host';
    } else {
      // Turret existerar inte — släpp
      p._mountedTurretId = null;
      p._turretWeapon = null;
    }
  } else if (p) {
    // Inte mountad — clear turret-vapen
    p._turretWeapon = null;
    p._turretId = null;
    // Håll spelare PÅ trucken — rotera diff till truck-local space, clamp, rotera tillbaka.
    // Tidigare axis-aligned clamp fungerade fel när t.angle != 0 (kollision-shake).
    const angle = t.angle || 0;
    const cos = Math.cos(-angle), sin = Math.sin(-angle);
    const dx = p.x - t.x, dy = p.y - t.y;
    const lx = dx * cos - dy * sin, ly = dx * sin + dy * cos;
    const maxX = t.w/2 - 12, maxY = t.h/2 - 12;
    const cx = Math.max(-maxX, Math.min(maxX, lx));
    const cy = Math.max(-maxY, Math.min(maxY, ly));
    if (cx !== lx || cy !== ly) {
      const cos2 = Math.cos(angle), sin2 = Math.sin(angle);
      p.x = t.x + cx * cos2 - cy * sin2;
      p.y = t.y + cx * sin2 + cy * cos2;
    }
  }
  // Markera vilka turrets som är claim:ade (host + partners) + lås positions
  if (Coop.active && Coop.isHost) {
    // Reset alla claims för host-spelaren först (kommer sätts om i blocket ovan)
    for (const tr of t.turrets) {
      if (tr.occupiedBy === 'host' && (!p || p._mountedTurretId !== tr.id)) tr.occupiedBy = null;
    }
    // Sätt host-claim om mountad
    if (p && p._mountedTurretId) {
      const tr = t.turrets.find(x => x.id === p._mountedTurretId);
      if (tr) tr.occupiedBy = 'host';
    }
    // Lås partner-positioner till deras turret (bara om partner._mountedTurretId via mount_req)
    for (const [pid, partner] of Coop.players) {
      if (!partner) continue;
      if (partner._mountedTurretId) {
        const tr = t.turrets.find(x => x.id === partner._mountedTurretId);
        if (tr) {
          partner.x = t.x + tr.offsetX;
          partner.y = t.y + tr.offsetY;
          partner.targetX = partner.x; partner.targetY = partner.y;
          tr.occupiedBy = pid;
        }
      }
    }
  } else if (!Coop.active) {
    // Single-player: bara host
    for (const tr of t.turrets) {
      tr.occupiedBy = (p && p._mountedTurretId === tr.id) ? 'host' : null;
    }
  }
  // Truck tar skada från fiender som rör vid den
  for (const e of state.enemies) {
    if (e.dead) continue;
    const ed = Math.hypot(e.x - t.x, e.y - t.y);
    if (ed < (t.w/2) + e.r) {
      if (e.dmg > 0 && (!t._lastHit || now - t._lastHit > 300)) {
        t._lastHit = now;
        t.hp = Math.max(0, t.hp - e.dmg);
        triggerShake(4, 0.15);
        if (t.hp <= 0) {
          t.alive = false;
          explode(t.x, t.y, 200, 0, true);
          triggerShake(20, 0.8);
          endGame(false);
        }
      }
    }
  }
}

function drawTruck() {
  const t = state.truck;
  if (!t) return;
  const x = t.x - state.camera.x;
  const y = t.y - state.camera.y;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(t.angle);
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(-t.w/2 + 4, -t.h/2 + 6, t.w, t.h);
  // Lastbils-platform
  ctx.fillStyle = '#3a3a44';
  ctx.fillRect(-t.w/2, -t.h/2, t.w, t.h);
  // Paneler/raster
  ctx.fillStyle = '#5a5a64';
  ctx.fillRect(-t.w/2, -t.h/2, t.w, 4);
  ctx.fillRect(-t.w/2, t.h/2 - 4, t.w, 4);
  // Ramar runt
  ctx.strokeStyle = '#1a1a22'; ctx.lineWidth = 2;
  ctx.strokeRect(-t.w/2, -t.h/2, t.w, t.h);
  // Hjul (4 st)
  ctx.fillStyle = '#1a1a1a';
  for (const wpos of [-t.w/2 + 30, -t.w/2 + 80, t.w/2 - 80, t.w/2 - 30]) {
    ctx.fillRect(wpos - 8, -t.h/2 - 6, 16, 8);
    ctx.fillRect(wpos - 8,  t.h/2 - 2, 16, 8);
  }
  // Ratt-platsen (förare framåt)
  ctx.fillStyle = '#2a2a34';
  ctx.fillRect(t.w/2 - 40, -t.h/2 + 4, 36, t.h - 8);
  ctx.fillStyle = '#3acaff';
  ctx.fillRect(t.w/2 - 30, -10, 16, 20);
  // Pansar-detalj
  ctx.fillStyle = '#7a7a84';
  ctx.fillRect(-t.w/2 + 6, -t.h/2 + 8, 30, t.h - 16);
  // Turrets
  for (const tr of t.turrets) {
    const tx = tr.offsetX, ty = tr.offsetY;
    ctx.fillStyle = tr.occupiedBy ? '#aa3aff' : '#222';
    ctx.beginPath(); ctx.arc(tx, ty, 14, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = tr.occupiedBy ? '#fff' : '#666'; ctx.lineWidth = 2;
    ctx.stroke();
    // Ikon
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.fillText(tr.icon, tx, ty + 5);
  }
  ctx.restore();
  // HP-bar ovanför trucken
  const hpW = 200, hpH = 8;
  const hpX = x - hpW/2, hpY = y - t.h/2 - 30;
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(hpX - 2, hpY - 2, hpW + 4, hpH + 4);
  ctx.fillStyle = t.hp / t.maxHp > 0.3 ? '#5aff5a' : '#ff5a5a';
  ctx.fillRect(hpX, hpY, hpW * (t.hp / t.maxHp), hpH);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
  ctx.fillText('🚚 TRUCK ' + Math.ceil(t.hp) + '/' + t.maxHp, x, hpY - 6);
  ctx.shadowBlur = 0;
}

function spawnCompanion() {
  if (!save.companions || !save.companions.active) { state.companion = null; return; }
  // PvP-modes (tdm/ctf/siege) tillåter inte companion — orättvist + ingen shop att köpa
  if (Coop.active && Coop.config && (Coop.config.tdm || Coop.config.ctf || Coop.config.siege || Coop.config.gungame)) {
    state.companion = null; return;
  }
  const id = save.companions.active;
  const comp = getCompanionById(id);
  if (!comp) { state.companion = null; return; }
  // Rensa persisted death-state vid spawn (revive eller new run)
  if (save.companions.dead && save.companions.dead[id]) {
    delete save.companions.dead[id];
    persist();
  }
  const lvl = save.companions.level[id] || 0;
  const stats = companionStats(comp, lvl);
  const p = state.player;
  state.companion = {
    id, comp, lvl,
    x: p ? p.x + 30 : 1000, y: p ? p.y + 30 : 1000,
    r: 12,
    hp: stats.hp, maxHp: stats.hp, dmg: stats.dmg, speed: stats.speed,
    range: stats.range, cooldown: stats.cooldown,
    lastAct: 0, target: null, alive: true,
    angle: 0, walkPhase: 0,
    flashUntil: 0, // damage-flash-timestamp (sätts av damageCompanion / event)
  };
}
function updateCompanion(dt, now) {
  const c = state.companion;
  if (!c || !c.alive || !state.player) return;
  const p = state.player;
  // Följ spelaren — håll avstånd 50-90px
  const dx = p.x - c.x, dy = p.y - c.y;
  const d = Math.hypot(dx, dy) || 1;
  const ideal = 60;
  if (d > ideal + 30) {
    c.x += (dx/d) * c.speed * dt;
    c.y += (dy/d) * c.speed * dt;
    c.walkPhase += dt * 8;
  }
  // Hitta närmsta fiende
  let target = null, bestD = c.range;
  for (const e of state.enemies) {
    if (e.dead) continue;
    const ed = Math.hypot(e.x - c.x, e.y - c.y);
    if (ed < bestD) { bestD = ed; target = e; }
  }
  c.target = target;
  if (target) {
    c.angle = Math.atan2(target.y - c.y, target.x - c.x);
  }
  // Specialhandling per companion-typ
  if (c.id === 'metaldog' && target && bestD < 50 && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // bett — staggra + skada
    target.staggerUntil = now + 600;
    damageEnemy(target, c.dmg, false);
    spawnParticles(target.x, target.y, '#ffae3a', 6, 120);
    Audio.kill && Audio.kill();
  } else if (c.id === 'drone' && target && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // Skjut laser-skott
    const ang = c.angle;
    state.bullets.push({
      x: c.x, y: c.y, vx: Math.cos(ang) * 800, vy: Math.sin(ang) * 800,
      dmg: c.dmg, life: 0.8, r: 3, color: '#3acaff', hostile: false,
      style: 'plasma', _companion: true,
    });
  } else if (c.id === 'spacemonkey' && target && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // Plasma-bomb mot target
    state.bullets.push({
      x: c.x, y: c.y, vx: Math.cos(c.angle) * 380, vy: Math.sin(c.angle) * 380,
      dmg: c.dmg, life: 1.6, r: 6, color: '#aa3aff', hostile: false,
      style: 'plasma', _companion: true, explosive: 80,
    });
  }
}
function drawCompanion() {
  const c = state.companion;
  if (!c || !c.alive) return;
  const x = c.x - state.camera.x;
  const y = c.y - state.camera.y;
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath(); ctx.ellipse(x + 2, y + 12, 12, 4, 0, 0, Math.PI*2); ctx.fill();
  // HP-bar ovanför companion — alltid synlig (subtilare när full)
  {
    const bw = 28, bh = 4;
    const bx = x - bw / 2, by = y - 22;
    const frac = Math.max(0, c.hp / c.maxHp);
    const fullAlpha = frac >= 1 ? 0.5 : 1.0;
    ctx.globalAlpha = fullAlpha;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(bx - 1, by - 1, bw + 2, bh + 2);
    ctx.fillStyle = frac > 0.5 ? '#5aff5a' : (frac > 0.25 ? '#ffd54a' : '#ff5a5a');
    ctx.fillRect(bx, by, bw * frac, bh);
    ctx.globalAlpha = 1;
  }
  // Damage flash (vit overlay 100ms efter skada)
  const flashUntil = c.flashUntil || 0;
  if (performance.now() < flashUntil) ctx.globalCompositeOperation = 'lighter';
  if (c.id === 'metaldog') {
    // Robothund — kropp + ben + huvud
    ctx.translate(x, y);
    ctx.rotate(c.angle);
    // ben (alternerar)
    const legSwing = Math.sin(c.walkPhase);
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(-8, -6 - legSwing*1.5, 3, 5);
    ctx.fillRect(-8,  3 + legSwing*1.5, 3, 5);
    ctx.fillRect(6, -6 + legSwing*1.5, 3, 5);
    ctx.fillRect(6,  3 - legSwing*1.5, 3, 5);
    // kropp (silver-grå metall)
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(-9, -5, 18, 10);
    ctx.fillStyle = '#5a5a5a';
    ctx.fillRect(-9, -5, 18, 3);
    // huvud
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(7, -4, 8, 8);
    // röda ögon
    ctx.fillStyle = c.comp.accent;
    ctx.shadowColor = c.comp.accent; ctx.shadowBlur = 4;
    ctx.fillRect(11, -3, 2, 2);
    ctx.fillRect(11,  1, 2, 2);
    ctx.shadowBlur = 0;
    // svans
    ctx.strokeStyle = '#3a3a3a'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(-14, -3); ctx.stroke();
  } else if (c.id === 'drone') {
    const t = performance.now() / 200;
    const hover = Math.sin(t) * 2;
    ctx.translate(x, y + hover);
    ctx.rotate(c.angle * 0.3);
    // skiva
    ctx.fillStyle = c.comp.color;
    ctx.shadowColor = c.comp.color; ctx.shadowBlur = 8;
    ctx.beginPath(); ctx.ellipse(0, 0, 10, 4, 0, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    // mitt-led
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(0, 0, 2.5, 0, Math.PI*2); ctx.fill();
    // 4 propellrar
    const pt = performance.now() / 30;
    ctx.strokeStyle = 'rgba(255,255,255,0.3)'; ctx.lineWidth = 1.5;
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2 + pt;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 6, Math.sin(a) * 6);
      ctx.lineTo(Math.cos(a) * 11, Math.sin(a) * 11);
      ctx.stroke();
    }
  } else if (c.id === 'spacemonkey') {
    ctx.translate(x, y);
    // hopp-animation
    const bounce = Math.abs(Math.sin(c.walkPhase)) * -3;
    ctx.translate(0, bounce);
    // kropp (brun apa)
    ctx.fillStyle = c.comp.color;
    ctx.beginPath(); ctx.arc(0, 2, 8, 0, Math.PI*2); ctx.fill();
    // huvud
    ctx.beginPath(); ctx.arc(0, -6, 6, 0, Math.PI*2); ctx.fill();
    // ansikte (lila glow)
    ctx.fillStyle = '#f4d4a4';
    ctx.beginPath(); ctx.arc(0, -5, 4, 0, Math.PI*2); ctx.fill();
    // ögon
    ctx.fillStyle = c.comp.accent;
    ctx.shadowColor = c.comp.accent; ctx.shadowBlur = 4;
    ctx.beginPath(); ctx.arc(-1.5, -6, 1, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(1.5, -6, 1, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    // armar (sträcker mot target)
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(-9, 0, 4, 5);
    ctx.fillRect( 5, 0, 4, 5);
    // hjälm/space-glas
    ctx.strokeStyle = c.comp.accent; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(0, -6, 7, 0, Math.PI*2); ctx.stroke();
  }
  ctx.restore();
  // namn-tag
  ctx.fillStyle = c.comp.accent;
  ctx.font = 'bold 9px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
  ctx.fillText(c.comp.icon, x, y - 16);
  ctx.shadowBlur = 0;
}

function updateDrone(dt, now) {
  if (!state.drone || !state.drone.alive || !state.player) return;
  const d = state.drone;
  const p = state.player;
  // Cirkulera runt spelaren
  d.angle += dt * 1.5;
  const orbitR = 50;
  const tx = p.x + Math.cos(d.angle) * orbitR;
  const ty = p.y + Math.sin(d.angle) * orbitR;
  d.x += (tx - d.x) * 8 * dt;
  d.y += (ty - d.y) * 8 * dt;
  // Skjut närmsta fiende
  if (now - d.lastShot > 600) {
    let target = null, bestD = 380;
    for (const e of state.enemies) {
      if (e.dead) continue;
      const dst = Math.hypot(e.x - d.x, e.y - d.y);
      if (dst < bestD) { bestD = dst; target = e; }
    }
    if (target) {
      d.lastShot = now;
      const ang = Math.atan2(target.y - d.y, target.x - d.x);
      state.bullets.push({
        x: d.x, y: d.y, vx: Math.cos(ang)*700, vy: Math.sin(ang)*700,
        dmg: 18, life: 1.2, r: 3, color: '#3acaff', hostile: false,
        style: 'drone',
      });
    }
  }
}
// Rita emote-bubbla ovanför en spelare/partner
function drawEmoteBubble(em, x, y, r) {
  const now = performance.now();
  if (!em || !em.until || now > em.until) return;
  const totalDur = em.dur || 3500;
  const t = em.until - now;
  const elapsed = totalDur - t;
  // Pop-in: scale 0.4 → 1 (overshoot 1.15 vid 120ms)
  let scale;
  if (elapsed < 120) scale = 0.4 + (elapsed / 120) * 0.75;
  else if (elapsed < 200) scale = 1.15 - ((elapsed - 120) / 80) * 0.15;
  else scale = 1;
  // Fade-out: sista 400ms
  const alpha = t > 400 ? 1 : Math.max(0, t / 400);
  // Bobbing: subtil floating
  const bob = Math.sin(elapsed / 250) * 2;
  ctx.save();
  ctx.globalAlpha = alpha;
  const cx = x;
  const cy = y - r - 30 + bob;
  // Bara emojin — ingen bubbla, ingen border. Soft drop-shadow för läsbarhet
  // mot game-bg så emojin pop:par utan att behöva white-box runt.
  ctx.shadowColor = 'rgba(0,0,0,0.7)';
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 2;
  ctx.font = 'bold ' + Math.round(32 * scale) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#fff'; // fallback om systemet inte renderar emoji som färg
  ctx.fillText(em.emoji, cx, cy);
  ctx.restore();
}

// TDM: rita pulsande team-ring under varje spelare för friend/foe-identifiering
function drawTdmTeamRings() {
  if (!Coop.tdmTeams) return;
  const pulse = 0.85 + Math.sin(performance.now() / 200) * 0.15;
  const drawRing = (wx, wy, team, isMe) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff3a3a' : '#3a8aff';
    const fillCol = team === 'red' ? 'rgba(255,58,58,0.22)' : 'rgba(58,138,255,0.22)';
    const r = 24;
    ctx.save();
    // Fylld inner-disk för stark team-identifiering — synlig direkt vid blick
    ctx.fillStyle = fillCol;
    ctx.beginPath();
    ctx.arc(x, y + 14, r, 0, Math.PI * 2);
    ctx.fill();
    // Tjock ring + glow
    ctx.strokeStyle = color;
    ctx.lineWidth = isMe ? 4 : 3;
    ctx.shadowColor = color;
    ctx.shadowBlur = 14 * pulse;
    ctx.globalAlpha = 1;
    // Color-blind safety: röd = solid ring, blå = streckad (deuteranope-vänligt)
    if (team === 'blue') ctx.setLineDash([8, 5]);
    ctx.beginPath();
    ctx.arc(x, y + 14, r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  };
  // Min egen ring
  if (state.player && Coop.tdmTeams[Coop.myId]) {
    drawRing(state.player.x, state.player.y, Coop.tdmTeams[Coop.myId], true);
  }
  // Partners
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    if (p.hp !== undefined && p.hp <= 0) continue;
    const team = Coop.tdmTeams[pid];
    if (!team) continue;
    drawRing(p.x, p.y, team, false);
  }
}

function drawCtfTeamRings() {
  if (!Coop.ctfTeams) return;
  const pulse = 0.85 + Math.sin(performance.now() / 200) * 0.15;
  const drawRing = (wx, wy, team, isMe) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = isMe ? 3 : 2;
    ctx.shadowColor = color;
    ctx.shadowBlur = 12 * pulse;
    ctx.globalAlpha = 0.9;
    if (team === 'blue') ctx.setLineDash([6, 4]);
    ctx.beginPath();
    ctx.arc(x, y + 14, 22, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  };
  if (state.player && Coop.ctfTeams[Coop.myId]) {
    drawRing(state.player.x, state.player.y, Coop.ctfTeams[Coop.myId], true);
  }
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    if (p.hp !== undefined && p.hp <= 0) continue;
    const team = Coop.ctfTeams[pid];
    if (!team) continue;
    drawRing(p.x, p.y, team, false);
  }
}

// CTF: team-tinted floor halves — visa direkt vem äger vilken sida av arenan.
// Subtilt så det inte överröstar player/enemies.
function drawCtfArenaFloor() {
  const arena = state.ctfArena;
  if (!arena) return;
  const cx = state.camera.x, cy = state.camera.y;
  ctx.save();
  // Röd sida (vänster halva)
  ctx.fillStyle = 'rgba(255,60,60,0.05)';
  ctx.fillRect(0 - cx, 0 - cy, arena.worldW * 0.45, arena.worldH);
  // Blå sida (höger halva)
  ctx.fillStyle = 'rgba(60,140,255,0.05)';
  ctx.fillRect(arena.worldW * 0.55 - cx, 0 - cy, arena.worldW * 0.45, arena.worldH);
  // Mittlinje (neutral zone)
  ctx.strokeStyle = 'rgba(255,255,255,0.10)';
  ctx.lineWidth = 2;
  ctx.setLineDash([12, 12]);
  ctx.beginPath();
  ctx.moveTo(arena.worldW * 0.5 - cx, 0 - cy);
  ctx.lineTo(arena.worldW * 0.5 - cx, arena.worldH - cy);
  ctx.stroke();
  ctx.setLineDash([]);
  // Subtila team-cirklar runt baser (ambient glow)
  const pulse = 0.5 + Math.sin(performance.now() / 700) * 0.2;
  for (const team of ['red', 'blue']) {
    const f = state.ctfFlags && state.ctfFlags[team];
    if (!f) continue;
    const bx = f.baseX - cx, by = f.baseY - cy;
    const color = team === 'red' ? 'rgba(255,90,90,' : 'rgba(90,170,255,';
    // Tighter pulse-glow (90px var 220px) så bara området DIREKT runt flag-stand
    // är highlightat — annars överlappade glow:n med decorations som RED 4 LIFE.
    const grad = ctx.createRadialGradient(bx, by, 15, bx, by, 90);
    grad.addColorStop(0, color + (0.20 * pulse) + ')');
    grad.addColorStop(1, color + '0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(bx, by, 90, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

// Generisk wall-render — detaljerad pixel-art-style rendering för varje kind.
// Använd helper-funktioner per typ så koden är läsbar. Alla helpers tar
// (x, y, w, h) som ABSOLUTA skärm-koord (kameran är redan applicerad).
function drawPvpWalls(walls) {
  if (!walls) return;
  // Avrunda kameran så väggar (integer-koord) renderas vid exakta pixel-positioner.
  // Annars: camera float → wall screen-pos float → anti-aliased blur → wobble vid kamera-pan.
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  // Shadow under varje wall (drop-shadow) först så de lager-lurar visuellt
  ctx.save();
  for (const w of walls) {
    // Träd har shrunken collision-bbox men större visuell krona — använd visualX/Y/W/H när satt.
    const renderX = (w.visualX != null) ? w.visualX : w.x;
    const renderY = (w.visualY != null) ? w.visualY : w.y;
    const renderW = (w.visualW != null) ? w.visualW : w.w;
    const renderH = (w.visualH != null) ? w.visualH : w.h;
    const x = renderX - cx, y = renderY - cy;
    if (x + renderW < -20 || x > viewW + 20 || y + renderH < -20 || y > viewH + 20) continue;
    // Drop-shadow för depth (ej för low dividers eller pipes som ligger på marken).
    // EXKLUDERA alla BR-skog-walls + landmark-walls som har EGEN mjuk ellips-skugga
    // (annars får man dubbel-skugga: gammal fyrkantig + ny rund).
    const _brHasOwnShadow = (
      w.kind === 'tree_oak' || w.kind === 'tree_pine' || w.kind === 'tree_stump' ||
      w.kind === 'tree_giant_oak' ||
      w.kind === 'rock_large' || w.kind === 'rock_small' || w.kind === 'mountain_peak' ||
      w.kind === 'cabin_wall_wood' || w.kind === 'cabin_window' ||
      w.kind === 'burning_car' || w.kind === 'burning_truck' || w.kind === 'burning_caravan' ||
      w.kind === 'excavator_wreck' || w.kind === 'hunting_tower' ||
      w.kind === 'tent' || w.kind === 'well' || w.kind === 'haystack' ||
      w.kind === 'woodpile' || w.kind === 'stone_wall' || w.kind === 'stone_wall_low' ||
      w.kind === 'wooden_fence' || w.kind === 'chicken_coop' || w.kind === 'picnic_table' ||
      w.kind === 'campfire' || w.kind === 'boat' || w.kind === 'bridge' ||
      w.kind === 'plane_fuselage' || w.kind === 'plane_wing' || w.kind === 'plane_tail' ||
      w.kind === 'church_ruin' || w.kind === 'cemetery_gravestone' ||
      w.kind === 'cliff_edge' || w.kind === 'standing_stone' || w.kind === 'altar_stone' ||
      w.kind === 'pump_jack' || w.kind === 'lighthouse' ||
      w.kind === 'wooden_bench' || w.kind === 'flower_pot' ||
      w.kind === 'wagon_cart' || w.kind === 'rune_stone' ||
      w.kind === 'shipping_container' || w.kind === 'silo' || w.kind === 'building' ||
      w.kind === 'lake_water_block' ||
      w.kind === 'ufo_wreck' || w.kind === 'ufo_debris' ||
      w.kind === 'alien_crystal' || w.kind === 'skull_totem'
    );
    if (w.kind !== 'pipe' && w.kind !== 'wall_divider' && !_brHasOwnShadow) {
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.fillRect(x + 2, y + Math.max(3, renderH * 0.06), renderW, renderH);
    }
    // Stabil hash per-wall baserat på WORLD-koord (konstant). Tidigare beräknades
    // hash från SCREEN-coords (x,y) inom helpers → bullet-holes, concrete-dots och
    // wood-grain "vandrade" varje frame när kameran rörde sig.
    const seed = ((renderX * 7) ^ (renderY * 13) ^ (renderW * 5) ^ (renderH * 11)) | 0;
    // Rita själva obstaclet
    if (w.kind === 'wall_red_base' || w.kind === 'wall_blue_base') drawBaseWall(x, y, renderW, renderH, w.kind === 'wall_red_base', seed);
    else if (w.kind === 'wall_pillar') drawPillar(x, y, renderW, renderH, seed);
    else if (w.kind === 'wall_divider') drawDivider(x, y, renderW, renderH);
    else if (w.kind === 'sandbag') drawSandbag(x, y, renderW, renderH);
    else if (w.kind === 'barrel') drawBarrel(x, y, renderW, renderH);
    else if (w.kind === 'debris') drawDebris(x, y, renderW, renderH, seed);
    else if (w.kind === 'barricade') drawBarricade(x, y, renderW, renderH);
    else if (w.kind === 'pipe') drawPipe(x, y, renderW, renderH);
    else if (w.kind === 'crate') drawCrate(x, y, renderW, renderH, seed);
    else if (w.kind === 'truck') drawTruck(x, y, renderW, renderH, seed);
    else if (w.kind === 'van') drawVan(x, y, renderW, renderH, seed);
    else if (w.kind === 'car_wreck') drawCarWreck(x, y, renderW, renderH, seed);
    else if (w.kind === 'guardhouse') drawGuardhouse(x, y, renderW, renderH);
    else if (w.kind === 'ramp') drawRamp(x, y, renderW, renderH);
    else if (w.kind === 'oil_drum') drawOilDrum(x, y, renderW, renderH, seed);
    else if (w.kind === 'fire_drum') drawFireDrum(x, y, renderW, renderH, seed);
    else if (w.kind === 'lamppost') drawLamppost(x, y, renderW, renderH, renderX, renderY);
    else if (w.kind === 'broken_pillar') drawBrokenPillar(x, y, renderW, renderH, seed);
    else if (w.kind === 'tagged_pillar') drawTaggedPillar(x, y, renderW, renderH, seed);
    else if (w.kind === 'concrete') drawConcreteWall(x, y, renderW, renderH);
    else if (w.kind === 'bollard') drawBollard(x, y, renderW, renderH);
    else if (w.kind === 'dumpster_fire') drawDumpsterFire(x, y, renderW, renderH, seed);
    else if (w.kind === 'stairwell_door') drawStairwellDoor(x, y, renderW, renderH);
    else if (w.kind === 'pay_machine') drawPayMachine(x, y, renderW, renderH);
    else if (w.kind === 'jersey_barrier') drawJerseyBarrier(x, y, renderW, renderH);
    else if (w.kind === 'shipping_container') drawShippingContainer(x, y, renderW, renderH, w.color || 'orange', seed);
    else if (w.kind === 'silo') drawSilo(x, y, renderW, renderH, seed);
    else if (w.kind === 'building') drawBuilding(x, y, renderW, renderH, seed);
    // BR skog-karta wall-kinds
    else if (w.kind === 'tree_oak') drawTreeOak(x, y, renderW, renderH, seed);
    else if (w.kind === 'tree_pine') drawTreePine(x, y, renderW, renderH, seed);
    else if (w.kind === 'tree_stump') drawTreeStump(x, y, renderW, renderH, seed);
    else if (w.kind === 'rock_large') drawRock(x, y, renderW, renderH, seed, true);
    else if (w.kind === 'rock_small') drawRock(x, y, renderW, renderH, seed, false);
    else if (w.kind === 'mountain_peak') drawMountainPeak(x, y, renderW, renderH, seed);
    else if (w.kind === 'cabin_wall_wood') drawCabinWallWood(x, y, renderW, renderH, seed);
    else if (w.kind === 'burning_car') drawBurningCar(x, y, renderW, renderH, seed);
    else if (w.kind === 'burning_truck') drawBurningTruck(x, y, renderW, renderH, seed);
    else if (w.kind === 'burning_caravan') drawBurningCaravan(x, y, renderW, renderH, seed);
    else if (w.kind === 'excavator_wreck') drawExcavatorWreck(x, y, renderW, renderH, seed);
    else if (w.kind === 'hunting_tower') drawHuntingTower(x, y, renderW, renderH, seed);
    else if (w.kind === 'tent') drawTent(x, y, renderW, renderH, w.color || 'red', seed);
    else if (w.kind === 'well') drawWell(x, y, renderW, renderH, seed);
    else if (w.kind === 'haystack') drawHaystack(x, y, renderW, renderH, seed);
    else if (w.kind === 'woodpile') drawWoodpile(x, y, renderW, renderH, seed);
    else if (w.kind === 'stone_wall') drawStoneWall(x, y, renderW, renderH, false);
    else if (w.kind === 'stone_wall_low') drawStoneWall(x, y, renderW, renderH, true);
    else if (w.kind === 'wooden_fence') drawWoodenFence(x, y, renderW, renderH);
    else if (w.kind === 'chicken_coop') drawChickenCoop(x, y, renderW, renderH, seed);
    else if (w.kind === 'picnic_table') drawPicnicTable(x, y, renderW, renderH);
    else if (w.kind === 'campfire') drawCampfire(x, y, renderW, renderH, seed);
    else if (w.kind === 'boat') drawBoat(x, y, renderW, renderH, seed);
    else if (w.kind === 'bridge') drawBridge(x, y, renderW, renderH);
    // === LANDMARKS v1.329 ===
    else if (w.kind === 'plane_fuselage') drawPlaneFuselage(x, y, renderW, renderH, seed);
    else if (w.kind === 'plane_wing') drawPlaneWing(x, y, renderW, renderH);
    else if (w.kind === 'plane_tail') drawPlaneTail(x, y, renderW, renderH);
    else if (w.kind === 'church_ruin') drawChurchRuin(x, y, renderW, renderH, seed);
    else if (w.kind === 'cemetery_gravestone') drawGravestone(x, y, renderW, renderH, seed, w);
    else if (w.kind === 'cliff_edge') drawCliffEdge(x, y, renderW, renderH, seed);
    else if (w.kind === 'standing_stone') drawStandingStone(x, y, renderW, renderH, seed);
    else if (w.kind === 'altar_stone') drawAltarStone(x, y, renderW, renderH);
    else if (w.kind === 'pump_jack') drawPumpJack(x, y, renderW, renderH);
    else if (w.kind === 'lighthouse') drawLighthouse(x, y, renderW, renderH);
    else if (w.kind === 'wooden_bench') drawWoodenBench(x, y, renderW, renderH);
    else if (w.kind === 'flower_pot') drawFlowerPot(x, y, renderW, renderH);
    else if (w.kind === 'wagon_cart') drawWagonCart(x, y, renderW, renderH, seed);
    else if (w.kind === 'tree_giant_oak') drawTreeGiantOak(x, y, renderW, renderH, seed);
    else if (w.kind === 'rune_stone') drawRuneStone(x, y, renderW, renderH, seed);
    else if (w.kind === 'cabin_window') drawCabinWindow(x, y, renderW, renderH);
    else if (w.kind === 'lake_water_block') { /* osynlig collision-wall — render hanteras av lake_water_polygon decoration */ }
    else if (w.kind === 'ufo_wreck') drawUfoWreck(x, y, renderW, renderH, seed);
    else if (w.kind === 'ufo_debris') drawUfoDebris(x, y, renderW, renderH, seed);
    else if (w.kind === 'alien_crystal') drawAlienCrystal(x, y, renderW, renderH, seed);
    else if (w.kind === 'skull_totem') drawSkullTotem(x, y, renderW, renderH, seed);
    else { ctx.fillStyle = '#5a5a5a'; ctx.fillRect(x, y, renderW, renderH); }
  }
  ctx.restore();
}

// Base-wall: stålplattor med nitar + lag-färg + slitage + bullet-holes
function drawBaseWall(x, y, w, h, isRed, seed) {
  const baseDark = isRed ? '#3a1010' : '#10204a';
  const baseMid = isRed ? '#5a2828' : '#1a3060';
  const stroke = isRed ? '#ff6060' : '#60a0ff';
  // Gradient fyllning för 3D-look
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, baseMid);
  grad.addColorStop(0.5, baseDark);
  grad.addColorStop(1, baseMid);
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Plattor-segmentering (varje 60-80 px)
  const segW = Math.max(40, w > h ? w / Math.max(2, Math.round(w / 80)) : w);
  const segH = Math.max(40, h > w ? h / Math.max(2, Math.round(h / 80)) : h);
  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
  ctx.lineWidth = 1;
  if (w > h) {
    for (let i = segW; i < w; i += segW) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + 2);
      ctx.lineTo(x + i, y + h - 2);
      ctx.stroke();
    }
  } else {
    for (let i = segH; i < h; i += segH) {
      ctx.beginPath();
      ctx.moveTo(x + 2, y + i);
      ctx.lineTo(x + w - 2, y + i);
      ctx.stroke();
    }
  }
  // Nitar (små cirklar i hörnen + längs kanterna)
  const rivetR = 1.8;
  const rivetColor = '#222';
  const rivetHi = isRed ? '#7a3030' : '#3050a0';
  const placeRivet = (rx, ry) => {
    ctx.fillStyle = rivetColor;
    ctx.beginPath(); ctx.arc(rx, ry, rivetR, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = rivetHi;
    ctx.beginPath(); ctx.arc(rx - 0.5, ry - 0.5, rivetR * 0.4, 0, Math.PI * 2); ctx.fill();
  };
  // Hörn-nitar
  placeRivet(x + 5, y + 5);
  placeRivet(x + w - 5, y + 5);
  placeRivet(x + 5, y + h - 5);
  placeRivet(x + w - 5, y + h - 5);
  // Längs långsidor
  if (w > 60) {
    for (let i = 30; i < w - 10; i += 30) {
      placeRivet(x + i, y + 5);
      placeRivet(x + i, y + h - 5);
    }
  }
  if (h > 60) {
    for (let i = 30; i < h - 10; i += 30) {
      placeRivet(x + 5, y + i);
      placeRivet(x + w - 5, y + i);
    }
  }
  // Bullet-holes — använd seed (world-coord-baserad) så de inte vandrar
  const hash = seed || 0;
  const holes = Math.min(3, Math.floor((w + h) / 120));
  for (let i = 0; i < holes; i++) {
    const hx = x + 10 + ((hash * (i + 1) * 23) & 0xff) % Math.max(1, w - 20);
    const hy = y + 10 + ((hash * (i + 3) * 31) & 0xff) % Math.max(1, h - 20);
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(hx, hy, 2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(180,180,180,0.4)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.arc(hx, hy, 3.5, 0, Math.PI * 2); ctx.stroke();
  }
  // Lag-färgad ram (subtil)
  ctx.strokeStyle = stroke;
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// Pillar: betongpelare med synligt rebar + sprickor + bullet-holes
function drawPillar(x, y, w, h, seed) {
  // Concrete-gradient
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#4a4a4a');
  grad.addColorStop(0.5, '#606060');
  grad.addColorStop(1, '#3a3a3a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Yttre kant
  ctx.strokeStyle = '#2a2a2a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Inner highlight (left edge)
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(x + 2, y + 2, 2, h - 4);
  // Concrete texture (noise-dots) — använd seed så texturen är stabil
  const hash = seed || 0;
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  for (let i = 0; i < 8; i++) {
    const px = x + 2 + ((hash * (i + 1) * 7) & 0xff) % (w - 4);
    const py = y + 2 + ((hash * (i + 7) * 13) & 0xff) % (h - 4);
    ctx.fillRect(px, py, 1.5, 1.5);
  }
  // Sprickor (zig-zag-linjer)
  ctx.strokeStyle = 'rgba(0,0,0,0.6)';
  ctx.lineWidth = 1;
  if (h > 100) {
    ctx.beginPath();
    const midX = x + w / 2;
    ctx.moveTo(midX, y + h * 0.2);
    ctx.lineTo(midX - 2, y + h * 0.35);
    ctx.lineTo(midX + 1, y + h * 0.5);
    ctx.lineTo(midX - 3, y + h * 0.65);
    ctx.lineTo(midX + 2, y + h * 0.8);
    ctx.stroke();
  }
  // Exponerad rebar i toppen om hög pillar
  if (h > 100) {
    ctx.strokeStyle = '#5a3a1a';
    ctx.lineWidth = 1.5;
    for (let rx = x + 6; rx < x + w - 6; rx += 6) {
      ctx.beginPath();
      ctx.moveTo(rx, y);
      ctx.lineTo(rx, y - 4);
      ctx.stroke();
    }
    // Rost-orange tipp
    ctx.fillStyle = '#9a5a20';
    for (let rx = x + 6; rx < x + w - 6; rx += 6) {
      ctx.fillRect(rx - 1, y - 4, 2, 2);
    }
  }
  // Bullet-holes
  const holesN = Math.floor(h / 60);
  for (let i = 0; i < holesN; i++) {
    const hx = x + 5 + ((hash * (i + 1) * 19) & 0xff) % (w - 10);
    const hy = y + 20 + (i * h / Math.max(1, holesN)) | 0;
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(hx, hy, 1.5, 0, Math.PI * 2); ctx.fill();
  }
}

// Divider: jersey-barrier-style med reflektiv-stripes
function drawDivider(x, y, w, h) {
  // Concrete-gradient (top → bottom)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#5a5a5a');
  grad.addColorStop(0.5, '#404040');
  grad.addColorStop(1, '#2a2a2a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Kant
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Reflective gul-svart stripes (varannan)
  const stripeW = 12;
  for (let i = 0; i < w; i += stripeW * 2) {
    ctx.fillStyle = 'rgba(255,213,74,0.85)';
    ctx.fillRect(x + i, y + h * 0.3, Math.min(stripeW, w - i), h * 0.4);
  }
  // Yttre kant (mörk)
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x, y + h - 2, w, 2);
}

// Sandsäck: stack av runda säckar med stitches + rope
function drawSandbag(x, y, w, h) {
  // Antal säckar baserat på bredd (varje säck ~36px)
  const bagW = 36;
  const bags = Math.max(1, Math.floor(w / bagW));
  const actualBagW = w / bags;
  for (let i = 0; i < bags; i++) {
    const bx = x + i * actualBagW;
    const bw = actualBagW;
    // Säck-bas (rounded shape via gradient)
    const grad = ctx.createLinearGradient(bx, y, bx, y + h);
    grad.addColorStop(0, '#b89060');
    grad.addColorStop(0.5, '#9a7440');
    grad.addColorStop(1, '#6a4e2a');
    ctx.fillStyle = grad;
    ctx.beginPath();
    if (typeof ctx.roundRect === 'function') {
      ctx.roundRect(bx + 1, y + 1, bw - 2, h - 2, Math.min(6, h * 0.3));
    } else {
      ctx.rect(bx + 1, y + 1, bw - 2, h - 2);
    }
    ctx.fill();
    // Kant (mörk konturlinje)
    ctx.strokeStyle = '#3a2810';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // Stitching (sömmar) — horisontella streck längs ovansidan
    ctx.strokeStyle = 'rgba(40,25,5,0.7)';
    ctx.lineWidth = 0.8;
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(bx + 4, y + 3);
    ctx.lineTo(bx + bw - 4, y + 3);
    ctx.stroke();
    ctx.setLineDash([]);
    // Mid-tie (rep i mitten)
    ctx.fillStyle = '#5a3a15';
    ctx.fillRect(bx + bw / 2 - 2, y + 2, 4, h - 4);
    // Knut i mitten
    ctx.fillStyle = '#7a5025';
    ctx.beginPath();
    ctx.arc(bx + bw / 2, y + h / 2, Math.min(3, h * 0.2), 0, Math.PI * 2);
    ctx.fill();
    // Top-highlight
    ctx.fillStyle = 'rgba(255,220,180,0.25)';
    ctx.fillRect(bx + 4, y + 2, bw - 8, 2);
  }
}

// Explosivt fat: cylinder med metal-bands + biohazard + dripps
function drawBarrel(x, y, w, h) {
  const cx = x + w / 2;
  const cy = y + h / 2;
  // Yttre cirkel (top-view-style ovanifrån). Använd lite rektangel för "djup"
  ctx.fillStyle = '#2a0808';
  ctx.fillRect(x, y, w, h);
  // Huvud-cirkel (3D-bowl)
  const grad = ctx.createRadialGradient(cx - 2, cy - 2, 1, cx, cy, w * 0.55);
  grad.addColorStop(0, '#ff6060');
  grad.addColorStop(0.5, '#aa2020');
  grad.addColorStop(1, '#5a1010');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.5, 0, Math.PI * 2);
  ctx.fill();
  // Metal-band runt (yttre)
  ctx.strokeStyle = '#3a3a3a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.5, 0, Math.PI * 2);
  ctx.stroke();
  // Inner-cirkel (top-opening)
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.32, 0, Math.PI * 2);
  ctx.stroke();
  // Biohazard-symbol (☢) i mitten
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold ' + Math.floor(w * 0.5) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = '#000';
  ctx.shadowBlur = 2;
  ctx.fillText('☢', cx, cy);
  ctx.shadowBlur = 0;
  // Drip-streck nedanför (looks dangerous)
  ctx.strokeStyle = '#2a0a0a';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - 4, cy + w * 0.45);
  ctx.lineTo(cx - 5, y + h + 2);
  ctx.moveTo(cx + 3, cy + w * 0.4);
  ctx.lineTo(cx + 4, y + h + 1);
  ctx.stroke();
  // Top-highlight (reflective)
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath();
  ctx.arc(cx - w * 0.18, cy - w * 0.18, w * 0.1, 0, Math.PI * 2);
  ctx.fill();
}

// Debris: jaggad metallbit med rost + rivets
function drawDebris(x, y, w, h, seed) {
  // Bakgrund (mörk skugga-area)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x, y, w, h);
  // Mestadels mörkgrå metal med rost
  ctx.fillStyle = '#4a4a52';
  ctx.beginPath();
  // Jaggad oregelbunden form (seed används för stabilitet, även om current
  // polygon-form är hårdkodad relativ till x/y så seeds bara håller framtida
  // randomisering konsekvent)
  const hash = seed || 0;
  ctx.moveTo(x + 2, y + 4);
  ctx.lineTo(x + w * 0.3, y + 1);
  ctx.lineTo(x + w * 0.6, y + 3);
  ctx.lineTo(x + w - 2, y + 2);
  ctx.lineTo(x + w - 1, y + h * 0.4);
  ctx.lineTo(x + w - 4, y + h - 3);
  ctx.lineTo(x + w * 0.5, y + h - 1);
  ctx.lineTo(x + 3, y + h - 2);
  ctx.lineTo(x + 1, y + h * 0.5);
  ctx.closePath();
  ctx.fill();
  // Rost-fläckar (orange-bruna)
  ctx.fillStyle = '#7a4a20';
  ctx.beginPath();
  ctx.arc(x + w * 0.3, y + h * 0.4, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#9a5a30';
  ctx.beginPath();
  ctx.arc(x + w * 0.7, y + h * 0.6, 3, 0, Math.PI * 2);
  ctx.fill();
  // Rivets/bolts (silver-små cirklar)
  const placeBolt = (bx, by) => {
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.arc(bx, by, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#7a7a80';
    ctx.beginPath(); ctx.arc(bx - 0.3, by - 0.3, 0.6, 0, Math.PI * 2); ctx.fill();
  };
  placeBolt(x + w * 0.2, y + h * 0.2);
  placeBolt(x + w * 0.8, y + h * 0.25);
  placeBolt(x + w * 0.4, y + h * 0.7);
  // Sprick-linjer
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.15, y + h * 0.1);
  ctx.lineTo(x + w * 0.6, y + h * 0.5);
  ctx.lineTo(x + w * 0.85, y + h * 0.45);
  ctx.stroke();
}

// Barricade: korslagda träplankor med spikar + slitage
function drawBarricade(x, y, w, h) {
  // Bakgrund (svagt mörkare)
  ctx.fillStyle = '#3a2a18';
  ctx.fillRect(x, y, w, h);
  // Tre plankor överlappande
  const plankH = Math.max(6, h * 0.55);
  const drawPlank = (px, py, pw, ph, rot, color1, color2) => {
    ctx.save();
    ctx.translate(px + pw / 2, py + ph / 2);
    if (rot) ctx.rotate(rot);
    const grad = ctx.createLinearGradient(-pw / 2, -ph / 2, -pw / 2, ph / 2);
    grad.addColorStop(0, color1);
    grad.addColorStop(0.5, color2);
    grad.addColorStop(1, color1);
    ctx.fillStyle = grad;
    ctx.fillRect(-pw / 2, -ph / 2, pw, ph);
    ctx.strokeStyle = '#3a2810';
    ctx.lineWidth = 1;
    ctx.strokeRect(-pw / 2 + 0.5, -ph / 2 + 0.5, pw - 1, ph - 1);
    // Trä-grain (horisontella linjer)
    ctx.strokeStyle = 'rgba(50,30,10,0.4)';
    ctx.lineWidth = 0.5;
    for (let i = -ph / 2 + 2; i < ph / 2; i += 3) {
      ctx.beginPath();
      ctx.moveTo(-pw / 2 + 2, i);
      ctx.lineTo(pw / 2 - 2, i);
      ctx.stroke();
    }
    // Spikar
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.arc(-pw / 2 + 4, 0, 1.8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(pw / 2 - 4, 0, 1.8, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#7a7a80';
    ctx.beginPath(); ctx.arc(-pw / 2 + 4 - 0.3, -0.3, 0.6, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(pw / 2 - 4 - 0.3, -0.3, 0.6, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  };
  // Bottenplanka (rakt)
  drawPlank(x, y + h - plankH, w, plankH, 0, '#8a6a3a', '#6a4a20');
  // Korslagd planka (lite roterad)
  drawPlank(x + 4, y, w - 8, plankH * 0.9, -0.05, '#9a7a40', '#7a5a28');
  // Yttre kontur
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// Rör: cylindriskt metallrör med flänsar + bolts + ångström
function drawPipe(x, y, w, h) {
  // Cylinder gradient (top → bottom för horisontellt rör)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#7a98a8');
  grad.addColorStop(0.45, '#4a6a7a');
  grad.addColorStop(0.5, '#3a5a6a');
  grad.addColorStop(0.55, '#4a6a7a');
  grad.addColorStop(1, '#1a3040');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Top-highlight (reflective shine)
  ctx.fillStyle = 'rgba(220,240,255,0.5)';
  ctx.fillRect(x, y + 1, w, 2);
  // Botten-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x, y + h - 2, w, 2);
  // Flänsar i ändarna (bredare cirkel-bands)
  ctx.fillStyle = '#3a4a55';
  ctx.fillRect(x, y - 2, 8, h + 4);
  ctx.fillRect(x + w - 8, y - 2, 8, h + 4);
  ctx.strokeStyle = '#1a2a35';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y - 2, 7, h + 4);
  ctx.strokeRect(x + w - 7.5, y - 2, 7, h + 4);
  // Bolts på flänsarna
  const placeBolt = (bx, by) => {
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath(); ctx.arc(bx, by, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#aaa';
    ctx.beginPath(); ctx.arc(bx - 0.3, by - 0.3, 0.6, 0, Math.PI * 2); ctx.fill();
  };
  placeBolt(x + 4, y);
  placeBolt(x + 4, y + h - 1);
  placeBolt(x + w - 4, y);
  placeBolt(x + w - 4, y + h - 1);
  // Rost-strimmor längs röret
  ctx.fillStyle = 'rgba(120,60,20,0.4)';
  ctx.fillRect(x + w * 0.3, y + h * 0.3, 2, h * 0.4);
  ctx.fillRect(x + w * 0.65, y + h * 0.5, 2, h * 0.3);
}

// Crate: trälåda med plankor, hörn-band, stamps
function drawCrate(x, y, w, h, seed) {
  // Gradient-bakgrund för wood-tone
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#9a6a3a');
  grad.addColorStop(0.5, '#7a4a20');
  grad.addColorStop(1, '#5a3010');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Plankor (horisontella separator-linjer)
  ctx.strokeStyle = '#3a1a0a';
  ctx.lineWidth = 1.2;
  const plankCount = Math.max(2, Math.floor(h / 25));
  for (let i = 1; i < plankCount; i++) {
    const py = y + (h / plankCount) * i;
    ctx.beginPath();
    ctx.moveTo(x + 2, py);
    ctx.lineTo(x + w - 2, py);
    ctx.stroke();
  }
  // Trä-grain (subtila vertikala streck) — använd seed så grain inte vandrar
  ctx.strokeStyle = 'rgba(40,20,5,0.3)';
  ctx.lineWidth = 0.6;
  const hash = seed || 0;
  for (let i = 0; i < 4; i++) {
    const gx = x + 4 + ((hash * (i + 1) * 13) & 0x7f) % (w - 8);
    ctx.beginPath();
    ctx.moveTo(gx, y + 2);
    ctx.lineTo(gx, y + h - 2);
    ctx.stroke();
  }
  // Hörn-metall-bands (mörka L-shapes)
  ctx.fillStyle = '#3a2818';
  const cornerSize = Math.min(8, Math.floor(Math.min(w, h) * 0.25));
  // Top-left
  ctx.fillRect(x, y, cornerSize, 2);
  ctx.fillRect(x, y, 2, cornerSize);
  // Top-right
  ctx.fillRect(x + w - cornerSize, y, cornerSize, 2);
  ctx.fillRect(x + w - 2, y, 2, cornerSize);
  // Bottom-left
  ctx.fillRect(x, y + h - 2, cornerSize, 2);
  ctx.fillRect(x, y + h - cornerSize, 2, cornerSize);
  // Bottom-right
  ctx.fillRect(x + w - cornerSize, y + h - 2, cornerSize, 2);
  ctx.fillRect(x + w - 2, y + h - cornerSize, 2, cornerSize);
  // Nitar i hörnen
  const placeNail = (nx, ny) => {
    ctx.fillStyle = '#1a1010';
    ctx.beginPath(); ctx.arc(nx, ny, 1.3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#888';
    ctx.beginPath(); ctx.arc(nx - 0.2, ny - 0.2, 0.5, 0, Math.PI * 2); ctx.fill();
  };
  placeNail(x + 3, y + 3);
  placeNail(x + w - 3, y + 3);
  placeNail(x + 3, y + h - 3);
  placeNail(x + w - 3, y + h - 3);
  // Stamp/label (om tillräckligt stor)
  if (w >= 60 && h >= 60) {
    ctx.save();
    ctx.translate(x + w / 2, y + h * 0.6);
    ctx.rotate(-0.08);
    ctx.fillStyle = 'rgba(20,10,5,0.55)';
    ctx.strokeStyle = 'rgba(20,10,5,0.55)';
    ctx.lineWidth = 1.5;
    ctx.font = 'bold ' + Math.floor(w * 0.18) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('AMMO', 0, 0);
    // Frame runt stamp
    ctx.strokeRect(-w * 0.28, -h * 0.12, w * 0.56, h * 0.24);
    ctx.restore();
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0a05';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// === JUGGERNAUT-WALL-RENDERS ====================================================

function drawConcreteWall(x, y, w, h) {
  // Perimeter-betong med mörk fog + textur
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#3a3a40');
  grad.addColorStop(0.5, '#2a2a2e');
  grad.addColorStop(1, '#1a1a1e');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Streckad fog ovanpå
  ctx.fillStyle = 'rgba(10,10,12,0.6)';
  ctx.fillRect(x, y, w, 2);
  ctx.fillRect(x, y + h - 2, w, 2);
  // Bullet-marks (random)
  ctx.fillStyle = '#0a0a0a';
  if (w > 100) {
    for (let i = 0; i < Math.min(8, w / 200); i++) {
      const mx = x + 20 + ((i * 137) % (w - 40));
      const my = y + (i % 2 === 0 ? 4 : h - 6);
      ctx.beginPath(); ctx.arc(mx, my, 1.5, 0, Math.PI * 2); ctx.fill();
    }
  }
}

function drawTruck(x, y, w, h, seed) {
  // Cargo-lastbil/skåpbil sett ovanifrån — cab + cargo + hjul + detaljer
  const isHorizontal = w > h;
  const bodyLen = isHorizontal ? w : h;
  const bodyW = isHorizontal ? h : w;
  // Lastbil-färg (deterministic per pos)
  const colors = ['#5a4a30', '#3a4a5a', '#5a3a3a', '#4a4a4a'];
  const bodyColor = colors[(seed >>> 4) & 3];
  const bodyDark = '#1a1a1a';
  ctx.save();
  ctx.translate(x, y);
  // Skugga under
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(2, 4, w, h);
  // Body shadow-dark stripe
  ctx.fillStyle = bodyDark;
  ctx.fillRect(0, 0, w, h);
  // Body main color
  ctx.fillStyle = bodyColor;
  ctx.fillRect(2, 2, w - 4, h - 4);
  // Cab (front kvadrat, mörkare)
  if (isHorizontal) {
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(w - 22, 2, 20, h - 4);
    ctx.fillStyle = '#0a1a3a';
    // Vindruta
    ctx.fillRect(w - 18, 4, 14, 6);
    // Reflektion på vindruta
    ctx.fillStyle = '#3a6a8a';
    ctx.fillRect(w - 17, 5, 6, 1);
    // Strålkastare
    ctx.fillStyle = '#fff8a0';
    ctx.shadowColor = '#fff8a0'; ctx.shadowBlur = 4;
    ctx.fillRect(w - 4, 4, 2, 3);
    ctx.fillRect(w - 4, h - 7, 2, 3);
    ctx.shadowBlur = 0;
  } else {
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(2, h - 22, w - 4, 20);
    ctx.fillStyle = '#0a1a3a';
    ctx.fillRect(4, h - 18, w - 8, 6);
    ctx.fillStyle = '#fff8a0';
    ctx.fillRect(4, h - 4, 3, 2);
    ctx.fillRect(w - 7, h - 4, 3, 2);
  }
  // Cargo-area panel-lines (3-4 vertikala)
  ctx.strokeStyle = bodyDark;
  ctx.lineWidth = 1;
  const panelCount = 4;
  if (isHorizontal) {
    for (let i = 1; i < panelCount; i++) {
      const px = (w - 22) * (i / panelCount);
      ctx.beginPath(); ctx.moveTo(px, 4); ctx.lineTo(px, h - 4); ctx.stroke();
    }
  } else {
    for (let i = 1; i < panelCount; i++) {
      const py = (h - 22) * (i / panelCount);
      ctx.beginPath(); ctx.moveTo(4, py); ctx.lineTo(w - 4, py); ctx.stroke();
    }
  }
  // Top-highlight
  ctx.fillStyle = mixColors(bodyColor, '#ffffff', 0.3);
  if (isHorizontal) ctx.fillRect(2, 2, w - 4, 1.5);
  else ctx.fillRect(2, 2, 1.5, h - 4);
  // 4 hjul (mörka cirklar i hörnen)
  ctx.fillStyle = '#0a0a0a';
  const wR = Math.min(bodyW * 0.18, 5);
  if (isHorizontal) {
    ctx.fillRect(8, -wR * 0.5, 10, wR * 0.7);
    ctx.fillRect(w - 30, -wR * 0.5, 10, wR * 0.7);
    ctx.fillRect(8, h - wR * 0.2, 10, wR * 0.7);
    ctx.fillRect(w - 30, h - wR * 0.2, 10, wR * 0.7);
  } else {
    ctx.fillRect(-wR * 0.5, 8, wR * 0.7, 10);
    ctx.fillRect(w - wR * 0.2, 8, wR * 0.7, 10);
    ctx.fillRect(-wR * 0.5, h - 30, wR * 0.7, 10);
    ctx.fillRect(w - wR * 0.2, h - 30, wR * 0.7, 10);
  }
  // Rost / slitage (3-4 fläckar)
  ctx.fillStyle = '#3a2a18';
  for (let i = 0; i < 4; i++) {
    const rx = 6 + ((seed * (i + 1) * 17) % (w - 30));
    const ry = 6 + ((seed * (i + 2) * 13) % (h - 12));
    ctx.fillRect(rx, ry, 3, 2);
  }
  // Yttre dark outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawVan(x, y, w, h, seed) {
  // Skåpbil — kortare än lastbil, mer kvadratisk
  drawTruck(x, y, w, h, seed); // återanvänd truck-design (mindre proportioner)
  // Lägg på en distinkt "VAN"-detalj: stege på taket (3 streck)
  ctx.save();
  ctx.strokeStyle = '#3a3a3a';
  ctx.lineWidth = 1.2;
  if (w > h) {
    ctx.beginPath();
    ctx.moveTo(x + 10, y + h / 2 - 2); ctx.lineTo(x + w - 30, y + h / 2 - 2);
    ctx.moveTo(x + 10, y + h / 2 + 2); ctx.lineTo(x + w - 30, y + h / 2 + 2);
    for (let i = 0; i < 4; i++) {
      const lx = x + 14 + i * ((w - 50) / 4);
      ctx.moveTo(lx, y + h / 2 - 2); ctx.lineTo(lx, y + h / 2 + 2);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function drawCarWreck(x, y, w, h, seed) {
  // Utbrunnen bil: svart-sotigt skelett med trasiga fönster + öppna dörrar
  const isHorizontal = w > h;
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 5, w, h);
  // Body — mycket mörk, sotad
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(x, y, w, h);
  // Brand-fläckar / sot-streaks (mörkare)
  ctx.fillStyle = '#0a0808';
  for (let i = 0; i < 6; i++) {
    const fx = x + 4 + ((seed * (i + 1) * 19) % (w - 8));
    const fy = y + 4 + ((seed * (i + 3) * 23) % (h - 8));
    ctx.fillRect(fx, fy, 4, 3);
  }
  // Orange-roströd glow var här lågorna brunnit
  ctx.fillStyle = 'rgba(180, 60, 20, 0.25)';
  ctx.fillRect(x + 4, y + 4, w - 8, h - 8);
  // Trasiga fönster (mörka rektanglar)
  ctx.fillStyle = '#0a0a0a';
  if (isHorizontal) {
    ctx.fillRect(x + w * 0.2, y + 3, w * 0.6, 3);
    ctx.fillRect(x + w * 0.2, y + h - 6, w * 0.6, 3);
  } else {
    ctx.fillRect(x + 3, y + h * 0.2, 3, h * 0.6);
    ctx.fillRect(x + w - 6, y + h * 0.2, 3, h * 0.6);
  }
  // Tak (mörkare mid-stripe — välter / krossad)
  ctx.fillStyle = '#0a0a08';
  if (isHorizontal) {
    ctx.fillRect(x + w * 0.25, y + h * 0.35, w * 0.5, h * 0.3);
  } else {
    ctx.fillRect(x + w * 0.35, y + h * 0.25, w * 0.3, h * 0.5);
  }
  // Hjul — 4 förbrända ringar
  ctx.fillStyle = '#000';
  ctx.strokeStyle = '#3a1a08';
  ctx.lineWidth = 0.8;
  const wheels = isHorizontal
    ? [[x + 12, y - 1], [x + w - 12, y - 1], [x + 12, y + h + 1], [x + w - 12, y + h + 1]]
    : [[x - 1, y + 12], [x + w + 1, y + 12], [x - 1, y + h - 12], [x + w + 1, y + h - 12]];
  for (const [wx, wy] of wheels) {
    ctx.beginPath();
    ctx.ellipse(wx, wy, 5, 3, 0, 0, Math.PI*2);
    ctx.fill(); ctx.stroke();
  }
  // Rost-orange highlights (random)
  ctx.fillStyle = 'rgba(180, 90, 40, 0.4)';
  ctx.fillRect(x + 2, y + 2, w - 4, 0.5);
  ctx.fillRect(x + 2, y + h - 2.5, w - 4, 0.5);
  // Yttre dark outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawGuardhouse(x, y, w, h) {
  // Vakthytt: liten betong-bod med fönster + dörr
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x + 3, y + 5, w, h);
  // Bas: gradient grå betong
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#5a5a5a');
  grad.addColorStop(0.5, '#7a7a7a');
  grad.addColorStop(1, '#4a4a4a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Tak (mörkt)
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(x, y, w, 4);
  // Tak-highlight
  ctx.fillStyle = '#5a5a5a';
  ctx.fillRect(x, y, w, 1);
  // Stora fönster (2 framsidor — vänd mot center)
  ctx.fillStyle = '#1a3a5a';
  ctx.fillRect(x + 10, y + 12, w - 20, h - 30);
  // Vindruta reflektion
  ctx.fillStyle = '#3a6a8a';
  ctx.fillRect(x + 12, y + 14, (w - 24) * 0.4, 2);
  // Window-frame
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 10, y + 12, w - 20, h - 30);
  // Horisontellt fönster-streck (mitten)
  ctx.beginPath();
  ctx.moveTo(x + 10, y + 12 + (h - 30) / 2); ctx.lineTo(x + w - 10, y + 12 + (h - 30) / 2);
  ctx.stroke();
  // Vertikalt center-streck
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y + 12); ctx.lineTo(x + w / 2, y + h - 18);
  ctx.stroke();
  // Dörr (under fönstret)
  ctx.fillStyle = '#3a2a1a';
  ctx.fillRect(x + (w - 14) / 2, y + h - 16, 14, 12);
  ctx.fillStyle = '#1a0a08';
  ctx.fillRect(x + (w - 14) / 2, y + h - 16, 14, 1);
  // Dörr-handtag
  ctx.fillStyle = '#ffd54a';
  ctx.fillRect(x + (w - 14) / 2 + 10, y + h - 10, 1.5, 2);
  // SECURITY-text på sidan
  ctx.fillStyle = '#ff5a3a';
  ctx.font = 'bold 7px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('SECURITY', x + w / 2, y + 9);
  // Yttre outline
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawRamp(x, y, w, h) {
  // Bilramp — diagonal gradient som ser ut som en sluttning
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Bas gradient (mörk → ljus → mörk = "valv-känsla")
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#2a2a2a');
  grad.addColorStop(0.5, '#5a5a5a');
  grad.addColorStop(1, '#2a2a2a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Diagonala chevron-arrows (uppåt-pekande, gula) som indikerar slope
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = 2.5;
  const chevronCount = Math.max(2, Math.floor(w / 60));
  for (let i = 0; i < chevronCount; i++) {
    const cx = x + 15 + i * (w / chevronCount);
    ctx.beginPath();
    ctx.moveTo(cx, y + h * 0.75);
    ctx.lineTo(cx + 12, y + h * 0.35);
    ctx.lineTo(cx + 24, y + h * 0.75);
    ctx.stroke();
  }
  // Kant-striping (svart-gul varning)
  for (let i = 0; i < w; i += 12) {
    ctx.fillStyle = i % 24 < 12 ? '#ffd54a' : '#1a1a1a';
    ctx.fillRect(x + i, y, 12, 3);
    ctx.fillRect(x + i, y + h - 3, 12, 3);
  }
  // Yttre outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawOilDrum(x, y, w, h, seed) {
  // Industrifat — sealed steel barrel top-down. Realistisk metallic-look med
  // 3 koncentriska ringar (rolling ribs), screw-cap, deep shadows.
  ctx.save();
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Skugga under
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.ellipse(cx + 2, cy + 5, r + 1, 4, 0, 0, Math.PI*2); ctx.fill();
  // Bas — mörk metall (industri-blå-grå)
  const baseGrad = ctx.createRadialGradient(cx - r * 0.4, cy - r * 0.4, r * 0.2, cx, cy, r);
  baseGrad.addColorStop(0, '#7a7a82');
  baseGrad.addColorStop(0.55, '#3a3a40');
  baseGrad.addColorStop(1, '#1a1a20');
  ctx.fillStyle = baseGrad;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  // 3 rolling-ribs (koncentriska ringar — typiska industriella oljefat)
  ctx.strokeStyle = '#0a0a0e';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.85, 0, Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.65, 0, Math.PI*2); ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.45, 0, Math.PI*2); ctx.stroke();
  // Ring-highlights (vita streck på vänster-sida av varje ring)
  ctx.strokeStyle = 'rgba(180, 180, 195, 0.7)';
  ctx.lineWidth = 0.5;
  for (const rr of [0.85, 0.65, 0.45]) {
    ctx.beginPath();
    ctx.arc(cx, cy, r * rr, Math.PI * 1.1, Math.PI * 1.6);
    ctx.stroke();
  }
  // Center-cap (bung — screw-cap för påfyllning)
  ctx.fillStyle = '#1a1a1e';
  ctx.beginPath(); ctx.arc(cx + r * 0.18, cy - r * 0.05, r * 0.15, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#5a5a62';
  ctx.beginPath(); ctx.arc(cx + r * 0.18, cy - r * 0.05, r * 0.11, 0, Math.PI*2); ctx.fill();
  // Cap-cross (insex)
  ctx.strokeStyle = '#0a0a0e';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(cx + r * 0.12, cy - r * 0.05); ctx.lineTo(cx + r * 0.24, cy - r * 0.05);
  ctx.moveTo(cx + r * 0.18, cy - r * 0.11); ctx.lineTo(cx + r * 0.18, cy + r * 0.01);
  ctx.stroke();
  // Secondary vent (mindre skruv på motsatt sida)
  ctx.fillStyle = '#1a1a1e';
  ctx.beginPath(); ctx.arc(cx - r * 0.22, cy + r * 0.05, r * 0.08, 0, Math.PI*2); ctx.fill();
  // Subtle skada/dunk (en mörk konkav-fläck)
  ctx.fillStyle = 'rgba(10, 10, 14, 0.4)';
  ctx.beginPath(); ctx.ellipse(cx + r * 0.4, cy + r * 0.3, r * 0.18, r * 0.1, 0.5, 0, Math.PI*2); ctx.fill();
  // Yttre dark outline
  ctx.strokeStyle = '#0a0a0e';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.stroke();
  ctx.restore();
}

function drawFireDrum(x, y, w, h, seed) {
  // Brinnande fat — top-down vy. Cylindrisk fat-rim runt MÖRK ÖPPNING i mitten.
  // Eld kommer ut FRÅN öppningen (logiskt — fatet är öppet i toppen och brinner inuti).
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  const t = performance.now();
  const flicker = 0.85 + Math.sin(t / 70 + (seed & 0xff)) * 0.15;
  ctx.save();
  // Ljuspöl på golvet — varmt orange runt fatet
  const lightR = 90;
  const lightGrad = ctx.createRadialGradient(cx, cy, 4, cx, cy, lightR);
  lightGrad.addColorStop(0, `rgba(255, 140, 50, ${0.5 * flicker})`);
  lightGrad.addColorStop(0.6, `rgba(255, 100, 30, ${0.18 * flicker})`);
  lightGrad.addColorStop(1, 'rgba(255, 80, 20, 0)');
  ctx.fillStyle = lightGrad;
  ctx.fillRect(cx - lightR, cy - lightR, lightR * 2, lightR * 2);
  // Skugga under fatet
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.ellipse(cx + 1, cy + 4, r + 2, 4, 0, 0, Math.PI*2); ctx.fill();

  // FAT-KROPP (rund top-down) — rostig metall
  // Outer rim (sotad bränd metall — mörkare än ett vanligt oljefat eftersom det brinner)
  ctx.fillStyle = '#1a0a06';
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  // Tjock metall-rim (där öppningen är) — ljusare
  ctx.fillStyle = '#4a3018';
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#2a1808';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.78, 0, Math.PI*2); ctx.fill();
  // ÖPPNINGEN (mörk hål in i fatet — fyrkantig form med oregelbunden glow)
  ctx.fillStyle = '#000000';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.65, 0, Math.PI*2); ctx.fill();
  // Hot orange glow INUTI öppningen (där elden kommer ifrån)
  const innerGrad = ctx.createRadialGradient(cx, cy, 1, cx, cy, r * 0.65);
  innerGrad.addColorStop(0, `rgba(255, 230, 150, ${flicker})`);
  innerGrad.addColorStop(0.3, `rgba(255, 160, 50, ${0.95 * flicker})`);
  innerGrad.addColorStop(0.7, `rgba(180, 60, 20, ${0.7 * flicker})`);
  innerGrad.addColorStop(1, 'rgba(60, 20, 10, 0.5)');
  ctx.fillStyle = innerGrad;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.65, 0, Math.PI*2); ctx.fill();
  // Rim-highlight (vänster sida — vit reflex från flammorna)
  ctx.fillStyle = '#7a5028';
  ctx.beginPath(); ctx.arc(cx - r * 0.4, cy - r * 0.3, r * 0.18, 0, Math.PI*2); ctx.fill();
  // Rost-fläckar på fat-rimmen
  ctx.fillStyle = '#7a3818';
  ctx.fillRect(cx + r * 0.55, cy - r * 0.3, 2, 1.5);
  ctx.fillRect(cx - r * 0.7, cy + r * 0.3, 2, 1.5);
  ctx.fillRect(cx + r * 0.3, cy + r * 0.6, 1.5, 1);
  // Yttre dark outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.stroke();

  // FLAMMOR — kommer UPP UR öppningen (top-down: flammorna är centerade på cy och växer ut)
  const flameSize = r * 1.4 + Math.sin(t / 70) * 3;
  // Yttre orange ring (bredast)
  ctx.fillStyle = `rgba(255, 100, 30, ${0.55 * flicker})`;
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const variation = 0.85 + Math.sin(t / 90 + i * 1.7 + seed) * 0.25;
    const rr = flameSize * variation;
    const px = cx + Math.cos(a) * rr;
    const py = cy + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath(); ctx.fill();
  // Mid yellow flame
  ctx.fillStyle = `rgba(255, 200, 60, ${0.8 * flicker})`;
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const variation = 0.75 + Math.sin(t / 80 + i * 2.1 + seed * 0.7) * 0.22;
    const rr = flameSize * 0.7 * variation;
    const px = cx + Math.cos(a) * rr;
    const py = cy + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath(); ctx.fill();
  // Vit hot-core (i mitten av öppningen)
  ctx.fillStyle = `rgba(255, 250, 220, ${flicker})`;
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const variation = 0.7 + Math.sin(t / 60 + i * 2.3) * 0.3;
    const rr = flameSize * 0.32 * variation;
    const px = cx + Math.cos(a) * rr;
    const py = cy + Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath(); ctx.fill();
  // Outer glow (radial halo)
  ctx.shadowColor = '#ff7030'; ctx.shadowBlur = 22 * flicker;
  ctx.fillStyle = `rgba(255, 180, 50, ${0.35 * flicker})`;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.5, 0, Math.PI*2); ctx.fill();
  ctx.shadowBlur = 0;
  // Sparks som flyger uppåt OCH utåt (lite åt sidorna eftersom det är top-down)
  const sparkSeed = Math.floor(t / 100) + (seed & 0xff);
  for (let i = 0; i < 6; i++) {
    const sphase = (t / 700 + i * 0.17 + (sparkSeed & 0x1f) / 31) % 1;
    const sa = ((sparkSeed + i * 7) & 0xff) / 255 * Math.PI * 2;
    const sdist = sphase * 22;
    const sx = cx + Math.cos(sa) * sdist;
    const sy = cy + Math.sin(sa) * sdist;
    ctx.fillStyle = `rgba(255, ${150 + i * 18}, 50, ${(1 - sphase) * 0.9})`;
    ctx.beginPath(); ctx.arc(sx, sy, 1 + (1 - sphase) * 0.6, 0, Math.PI*2); ctx.fill();
  }
  // Subtle smoke ovanför (mörk transparent puff som drar uppåt-utåt)
  ctx.fillStyle = `rgba(40, 35, 30, ${0.18 + Math.sin(t / 250) * 0.04})`;
  ctx.beginPath();
  ctx.arc(cx - 3 + Math.sin(t / 200) * 2, cy - 5, 6, 0, Math.PI*2); ctx.fill();
  ctx.beginPath();
  ctx.arc(cx + 4 + Math.cos(t / 180) * 2, cy - 3, 4, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

function drawLamppost(x, y, w, h, worldX, worldY) {
  // Tak-monterad lyktstolpe (sticker NER från taket). Pole + lamp-head + light-pool
  // Använd world-coords för deterministic flicker per pos
  const t = performance.now();
  const flickerSeed = ((worldX * 17 + worldY * 23) | 0);
  const flickerPhase = (t / 1000) * 4 + flickerSeed * 0.1;
  const flickerNoise = Math.sin(flickerPhase * 7.3) * Math.cos(flickerPhase * 11.7);
  const isOn = flickerNoise > -0.3;
  const intensity = isOn ? (0.8 + Math.sin(flickerPhase * 3.2) * 0.2) : (Math.random() < 0.08 ? 0.35 : 0);
  ctx.save();
  // Ljus-pöl på marken — render FÖRST
  if (intensity > 0.1) {
    const poolR = 95;
    const poolGrad = ctx.createRadialGradient(x + w / 2, y + h + 14, 4, x + w / 2, y + h + 14, poolR);
    poolGrad.addColorStop(0, `rgba(220, 230, 255, ${0.35 * intensity})`);
    poolGrad.addColorStop(0.45, `rgba(180, 210, 255, ${0.18 * intensity})`);
    poolGrad.addColorStop(1, 'rgba(180, 210, 255, 0)');
    ctx.fillStyle = poolGrad;
    ctx.fillRect(x + w / 2 - poolR, y + h + 14 - poolR, poolR * 2, poolR * 2);
  }
  // Skugga under pole
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Pole-bas (mörk metall)
  ctx.fillStyle = '#1a1a20';
  ctx.fillRect(x, y, w, h);
  // Pole highlight (vänster)
  ctx.fillStyle = '#3a3a48';
  ctx.fillRect(x, y, 1.5, h);
  // Pole top-cap (mörk topp)
  ctx.fillStyle = '#0a0a0e';
  ctx.fillRect(x - 1, y - 1, w + 2, 2);
  // Lamp-fixture (sticker ut ovanpå pole — lampskärm)
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(x - 6, y - 7, w + 12, 5);
  // Lampskärm-inner-glow när på
  if (intensity > 0.05) {
    ctx.fillStyle = `rgba(220, 240, 255, ${intensity})`;
    ctx.shadowColor = '#a8d0ff'; ctx.shadowBlur = 14 * intensity;
    ctx.fillRect(x - 5, y - 6, w + 10, 3);
    ctx.shadowBlur = 0;
    // Vit hot-streak
    ctx.fillStyle = `rgba(255, 255, 255, ${intensity * 0.7})`;
    ctx.fillRect(x - 5, y - 5.5, w + 10, 1);
  } else {
    // Av — mörkt
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(x - 5, y - 6, w + 10, 3);
  }
  // Lampskärm-fastsättnings-skruvar
  ctx.fillStyle = '#3a3a40';
  ctx.beginPath(); ctx.arc(x - 4, y - 4, 0.7, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + w + 4, y - 4, 0.7, 0, Math.PI*2); ctx.fill();
  // Mount-bracket (övre del — tak-fastsättning)
  ctx.fillStyle = '#2a2a30';
  ctx.fillRect(x - 2, y - 12, w + 4, 5);
  ctx.fillStyle = '#5a5a60';
  ctx.fillRect(x - 2, y - 12, w + 4, 1);
  ctx.restore();
}

function drawBrokenPillar(x, y, w, h, seed) {
  // Trasig pelare — exponerad rebar + sprickor + raserad topp
  drawPillar(x, y, w, h, seed);
  ctx.save();
  // Stor diagonal spricka
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(x, y + h * 0.3);
  ctx.lineTo(x + w * 0.5, y + h * 0.5);
  ctx.lineTo(x + w, y + h * 0.4);
  ctx.stroke();
  // Exponerad rebar (rostig metallpinne sticker ut)
  ctx.strokeStyle = '#8a4818';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.3, y - 4);
  ctx.lineTo(x + w * 0.3, y + h * 0.4);
  ctx.moveTo(x + w * 0.7, y - 6);
  ctx.lineTo(x + w * 0.7, y + h * 0.3);
  ctx.stroke();
  // Rebar-böjningar (top)
  ctx.beginPath();
  ctx.moveTo(x + w * 0.3, y - 4); ctx.lineTo(x + w * 0.3 - 3, y - 8);
  ctx.moveTo(x + w * 0.7, y - 6); ctx.lineTo(x + w * 0.7 + 4, y - 9);
  ctx.stroke();
  // Concrete-chunks-rubble vid botten
  ctx.fillStyle = '#3a3a40';
  ctx.fillRect(x - 2, y + h - 2, 4, 3);
  ctx.fillRect(x + w - 2, y + h - 3, 5, 4);
  ctx.fillStyle = '#5a5a60';
  ctx.fillRect(x - 1, y + h - 2, 1, 1);
  ctx.restore();
}

function drawBollard(x, y, w, h) {
  // Cylindrisk betong-pollare med gul-svart varnings-stripe + reflex
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.ellipse(cx + 1.5, cy + 3, r + 1, 3, 0, 0, Math.PI*2); ctx.fill();
  // Bas (betong-grå med radial-gradient för cylinder-känsla)
  const grad = ctx.createRadialGradient(cx - r * 0.4, cy - r * 0.4, r * 0.2, cx, cy, r);
  grad.addColorStop(0, '#9a9a9a');
  grad.addColorStop(0.6, '#5a5a5a');
  grad.addColorStop(1, '#2a2a2a');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  // Gul varnings-stripe (cirkulär band runt mid)
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = Math.max(1.5, r * 0.4);
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.92, 0, Math.PI*2); ctx.stroke();
  // Svart kant runt gul-stripe (klassisk varnings-look)
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 0.8;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.7, 0, Math.PI*2); ctx.stroke();
  // Reflex-fläckar (3 vita prickar på gula stripen)
  ctx.fillStyle = '#fff';
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * Math.PI * 2 - Math.PI / 6;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(a) * r * 0.92, cy + Math.sin(a) * r * 0.92, 0.6, 0, Math.PI*2);
    ctx.fill();
  }
  // Top-cap (mörkare mitten)
  ctx.fillStyle = '#3a3a3a';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.35, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#5a5a5a';
  ctx.beginPath(); ctx.arc(cx - r * 0.1, cy - r * 0.1, r * 0.15, 0, Math.PI*2); ctx.fill();
  // Slitage-spår (mörka streck längs sidan)
  ctx.strokeStyle = 'rgba(20, 20, 20, 0.5)';
  ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.moveTo(cx + r * 0.5, cy + r * 0.4); ctx.lineTo(cx + r * 0.8, cy + r * 0.2);
  ctx.stroke();
  // Yttre outline
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.stroke();
}

function drawDumpsterFire(x, y, w, h, seed) {
  // Brinnande soptunna/dumpster — stor rektangulär metallcontainer med
  // öppet lock och flammor som strömmar ut. Sotad, grön/rostig, varningar.
  const t = performance.now();
  const flicker = 0.85 + Math.sin(t / 80 + (seed & 0xff)) * 0.15;
  ctx.save();
  // Ljuspöl på golvet (varmt orange) — först
  const lightR = 110;
  const lightGrad = ctx.createRadialGradient(x + w / 2, y + h / 2, 6, x + w / 2, y + h / 2, lightR);
  lightGrad.addColorStop(0, `rgba(255, 140, 50, ${0.5 * flicker})`);
  lightGrad.addColorStop(0.6, `rgba(255, 100, 30, ${0.2 * flicker})`);
  lightGrad.addColorStop(1, 'rgba(255, 80, 20, 0)');
  ctx.fillStyle = lightGrad;
  ctx.fillRect(x + w / 2 - lightR, y + h / 2 - lightR, lightR * 2, lightR * 2);
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.fillRect(x + 3, y + 5, w, h);
  // Bas-kropp (grön/sotad metall — dumpster-klassiker)
  ctx.fillStyle = '#2a3a25';
  ctx.fillRect(x, y, w, h);
  // Sotade fläckar (svart-fläckar från elden)
  ctx.fillStyle = '#0a0a08';
  ctx.fillRect(x + 2, y + 2, w - 4, 6);
  ctx.fillStyle = '#1a1a14';
  ctx.fillRect(x + w * 0.2, y + 4, w * 0.3, h * 0.3);
  ctx.fillRect(x + w * 0.6, y + 6, w * 0.2, h * 0.4);
  // Top-rim (lite ljusare — lock-kant där elden går upp)
  ctx.fillStyle = '#4a5a40';
  ctx.fillRect(x, y, w, 3);
  // Öppning (mörk öppet topp där flammorna kommer från)
  ctx.fillStyle = '#000';
  ctx.fillRect(x + 4, y + 3, w - 8, 5);
  // Inner hot glow inuti dumpstern
  const innerG = ctx.createLinearGradient(0, y + 3, 0, y + 8);
  innerG.addColorStop(0, `rgba(255, 200, 100, ${0.9 * flicker})`);
  innerG.addColorStop(1, `rgba(180, 60, 20, ${0.7 * flicker})`);
  ctx.fillStyle = innerG;
  ctx.fillRect(x + 4, y + 3, w - 8, 5);
  // Vertikala ribbor (typiska dumpster-paneler)
  ctx.strokeStyle = '#1a2a18';
  ctx.lineWidth = 0.8;
  const ribCount = 6;
  for (let i = 1; i < ribCount; i++) {
    const rx = x + (w * i / ribCount);
    ctx.beginPath();
    ctx.moveTo(rx, y + 8); ctx.lineTo(rx, y + h - 4);
    ctx.stroke();
  }
  // 4 hjul-bockar i hörnen
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x + 2, y + h - 4, 4, 4);
  ctx.fillRect(x + w - 6, y + h - 4, 4, 4);
  // FLAMMOR ovanför öppning (multi-lager)
  const flameH = h * 0.8 + Math.sin(t / 70) * 4;
  // Yttre orange
  ctx.fillStyle = `rgba(255, 100, 30, ${0.6 * flicker})`;
  ctx.beginPath();
  ctx.moveTo(x + 4, y + 3);
  ctx.quadraticCurveTo(x + w * 0.25 + Math.sin(t / 100) * 3, y - flameH * 0.6, x + w * 0.45, y - flameH * 0.85);
  ctx.quadraticCurveTo(x + w / 2 + Math.sin(t / 80) * 4, y - flameH, x + w * 0.55, y - flameH * 0.85);
  ctx.quadraticCurveTo(x + w * 0.75 + Math.sin(t / 90) * 3, y - flameH * 0.6, x + w - 4, y + 3);
  ctx.closePath(); ctx.fill();
  // Mid yellow
  ctx.fillStyle = `rgba(255, 200, 60, ${0.85 * flicker})`;
  ctx.beginPath();
  ctx.moveTo(x + 8, y + 3);
  ctx.quadraticCurveTo(x + w * 0.3 + Math.sin(t / 90) * 2, y - flameH * 0.5, x + w * 0.47, y - flameH * 0.72);
  ctx.quadraticCurveTo(x + w / 2 + Math.sin(t / 70) * 3, y - flameH * 0.82, x + w * 0.53, y - flameH * 0.72);
  ctx.quadraticCurveTo(x + w * 0.7 + Math.sin(t / 95) * 2, y - flameH * 0.5, x + w - 8, y + 3);
  ctx.closePath(); ctx.fill();
  // Vit hot-core (i mitten)
  ctx.fillStyle = `rgba(255, 250, 220, ${flicker})`;
  ctx.beginPath();
  ctx.ellipse(x + w / 2 + Math.sin(t / 60) * 2, y - flameH * 0.4, 4, 8, 0, 0, Math.PI*2); ctx.fill();
  // Glow halo
  ctx.shadowColor = '#ff7030'; ctx.shadowBlur = 18 * flicker;
  ctx.fillStyle = `rgba(255, 180, 50, ${0.4 * flicker})`;
  ctx.beginPath(); ctx.arc(x + w / 2, y - flameH * 0.3, 6, 0, Math.PI*2); ctx.fill();
  ctx.shadowBlur = 0;
  // Sparks som flyger upp
  const sparkSeed = Math.floor(t / 100) + (seed & 0xff);
  for (let i = 0; i < 5; i++) {
    const sphase = (t / 700 + i * 0.2) % 1;
    const sx = x + w / 2 + Math.sin((sparkSeed + i) * 13) * 12;
    const sy = y - sphase * 45;
    ctx.fillStyle = `rgba(255, ${150 + i * 25}, 50, ${1 - sphase})`;
    ctx.beginPath(); ctx.arc(sx, sy, 1 + (1 - sphase) * 0.6, 0, Math.PI*2); ctx.fill();
  }
  // Smoke ovanför flammorna
  ctx.fillStyle = `rgba(40, 35, 30, ${0.25 + Math.sin(t / 250) * 0.05})`;
  ctx.beginPath(); ctx.arc(x + w / 2 - 4 + Math.sin(t / 200) * 3, y - flameH - 4, 6, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + w / 2 + 5 + Math.cos(t / 180) * 2, y - flameH - 8, 4, 0, Math.PI*2); ctx.fill();
  // Yellow warning-stripe (klassisk dumpster-varning)
  ctx.fillStyle = '#ffd54a';
  ctx.fillRect(x, y + h - 8, w, 3);
  // Svart-gul varnings-pattern
  ctx.fillStyle = '#1a1a1a';
  for (let i = 0; i < w / 8; i++) {
    if (i % 2 === 0) ctx.fillRect(x + i * 8, y + h - 8, 4, 3);
  }
  // Yttre outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawStairwellDoor(x, y, w, h) {
  // Trapphusdörr — stålram + dörr + EXIT-skylt + glaspartier
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Ram (mörk metall)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x, y, w, h);
  // Dörr-bas (stål-grå)
  ctx.fillStyle = '#3a3a3a';
  ctx.fillRect(x + 2, y + 2, w - 4, h - 4);
  // Dörr-gradient (lite 3D)
  const grad = ctx.createLinearGradient(x, 0, x + w, 0);
  grad.addColorStop(0, '#4a4a4a');
  grad.addColorStop(0.5, '#5a5a5a');
  grad.addColorStop(1, '#3a3a3a');
  ctx.fillStyle = grad;
  ctx.fillRect(x + 3, y + 3, w - 6, h - 6);
  // Glasruta (top-half — säkerhetsglas med wire-mesh)
  ctx.fillStyle = '#1a2a3a';
  ctx.fillRect(x + 6, y + 5, w - 12, h * 0.35);
  // Wire-mesh (kryss-mönster)
  ctx.strokeStyle = '#3a3a3a';
  ctx.lineWidth = 0.4;
  const meshSz = 4;
  for (let mx = x + 6; mx < x + w - 6; mx += meshSz) {
    ctx.beginPath();
    ctx.moveTo(mx, y + 5); ctx.lineTo(mx, y + 5 + h * 0.35);
    ctx.stroke();
  }
  for (let my = y + 5; my < y + 5 + h * 0.35; my += meshSz) {
    ctx.beginPath();
    ctx.moveTo(x + 6, my); ctx.lineTo(x + w - 6, my);
    ctx.stroke();
  }
  // Reflektion på glaset
  ctx.fillStyle = 'rgba(180, 200, 220, 0.18)';
  ctx.fillRect(x + 7, y + 6, w - 14, 3);
  // Dörrhandtag (horisontellt push-bar)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x + 4, y + h * 0.55, w - 8, 2);
  ctx.fillStyle = '#7a7a7a';
  ctx.fillRect(x + 4, y + h * 0.55, w - 8, 0.6);
  // Handtag-stöd (2 små brackets)
  ctx.fillStyle = '#5a5a5a';
  ctx.fillRect(x + 6, y + h * 0.54, 2, 4);
  ctx.fillRect(x + w - 8, y + h * 0.54, 2, 4);
  // EXIT-skylt ovanför dörren (grön LED-emaljerad skylt)
  ctx.fillStyle = '#0a2a0a';
  ctx.fillRect(x + 4, y + 4, w - 8, 6);
  ctx.fillStyle = '#3aff5a';
  ctx.shadowColor = '#3aff5a'; ctx.shadowBlur = 4;
  ctx.font = 'bold 8px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('EXIT', x + w / 2, y + 7);
  ctx.shadowBlur = 0;
  // Trapp-symbol nedanför handtag
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold 14px sans-serif';
  ctx.fillText('⤓', x + w / 2, y + h * 0.78);
  // Hinges (gångjärn — 2 mörka cirklar på vänster sida)
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath(); ctx.arc(x + 4, y + 8, 1.2, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + 4, y + h - 8, 1.2, 0, Math.PI*2); ctx.fill();
  // Yttre outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

function drawPayMachine(x, y, w, h) {
  // Parkerings-automat — vertikal stolpe med touchscreen + slot
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Pole-bas (stål-grå)
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(x, y, w, h);
  // Top-housing (rundare)
  ctx.fillStyle = '#3a3a3a';
  ctx.fillRect(x, y, w, h * 0.65);
  // Highlight (top edge)
  ctx.fillStyle = '#5a5a5a';
  ctx.fillRect(x, y, w, 1.5);
  ctx.fillStyle = '#5a5a5a';
  ctx.fillRect(x, y, 1.5, h * 0.65);
  // Touchscreen (mörk cyan)
  ctx.fillStyle = '#0a1a2a';
  ctx.fillRect(x + 3, y + 4, w - 6, h * 0.35);
  // Screen content (vit text + cyan UI)
  ctx.fillStyle = '#3acaff';
  ctx.font = 'bold 5px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('P', x + w / 2, y + 9);
  ctx.fillStyle = '#fff';
  ctx.font = '4px monospace';
  ctx.fillText('20:00', x + w / 2, y + 14);
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold 5px monospace';
  ctx.fillText('50kr', x + w / 2, y + 19);
  // Screen-frame
  ctx.strokeStyle = '#1a2a3a';
  ctx.lineWidth = 0.5;
  ctx.strokeRect(x + 3, y + 4, w - 6, h * 0.35);
  // Card-slot (horisontell)
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(x + 4, y + h * 0.45, w - 8, 1.5);
  // Slot-label
  ctx.fillStyle = '#ffd54a';
  ctx.font = '3px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('CARD', x + w / 2, y + h * 0.5);
  // Coin-slot (rund)
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath(); ctx.arc(x + w / 2, y + h * 0.6, 1.5, 0, Math.PI*2); ctx.fill();
  // Receipt-slot (vid botten)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x + 3, y + h * 0.75, w - 6, 1);
  // Pole-bas (smal stolpe)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x + w * 0.3, y + h * 0.85, w * 0.4, h * 0.15);
  // "PAY HERE"-text på top-housing
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold 4px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('PAY HERE', x + w / 2, y + 3);
  // Yttre outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// SHIPPING CONTAINER — 40-fot frakt-container med ribbor, lås, color-coded.
// Färg-paletten styrs av color-property: orange/blue/rust/green/yellow/red/gold.
function drawShippingContainer(x, y, w, h, colorKey, seed) {
  const palette = {
    orange: { main: '#c47a30', dark: '#7a4a18', high: '#e0954a', stroke: '#3a1a08' },
    blue:   { main: '#2a5a8a', dark: '#15304a', high: '#4080b0', stroke: '#0a1828' },
    rust:   { main: '#7a4a30', dark: '#3a2418', high: '#9a6045', stroke: '#1a0e08' },
    green:  { main: '#3a6a3a', dark: '#1a3a1a', high: '#5a8a5a', stroke: '#0a1a0a' },
    yellow: { main: '#aa8a20', dark: '#5a4a10', high: '#d4aa30', stroke: '#2a2a08' },
    red:    { main: '#8a2a2a', dark: '#5a1010', high: '#b04545', stroke: '#2a0808' },
    gold:   { main: '#aa8030', dark: '#5a4010', high: '#d4a040', stroke: '#3a2008' },
  };
  const p = palette[colorKey] || palette.orange;
  const isHorizontal = w > h;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.96, w * 0.5, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  const grad = isHorizontal
    ? ctx.createLinearGradient(x, y, x, y + h)
    : ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, p.high);
  grad.addColorStop(0.4, p.main);
  grad.addColorStop(1, p.dark);
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Ribbor (korrugerade plattor) — viktigt för "container"-look
  ctx.strokeStyle = p.stroke;
  ctx.lineWidth = 1;
  if (isHorizontal) {
    for (let i = 12; i < w; i += 12) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + 3);
      ctx.lineTo(x + i, y + h - 3);
      ctx.stroke();
    }
    // Top + bottom edge — mörkare bands
    ctx.fillStyle = p.dark;
    ctx.fillRect(x, y, w, 4);
    ctx.fillRect(x, y + h - 4, w, 4);
  } else {
    for (let i = 12; i < h; i += 12) {
      ctx.beginPath();
      ctx.moveTo(x + 3, y + i);
      ctx.lineTo(x + w - 3, y + i);
      ctx.stroke();
    }
    ctx.fillStyle = p.dark;
    ctx.fillRect(x, y, 4, h);
    ctx.fillRect(x + w - 4, y, 4, h);
  }
  // Yttre kant (mörk ram)
  ctx.strokeStyle = p.stroke;
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Dörrar i ena änden (vertikala streck + lås)
  const doorSide = isHorizontal ? 'right' : 'bottom';
  if (doorSide === 'right' && w > 60) {
    const dx = x + w - 12;
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(dx, y + 4); ctx.lineTo(dx, y + h - 4); ctx.stroke();
    // Lås (3 små svarta cirklar)
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath(); ctx.arc(dx + 4, y + h * 0.3, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(dx + 4, y + h * 0.5, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(dx + 4, y + h * 0.7, 2, 0, Math.PI * 2); ctx.fill();
  } else if (doorSide === 'bottom' && h > 60) {
    const dy = y + h - 12;
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(x + 4, dy); ctx.lineTo(x + w - 4, dy); ctx.stroke();
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath(); ctx.arc(x + w * 0.3, dy + 4, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(x + w * 0.5, dy + 4, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(x + w * 0.7, dy + 4, 2, 0, Math.PI * 2); ctx.fill();
  }
  // Container-text "HAULSEA 4282-XX" eller stencilerat nummer (seed-baserat)
  const hashSeed = (seed | 0) & 0xfff;
  const codeA = String.fromCharCode(65 + (hashSeed & 0x1f) % 26);
  const codeB = String.fromCharCode(65 + ((hashSeed >> 4) & 0x1f) % 26);
  const codeN = (hashSeed * 7) % 9999;
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.font = 'bold 9px monospace';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  if (isHorizontal && w > 80) {
    ctx.fillText(codeA + codeB + '-' + String(codeN).padStart(4, '0'), x + 8, y + 6);
  } else if (h > 80) {
    ctx.save();
    ctx.translate(x + 6, y + 10);
    ctx.rotate(Math.PI / 2);
    ctx.fillText(codeA + codeB + '-' + String(codeN).padStart(4, '0'), 0, 0);
    ctx.restore();
  }
  // Rost-fläckar (seed-baserat)
  ctx.fillStyle = 'rgba(60, 30, 10, 0.45)';
  for (let i = 0; i < 4; i++) {
    const rx = x + 5 + ((hashSeed * (i + 1) * 13) & 0xff) % Math.max(1, w - 12);
    const ry = y + 5 + ((hashSeed * (i + 3) * 17) & 0xff) % Math.max(1, h - 12);
    ctx.beginPath();
    ctx.arc(rx, ry, 2 + (i % 2), 0, Math.PI * 2);
    ctx.fill();
  }
  // Color-key glow (gold-container ska sticka ut) — PERF: ingen shadowBlur,
  // använd 2-pass-stroke istället (yttre tjock semi-trans, inre tunn solid).
  if (colorKey === 'gold') {
    ctx.strokeStyle = 'rgba(255, 213, 74, 0.35)';
    ctx.lineWidth = 4;
    ctx.strokeRect(x - 1, y - 1, w + 2, h + 2);
    ctx.strokeStyle = '#ffd54a';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  }
}

// SILO — cylindrisk industri-silo (sett uppifrån = cirkel med stripes + topp-kupol)
function drawSilo(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, r * 0.95, r * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-cylindern (radial-gradient så det ser ut som 3D-rör)
  const grad = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, r * 0.1, cx, cy, r);
  grad.addColorStop(0, '#b0a890');
  grad.addColorStop(0.6, '#8a8270');
  grad.addColorStop(1, '#4a4438');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Vertikala panel-skarvar (cylindrisk look)
  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
  ctx.lineWidth = 1;
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 4) {
    const x1 = cx + Math.cos(a) * r * 0.85;
    const y1 = cy + Math.sin(a) * r * 0.85;
    const x2 = cx + Math.cos(a) * r;
    const y2 = cy + Math.sin(a) * r;
    ctx.beginPath();
    ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.stroke();
  }
  // Stencilerat namn på sidan (seed-baserat)
  ctx.fillStyle = 'rgba(255, 213, 74, 0.55)';
  ctx.font = 'bold 10px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const labels = ['GRAIN', 'OIL', 'FUEL', 'CHEM', 'ASH', 'FEED'];
  const lbl = labels[(seed | 0) % labels.length];
  ctx.fillText(lbl, cx, cy);
  // Topp-kupol (HALV-cirkel ovanpå för 3D-känsla — på toppen av cirkeln)
  ctx.fillStyle = '#5a5450';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.4, Math.PI, 0);
  ctx.fill();
  // Topp-ventil (cirkel i toppen)
  ctx.fillStyle = '#3a3530';
  ctx.beginPath();
  ctx.arc(cx, cy - r * 0.2, r * 0.15, 0, Math.PI * 2);
  ctx.fill();
  // Vit warning-stripe (en horisontell ring runt mitten)
  ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
  ctx.fillRect(cx - r, cy + r * 0.2, r * 2, 2);
  // Rost-fläckar
  ctx.fillStyle = 'rgba(80, 40, 15, 0.6)';
  for (let i = 0; i < 3; i++) {
    const a = (seed * (i + 1)) * 0.7;
    const rr = r * (0.5 + ((seed * (i + 5)) & 0xff) / 512);
    const rx = cx + Math.cos(a) * rr;
    const ry = cy + Math.sin(a) * rr;
    ctx.beginPath();
    ctx.arc(rx, ry, 3, 0, Math.PI * 2);
    ctx.fill();
  }
  // Yttre mörk kant
  ctx.strokeStyle = '#2a2418';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.stroke();
}

// BUILDING — stort industrihus med tak-mönster, fönster, dörrar, antenn
function drawBuilding(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.97, w * 0.52, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  // Tak-färg (gradient: ljus → mörk för "uppifrån"-perspektiv)
  const grad = ctx.createLinearGradient(x, y, x + w, y + h);
  grad.addColorStop(0, '#6a605a');
  grad.addColorStop(0.5, '#4a4438');
  grad.addColorStop(1, '#2a2418');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Yttre kant (mörk)
  ctx.strokeStyle = '#1a1408';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
  // Tak-paneler (rutmönster — concrete-tiles uppifrån)
  const tileSize = 40;
  ctx.strokeStyle = 'rgba(20, 18, 12, 0.55)';
  ctx.lineWidth = 1;
  for (let i = tileSize; i < w; i += tileSize) {
    ctx.beginPath();
    ctx.moveTo(x + i, y + 3); ctx.lineTo(x + i, y + h - 3);
    ctx.stroke();
  }
  for (let j = tileSize; j < h; j += tileSize) {
    ctx.beginPath();
    ctx.moveTo(x + 3, y + j); ctx.lineTo(x + w - 3, y + j);
    ctx.stroke();
  }
  // Vent/AC-units på taket (4 små rektanglar)
  const hashSeed = (seed | 0) & 0xfff;
  for (let i = 0; i < 4; i++) {
    const ux = x + 15 + ((hashSeed * (i + 1) * 23) & 0xff) % Math.max(1, w - 50);
    const uy = y + 15 + ((hashSeed * (i + 3) * 17) & 0xff) % Math.max(1, h - 50);
    ctx.fillStyle = '#9a9080';
    ctx.fillRect(ux, uy, 20, 14);
    ctx.fillStyle = '#3a3328';
    ctx.fillRect(ux + 2, uy + 2, 16, 10);
    // Grid i mitten
    ctx.fillStyle = '#5a5040';
    ctx.fillRect(ux + 4, uy + 4, 12, 2);
    ctx.fillRect(ux + 4, uy + 8, 12, 2);
    ctx.strokeStyle = '#1a1408';
    ctx.lineWidth = 0.5;
    ctx.strokeRect(ux + 0.5, uy + 0.5, 19, 13);
  }
  // Vent-rör i hörnet (cirkel)
  ctx.fillStyle = '#5a5040';
  ctx.beginPath();
  ctx.arc(x + 18, y + 18, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#1a1408';
  ctx.beginPath();
  ctx.arc(x + 18, y + 18, 3, 0, Math.PI * 2);
  ctx.fill();
  // Skylight (glas-ruta i mitten av takets nedre del)
  if (w > 120 && h > 120) {
    const slX = x + w / 2 - 25, slY = y + h / 2 - 15;
    ctx.fillStyle = '#2a3a4a';
    ctx.fillRect(slX, slY, 50, 30);
    // Glas-mönster
    ctx.strokeStyle = '#4a6080';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(slX + 25, slY); ctx.lineTo(slX + 25, slY + 30);
    ctx.moveTo(slX, slY + 15); ctx.lineTo(slX + 50, slY + 15);
    ctx.stroke();
    // Reflektion
    ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.fillRect(slX + 2, slY + 2, 16, 10);
    ctx.strokeStyle = '#1a1408';
    ctx.lineWidth = 1;
    ctx.strokeRect(slX + 0.5, slY + 0.5, 49, 29);
  }
  // Antenn (cross-shape om byggnaden är stor)
  if (w > 180 || h > 180) {
    const ax = x + w * 0.8;
    const ay = y + h * 0.2;
    ctx.strokeStyle = '#1a1408';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(ax, ay - 8); ctx.lineTo(ax, ay + 8);
    ctx.moveTo(ax - 6, ay - 4); ctx.lineTo(ax + 6, ay - 4);
    ctx.moveTo(ax - 4, ay); ctx.lineTo(ax + 4, ay);
    ctx.stroke();
    // Röd LED-topp (PERF: dubbel-arc istället för shadowBlur)
    ctx.fillStyle = 'rgba(255, 48, 48, 0.45)';
    ctx.beginPath();
    ctx.arc(ax, ay - 8, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ff3030';
    ctx.beginPath();
    ctx.arc(ax, ay - 8, 1.8, 0, Math.PI * 2);
    ctx.fill();
  }
  // Roof number (för identifiering)
  if (w > 100 && h > 100) {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.font = 'bold 18px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const num = (((seed | 0) * 13) & 0xff) % 99;
    ctx.fillText('#' + String(num).padStart(2, '0'), x + w / 2, y + h - 20);
  }
}

// ============================================================
// BATTLE ROYALE SKOG-KARTA — wall-renderers
// ============================================================

// TRÄD-EK — brun stam (centerd dot) + grön krona uppifrån
function drawTreeOak(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Liten kompakt skugga DIREKT under (inte offset åt sidan)
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  ctx.beginPath();
  ctx.ellipse(cx + 2, cy + 2, r * 0.95, r * 0.85, 0, 0, Math.PI * 2);
  ctx.fill();
  // Yttre krona (mörkare grön ring)
  ctx.fillStyle = '#1a3a1a';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Inre krona (ljusare grön) — radial-gradient för 3D-känsla
  const grad = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, r * 0.1, cx, cy, r);
  grad.addColorStop(0, '#5aaa3a');
  grad.addColorStop(0.5, '#3a7a2a');
  grad.addColorStop(1, '#1a3a18');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.92, 0, Math.PI * 2);
  ctx.fill();
  // Lövkluster-noise (små mörka prickar)
  ctx.fillStyle = 'rgba(20, 50, 20, 0.55)';
  for (let i = 0; i < 6; i++) {
    const ang = (seed * (i + 1)) % (Math.PI * 2);
    const dist = r * 0.4 + ((seed * (i + 3)) & 0xff) / 800 * r * 0.3;
    const px = cx + Math.cos(ang) * dist;
    const py = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.arc(px, py, 2.5 + (i % 2), 0, Math.PI * 2);
    ctx.fill();
  }
  // Ljus-highlight ovanifrån
  ctx.fillStyle = 'rgba(150, 220, 100, 0.25)';
  ctx.beginPath();
  ctx.arc(cx - r * 0.25, cy - r * 0.25, r * 0.35, 0, Math.PI * 2);
  ctx.fill();
  // Brun stam i mitten (synlig som mörk centrum-dot)
  ctx.fillStyle = '#3a2818';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.15, 0, Math.PI * 2);
  ctx.fill();
  // Stam highlight
  ctx.fillStyle = '#5a3a20';
  ctx.beginPath();
  ctx.arc(cx - 1, cy - 1, r * 0.08, 0, Math.PI * 2);
  ctx.fill();
}

// TRÄD-TALL — triangulär krona, mörkare grön
function drawTreePine(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Liten kompakt skugga
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  ctx.beginPath();
  ctx.ellipse(cx + 2, cy + 2, r * 0.85, r * 0.8, 0, 0, Math.PI * 2);
  ctx.fill();
  // Yttre triangulär krona (3 lager för "barrträd"-look)
  ctx.fillStyle = '#1a3a1a';
  ctx.beginPath();
  ctx.moveTo(cx, cy - r);
  ctx.lineTo(cx + r, cy + r * 0.8);
  ctx.lineTo(cx - r, cy + r * 0.8);
  ctx.closePath();
  ctx.fill();
  // Mid-layer
  ctx.fillStyle = '#2a5a2a';
  ctx.beginPath();
  ctx.moveTo(cx, cy - r * 0.7);
  ctx.lineTo(cx + r * 0.85, cy + r * 0.6);
  ctx.lineTo(cx - r * 0.85, cy + r * 0.6);
  ctx.closePath();
  ctx.fill();
  // Top-layer (ljusast)
  ctx.fillStyle = '#3a7a3a';
  ctx.beginPath();
  ctx.moveTo(cx, cy - r * 0.5);
  ctx.lineTo(cx + r * 0.6, cy + r * 0.3);
  ctx.lineTo(cx - r * 0.6, cy + r * 0.3);
  ctx.closePath();
  ctx.fill();
  // Barr-noise (små streck)
  ctx.strokeStyle = 'rgba(20, 50, 20, 0.45)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 8; i++) {
    const ang = ((seed * (i + 1) * 17) & 0xff) / 255 * Math.PI * 2;
    const dist = r * 0.4 + ((seed * (i + 3)) & 0xff) / 800 * r * 0.3;
    const px = cx + Math.cos(ang) * dist;
    const py = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(px + Math.cos(ang) * 4, py + Math.sin(ang) * 4);
    ctx.stroke();
  }
  // Brun stam-dot
  ctx.fillStyle = '#2a1808';
  ctx.beginPath();
  ctx.arc(cx, cy + r * 0.6, r * 0.12, 0, Math.PI * 2);
  ctx.fill();
}

// TRÄDSTUBBE — bruna ringar uppifrån (årsringar)
function drawTreeStump(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.beginPath();
  ctx.arc(cx + 2, cy + 3, r, 0, Math.PI * 2);
  ctx.fill();
  // Bas (mörk-brun ring)
  ctx.fillStyle = '#2a1808';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Topp (ljus-brun)
  ctx.fillStyle = '#7a5a30';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.9, 0, Math.PI * 2);
  ctx.fill();
  // Årsringar
  ctx.strokeStyle = '#5a3a20';
  ctx.lineWidth = 0.8;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.9 * (i / 4), 0, Math.PI * 2);
    ctx.stroke();
  }
  // Center-dot
  ctx.fillStyle = '#3a2008';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.1, 0, Math.PI * 2);
  ctx.fill();
}

// STEN — organisk grå form med highlights
function drawRock(x, y, w, h, seed, isLarge) {
  const cx = x + w / 2, cy = y + h / 2;
  // Kompakt skugga
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath();
  ctx.ellipse(cx + 2, cy + 2, w * 0.5, h * 0.45, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-form (organisk — 6-sided polygon)
  ctx.fillStyle = isLarge ? '#5a5a5a' : '#6a6a6a';
  ctx.beginPath();
  const points = 6;
  for (let i = 0; i < points; i++) {
    const ang = (i / points) * Math.PI * 2;
    const noise = 0.85 + ((seed * (i + 1)) & 0xff) / 800 * 0.3;
    const px = cx + Math.cos(ang) * (w / 2) * noise;
    const py = cy + Math.sin(ang) * (h / 2) * noise;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
  // Top highlight (radial-gradient för 3D)
  const grad = ctx.createRadialGradient(cx - w * 0.2, cy - h * 0.2, 2, cx, cy, w * 0.5);
  grad.addColorStop(0, 'rgba(180, 180, 180, 0.5)');
  grad.addColorStop(0.6, 'rgba(120, 120, 120, 0.15)');
  grad.addColorStop(1, 'rgba(80, 80, 80, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.ellipse(cx, cy, w * 0.45, h * 0.42, 0, 0, Math.PI * 2);
  ctx.fill();
  // Sprickor (mörka linjer)
  ctx.strokeStyle = 'rgba(20, 20, 20, 0.6)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - w * 0.2, cy - h * 0.1);
  ctx.lineTo(cx + w * 0.1, cy + h * 0.15);
  ctx.stroke();
  if (isLarge) {
    ctx.beginPath();
    ctx.moveTo(cx + w * 0.15, cy - h * 0.2);
    ctx.lineTo(cx - w * 0.05, cy);
    ctx.stroke();
  }
  // Mossa-fläckar (gröna prickar)
  ctx.fillStyle = 'rgba(60, 100, 40, 0.55)';
  for (let i = 0; i < (isLarge ? 4 : 2); i++) {
    const ang = (seed * (i + 1)) * 0.5;
    const dist = (w * 0.3) + ((seed * i) & 0xff) / 1024 * w * 0.2;
    const mx = cx + Math.cos(ang) * dist;
    const my = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.arc(mx, my, 3 + (i % 2), 0, Math.PI * 2);
    ctx.fill();
  }
}

// MOUNTAIN PEAK — klippspets ovanpå bergsmassivet (för silhuettering)
// Triangulär/oregelbunden topp med snö-spets, mörka skuggor, ger berget en
// faktisk profil sett uppifrån (inte bara en plan rektangulär klippvägg).
function drawMountainPeak(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.beginPath();
  ctx.ellipse(cx + 3, y + h * 0.95, w * 0.55, h * 0.2, 0, 0, Math.PI * 2);
  ctx.fill();
  // Peak-form (5-7 punkter polygon med VARIATION, ser oregelbunden ut)
  const points = 7;
  ctx.beginPath();
  for (let i = 0; i < points; i++) {
    const ang = (i / points) * Math.PI * 2 - Math.PI / 2; // start uppåt
    const noise = 0.75 + ((seed * (i + 1) * 7) & 0xff) / 800 * 0.35;
    // Översta punkten extra skarp (peak)
    const sharpness = (i === 0) ? 1.05 : noise;
    const px = cx + Math.cos(ang) * (w / 2) * sharpness;
    const py = cy + Math.sin(ang) * (h / 2) * sharpness;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  // Bas-fyllning (mörk stengrå)
  const baseGrad = ctx.createLinearGradient(x, y, x, y + h);
  baseGrad.addColorStop(0, '#7a7670');
  baseGrad.addColorStop(0.4, '#5a564e');
  baseGrad.addColorStop(0.8, '#3a3630');
  baseGrad.addColorStop(1, '#1e1a14');
  ctx.fillStyle = baseGrad;
  ctx.fill();
  // SNÖ-CAP på toppen (varför inte — gör berget mer mountain-like)
  ctx.save();
  ctx.clip(); // fortsätter använda peak-polygon som clip
  ctx.fillStyle = 'rgba(240, 245, 250, 0.85)';
  ctx.beginPath();
  ctx.moveTo(cx, y - 2);
  ctx.lineTo(cx + w * 0.35, y + h * 0.25);
  ctx.lineTo(cx + w * 0.18, y + h * 0.18);
  ctx.lineTo(cx, y + h * 0.30);
  ctx.lineTo(cx - w * 0.20, y + h * 0.18);
  ctx.lineTo(cx - w * 0.35, y + h * 0.25);
  ctx.closePath();
  ctx.fill();
  // Snö-skugga (svag blå-grå)
  ctx.fillStyle = 'rgba(160, 170, 185, 0.4)';
  ctx.beginPath();
  ctx.moveTo(cx - w * 0.05, y + h * 0.08);
  ctx.lineTo(cx + w * 0.30, y + h * 0.26);
  ctx.lineTo(cx + w * 0.10, y + h * 0.22);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
  // Stenfasetter (mörka sprickor från topp ner längs sidor)
  ctx.strokeStyle = 'rgba(15, 12, 10, 0.65)';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 3; i++) {
    const sx = cx + Math.cos((i - 1) * 0.6 + Math.PI / 2) * w * 0.15;
    const sy = y + h * 0.20;
    const ex = cx + Math.cos((i - 1) * 0.7) * w * 0.40;
    const ey = y + h * 0.85;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo(cx + ((seed * (i + 3)) & 0xff) / 4 - 16, (sy + ey) / 2, ex, ey);
    ctx.stroke();
  }
  // Yttre outline (mörk silhuett)
  ctx.strokeStyle = 'rgba(8, 6, 4, 0.85)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  for (let i = 0; i < points; i++) {
    const ang = (i / points) * Math.PI * 2 - Math.PI / 2;
    const noise = 0.75 + ((seed * (i + 1) * 7) & 0xff) / 800 * 0.35;
    const sharpness = (i === 0) ? 1.05 : noise;
    const px = cx + Math.cos(ang) * (w / 2) * sharpness;
    const py = cy + Math.sin(ang) * (h / 2) * sharpness;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();
}

// STUGA-VÄGG TRÄ — planschstruktur med nitar
function drawCabinWallWood(x, y, w, h, seed) {
  // (Ingen skugga — cabin walls är "marken-höjd")
  // Bas-färg (mörk-brun trä)
  const grad = w > h
    ? ctx.createLinearGradient(0, y, 0, y + h)
    : ctx.createLinearGradient(x, 0, x + w, 0);
  grad.addColorStop(0, '#7a5028');
  grad.addColorStop(0.5, '#5a3818');
  grad.addColorStop(1, '#3a2008');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Planka-skarvar (horisontella om bred, vertikala om hög)
  ctx.strokeStyle = 'rgba(20, 14, 4, 0.7)';
  ctx.lineWidth = 1;
  if (w > h) {
    // Horisontell vägg — vertikala plankor (var 30px)
    for (let i = 30; i < w; i += 30) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + 2); ctx.lineTo(x + i, y + h - 2);
      ctx.stroke();
    }
  } else {
    // Vertikal vägg — horisontella plankor
    for (let i = 30; i < h; i += 30) {
      ctx.beginPath();
      ctx.moveTo(x + 2, y + i); ctx.lineTo(x + w - 2, y + i);
      ctx.stroke();
    }
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0a04';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Knotar (stop-dots i trä)
  ctx.fillStyle = '#2a1808';
  for (let i = 0; i < 3; i++) {
    const kx = x + 5 + ((seed * (i + 1) * 13) & 0xff) % Math.max(1, w - 10);
    const ky = y + 4 + ((seed * (i + 3) * 17) & 0xff) % Math.max(1, h - 8);
    ctx.beginPath();
    ctx.arc(kx, ky, 1.5, 0, Math.PI * 2);
    ctx.fill();
  }
}

// BRINNANDE BIL — bil-shape med eld i mitten
function drawBurningCar(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.52, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Förbrunnen kaross (mörk grå)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#3a3028');
  grad.addColorStop(0.5, '#1a1408');
  grad.addColorStop(1, '#2a1810');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Yttre kant + sotigt
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Fönsterruta (tom — krossad)
  ctx.fillStyle = '#000';
  ctx.fillRect(x + w * 0.15, y + h * 0.15, w * 0.7, h * 0.3);
  // Brinnande motor (orange + röd)
  const t = performance.now() / 1000;
  const flicker = 0.7 + Math.sin(t * 8) * 0.3;
  ctx.fillStyle = 'rgba(255, 80, 20, ' + (0.6 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy - h * 0.1, w * 0.15, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 220, 60, ' + (0.85 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy - h * 0.1, w * 0.08, 0, Math.PI * 2);
  ctx.fill();
  // 4 hjul-svartning
  ctx.fillStyle = '#000';
  ctx.fillRect(x + 2, y + 4, w * 0.12, h * 0.18);
  ctx.fillRect(x + w * 0.86, y + 4, w * 0.12, h * 0.18);
  ctx.fillRect(x + 2, y + h - h * 0.22, w * 0.12, h * 0.18);
  ctx.fillRect(x + w * 0.86, y + h - h * 0.22, w * 0.12, h * 0.18);
  // Rust-streck
  ctx.fillStyle = 'rgba(90, 40, 15, 0.6)';
  for (let i = 0; i < 4; i++) {
    const rx = x + 5 + ((seed * (i + 1) * 13) & 0xff) % (w - 10);
    const ry = y + 5 + ((seed * (i + 3) * 17) & 0xff) % (h - 10);
    ctx.fillRect(rx, ry, 4, 2);
  }
}

// BRINNANDE LASTBIL — större version med släp
function drawBurningTruck(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.52, h * 0.15, 0, 0, Math.PI * 2);
  ctx.fill();
  // Hytt (vänster 30%)
  const cabW = w * 0.3;
  ctx.fillStyle = '#2a1810';
  ctx.fillRect(x, y, cabW, h);
  // Lastutrymme (höger 70%) — open-top, exposed
  ctx.fillStyle = '#1a1408';
  ctx.fillRect(x + cabW, y, w - cabW, h);
  // Yttre kant
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.8;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.beginPath();
  ctx.moveTo(x + cabW, y);
  ctx.lineTo(x + cabW, y + h);
  ctx.stroke();
  // Brinnande lastutrymme + hytt
  const t = performance.now() / 1000;
  const flicker = 0.6 + Math.sin(t * 9) * 0.4;
  ctx.fillStyle = 'rgba(255, 90, 30, ' + (0.55 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(x + cabW + (w - cabW) / 2, y + h / 2, h * 0.35, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 220, 80, ' + (0.9 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(x + cabW + (w - cabW) / 2, y + h / 2, h * 0.2, 0, Math.PI * 2);
  ctx.fill();
  // Mindre eld vid hytt
  ctx.fillStyle = 'rgba(255, 120, 40, ' + (0.6 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(x + cabW / 2, y + h * 0.3, 6, 0, Math.PI * 2);
  ctx.fill();
  // Hjul (6 st för lastbil)
  ctx.fillStyle = '#000';
  ctx.fillRect(x + 4, y + 2, cabW * 0.3, h * 0.15);
  ctx.fillRect(x + 4, y + h - h * 0.17, cabW * 0.3, h * 0.15);
  for (let i = 0; i < 4; i++) {
    const hx = x + cabW + 10 + i * ((w - cabW - 20) / 4);
    ctx.fillRect(hx, y + 2, 12, h * 0.13);
    ctx.fillRect(hx, y + h - h * 0.15, 12, h * 0.13);
  }
}

// BRINNANDE HUSVAGN — boxig, mörk, eld
function drawBurningCaravan(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.94, w * 0.5, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Kaross (vit-grå, sotat)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#5a4a40');
  grad.addColorStop(0.5, '#3a2a20');
  grad.addColorStop(1, '#1a1208');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Yttre kant
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // 2 stora fönster (krossade)
  ctx.fillStyle = '#000';
  ctx.fillRect(x + w * 0.15, y + h * 0.2, w * 0.3, h * 0.4);
  ctx.fillRect(x + w * 0.55, y + h * 0.2, w * 0.3, h * 0.4);
  // Dörr
  ctx.fillStyle = '#1a0e08';
  ctx.fillRect(x + w * 0.05, y + h * 0.65, w * 0.1, h * 0.3);
  // Brinnande tak
  const t = performance.now() / 1000;
  const flicker = 0.7 + Math.sin(t * 7) * 0.3;
  ctx.fillStyle = 'rgba(255, 100, 30, ' + (0.5 * flicker) + ')';
  ctx.fillRect(x + w * 0.1, y + h * 0.05, w * 0.8, h * 0.1);
  ctx.fillStyle = 'rgba(255, 200, 60, ' + (0.85 * flicker) + ')';
  ctx.fillRect(x + w * 0.2, y + h * 0.08, w * 0.6, h * 0.05);
  // Sot-streck nerifrån fönstren
  ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
  ctx.fillRect(x + w * 0.15, y + h * 0.6, w * 0.3, 6);
  ctx.fillRect(x + w * 0.55, y + h * 0.6, w * 0.3, 6);
  // Hjul
  ctx.fillStyle = '#000';
  ctx.fillRect(x + w * 0.1, y + h * 0.9, w * 0.15, h * 0.1);
  ctx.fillRect(x + w * 0.75, y + h * 0.9, w * 0.15, h * 0.1);
}

// GRÄVMASKIN-VRAK — gul/orange industri-fordon
function drawExcavatorWreck(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.34)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.52, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-larvband (svart)
  ctx.fillStyle = '#1a1408';
  ctx.fillRect(x, y + h * 0.7, w, h * 0.3);
  // Hytt (gul, sotat)
  ctx.fillStyle = '#7a6020';
  ctx.fillRect(x + w * 0.15, y + h * 0.15, w * 0.5, h * 0.55);
  // Hytt-fönster (krossad)
  ctx.fillStyle = '#000';
  ctx.fillRect(x + w * 0.2, y + h * 0.22, w * 0.4, h * 0.25);
  // Arm + skopa (utsträckt)
  ctx.fillStyle = '#5a4818';
  ctx.fillRect(x + w * 0.5, y + h * 0.3, w * 0.45, h * 0.15);
  ctx.fillStyle = '#2a2008';
  ctx.fillRect(x + w * 0.85, y + h * 0.3, w * 0.12, h * 0.4); // skopa
  // Eld från motor
  const t = performance.now() / 1000;
  const flicker = 0.7 + Math.sin(t * 8) * 0.3;
  ctx.fillStyle = 'rgba(255, 100, 30, ' + (0.5 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(x + w * 0.4, y + h * 0.4, 8, 0, Math.PI * 2);
  ctx.fill();
  // Yttre kant
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Rost
  ctx.fillStyle = 'rgba(90, 40, 15, 0.5)';
  for (let i = 0; i < 5; i++) {
    const rx = x + 5 + ((seed * (i + 1) * 13) & 0xff) % (w - 10);
    const ry = y + 5 + ((seed * (i + 3) * 17) & 0xff) % (h - 10);
    ctx.fillRect(rx, ry, 4, 2);
  }
}

// JAKTTORN — träplattform på pelare, uppifrån
function drawHuntingTower(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.5, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-platform (mörk-brun)
  ctx.fillStyle = '#3a2818';
  ctx.fillRect(x, y, w, h);
  // Trä-plankor (cross pattern)
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 1.2;
  for (let i = 12; i < w; i += 12) {
    ctx.beginPath();
    ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + h);
    ctx.stroke();
  }
  // 4 hörnpelare (uppifrån = mörka prickar)
  ctx.fillStyle = '#0a0408';
  ctx.beginPath(); ctx.arc(x + 6, y + 6, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + w - 6, y + 6, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + 6, y + h - 6, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + w - 6, y + h - 6, 4, 0, Math.PI * 2); ctx.fill();
  // Stege (vid framsida)
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x + w * 0.4, y + h - 4, w * 0.2, 8);
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 0.8;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(x + w * 0.4, y + h - 4 + i * 2);
    ctx.lineTo(x + w * 0.6, y + h - 4 + i * 2);
    ctx.stroke();
  }
  // Räcke (markeringssträck)
  ctx.strokeStyle = '#0a0408';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 3, y + 3, w - 6, h - 6);
  // Höglandare-emblem (litet hjort-skull)
  ctx.fillStyle = '#9a9080';
  ctx.font = 'bold 14px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('🦌', cx, cy);
}

// TÄLT — triangulär från ovan
function drawTent(x, y, w, h, color, seed) {
  const palette = {
    red:    { main: '#a02828', dark: '#5a1010', stripe: '#ddaa70' },
    blue:   { main: '#2a5080', dark: '#102040', stripe: '#a0c0e0' },
    green:  { main: '#2a6028', dark: '#103010', stripe: '#a0c080' },
    orange: { main: '#a06028', dark: '#5a2810', stripe: '#e0a050' },
  };
  const p = palette[color] || palette.red;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.5, h * 0.12, 0, 0, Math.PI * 2);
  ctx.fill();
  // Tält-form (triangel)
  ctx.fillStyle = p.main;
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y);
  ctx.lineTo(x + w, y + h);
  ctx.lineTo(x, y + h);
  ctx.closePath();
  ctx.fill();
  // Mörk sida (höger)
  ctx.fillStyle = p.dark;
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y);
  ctx.lineTo(x + w, y + h);
  ctx.lineTo(x + w / 2, y + h);
  ctx.closePath();
  ctx.fill();
  // Diagonala stripes (textil-textur)
  ctx.strokeStyle = p.stripe;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.4;
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.moveTo(x + (i * w / 6), y + h);
    ctx.lineTo(x + w / 2 - 2, y + 4);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  // Yttre kant
  ctx.strokeStyle = '#0a0408';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y);
  ctx.lineTo(x + w, y + h);
  ctx.lineTo(x, y + h);
  ctx.closePath();
  ctx.stroke();
  // Dörröppning (mörkt triangulär)
  ctx.fillStyle = '#0a0408';
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y + h * 0.4);
  ctx.lineTo(x + w * 0.65, y + h - 1);
  ctx.lineTo(x + w * 0.35, y + h - 1);
  ctx.closePath();
  ctx.fill();
  // Topp-spets
  ctx.fillStyle = p.stripe;
  ctx.beginPath();
  ctx.arc(x + w / 2, y, 2, 0, Math.PI * 2);
  ctx.fill();
}

// BRUNN — stenring uppifrån, vatten i mitten
function drawWell(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, r * 0.95, r * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();
  // Yttre stenring (mörkare)
  ctx.fillStyle = '#3a3028';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Stenar i ringen (separata polygoner)
  ctx.fillStyle = '#5a5048';
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2;
    const px = cx + Math.cos(ang) * (r * 0.85);
    const py = cy + Math.sin(ang) * (r * 0.85);
    ctx.beginPath();
    ctx.arc(px, py, r * 0.18, 0, Math.PI * 2);
    ctx.fill();
  }
  // Inre öppning (mörkt vatten)
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 0.6);
  grad.addColorStop(0, '#0a1828');
  grad.addColorStop(0.7, '#1a3848');
  grad.addColorStop(1, '#2a4858');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.6, 0, Math.PI * 2);
  ctx.fill();
  // Vatten-reflexion (vit highlight)
  ctx.fillStyle = 'rgba(200, 220, 255, 0.4)';
  ctx.beginPath();
  ctx.ellipse(cx - r * 0.15, cy - r * 0.15, r * 0.2, r * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Mossa runt kanten
  ctx.fillStyle = 'rgba(60, 100, 40, 0.5)';
  for (let i = 0; i < 4; i++) {
    const ang = (seed * (i + 1)) % (Math.PI * 2);
    const mx = cx + Math.cos(ang) * (r * 0.9);
    const my = cy + Math.sin(ang) * (r * 0.9);
    ctx.beginPath();
    ctx.arc(mx, my, 3, 0, Math.PI * 2);
    ctx.fill();
  }
  // Kant-stroke
  ctx.strokeStyle = '#1a1408';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.stroke();
}

// HÖSTACK — gul oval med strå
function drawHaystack(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.26)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.94, w * 0.5, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas (mörk gul-brun)
  const grad = ctx.createRadialGradient(cx, cy - h * 0.2, 5, cx, cy, w * 0.55);
  grad.addColorStop(0, '#e4c060');
  grad.addColorStop(0.5, '#c09040');
  grad.addColorStop(1, '#7a5818');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.ellipse(cx, cy, w * 0.5, h * 0.48, 0, 0, Math.PI * 2);
  ctx.fill();
  // Strå-texture (många små streck)
  ctx.strokeStyle = 'rgba(120, 80, 20, 0.7)';
  ctx.lineWidth = 0.6;
  for (let i = 0; i < 30; i++) {
    const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
    const dist = ((seed * (i + 3) * 17) & 0xff) / 255 * w * 0.4;
    const sx = cx + Math.cos(ang) * dist;
    const sy = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(sx + Math.cos(ang) * 5, sy + Math.sin(ang) * 5);
    ctx.stroke();
  }
  // Top highlight
  ctx.fillStyle = 'rgba(255, 230, 100, 0.4)';
  ctx.beginPath();
  ctx.ellipse(cx - w * 0.15, cy - h * 0.2, w * 0.2, h * 0.15, 0, 0, Math.PI * 2);
  ctx.fill();
  // Kant-stroke
  ctx.strokeStyle = '#5a3818';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(cx, cy, w * 0.5, h * 0.48, 0, 0, Math.PI * 2);
  ctx.stroke();
}

// VEDSTAPEL — staplade bruna stockar
function drawWoodpile(x, y, w, h, seed) {
  // (Ingen skugga — vedstapel ligger nära marken)
  // Bas (mörk-brun rektangel)
  ctx.fillStyle = '#3a2818';
  ctx.fillRect(x, y, w, h);
  // Yttre kant
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Staplade stockar (cirklar uppifrån)
  const logR = Math.min(h, 8) / 2;
  const logsPerRow = Math.floor(w / (logR * 2));
  const rows = Math.floor(h / (logR * 2));
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < logsPerRow; c++) {
      const lx = x + logR + c * logR * 2 + (r % 2 === 0 ? 0 : logR);
      const ly = y + logR + r * logR * 2;
      if (lx + logR > x + w || ly + logR > y + h) continue;
      // Outer dark ring
      ctx.fillStyle = '#5a3a18';
      ctx.beginPath();
      ctx.arc(lx, ly, logR, 0, Math.PI * 2);
      ctx.fill();
      // Inner light (årsringar)
      ctx.fillStyle = '#9a7038';
      ctx.beginPath();
      ctx.arc(lx, ly, logR * 0.8, 0, Math.PI * 2);
      ctx.fill();
      // Center
      ctx.fillStyle = '#5a3a18';
      ctx.beginPath();
      ctx.arc(lx, ly, logR * 0.3, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

// STENMUR — stora stenblock med fogar (low = lägre/kortare för "field-fence")
function drawStoneWall(x, y, w, h, isLow) {
  // (Ingen skugga — mur är "marken-höjd")
  // Bas (mossigt grå)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#7a7268');
  grad.addColorStop(0.5, '#5a5248');
  grad.addColorStop(1, '#3a3228');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // CLIP till wall-bounds så stenblock-strokes inte sticker ut
  ctx.save();
  ctx.beginPath();
  ctx.rect(x, y, w, h);
  ctx.clip();
  // Stenblock (organisk fogar) — anpassa storlek till wall-dimensioner
  ctx.strokeStyle = 'rgba(20, 15, 8, 0.7)';
  ctx.lineWidth = 1;
  // Skala stoneW/stoneH per wall så de aldrig är större än wall-bounds
  const stoneW = Math.min(isLow ? 22 : 35, Math.max(8, Math.floor(Math.max(w, h) / 3)));
  const stoneH = Math.min(isLow ? 14 : 20, Math.max(6, Math.floor(Math.min(w, h) / 1.5)));
  if (w > h) {
    // Horisontell mur — stenblock i rader
    for (let yy = 0; yy < h; yy += stoneH) {
      const offset = (yy / stoneH) % 2 === 0 ? 0 : stoneW / 2;
      for (let xx = offset; xx < w; xx += stoneW) {
        // Beräkna faktiska storlek (clip kontot om vi går utanför)
        const drawW = Math.min(stoneW, w - xx) - 1;
        const drawH = Math.min(stoneH, h - yy) - 1;
        if (drawW > 0 && drawH > 0) {
          ctx.strokeRect(x + xx + 0.5, y + yy + 0.5, drawW, drawH);
        }
      }
    }
  } else {
    // Vertikal mur
    for (let xx = 0; xx < w; xx += stoneH) {
      const offset = (xx / stoneH) % 2 === 0 ? 0 : stoneW / 2;
      for (let yy = offset; yy < h; yy += stoneW) {
        const drawW = Math.min(stoneH, w - xx) - 1;
        const drawH = Math.min(stoneW, h - yy) - 1;
        if (drawW > 0 && drawH > 0) {
          ctx.strokeRect(x + xx + 0.5, y + yy + 0.5, drawW, drawH);
        }
      }
    }
  }
  // Mossa-fläckar (clippad inom wall)
  ctx.fillStyle = 'rgba(50, 90, 40, 0.55)';
  const mossCount = Math.floor((w + h) / 40);
  for (let i = 0; i < mossCount; i++) {
    const mx = x + 3 + (i * 30) % Math.max(1, w - 6);
    const my = y + 2 + ((i * 17) % Math.max(1, h - 4));
    ctx.beginPath();
    ctx.ellipse(mx, my, 4, 2.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore(); // släpp clip
  // Yttre stroke
  ctx.strokeStyle = '#1a1408';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// TRÄSTAKET — bruna plankor
function drawWoodenFence(x, y, w, h) {
  // (Ingen skugga — staket är "marken-höjd")
  // Bas (brun)
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x, y, w, h);
  // Planka-streck
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 1;
  if (w > h) {
    for (let i = 8; i < w; i += 8) {
      ctx.beginPath();
      ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + h);
      ctx.stroke();
    }
  } else {
    for (let i = 8; i < h; i += 8) {
      ctx.beginPath();
      ctx.moveTo(x, y + i); ctx.lineTo(x + w, y + i);
      ctx.stroke();
    }
  }
  ctx.strokeStyle = '#0a0408';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// HÖNSBUR — liten träbur
function drawChickenCoop(x, y, w, h, seed) {
  // Minimal mjuk ellips-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.96, w * 0.45, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas
  ctx.fillStyle = '#7a5828';
  ctx.fillRect(x, y, w, h);
  // Tak (mörkare brun)
  ctx.fillStyle = '#3a2010';
  ctx.fillRect(x, y, w, h * 0.35);
  // Dörr
  ctx.fillStyle = '#1a0a04';
  ctx.fillRect(x + w * 0.35, y + h * 0.5, w * 0.3, h * 0.45);
  // Kläder-pinne (vit liten cirkel = höns)
  ctx.fillStyle = '#f0f0e0';
  ctx.beginPath();
  ctx.arc(x + w * 0.2, y + h * 0.8, 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ff5050';
  ctx.beginPath();
  ctx.arc(x + w * 0.2, y + h * 0.76, 1.5, 0, Math.PI * 2);
  ctx.fill();
  // Yttre kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// PICKNICKBORD — bord med bänkar
function drawPicnicTable(x, y, w, h) {
  // Minimal mjuk ellips-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.2)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.45, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bord-bas (brun)
  ctx.fillStyle = '#7a5028';
  ctx.fillRect(x, y, w, h);
  // Plankor (3 plankor)
  ctx.strokeStyle = '#3a2010';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + w / 3, y); ctx.lineTo(x + w / 3, y + h);
  ctx.moveTo(x + 2 * w / 3, y); ctx.lineTo(x + 2 * w / 3, y + h);
  ctx.stroke();
  // Bänkar (mörkare-bruna lister på sidorna)
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x, y - 4, w, 4);
  ctx.fillRect(x, y + h, w, 4);
  // Kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// LÄGERELD — stenring + eld
function drawCampfire(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, r * 0.9, r * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();
  // Stenring (mörk grå)
  ctx.fillStyle = '#3a3028';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Stenarna (separata cirklar runt eldenring)
  ctx.fillStyle = '#5a5048';
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2;
    const px = cx + Math.cos(ang) * (r * 0.85);
    const py = cy + Math.sin(ang) * (r * 0.85);
    ctx.beginPath();
    ctx.arc(px, py, r * 0.22, 0, Math.PI * 2);
    ctx.fill();
  }
  // Vedstockar i mitten (X-pattern)
  ctx.strokeStyle = '#3a1808';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(cx - r * 0.4, cy - r * 0.4);
  ctx.lineTo(cx + r * 0.4, cy + r * 0.4);
  ctx.moveTo(cx + r * 0.4, cy - r * 0.4);
  ctx.lineTo(cx - r * 0.4, cy + r * 0.4);
  ctx.stroke();
  // Eld (animerat flicker)
  const t = performance.now() / 1000;
  const flicker = 0.7 + Math.sin(t * 9) * 0.3;
  ctx.fillStyle = 'rgba(255, 100, 30, ' + (0.7 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 200, 60, ' + (0.95 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 240, 120, ' + (0.8 * flicker) + ')';
  ctx.beginPath();
  ctx.arc(cx, cy - 2, r * 0.15, 0, Math.PI * 2);
  ctx.fill();
}

// BÅT — liten roddbåt uppifrån
function drawBoat(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.26)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.48, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  // Båt-skrov (mörk-brun)
  ctx.fillStyle = '#3a1810';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h / 2, w * 0.48, h * 0.48, 0, 0, Math.PI * 2);
  ctx.fill();
  // Inre (ljusare brun = öppen båt)
  ctx.fillStyle = '#7a4828';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h / 2, w * 0.4, h * 0.38, 0, 0, Math.PI * 2);
  ctx.fill();
  // Plankor
  ctx.strokeStyle = '#3a1810';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.15, y + h / 2); ctx.lineTo(x + w * 0.85, y + h / 2);
  ctx.stroke();
  // Sittbänkar (2 horisontella streck)
  ctx.fillStyle = '#5a3018';
  ctx.fillRect(x + w * 0.25, y + h * 0.3, w * 0.5, 3);
  ctx.fillRect(x + w * 0.25, y + h * 0.6, w * 0.5, 3);
  // Yttre rand
  ctx.strokeStyle = '#1a0a04';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h / 2, w * 0.48, h * 0.48, 0, 0, Math.PI * 2);
  ctx.stroke();
}

// BRO — trä-plankor över bäck
function drawBridge(x, y, w, h) {
  // (Ingen skugga — bro är "marken-höjd")
  // Bas (mörk-brun)
  ctx.fillStyle = '#3a2818';
  ctx.fillRect(x, y, w, h);
  // Plankor (horisontella streck)
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1.2;
  const plankW = 12;
  for (let i = plankW; i < w; i += plankW) {
    ctx.beginPath();
    ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + h);
    ctx.stroke();
  }
  // Räcken (sidor)
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x, y - 3, w, 3);
  ctx.fillRect(x, y + h, w, 3);
  // Nitar (på räcken)
  ctx.fillStyle = '#1a0e04';
  for (let i = 5; i < w; i += 20) {
    ctx.beginPath();
    ctx.arc(x + i, y - 1.5, 1, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x + i, y + h + 1.5, 1, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ============================================================
// BR LANDMARKS v1.329 — 6 stora visuella ikoner
// ============================================================

// PLANE FUSELAGE — krashat flygkroppen
function drawPlaneFuselage(x, y, w, h, seed) {
  // KRASHAT PLAN — INTE en fyrkant. Render som AVLÅNG TUB med trasig mitten där
  // flygkroppen knäcktes vid krasch, exponerade interiör, böjda metallplåtar.
  const cy = y + h / 2;
  // Mjuk skugga (oval för rundad form)
  ctx.fillStyle = 'rgba(0,0,0,0.42)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2 + 8, cy + 12, w * 0.52, h * 0.30, 0, 0, Math.PI * 2);
  ctx.fill();
  // ============ HUVUDKROPP — avlång rundad tub med BÖJD/KNÄCKT mitten ============
  // Plane består av 3 delar: bakre + främre (intakt) + KNÄCKZON i mitten (öppen)
  const breakStart = w * 0.35;
  const breakEnd = w * 0.50;
  // BAKRE sektion (vänster del, från x till x + breakStart)
  ctx.save();
  ctx.beginPath();
  // Rundad nos (vänster, smal)
  ctx.moveTo(x, cy);
  // Övre kant — något böjd nedåt mot break-zonen
  ctx.bezierCurveTo(x + 10, y - 4, x + breakStart * 0.4, y, x + breakStart, cy - h * 0.4);
  // Krasch-kanten (jagged top)
  ctx.lineTo(x + breakStart + 5, cy - h * 0.25);
  ctx.lineTo(x + breakStart - 3, cy);
  ctx.lineTo(x + breakStart + 4, cy + h * 0.15);
  ctx.lineTo(x + breakStart - 2, cy + h * 0.35);
  ctx.lineTo(x + breakStart, cy + h * 0.42);
  // Botten-kant — något böjd
  ctx.bezierCurveTo(x + breakStart * 0.4, y + h, x + 10, y + h + 4, x, cy);
  ctx.closePath();
  const bgrad = ctx.createLinearGradient(x, y, x, y + h);
  bgrad.addColorStop(0, '#9aa0a8');
  bgrad.addColorStop(0.45, '#7a808a');
  bgrad.addColorStop(0.6, '#5a5a60');
  bgrad.addColorStop(1, '#3a3038');
  ctx.fillStyle = bgrad;
  ctx.fill();
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.restore();
  // FRÄMRE sektion (höger del, från x + breakEnd till x + w) — cockpit-sidan
  // Tiltad något så det ser krashat ut
  ctx.save();
  // Tilt: pivot vid breakEnd, rotera -0.08 rad
  const pivX = x + breakEnd + 10;
  const pivY = cy + h * 0.10;
  ctx.translate(pivX, pivY);
  ctx.rotate(-0.10);
  ctx.translate(-pivX, -pivY);
  ctx.beginPath();
  // Krasch-kant (jagged left)
  ctx.moveTo(x + breakEnd, cy + h * 0.42);
  ctx.lineTo(x + breakEnd + 3, cy + h * 0.20);
  ctx.lineTo(x + breakEnd - 2, cy);
  ctx.lineTo(x + breakEnd + 5, cy - h * 0.20);
  ctx.lineTo(x + breakEnd, cy - h * 0.40);
  // Övre kant — fram till cockpit-nosen
  ctx.bezierCurveTo(x + w * 0.65, y - 2, x + w * 0.85, y, x + w - 18, cy - h * 0.42);
  // Rundad nos (höger)
  ctx.bezierCurveTo(x + w - 4, cy - h * 0.30, x + w + 2, cy - h * 0.10, x + w, cy);
  ctx.bezierCurveTo(x + w + 2, cy + h * 0.10, x + w - 4, cy + h * 0.30, x + w - 18, cy + h * 0.42);
  // Botten
  ctx.bezierCurveTo(x + w * 0.85, y + h, x + w * 0.65, y + h + 2, x + breakEnd, cy + h * 0.42);
  ctx.closePath();
  ctx.fillStyle = bgrad;
  ctx.fill();
  ctx.strokeStyle = '#1a0e08';
  ctx.lineWidth = 2;
  ctx.stroke();
  // Cockpit-glas (rundad front)
  ctx.fillStyle = '#1a2028';
  ctx.beginPath();
  ctx.ellipse(x + w - 30, cy, 22, h * 0.34, 0, 0, Math.PI * 2);
  ctx.fill();
  // Cockpit-window-glow
  ctx.fillStyle = 'rgba(110, 140, 170, 0.55)';
  ctx.beginPath();
  ctx.ellipse(x + w - 30, cy - 3, 16, h * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.ellipse(x + w - 30, cy, 22, h * 0.34, 0, 0, Math.PI * 2);
  ctx.stroke();
  // Cockpit-spricka (krossat glas)
  ctx.strokeStyle = 'rgba(20, 25, 35, 0.85)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(x + w - 38, cy - 4);
  ctx.lineTo(x + w - 28, cy + 2);
  ctx.lineTo(x + w - 22, cy - 5);
  ctx.stroke();
  // Krossade fönster (rad runda fönster längs främre sektion)
  ctx.fillStyle = '#0a0408';
  for (let i = 0; i < 4; i++) {
    const wx = x + breakEnd + 18 + i * 30;
    if (wx > x + w - 55) break;
    ctx.beginPath();
    ctx.ellipse(wx, cy, 7, 5, 0, 0, Math.PI * 2);
    ctx.fill();
    // Spricka över fönstret
    ctx.strokeStyle = 'rgba(70, 80, 95, 0.5)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(wx - 6, cy - 1); ctx.lineTo(wx + 6, cy + 2);
    ctx.stroke();
  }
  ctx.restore();
  // ============ KNÄCK-ZON I MITTEN — exponerad interiör (mörk) ============
  ctx.save();
  // Mörk hål-bakgrund mellan break-sektionerna
  ctx.fillStyle = '#0e0a08';
  ctx.beginPath();
  ctx.moveTo(x + breakStart, cy - h * 0.40);
  ctx.lineTo(x + breakStart + 5, cy - h * 0.25);
  ctx.lineTo(x + breakStart - 3, cy);
  ctx.lineTo(x + breakStart + 4, cy + h * 0.15);
  ctx.lineTo(x + breakStart - 2, cy + h * 0.35);
  ctx.lineTo(x + breakStart, cy + h * 0.42);
  ctx.lineTo(x + breakEnd, cy + h * 0.42);
  ctx.lineTo(x + breakEnd + 3, cy + h * 0.20);
  ctx.lineTo(x + breakEnd - 2, cy);
  ctx.lineTo(x + breakEnd + 5, cy - h * 0.20);
  ctx.lineTo(x + breakEnd, cy - h * 0.40);
  ctx.closePath();
  ctx.fill();
  // Exponerade kablar/vajrar (rödorange + gula)
  const wires = ['#cc4020', '#ddaa30', '#888888', '#cc4020', '#5050aa'];
  for (let i = 0; i < wires.length; i++) {
    const yy = cy - h * 0.30 + i * h * 0.16;
    ctx.strokeStyle = wires[i];
    ctx.lineWidth = 1.5 + (i % 2);
    ctx.beginPath();
    ctx.moveTo(x + breakStart - 2, yy);
    // Slingrande
    ctx.bezierCurveTo(
      x + breakStart + 10, yy + 5,
      x + breakEnd - 10, yy - 3,
      x + breakEnd + 2, yy + 2
    );
    ctx.stroke();
  }
  // Stänger/balkar (mörkgrå metallbitar som sticker ut)
  ctx.fillStyle = '#3a3a40';
  ctx.fillRect(x + breakStart + 8, cy - h * 0.15, 16, 3);
  ctx.fillRect(x + breakEnd - 14, cy + h * 0.10, 12, 3);
  // Eld/glödande röda gnistor vid kraschpunkten
  const t = performance.now() / 1000;
  const flicker = 0.6 + Math.sin(t * 7) * 0.4;
  ctx.fillStyle = 'rgba(255, 80, 30, ' + (0.6 * flicker) + ')';
  ctx.beginPath();
  ctx.ellipse((x + breakStart + x + breakEnd) / 2, cy, 12, h * 0.28, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 200, 80, ' + (0.55 * flicker) + ')';
  ctx.beginPath();
  ctx.ellipse((x + breakStart + x + breakEnd) / 2, cy, 5, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  // ============ DETALJER ============
  // Airline logo + text (på bakre sektion, INTE över krasch-zonen)
  ctx.fillStyle = '#cc2020';
  ctx.fillRect(x + breakStart * 0.35, cy + h * 0.15, 35, 4);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('SKYAIR', x + breakStart * 0.35, cy + h * 0.30);
  // Sotiga sprickor på utsidan (random svarta-bruna fläckar)
  ctx.fillStyle = 'rgba(20, 10, 0, 0.65)';
  for (let i = 0; i < 8; i++) {
    const sx = x + ((seed * (i + 1) * 13) & 0xff) % w;
    const sy = y + ((seed * (i + 3) * 17) & 0xff) % h;
    // Skip om i krasch-zonen
    if (sx > x + breakStart - 10 && sx < x + breakEnd + 10) continue;
    ctx.beginPath();
    ctx.ellipse(sx, sy, 14, 5, ((seed * i) % 100) / 100, 0, Math.PI * 2);
    ctx.fill();
  }
  // Rivets längs sidor (bara intakta sektioner)
  ctx.fillStyle = '#3a2a18';
  for (let i = 6; i < w; i += 22) {
    // Hoppa över krasch-zonen
    if (x + i > x + breakStart - 5 && x + i < x + breakEnd + 5) continue;
    ctx.beginPath();
    ctx.arc(x + i, y + 8, 1.2, 0, Math.PI * 2);
    ctx.arc(x + i, y + h - 8, 1.2, 0, Math.PI * 2);
    ctx.fill();
  }
}

// PLANE WING — vinge
function drawPlaneWing(x, y, w, h) {
  // Mjuk ellips-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.55, h * 0.18, 0, 0, Math.PI * 2);
  ctx.fill();
  // RIKTIG VINGE-FORM: aerofoil-profil med rotation, tjockare vid rot, avsmalnande mot spets
  // Rotationsvinkel: höger vinge pekar utåt-bakåt, vänster spegelvänd via h-orientering
  const cx = x + w / 2, cy = y + h / 2;
  // Bestäm orientering — w > h: horisontell vinge, rot-änden närmast fuselagen.
  // Vi antar vingen pekar "från rot" till "spets" längs x-axeln, rot=vänster.
  // Tjockaste delen vid rot (höger sida av w=fuselag), tunn spets (vänster).
  // Path: rot-platt → bakkant kurva → spets → framkant kurva tillbaka
  const rootW = h * 0.9;        // rot-tjocklek
  const tipW = h * 0.35;        // spets-tjocklek
  const rootX = x + w;          // rot vid plane-fuselagen (höger för höger vinge — vi roterar inte, bara skissar)
  const tipX = x;               // spets är vänster
  const baseY = y + h / 2;
  // Skapa vinge-path (sett uppifrån): aerofoil → trapets med rundade hörn
  ctx.save();
  // Huvudvinge: gradient + path
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#9da3ad');
  grad.addColorStop(0.45, '#7a808a');
  grad.addColorStop(1, '#4a4d56');
  ctx.fillStyle = grad;
  ctx.beginPath();
  // Bakkant (rakare, lätt böjd)
  ctx.moveTo(rootX, baseY + rootW / 2);
  ctx.quadraticCurveTo(cx + 10, baseY + (rootW * 0.7) / 2, tipX + tipW * 0.3, baseY + tipW / 2);
  // Spets (avrundad)
  ctx.quadraticCurveTo(tipX - 4, baseY, tipX + tipW * 0.3, baseY - tipW / 2);
  // Framkant (skarpare bukt — typisk aerofoil leading edge)
  ctx.quadraticCurveTo(cx + 10, baseY - (rootW * 0.85) / 2, rootX, baseY - rootW / 2);
  ctx.closePath();
  ctx.fill();
  // Tunn highlight längs framkanten (sol-reflex)
  ctx.strokeStyle = 'rgba(220, 225, 235, 0.55)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(rootX, baseY - rootW / 2 + 2);
  ctx.quadraticCurveTo(cx + 10, baseY - (rootW * 0.85) / 2 + 2, tipX + tipW * 0.3, baseY - tipW / 2 + 1);
  ctx.stroke();
  // Mörk skuggad bakkant
  ctx.strokeStyle = 'rgba(20, 14, 10, 0.7)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(rootX, baseY + rootW / 2 - 1);
  ctx.quadraticCurveTo(cx + 10, baseY + (rootW * 0.7) / 2 - 1, tipX + tipW * 0.3, baseY + tipW / 2 - 1);
  ctx.stroke();
  // Aileron-fog (flaps) — 2 vertikala små streck nära spets-bakkant
  ctx.strokeStyle = 'rgba(15, 10, 6, 0.85)';
  ctx.lineWidth = 1.2;
  const flapY1 = baseY + tipW * 0.15;
  const flapY2 = baseY + rootW * 0.30;
  ctx.beginPath();
  ctx.moveTo(cx - 10, flapY1 + 3); ctx.lineTo(cx - 10, flapY1 - tipW * 0.4);
  ctx.moveTo(cx + 20, flapY2 + 3); ctx.lineTo(cx + 20, flapY2 - rootW * 0.6);
  ctx.stroke();
  // Vinge-luftintag/motor-bubbla under (mörk oval halvvägs ut)
  ctx.fillStyle = '#2a2e36';
  ctx.beginPath();
  ctx.ellipse(cx + 5, baseY + 2, h * 0.35, h * 0.18, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(15, 10, 6, 0.6)';
  ctx.lineWidth = 1;
  ctx.stroke();
  // Liten röd/vit randmarkering vid spetsen (navigationsljus-look)
  ctx.fillStyle = '#cc2020';
  ctx.fillRect(tipX + 1, baseY - 2, 4, 4);
  // Nitrader längs framkanten
  ctx.fillStyle = 'rgba(40, 30, 20, 0.55)';
  for (let i = 0; i < 8; i++) {
    const t = i / 7;
    const nx = rootX - t * (rootX - (tipX + tipW * 0.3));
    const ny = baseY - rootW / 2 + t * (rootW / 2 - tipW / 2) * 0.85;
    ctx.fillRect(nx - 0.5, ny - 0.5, 1.5, 1.5);
  }
  // Knäckta sprickor (vraket är ju kraschat — visuell skada)
  ctx.strokeStyle = 'rgba(15, 8, 4, 0.6)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - 20, baseY - rootW * 0.25);
  ctx.lineTo(cx - 5, baseY - rootW * 0.1);
  ctx.lineTo(cx + 8, baseY + rootW * 0.15);
  ctx.stroke();
  ctx.restore();
}

// PLANE TAIL — vertikal stjärt
function drawPlaneTail(x, y, w, h) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.96, w * 0.5, h * 0.12, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#7a7a80';
  ctx.fillRect(x, y, w, h);
  // Röd stripe (airline-logo)
  ctx.fillStyle = '#cc2020';
  ctx.fillRect(x, y + h * 0.3, w, h * 0.2);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// CHURCH RUIN — gotisk ruin med spira
function drawChurchRuin(x, y, w, h, seed) {
  const cx = x + w / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.36)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.97, w * 0.52, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas (gamla stenar)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#7a7268');
  grad.addColorStop(0.5, '#5a5248');
  grad.addColorStop(1, '#3a3228');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Sten-block (uppifrån)
  ctx.strokeStyle = 'rgba(20, 15, 8, 0.75)';
  ctx.lineWidth = 1;
  const stoneW = 35, stoneH = 25;
  for (let yy = 0; yy < h; yy += stoneH) {
    const offset = (yy / stoneH) % 2 === 0 ? 0 : stoneW / 2;
    for (let xx = offset; xx < w; xx += stoneW) {
      ctx.strokeRect(x + xx + 0.5, y + yy + 0.5, stoneW - 1, stoneH - 1);
    }
  }
  // Gotiska valv-öppningar (3 båglika fönster, krossade)
  for (let i = 0; i < 3; i++) {
    const wx = x + w * (0.2 + i * 0.3);
    const wy = y + h * 0.25;
    ctx.fillStyle = '#0a0408';
    ctx.beginPath();
    ctx.arc(wx, wy + 20, 12, Math.PI, 0);
    ctx.fillRect(wx - 12, wy + 20, 24, 25);
    ctx.fill();
    // Krossat glas-rester (vit prickar)
    ctx.fillStyle = '#9090a0';
    for (let g = 0; g < 4; g++) {
      ctx.fillRect(wx - 10 + g * 6, wy + 25 + (g % 2) * 8, 2, 2);
    }
  }
  // Stor entré-port (centrerad, nederst)
  ctx.fillStyle = '#1a0e04';
  ctx.beginPath();
  ctx.arc(cx, y + h - 50, 25, Math.PI, 0);
  ctx.fillRect(cx - 25, y + h - 50, 50, 50);
  ctx.fill();
  ctx.strokeStyle = '#3a2008';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, y + h - 50, 25, Math.PI, 0);
  ctx.stroke();
  // Spira (tornet uppifrån = mörk fyrkant med kors)
  ctx.fillStyle = '#3a2818';
  ctx.fillRect(cx - 20, y - 30, 40, 50);
  ctx.fillStyle = '#1a0e04';
  ctx.fillRect(cx - 18, y - 28, 36, 46);
  // Kors på toppen (gult)
  ctx.fillStyle = '#ffd54a';
  ctx.fillRect(cx - 2, y - 38, 4, 16);
  ctx.fillRect(cx - 7, y - 33, 14, 4);
  // Klocka i tornet (synlig som mörk cirkel)
  ctx.fillStyle = '#3a2818';
  ctx.beginPath();
  ctx.arc(cx, y - 8, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#1a0e04';
  ctx.beginPath();
  ctx.arc(cx, y - 8, 3, 0, Math.PI * 2);
  ctx.fill();
  // Mossa (gröna fläckar)
  ctx.fillStyle = 'rgba(50, 90, 40, 0.6)';
  for (let i = 0; i < 8; i++) {
    const mx = x + 5 + ((seed * (i + 1) * 13) & 0xff) % (w - 10);
    const my = y + 10 + ((seed * (i + 3) * 17) & 0xff) % (h - 20);
    ctx.beginPath();
    ctx.ellipse(mx, my, 6, 3, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // Yttre kant
  ctx.strokeStyle = '#1a1408';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// GRAVESTONE — liten gravsten i kyrkogården
// Förinitierad namn-pool för gravstenar — sorted-deterministic per seed.
const _GRAVE_NAMES = [
  'BJÖRN', 'ASTRID', 'SVEN', 'INGA', 'OLAF', 'GUDRUN', 'ERIK', 'LARS',
  'HELGA', 'KARL', 'MAGNUS', 'SIGRID', 'AXEL', 'EBBA', 'GUSTAV', 'ELIN',
];

function drawGravestone(x, y, w, h, seed, wallData) {
  // Liten mjuk skugga
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.97, w * 0.5, h * 0.12, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-sten — mörkare grå nedan
  ctx.fillStyle = '#3a3530';
  ctx.beginPath();
  ctx.arc(x + w / 2, y + 6, w / 2, Math.PI, 0);
  ctx.fillRect(x, y + 6, w, h - 6);
  ctx.fill();
  // Ljus framsida (lite ljusare)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#7a7268');
  grad.addColorStop(0.6, '#5a5048');
  grad.addColorStop(1, '#3a3530');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x + w / 2, y + 5, w / 2 - 2, Math.PI, 0);
  ctx.fillRect(x + 2, y + 5, w - 4, h - 9);
  ctx.fill();
  // Kors i toppen (litet)
  ctx.fillStyle = '#1a1408';
  ctx.fillRect(x + w / 2 - 1, y + 8, 2, 5);
  ctx.fillRect(x + w / 2 - 3, y + 10, 6, 1.5);
  // NAMN på stenen — prio explicit graveName från arena, annars seed-baserat
  let name, birthYear, deathYear;
  if (wallData && wallData.graveName) {
    name = wallData.graveName;
    birthYear = wallData.graveBirth || 1880;
    deathYear = wallData.graveDeath || 1950;
  } else {
    const nameIdx = ((seed >>> 0) ^ ((seed >>> 5))) & 0xf;
    name = _GRAVE_NAMES[nameIdx % _GRAVE_NAMES.length];
    birthYear = 1860 + (((seed * 13) >>> 0) & 0x7f);
    deathYear = Math.min(1995, birthYear + 35 + (((seed * 17) >>> 0) & 0x3f));
  }
  ctx.fillStyle = '#1a1408';
  ctx.font = 'bold 6px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(name, x + w / 2, y + h * 0.55);
  ctx.font = 'bold 5px serif';
  ctx.fillText(birthYear + '–' + deathYear, x + w / 2, y + h * 0.78);
  // Mossa-bas (lägre tjocklek så vi inte täcker text)
  ctx.fillStyle = 'rgba(50, 80, 40, 0.4)';
  ctx.fillRect(x, y + h - 3, w, 3);
  // Subtil "spricka" (random)
  if ((seed & 3) === 0) {
    ctx.strokeStyle = 'rgba(20, 18, 12, 0.55)';
    ctx.lineWidth = 0.4;
    ctx.beginPath();
    ctx.moveTo(x + w * 0.3, y + h * 0.3);
    ctx.lineTo(x + w * 0.4, y + h * 0.6);
    ctx.stroke();
  }
}

// CLIFF EDGE — klippkanten över vattenfalls
function drawCliffEdge(x, y, w, h, seed) {
  // ORGANISK BERGSMASS — INTE en fyrkant. Render som irregulär polygon-form
  // med gradient, klippspetsar uppåt, snöcap, ridge-fasetter och mörk skugga.
  const cx = x + w / 2, cy = y + h / 2;
  // ============ Bygg irregulär polygon-kontur runt bbox ============
  // 16 punkter runt rektangeln med per-punkt noise — ger mountain-silhuett
  const N = 16;
  const pts = [];
  for (let i = 0; i < N; i++) {
    const f = i / N;
    const ang = f * Math.PI * 2;
    // Basform: punkt på rektangelns kant baserat på vinkel
    const dx0 = Math.cos(ang);
    const dy0 = Math.sin(ang);
    // Skalfaktor som matchar rektangeln (rektangulär basform)
    const absX = Math.abs(dx0), absY = Math.abs(dy0);
    const rs = Math.min(1 / Math.max(absX, 0.0001), 1 / Math.max(absY, 0.0001));
    let bx = cx + dx0 * rs * (w / 2);
    let by = cy + dy0 * rs * (h / 2);
    // Noise: pull punkter UTÅT på toppen (peaks), INÅT i hörn (avrundade), neutralt på sidor
    const noiseSeed = ((seed * (i + 1) * 73) >>> 0) % 1000;
    const baseNoise = (noiseSeed / 1000 - 0.5) * 0.18; // ±9%
    let scale = 1 + baseNoise;
    // Top-halvan: ger PEAKS (mer utåt)
    if (dy0 < -0.3) {
      const peakNoise = ((seed * (i + 7) * 113) >>> 0) % 1000;
      scale += (peakNoise / 1000) * 0.18; // 0..18% extra utåt
    }
    // Botten: drar inåt (skugg-fot)
    if (dy0 > 0.5) {
      scale -= 0.05;
    }
    bx = cx + (bx - cx) * scale;
    by = cy + (by - cy) * scale;
    pts.push({ x: bx, y: by });
  }
  // ============ Skugga (bredare än polygon för djup-effekt) ============
  ctx.save();
  ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
  ctx.beginPath();
  ctx.moveTo(pts[0].x + 6, pts[0].y + 10);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x + 6, pts[i].y + 10);
  ctx.closePath();
  ctx.fill();
  // ============ Mountain body — gradient + clip till polygon ============
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.closePath();
  ctx.save();
  ctx.clip();
  // Bas-gradient (mörk-blå-grå för riktig mountain-känsla)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#8a8478');     // ljus topp
  grad.addColorStop(0.25, '#6a6258');  // mid övre
  grad.addColorStop(0.55, '#4a4238');  // mid undre
  grad.addColorStop(0.85, '#2a2218');  // mörk botten
  grad.addColorStop(1, '#15100a');     // skuggig fot
  ctx.fillStyle = grad;
  ctx.fillRect(x - 20, y - 20, w + 40, h + 40);
  // ============ Ridge-fasetter (mörka diagonalstreck från topp ner) ============
  // Slumpmässigt placerade ridges som ger berget 3D-form
  ctx.strokeStyle = 'rgba(15, 10, 5, 0.55)';
  ctx.lineWidth = 1.8;
  const ridgeCount = 6;
  for (let i = 0; i < ridgeCount; i++) {
    const f = (i + 0.5) / ridgeCount;
    const topX = x + f * w + ((seed * (i + 3) * 31) % 40) - 20;
    const topY = y + 5;
    const botX = topX + ((seed * (i + 7) * 17) % 60) - 30;
    const botY = y + h - 8;
    ctx.beginPath();
    ctx.moveTo(topX, topY);
    // Lätt böjd ridge
    const midX = (topX + botX) / 2 + ((seed * (i + 11)) % 20) - 10;
    const midY = y + h * 0.5;
    ctx.quadraticCurveTo(midX, midY, botX, botY);
    ctx.stroke();
  }
  // ============ Stora sten-block (texture) — flera olika tonade fläckar ============
  for (let i = 0; i < 18; i++) {
    const px = x + ((seed * (i + 1) * 41) % 1000) / 1000 * w;
    const py = y + ((seed * (i + 5) * 67) % 1000) / 1000 * h;
    const psize = 22 + ((seed * (i + 3) * 13) % 30);
    const shade = ((seed * (i + 7) * 11) % 80);
    ctx.fillStyle = 'rgba(' + (40 + shade) + ',' + (35 + shade) + ',' + (28 + shade) + ',0.4)';
    ctx.beginPath();
    ctx.ellipse(px, py, psize, psize * 0.7, ((seed * i) % 100) / 100 * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  // ============ Spridda mörka skuggor (crevices) ============
  for (let i = 0; i < 10; i++) {
    const px = x + ((seed * (i + 13) * 89) % 1000) / 1000 * w;
    const py = y + ((seed * (i + 17) * 53) % 1000) / 1000 * h;
    ctx.fillStyle = 'rgba(10, 8, 6, 0.55)';
    ctx.beginPath();
    ctx.ellipse(px, py, 16 + (i % 5), 8 + (i % 4), ((seed * i) % 100) / 100, 0, Math.PI * 2);
    ctx.fill();
  }
  // ============ Snö-cap på toppen ============
  // Snön ligger som en band längs övre delen av polygonen, med oregelbundna fingrar
  // som droppar nedåt
  ctx.fillStyle = 'rgba(240, 245, 250, 0.85)';
  ctx.beginPath();
  // Start från övre vänster
  let snowStart = pts.findIndex(p => p.y < y + h * 0.12);
  if (snowStart < 0) snowStart = 0;
  // Gå längs övre kanten av polygonen
  ctx.moveTo(x - 10, y - 5);
  // Övre kant + finger-fall ned
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (p.y > y + h * 0.30) continue; // bara övre 30% blir snö
    ctx.lineTo(p.x, p.y);
  }
  ctx.lineTo(x + w + 10, y - 5);
  ctx.lineTo(x + w + 10, y + h * 0.22);
  // Oregelbundna snö-fingrar som faller ned
  const fingerCount = 5;
  for (let i = fingerCount - 1; i >= 0; i--) {
    const fx = x + (i + 1) / (fingerCount + 1) * w;
    const fy = y + h * (0.18 + ((seed * (i + 3) * 23) % 100) / 1000);
    ctx.lineTo(fx + 12, fy - 4);
    ctx.lineTo(fx, fy + ((seed * (i + 7)) % 30));
    ctx.lineTo(fx - 12, fy - 4);
  }
  ctx.lineTo(x - 10, y + h * 0.22);
  ctx.closePath();
  ctx.fill();
  // Snö-skugga (blå-grå)
  ctx.fillStyle = 'rgba(170, 180, 195, 0.35)';
  ctx.beginPath();
  ctx.moveTo(x - 10, y + h * 0.08);
  ctx.lineTo(x + w * 0.3, y + h * 0.04);
  ctx.lineTo(x + w * 0.65, y + h * 0.10);
  ctx.lineTo(x + w + 10, y + h * 0.16);
  ctx.lineTo(x + w + 10, y + h * 0.22);
  ctx.lineTo(x - 10, y + h * 0.22);
  ctx.closePath();
  ctx.fill();
  ctx.restore(); // pop polygon-clip
  // ============ Yttre mörk outline (silhuett) — efter clip ============
  ctx.strokeStyle = 'rgba(8, 6, 4, 0.85)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

// STANDING STONE — forntida menhir (del av stencirkel)
function drawStandingStone(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.96, w * 0.45, h * 0.12, 0, 0, Math.PI * 2);
  ctx.fill();
  // Avsmalnande triangular stone
  ctx.fillStyle = '#3a3028';
  ctx.beginPath();
  ctx.moveTo(cx, y);
  ctx.lineTo(x + w - 5, y + h);
  ctx.lineTo(x + 5, y + h);
  ctx.closePath();
  ctx.fill();
  // Highlight (vänster sida)
  ctx.fillStyle = '#6a5a50';
  ctx.beginPath();
  ctx.moveTo(cx, y);
  ctx.lineTo(cx, y + h);
  ctx.lineTo(x + 5, y + h);
  ctx.closePath();
  ctx.fill();
  // Sprickor
  ctx.strokeStyle = '#0a0408';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - 3, y + 8);
  ctx.lineTo(cx - 5, y + h * 0.5);
  ctx.lineTo(cx + 2, y + h * 0.8);
  ctx.stroke();
  // Mystiska runor (4 markeringar)
  ctx.fillStyle = '#aa3aff';
  for (let i = 0; i < 4; i++) {
    const ry = y + 12 + i * (h - 24) / 4;
    ctx.fillRect(cx - 2, ry, 4, 1);
    ctx.fillRect(cx - 2, ry + 2, 4, 1);
  }
  // Mossa bas
  ctx.fillStyle = 'rgba(50, 90, 40, 0.6)';
  ctx.fillRect(x + 5, y + h - 3, w - 10, 3);
}

// ALTAR STONE — centrum av stencirkel, mörk ritning
function drawAltarStone(x, y, w, h) {
  const cx = x + w / 2, cy = y + h / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.48, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Stenring (mörk)
  ctx.fillStyle = '#1a1408';
  ctx.beginPath();
  ctx.arc(cx, cy, w / 2, 0, Math.PI * 2);
  ctx.fill();
  // Inre platta
  ctx.fillStyle = '#3a2818';
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.4, 0, Math.PI * 2);
  ctx.fill();
  // Ritning (blod-röd pentagram)
  ctx.strokeStyle = '#aa1010';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const ang = -Math.PI / 2 + (i * 2 * Math.PI * 2) / 5;
    const px = cx + Math.cos(ang) * w * 0.3;
    const py = cy + Math.sin(ang) * w * 0.3;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.stroke();
  // Animerad mörk-aura (pulsar)
  const t = performance.now() / 1000;
  const pulse = 0.5 + Math.sin(t * 1.5) * 0.3;
  ctx.strokeStyle = 'rgba(170, 16, 16, ' + pulse + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.4, 0, Math.PI * 2);
  ctx.stroke();
}

// PUMP-JACK OLJERIGG — animerad pump-arm
function drawPumpJack(x, y, w, h) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.34)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.97, w * 0.5, h * 0.13, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-plattform (mörk-rost)
  ctx.fillStyle = '#3a2810';
  ctx.fillRect(x, y + h * 0.7, w, h * 0.3);
  // Stödram (gulrostigt)
  ctx.fillStyle = '#8a6028';
  ctx.fillRect(x + w * 0.2, y + h * 0.3, w * 0.6, h * 0.4);
  // Diagonal stöttor (X-pattern)
  ctx.strokeStyle = '#5a3a18';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.2, y + h * 0.3); ctx.lineTo(x + w * 0.8, y + h * 0.7);
  ctx.moveTo(x + w * 0.8, y + h * 0.3); ctx.lineTo(x + w * 0.2, y + h * 0.7);
  ctx.stroke();
  // Pump-arm (animerad — svänger upp-och-ner)
  const t = performance.now() / 1000;
  const armY = Math.sin(t * 1.2) * 8;
  ctx.fillStyle = '#1a1408';
  ctx.fillRect(x + w * 0.1, y + h * 0.25 + armY, w * 0.8, 8);
  // Pump-huvud (på vänster sida = "hästhuvudet")
  ctx.fillStyle = '#3a2008';
  ctx.beginPath();
  ctx.moveTo(x + w * 0.1, y + h * 0.2 + armY);
  ctx.lineTo(x + w * 0.05, y + h * 0.3 + armY);
  ctx.lineTo(x + w * 0.1, y + h * 0.4 + armY);
  ctx.lineTo(x + w * 0.2, y + h * 0.4 + armY);
  ctx.lineTo(x + w * 0.2, y + h * 0.2 + armY);
  ctx.closePath();
  ctx.fill();
  // Rusty rivets
  ctx.fillStyle = '#1a0e04';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(x + w * 0.3 + i * w * 0.12, y + h * 0.5, 2, 0, Math.PI * 2);
    ctx.fill();
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// LIGHTHOUSE — fyrtorn (cirkulär från ovan)
function drawLighthouse(x, y, w, h) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.36)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, r * 0.95, r * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-cirkel (vit)
  ctx.fillStyle = '#e0e0e0';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Röda stripes (3 horizontella band — uppifrån = ringar)
  ctx.fillStyle = '#cc2020';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.8, 0, Math.PI * 2);
  ctx.arc(cx, cy, r * 0.65, 0, Math.PI * 2);
  ctx.fill('evenodd');
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.45, 0, Math.PI * 2);
  ctx.arc(cx, cy, r * 0.3, 0, Math.PI * 2);
  ctx.fill('evenodd');
  // Topp-lyse (gul, animerat)
  const t = performance.now() / 1000;
  const pulse = 0.7 + Math.sin(t * 2) * 0.3;
  ctx.fillStyle = 'rgba(255, 220, 80, ' + pulse + ')';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.2, 0, Math.PI * 2);
  ctx.fill();
  // Roterande ljusstråle (linje från centrum)
  const beamAng = (t * 0.5) % (Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 220, 80, 0.25)';
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(beamAng - 0.3) * r * 3, cy + Math.sin(beamAng - 0.3) * r * 3);
  ctx.lineTo(cx + Math.cos(beamAng + 0.3) * r * 3, cy + Math.sin(beamAng + 0.3) * r * 3);
  ctx.closePath();
  ctx.fill();
  // Yttre kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.stroke();
}

// WOODEN BENCH — bänk utanför stuga
function drawWoodenBench(x, y, w, h) {
  // Minimal mjuk ellips-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.2)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.98, w * 0.45, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Sittsäte (brun)
  ctx.fillStyle = '#7a5028';
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x + 1, y + 1, w - 2, h - 2);
  // 3 plankor
  ctx.strokeStyle = '#3a2008';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(x, y + h / 3); ctx.lineTo(x + w, y + h / 3);
  ctx.moveTo(x, y + 2 * h / 3); ctx.lineTo(x + w, y + 2 * h / 3);
  ctx.stroke();
  // Ben (mörka kvadrater i hörnen)
  ctx.fillStyle = '#1a0e04';
  ctx.fillRect(x + 1, y + h - 2, 4, 4);
  ctx.fillRect(x + w - 5, y + h - 2, 4, 4);
}

// FLOWER POT — keramik-kruka med blommor
function drawFlowerPot(x, y, w, h) {
  const cx = x + w / 2;
  // Minimal mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.98, w * 0.4, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Kruka (terrakotta)
  ctx.fillStyle = '#aa6030';
  ctx.beginPath();
  ctx.moveTo(x + 1, y + h * 0.4);
  ctx.lineTo(x + w - 1, y + h * 0.4);
  ctx.lineTo(x + w - 3, y + h);
  ctx.lineTo(x + 3, y + h);
  ctx.closePath();
  ctx.fill();
  // Top-rand (mörkare)
  ctx.fillStyle = '#7a4020';
  ctx.fillRect(x, y + h * 0.4 - 2, w, 3);
  // Jord (mörk-brun)
  ctx.fillStyle = '#3a2010';
  ctx.fillRect(x + 2, y + h * 0.4, w - 4, 4);
  // Blommor (5 färg-prickar ovan)
  const colors = ['#ff6080', '#ffd040', '#a060ff', '#ffffff', '#ff8030'];
  for (let i = 0; i < 5; i++) {
    const fx = x + 2 + i * (w - 4) / 5;
    const fy = y + h * 0.2 + (i % 2) * 3;
    ctx.fillStyle = colors[i];
    ctx.beginPath();
    ctx.arc(fx, fy, 2, 0, Math.PI * 2);
    ctx.fill();
    // Stjälk
    ctx.strokeStyle = '#3a7a3a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(fx, fy + 2); ctx.lineTo(fx, y + h * 0.4);
    ctx.stroke();
  }
}

// WAGON CART — övergiven varuvagn
function drawWagonCart(x, y, w, h, seed) {
  // Mjuk ellips-skugga (under objektet)
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(x + w / 2, y + h * 0.95, w * 0.5, h * 0.14, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bottendelen (brun trä)
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x, y, w, h);
  // Plankor (tvärgående)
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1;
  for (let i = 8; i < w; i += 12) {
    ctx.beginPath();
    ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + h);
    ctx.stroke();
  }
  // 4 hjul (mörkbruna cirklar i hörnen)
  ctx.fillStyle = '#2a1408';
  ctx.beginPath();
  ctx.arc(x + 8, y + 4, 5, 0, Math.PI * 2);
  ctx.arc(x + w - 8, y + 4, 5, 0, Math.PI * 2);
  ctx.arc(x + 8, y + h - 4, 5, 0, Math.PI * 2);
  ctx.arc(x + w - 8, y + h - 4, 5, 0, Math.PI * 2);
  ctx.fill();
  // Hjul-ekrar
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1;
  for (const [hx, hy] of [[x + 8, y + 4], [x + w - 8, y + 4], [x + 8, y + h - 4], [x + w - 8, y + h - 4]]) {
    ctx.beginPath();
    ctx.moveTo(hx - 4, hy); ctx.lineTo(hx + 4, hy);
    ctx.moveTo(hx, hy - 4); ctx.lineTo(hx, hy + 4);
    ctx.stroke();
  }
  // Last (några brunt-grön påsar)
  ctx.fillStyle = '#7a6028';
  ctx.fillRect(x + 14, y + 8, 18, 10);
  ctx.fillStyle = '#5a4828';
  ctx.fillRect(x + 36, y + 6, 18, 12);
  ctx.fillStyle = '#3a5a3a';
  ctx.fillRect(x + 58, y + 10, 16, 10);
  // Dragstänger (mörka linjer)
  ctx.strokeStyle = '#3a2008';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - 12, y + h / 2); ctx.lineTo(x, y + h / 2);
  ctx.stroke();
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// TREE GIANT OAK — stor jätte-ek
function drawTreeGiantOak(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Kompakt stor skugga
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx + 3, cy + 3, r * 0.95, r * 0.9, 0, 0, Math.PI * 2);
  ctx.fill();
  // Yttre krona (mörkare grön ring)
  ctx.fillStyle = '#1a3a1a';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  // Mid-krona
  ctx.fillStyle = '#2a5a2a';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.95, 0, Math.PI * 2);
  ctx.fill();
  // Inner krona (radial-gradient för 3D)
  const grad = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, r * 0.1, cx, cy, r * 0.9);
  grad.addColorStop(0, '#6abc4a');
  grad.addColorStop(0.5, '#3a8a2a');
  grad.addColorStop(1, '#1a3a18');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.88, 0, Math.PI * 2);
  ctx.fill();
  // Multipla lövkluster (10 grupper)
  ctx.fillStyle = 'rgba(20, 50, 20, 0.55)';
  for (let i = 0; i < 12; i++) {
    const ang = (seed * (i + 1)) % (Math.PI * 2);
    const dist = r * 0.4 + ((seed * (i + 3)) & 0xff) / 800 * r * 0.3;
    const px = cx + Math.cos(ang) * dist;
    const py = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.arc(px, py, 4 + (i % 3), 0, Math.PI * 2);
    ctx.fill();
  }
  // Ljus-highlight
  ctx.fillStyle = 'rgba(150, 220, 100, 0.3)';
  ctx.beginPath();
  ctx.arc(cx - r * 0.25, cy - r * 0.25, r * 0.4, 0, Math.PI * 2);
  ctx.fill();
  // Brun stam i mitten (synlig, större)
  ctx.fillStyle = '#3a2818';
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.2, 0, Math.PI * 2);
  ctx.fill();
  // Årsringar (synlig i toppen)
  ctx.strokeStyle = '#5a3820';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.15, 0, Math.PI * 2);
  ctx.arc(cx, cy, r * 0.1, 0, Math.PI * 2);
  ctx.stroke();
  // Stam highlight
  ctx.fillStyle = '#7a5028';
  ctx.beginPath();
  ctx.arc(cx - 2, cy - 2, r * 0.1, 0, Math.PI * 2);
  ctx.fill();
}

// RUNE STONE — gammal sten med runor
function drawRuneStone(x, y, w, h, seed) {
  const cx = x + w / 2;
  // Minimal mjuk ellips-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.26)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.97, w * 0.45, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas (mörk-grå)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#6a6058');
  grad.addColorStop(1, '#3a3028');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Avrundad topp
  ctx.fillStyle = '#5a5048';
  ctx.beginPath();
  ctx.arc(cx, y + 5, w / 2, Math.PI, 0);
  ctx.fill();
  // Runor (3-4 mystiska tecken)
  ctx.fillStyle = '#aa3aff';
  ctx.font = 'bold 14px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const runes = ['ᚱ', 'ᚦ', 'ᚷ', 'ᛏ', 'ᛟ'];
  for (let i = 0; i < 4; i++) {
    const ry = y + 15 + i * (h - 25) / 4;
    ctx.fillText(runes[(seed + i) % runes.length], cx, ry);
  }
  // Mossa-bas
  ctx.fillStyle = 'rgba(50, 90, 40, 0.55)';
  ctx.fillRect(x, y + h - 5, w, 5);
  // Yttre kant
  ctx.strokeStyle = '#1a1408';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// CABIN WINDOW — trä-ram med glas-ruta (bullets passerar igenom)
function drawCabinWindow(x, y, w, h) {
  const isHorizontal = w > h;
  // Trä-ram (mörk-brun, samma färg som cabin_wall_wood)
  ctx.fillStyle = '#3a2008';
  ctx.fillRect(x, y, w, h);
  // Glas-ruta (insättning av blå, semi-transparent)
  const insetX = isHorizontal ? 3 : 2;
  const insetY = isHorizontal ? 2 : 3;
  ctx.fillStyle = 'rgba(140, 180, 210, 0.55)';
  ctx.fillRect(x + insetX, y + insetY, w - insetX * 2, h - insetY * 2);
  // Korsmönster (vit kors-spröjs)
  ctx.fillStyle = '#7a5028';
  if (isHorizontal) {
    // Vertikal spröjs mitt
    ctx.fillRect(x + w / 2 - 1, y + insetY, 2, h - insetY * 2);
  } else {
    // Horisontell spröjs mitt
    ctx.fillRect(x + insetX, y + h / 2 - 1, w - insetX * 2, 2);
  }
  // Reflektion (vit highlight uppe vänster)
  ctx.fillStyle = 'rgba(255, 255, 255, 0.18)';
  if (isHorizontal) {
    ctx.fillRect(x + insetX + 2, y + insetY + 1, (w - insetX * 2) * 0.3, 2);
  } else {
    ctx.fillRect(x + insetX + 1, y + insetY + 2, 2, (h - insetY * 2) * 0.3);
  }
  // Yttre kant (svart)
  ctx.strokeStyle = '#1a0a04';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// === KRASCHAT UFO — lutande, fragmenterat, med rök ===
function drawUfoWreck(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  const t = performance.now() / 1000;
  ctx.save();
  // Tilta hela disken (kraschat — lutar 15°)
  ctx.translate(cx, cy);
  ctx.rotate(0.28);
  ctx.translate(-cx, -cy);
  // Marknedslag-krater under (mörk-grön/lila)
  ctx.fillStyle = 'rgba(40, 20, 60, 0.6)';
  ctx.beginPath();
  ctx.ellipse(cx, cy + r * 0.1, r * 1.2, r * 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(60, 40, 80, 0.4)';
  ctx.beginPath();
  ctx.ellipse(cx, cy + r * 0.1, r * 0.9, r * 0.35, 0, 0, Math.PI * 2);
  ctx.fill();
  // Skugga under den lutande disken
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.beginPath();
  ctx.ellipse(cx, cy + r * 0.3, r * 0.85, r * 0.18, 0, 0, Math.PI * 2);
  ctx.fill();
  // Bas-disk — DEFORMERAD (en kant kollapsad)
  const grad1 = ctx.createRadialGradient(cx - r * 0.2, cy - r * 0.2, r * 0.15, cx, cy, r);
  grad1.addColorStop(0, '#9a9aaa');
  grad1.addColorStop(0.6, '#3a3a48');
  grad1.addColorStop(1, '#1a1a28');
  ctx.fillStyle = grad1;
  ctx.beginPath();
  // Asymetrisk disk-shape (deformerad)
  ctx.moveTo(cx + r * 0.95, cy + r * 0.1);
  ctx.quadraticCurveTo(cx + r * 0.4, cy + r * 0.55, cx - r * 0.3, cy + r * 0.5);
  ctx.quadraticCurveTo(cx - r * 0.95, cy + r * 0.3, cx - r * 0.9, cy - r * 0.2);
  ctx.quadraticCurveTo(cx - r * 0.7, cy - r * 0.55, cx, cy - r * 0.65);
  ctx.quadraticCurveTo(cx + r * 0.7, cy - r * 0.55, cx + r * 0.95, cy - r * 0.1);
  ctx.closePath();
  ctx.fill();
  // Krossat kupol-glas (matt-mörk pga skadat)
  ctx.fillStyle = 'rgba(40, 100, 60, 0.6)';
  ctx.beginPath();
  ctx.ellipse(cx - r * 0.1, cy - r * 0.15, r * 0.4, r * 0.25, 0, 0, Math.PI * 2);
  ctx.fill();
  // SPRICKOR i kupolen (mer dramatic)
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.85)';
  ctx.lineWidth = 1.8;
  for (let i = 0; i < 6; i++) {
    const ang = i * Math.PI / 3;
    ctx.beginPath();
    ctx.moveTo(cx - r * 0.1, cy - r * 0.15);
    ctx.lineTo(cx - r * 0.1 + Math.cos(ang) * r * 0.4, cy - r * 0.15 + Math.sin(ang) * r * 0.25);
    ctx.stroke();
  }
  // BORTBRUTEN PANEL — visa hål i diskens högra sida (där den slog i marken)
  ctx.fillStyle = '#0a0a14';
  ctx.beginPath();
  ctx.moveTo(cx + r * 0.6, cy + r * 0.05);
  ctx.lineTo(cx + r * 0.85, cy + r * 0.15);
  ctx.lineTo(cx + r * 0.75, cy + r * 0.35);
  ctx.lineTo(cx + r * 0.5, cy + r * 0.25);
  ctx.closePath();
  ctx.fill();
  // Exponerade interna ledningar i hålet
  ctx.strokeStyle = '#ff5050';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx + r * 0.55, cy + r * 0.1); ctx.lineTo(cx + r * 0.75, cy + r * 0.25);
  ctx.stroke();
  ctx.strokeStyle = '#5050ff';
  ctx.beginPath();
  ctx.moveTo(cx + r * 0.6, cy + r * 0.2); ctx.lineTo(cx + r * 0.7, cy + r * 0.32);
  ctx.stroke();
  // Slumrande LEDs (några dåliga, andra döda)
  const pulse = 0.5 + Math.sin(t * 2) * 0.3;
  for (let i = 0; i < 6; i++) {
    const ang = (i / 6) * Math.PI * 2 + 0.3;
    const lx = cx + Math.cos(ang) * r * 0.7;
    const ly = cy + Math.sin(ang) * r * 0.45;
    // Var-tredje är död
    if (i % 3 === 0) {
      ctx.fillStyle = '#1a1a28'; // död
    } else {
      ctx.fillStyle = 'rgba(120, 255, 150, ' + (pulse * 0.6) + ')';
    }
    ctx.beginPath();
    ctx.arc(lx, ly, 2.5, 0, Math.PI * 2);
    ctx.fill();
  }
  // Paneler runt kanten
  ctx.strokeStyle = '#0a0a14';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2;
    const px = cx + Math.cos(ang) * r * 0.85;
    const py = cy + Math.sin(ang) * r * 0.5;
    ctx.beginPath();
    ctx.arc(px, py, 5, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
  // Rök från kraschen (ANIMERAT, lila-grönt)
  for (let i = 0; i < 3; i++) {
    const phase = ((t * 0.5) + i * 0.4) % 1.5;
    const yOff = -phase * 60;
    const alpha = (1 - phase / 1.5) * 0.35;
    ctx.fillStyle = 'rgba(120, 80, 140, ' + alpha + ')';
    ctx.beginPath();
    ctx.arc(cx + Math.sin(t + i) * 8, cy + yOff, 14 + phase * 8, 0, Math.PI * 2);
    ctx.fill();
  }
}

// UFO-DEBRIS — fragmenterade metallbitar från kraschen
function drawUfoDebris(x, y, w, h, seed) {
  const cx = x + w / 2, cy = y + h / 2;
  // Liten skugga
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.4, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.save();
  // Slumpmässig rotation per seed
  ctx.translate(cx, cy);
  ctx.rotate(((seed * 7) & 0xff) / 255 * Math.PI);
  ctx.translate(-cx, -cy);
  // Metallbit (oregelbunden form)
  ctx.fillStyle = '#5a5a68';
  ctx.beginPath();
  ctx.moveTo(cx - w * 0.4, cy - h * 0.2);
  ctx.lineTo(cx + w * 0.3, cy - h * 0.35);
  ctx.lineTo(cx + w * 0.4, cy + h * 0.1);
  ctx.lineTo(cx + w * 0.1, cy + h * 0.4);
  ctx.lineTo(cx - w * 0.3, cy + h * 0.3);
  ctx.closePath();
  ctx.fill();
  // Ljus framsida (highlight)
  ctx.fillStyle = '#7a7a8a';
  ctx.beginPath();
  ctx.moveTo(cx - w * 0.3, cy - h * 0.15);
  ctx.lineTo(cx + w * 0.15, cy - h * 0.25);
  ctx.lineTo(cx + w * 0.2, cy);
  ctx.lineTo(cx - w * 0.25, cy + h * 0.1);
  ctx.closePath();
  ctx.fill();
  // Brännskador (mörka fläckar)
  ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
  ctx.beginPath();
  ctx.arc(cx - w * 0.1, cy + h * 0.05, w * 0.12, 0, Math.PI * 2);
  ctx.fill();
  // Exponerade ledningar (1-2)
  ctx.strokeStyle = '#ff5050';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx + w * 0.1, cy - h * 0.1);
  ctx.lineTo(cx + w * 0.3, cy + h * 0.05);
  ctx.stroke();
  // Yttre kant
  ctx.strokeStyle = '#1a1a28';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(cx - w * 0.4, cy - h * 0.2);
  ctx.lineTo(cx + w * 0.3, cy - h * 0.35);
  ctx.lineTo(cx + w * 0.4, cy + h * 0.1);
  ctx.lineTo(cx + w * 0.1, cy + h * 0.4);
  ctx.lineTo(cx - w * 0.3, cy + h * 0.3);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

// ALIEN-CRYSTAL: lila kristall med pulserande glöd
function drawAlienCrystal(x, y, w, h, seed) {
  const cx = x + w / 2;
  const t = performance.now() / 1000;
  const pulse = 0.6 + Math.sin(t * 1.5 + (seed & 0xf)) * 0.4;
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.55, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  const grad = ctx.createRadialGradient(cx, y + h / 2, 0, cx, y + h / 2, w);
  grad.addColorStop(0, 'rgba(200, 100, 255, ' + (0.5 * pulse) + ')');
  grad.addColorStop(0.6, 'rgba(160, 60, 220, ' + (0.2 * pulse) + ')');
  grad.addColorStop(1, 'rgba(100, 30, 180, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, y + h / 2, w, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#3a1858';
  ctx.beginPath();
  ctx.moveTo(cx, y);
  ctx.lineTo(x + w * 0.85, y + h * 0.4);
  ctx.lineTo(cx, y + h);
  ctx.lineTo(x + w * 0.15, y + h * 0.4);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(180, 100, 230, ' + (0.7 + pulse * 0.3) + ')';
  ctx.beginPath();
  ctx.moveTo(cx, y + 4);
  ctx.lineTo(x + w * 0.65, y + h * 0.5);
  ctx.lineTo(cx, y + h - 4);
  ctx.lineTo(x + w * 0.35, y + h * 0.5);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 220, 255, ' + (0.5 * pulse) + ')';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.45, w * 0.15, h * 0.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#1a0828';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(cx, y);
  ctx.lineTo(x + w * 0.85, y + h * 0.4);
  ctx.lineTo(cx, y + h);
  ctx.lineTo(x + w * 0.15, y + h * 0.4);
  ctx.closePath();
  ctx.stroke();
}

// SKULL-TOTEM: trädstam med 3 skallar staplade
function drawSkullTotem(x, y, w, h, seed) {
  const cx = x + w / 2;
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(cx, y + h * 0.95, w * 0.5, h * 0.1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#3a2810';
  ctx.fillRect(x + w * 0.3, y, w * 0.4, h);
  ctx.fillStyle = '#5a3818';
  ctx.fillRect(x + w * 0.32, y, w * 0.36, h - 4);
  for (let i = 0; i < 3; i++) {
    const sy = y + h * 0.15 + i * h * 0.27;
    ctx.fillStyle = '#e0d8c0';
    ctx.beginPath();
    ctx.ellipse(cx, sy, w * 0.32, h * 0.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#1a1408';
    ctx.beginPath();
    ctx.arc(cx - w * 0.1, sy - 1, 1.5, 0, Math.PI * 2);
    ctx.arc(cx + w * 0.1, sy - 1, 1.5, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.strokeStyle = '#3a2010';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx, y + h * 0.25); ctx.lineTo(cx, y + h * 0.85);
  ctx.stroke();
}

function drawJerseyBarrier(x, y, w, h) {
  // Jersey-betongbarriär — lång låg form med sluttande sidor + reflexer
  const isHorizontal = w > h;
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.fillRect(x + 2, y + 3, w, h);
  // Bas-form: top-shadow + body + bottom-base
  if (isHorizontal) {
    // Mörk top-edge
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(x, y, w, h * 0.15);
    // Body (ljus betong med gradient)
    const grad = ctx.createLinearGradient(0, y, 0, y + h);
    grad.addColorStop(0, '#6a6a6a');
    grad.addColorStop(0.5, '#8a8a8a');
    grad.addColorStop(1, '#5a5a5a');
    ctx.fillStyle = grad;
    ctx.fillRect(x, y + h * 0.15, w, h * 0.75);
    // Botten-bas (mörkare — bredare än top)
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(x, y + h * 0.9, w, h * 0.1);
    // Concrete-texture (random svaga prickar)
    const baSeed = ((x * 7) ^ (y * 11)) | 0;
    ctx.fillStyle = '#4a4a4a';
    for (let i = 0; i < w / 5; i++) {
      const dx = (baSeed * (i + 1) * 17) % w;
      const dy = ((baSeed * (i + 3)) % (h * 70)) / 100 + h * 0.2;
      ctx.fillRect(x + dx, y + dy, 1, 1);
    }
    // Diagonal reflex-streck (svart-gul varning)
    for (let i = 0; i < w; i += 16) {
      ctx.fillStyle = '#ffd54a';
      ctx.fillRect(x + i, y + h * 0.35, 8, 4);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x + i + 8, y + h * 0.35, 8, 4);
    }
    // Top edge highlight
    ctx.fillStyle = '#9a9a9a';
    ctx.fillRect(x, y + h * 0.15, w, 0.8);
    // Concrete-skarvar (var ~80px segment)
    ctx.strokeStyle = 'rgba(20, 20, 20, 0.6)';
    ctx.lineWidth = 1;
    for (let i = 80; i < w; i += 80) {
      ctx.beginPath();
      ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + h);
      ctx.stroke();
    }
  } else {
    // Vertikal version
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(x, y, w * 0.15, h);
    const grad = ctx.createLinearGradient(x, 0, x + w, 0);
    grad.addColorStop(0, '#6a6a6a');
    grad.addColorStop(0.5, '#8a8a8a');
    grad.addColorStop(1, '#5a5a5a');
    ctx.fillStyle = grad;
    ctx.fillRect(x + w * 0.15, y, w * 0.75, h);
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(x + w * 0.9, y, w * 0.1, h);
    for (let i = 0; i < h; i += 16) {
      ctx.fillStyle = '#ffd54a';
      ctx.fillRect(x + w * 0.35, y + i, 4, 8);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x + w * 0.35, y + i + 8, 4, 8);
    }
  }
  // Yttre outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

function drawTaggedPillar(x, y, w, h, seed) {
  // Tagged pelare — vanlig pelare med stor röd graffiti-tag
  drawPillar(x, y, w, h, seed);
  ctx.save();
  // Stor röd graffiti-tag (kryss / JUG-symbol)
  ctx.translate(x + w / 2, y + h / 2);
  ctx.font = 'italic 900 ' + Math.min(w, h) * 0.55 + 'px Impact, "Arial Black", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = '#aa0000'; ctx.shadowBlur = 4;
  ctx.fillStyle = '#ff3030';
  ctx.fillText('JUG', 0, 0);
  ctx.shadowBlur = 0;
  // Spray-drips
  ctx.fillStyle = '#ff3030';
  ctx.fillRect(-w * 0.2, h * 0.05, 1, 6);
  ctx.fillRect(w * 0.15, h * 0.05, 1, 4);
  ctx.beginPath(); ctx.arc(-w * 0.2 + 0.5, h * 0.05 + 7, 1.2, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

// Linjär färgblandning. Stöder #rgb, #rrggbb. t=0→a, t=1→b.
function mixColors(a, b, t) {
  const parseHex = (h) => {
    if (!h || h[0] !== '#') return [255, 255, 255];
    const s = h.length === 4 ? h[1]+h[1]+h[2]+h[2]+h[3]+h[3] : h.slice(1);
    return [parseInt(s.substr(0,2),16), parseInt(s.substr(2,2),16), parseInt(s.substr(4,2),16)];
  };
  const [ar, ag, ab] = parseHex(a);
  const [br, bg, bb] = parseHex(b);
  const mix = (x, y) => Math.round(x + (y - x) * t);
  return 'rgb(' + mix(ar, br) + ',' + mix(ag, bg) + ',' + mix(ab, bb) + ')';
}

// CTF: rita decorations — skyltar, klotter, lyktor, små flaggor.
// Ingen collision, bara visuell flavor. Renderas under walls.
function drawCtfDecorations() {
  const decos = state.ctfDecorations;
  if (!decos || !decos.length) return;
  // Avrunda kameran så decorations inte vobblar vid kamera-pan (sub-pixel rendering).
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const d of decos) {
    const x = d.x - cx, y = d.y - cy;
    // Cull (med marginal för rot/text-bounds)
    if (x < -200 || x > viewW + 200 || y < -100 || y > viewH + 100) continue;
    ctx.save();
    if (d.kind === 'sign') {
      const w = d.w || 120, h = d.h || 28;
      ctx.translate(x + w / 2, y + h / 2);
      if (d.rot) ctx.rotate(d.rot);
      // Skylt-bakgrund
      ctx.fillStyle = d.bg || '#222';
      ctx.fillRect(-w / 2, -h / 2, w, h);
      ctx.strokeStyle = d.fg || '#ffd54a';
      ctx.lineWidth = 2;
      ctx.strokeRect(-w / 2 + 0.5, -h / 2 + 0.5, w - 1, h - 1);
      // Skylt-text (stöder \n)
      ctx.fillStyle = d.fg || '#ffd54a';
      const fontSize = d.size || Math.min(h - 8, 14);
      ctx.font = 'bold ' + fontSize + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const lines = String(d.text || '').split('\n');
      const lineH = fontSize + 2;
      const startY = -(lines.length - 1) * lineH / 2;
      for (let li = 0; li < lines.length; li++) {
        ctx.fillText(lines[li], 0, startY + li * lineH);
      }
      // Nedhängande "kedja"-look längs ovansidan så det ser fastsatt ut
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(-w / 2 - 2, -h / 2 - 4, 3, 4);
      ctx.fillRect(w / 2 - 1, -h / 2 - 4, 3, 4);
    } else if (d.kind === 'graffiti') {
      ctx.translate(x, y);
      if (d.rot) ctx.rotate(d.rot);
      const fontSize = d.size || 16;
      const text = d.text || '';
      const baseColor = d.color || '#fff';
      // Realistic spray-paint: 5 lager + drips
      // Använd condensed font för "tag"-känsla
      ctx.font = 'italic 900 ' + fontSize + 'px "Impact","Arial Black",sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      // Mät för drips
      const metrics = ctx.measureText(text);
      const textW = metrics.width;
      // Layer 1: overspray haze runt hela texten (mörk halo)
      ctx.save();
      ctx.shadowColor = baseColor;
      ctx.shadowBlur = fontSize * 0.6;
      ctx.globalAlpha = 0.35;
      ctx.fillStyle = baseColor;
      ctx.fillText(text, 0, 0);
      ctx.restore();
      // Layer 2: tjock svart outline (kontur som ett tag)
      ctx.strokeStyle = '#000';
      ctx.lineWidth = Math.max(3, fontSize * 0.18);
      ctx.lineJoin = 'round';
      ctx.miterLimit = 2;
      ctx.globalAlpha = 0.85;
      ctx.strokeText(text, 0, 0);
      // Layer 3: huvudfärg fyllning
      ctx.fillStyle = baseColor;
      ctx.globalAlpha = 0.95;
      ctx.fillText(text, 0, 0);
      // Layer 4: ljusare highlight inom (upper-left, klassisk tag-style)
      ctx.fillStyle = mixColors(baseColor, '#ffffff', 0.45);
      ctx.globalAlpha = 0.55;
      ctx.fillText(text, -1, -1.5);
      // Layer 5: drips — droppar som rinner ner från bokstäver (deterministic hash)
      ctx.globalAlpha = 0.9;
      ctx.fillStyle = baseColor;
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      const dripHash = ((d.x * 13) | 0) + ((d.y * 7) | 0);
      const charSpacing = textW / Math.max(1, text.length);
      const numDrips = 2 + ((dripHash >> 3) & 0x3); // 2-5 drips
      for (let i = 0; i < numDrips; i++) {
        const charIdx = ((dripHash >> (i * 3)) & 0xff) % text.length;
        const dripX = charIdx * charSpacing + ((dripHash * (i + 1)) & 0xf) - 8;
        const dripLen = fontSize * 0.3 + ((dripHash >> i) & 0xf) * 0.8;
        const dropR = Math.max(1.5, fontSize * 0.08);
        // Vertikal streak
        ctx.fillRect(dripX, fontSize * 0.3, 1.5, dripLen);
        // Droppe i botten
        ctx.beginPath();
        ctx.arc(dripX + 0.75, fontSize * 0.3 + dripLen + dropR * 0.5, dropR, 0, Math.PI * 2);
        ctx.fill();
        // Subtil outline på droppen
        ctx.beginPath();
        ctx.arc(dripX + 0.75, fontSize * 0.3 + dripLen + dropR * 0.5, dropR, 0, Math.PI * 2);
        ctx.stroke();
      }
      // Layer 6: spray-dust speckles (små prickar runt texten)
      ctx.fillStyle = baseColor;
      ctx.globalAlpha = 0.6;
      const numSpeckles = 12 + ((dripHash >> 5) & 0x7);
      for (let i = 0; i < numSpeckles; i++) {
        const sx = ((dripHash * (i + 11)) & 0xff) / 255 * (textW + 30) - 15;
        const sy = (((dripHash >> 2) * (i + 7)) & 0xff) / 255 * (fontSize * 1.8) - fontSize * 0.7;
        const sr = 0.6 + (i & 1) * 0.4;
        ctx.beginPath();
        ctx.arc(sx, sy, sr, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    } else if (d.kind === 'flag_decoration') {
      // En riktig flagga: hög stolpe + topp-knopp + rektangulär våg-flagga med
      // animation. Mörk team-färg + ljusare highlight + svart kant + stjärna.
      const color = d.team === 'red' ? '#dd2020' : '#2050ff';
      const colorDark = d.team === 'red' ? '#8a0a0a' : '#0a2080';
      const colorLight = d.team === 'red' ? '#ff7070' : '#7090ff';
      // Hög stolpe (silver med träbas)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 1, y - 40, 2, 50);
      // Topp-knopp (gylne sphere)
      ctx.fillStyle = '#ffd54a';
      ctx.beginPath();
      ctx.arc(x, y - 41, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.8;
      ctx.stroke();
      // Flagga: rektangulär med wave-effekt (segmenterad så den ser ut att fladdra)
      const flagW = 24;
      const flagH = 16;
      const flagTop = y - 38;
      const segments = 4;
      const segW = flagW / segments;
      // Bakgrund (mörk skugga under flagga)
      ctx.fillStyle = colorDark;
      ctx.beginPath();
      let py0 = flagTop;
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + wave);
        else ctx.lineTo(px, py0 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Huvudfärg (samma form, lite mindre)
      ctx.fillStyle = color;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + 1 + wave);
        else ctx.lineTo(px, py0 + 1 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH - 1 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Ljusare topp-highlight
      ctx.fillStyle = colorLight;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + 1 + wave);
        else ctx.lineTo(px, py0 + 1 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + 4 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Star i mitten (vit, klassisk team-symbol)
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000';
      ctx.shadowBlur = 1;
      const starWave = Math.sin(t / 200 + segments * 0.3) * 2;
      ctx.fillText('★', x + 1 + flagW * 0.5, flagTop + flagH * 0.5 + starWave);
      ctx.shadowBlur = 0;
      // Kant runt flaggan
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + wave);
        else ctx.lineTo(px, py0 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH + wave);
      }
      ctx.closePath();
      ctx.stroke();
    } else if (d.kind === 'lantern') {
      const color = d.color || '#ffb84a';
      // Glow
      const pulse = 0.6 + Math.sin(t / 380 + (x + y) * 0.001) * 0.4;
      const grad = ctx.createRadialGradient(x, y, 4, x, y, 60);
      grad.addColorStop(0, color);
      grad.addColorStop(0.4, color + '44');
      grad.addColorStop(1, 'transparent');
      ctx.globalAlpha = 0.45 * pulse;
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, 60, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      // Lyktans bas
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 4, y - 6, 8, 12);
      ctx.fillStyle = color;
      ctx.fillRect(x - 3, y - 5, 6, 10);
    }
    ctx.restore();
  }
}

// CTF: rita turrets — bas + roterande pipa + hp-bar + förstörd-version
function drawCtfTurrets() {
  if (!state.ctfTurrets) return;
  // Avrunda kameran så turret-baser inte vobblar vid kamera-pan
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.ctfTurrets)) {
    const tur = state.ctfTurrets[id];
    const x = tur.x - cx, y = tur.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    const teamColor = tur.team === 'red' ? '#ff5a5a' : '#5aaaff';
    if (tur.destroyed) {
      // Förstörd: mörk vrak + flickering eld + rök-partiklar (spawnas av tick i runFrame)
      ctx.fillStyle = '#222';
      ctx.beginPath();
      ctx.arc(x, y, 24, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#444';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Flickering eld
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.6})`;
      ctx.beginPath();
      ctx.arc(x + (Math.random() - 0.5) * 8, y + (Math.random() - 0.5) * 8, 8 + Math.random() * 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = `rgba(255,200,60,${flicker * 0.4})`;
      ctx.beginPath();
      ctx.arc(x + (Math.random() - 0.5) * 4, y + (Math.random() - 0.5) * 4, 4 + Math.random() * 3, 0, Math.PI * 2);
      ctx.fill();
      // Spawna rök-partiklar då och då
      if (state.particles && state.particles.length < 200 && Math.random() < 0.15) {
        state.particles.push({
          x: tur.x + (Math.random() - 0.5) * 16,
          y: tur.y + (Math.random() - 0.5) * 16,
          vx: (Math.random() - 0.5) * 20,
          vy: -30 - Math.random() * 30,
          life: 1.2 + Math.random() * 0.8,
          color: 'rgba(80,80,80,0.5)',
          r: 8 + Math.random() * 4,
          isExplosion: true,
        });
      }
      // Rebuild-progress-ring: grön båge när team-spelare står och repar
      const p = tur.rebuildProgress || 0;
      if (p > 0) {
        ctx.lineWidth = 4;
        // Bakgrunds-spår
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.beginPath();
        ctx.arc(x, y, 32, 0, Math.PI * 2);
        ctx.stroke();
        // Progress
        ctx.strokeStyle = '#5aff5a';
        ctx.shadowColor = '#5aff5a';
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(x, y, 32, -Math.PI / 2, -Math.PI / 2 + p * Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        // Tid kvar (sekunder)
        const sLeft = Math.ceil((1 - p) * 20);
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(sLeft + 's', x, y - 40);
      }
    } else {
      // Aktiv: bas-cirkel
      ctx.fillStyle = '#333';
      ctx.beginPath();
      ctx.arc(x, y, tur.r, 0, Math.PI * 2);
      ctx.fill();
      // Lag-färgad ring
      ctx.strokeStyle = teamColor;
      ctx.lineWidth = 3;
      ctx.stroke();
      // Inner-detalj (turret-bas-skiva)
      ctx.fillStyle = '#555';
      ctx.beginPath();
      ctx.arc(x, y, tur.r * 0.65, 0, Math.PI * 2);
      ctx.fill();
      // Pipa — roterar mot occupants aim (vi har inte den, så vi pekar mot mid-arena)
      const aim = tur.aim || 0; // server kan skicka detta senare; tills då pekar mot mitten
      const dirX = Math.cos(aim), dirY = Math.sin(aim);
      ctx.strokeStyle = '#222';
      ctx.lineWidth = 8;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + dirX * (tur.r + 10), y + dirY * (tur.r + 10));
      ctx.stroke();
      ctx.lineCap = 'butt';
      // Occupant-indikator
      if (tur.occupantId) {
        const pulse = 0.6 + Math.sin(t / 200) * 0.4;
        ctx.fillStyle = `rgba(255,213,74,${pulse})`;
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
      }
      // HP-bar ovanför om skadad
      if (tur.hp < tur.maxHp) {
        const bw = 50;
        const hpFrac = Math.max(0, tur.hp / tur.maxHp);
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(x - bw / 2 - 1, y - tur.r - 16, bw + 2, 7);
        ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
        ctx.fillRect(x - bw / 2, y - tur.r - 15, bw * hpFrac, 5);
      }
    }
    ctx.restore();
  }
}

// CTF: rita walls — använd detaljerade drawPvpWalls med pixel-art per kind.
// Tidigare var detta en separat simpel version som ALDRIG anropade
// drawPvpWalls → nya detaljerade grafiken syntes aldrig.
function drawCtfWalls() {
  drawPvpWalls(state.ctfWalls);
}

// CTF: rita flag-stands + dropped flags + carrier-flagga ovanför bärare
function drawCtfFlags() {
  const flags = state.ctfFlags;
  if (!flags) return;
  // Avrunda kameran så flag-stands inte vobblar vid kamera-pan
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  const pulse = 0.7 + Math.sin(t / 250) * 0.3;
  ctx.save();

  const drawFlagStand = (team, f) => {
    const x = f.baseX - cx, y = f.baseY - cy;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    // Capture-zon ring (alltid synlig)
    ctx.strokeStyle = team === 'red' ? 'rgba(255,90,90,0.35)' : 'rgba(90,170,255,0.35)';
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 6]);
    ctx.beginPath();
    ctx.arc(x, y, state.ctfCaptureRadius || 50, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    // Pulserande glow när flagga är hemma
    if (f.atBase) {
      const glowR = 32 + pulse * 8;
      const grad = ctx.createRadialGradient(x, y, 8, x, y, glowR);
      grad.addColorStop(0, team === 'red' ? 'rgba(255,90,90,0.55)' : 'rgba(90,170,255,0.55)');
      grad.addColorStop(1, team === 'red' ? 'rgba(255,90,90,0)' : 'rgba(90,170,255,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, glowR, 0, Math.PI * 2);
      ctx.fill();
    }
    // Stor stolpe (hög + tjock, snyggare än tunn rektangel)
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(x - 2, y - 38, 4, 60);
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 0.6;
    ctx.strokeRect(x - 2, y - 38, 4, 60);
    // Topp-knopp (gylne sphere)
    ctx.fillStyle = '#ffd54a';
    ctx.beginPath();
    ctx.arc(x, y - 40, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    // Cirkulär bas-platta (hexagonal-look)
    const colorDark = team === 'red' ? '#5a1010' : '#102050';
    ctx.fillStyle = colorDark;
    ctx.beginPath();
    ctx.arc(x, y + 24, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y + 24, 11, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // Team-emblem på basen (☆)
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('★', x, y + 24);
    // Stor flagga med wave-segment, kant och stjärna (samma stil som flag_decoration)
    if (f.atBase) {
      const colorLight = team === 'red' ? '#ff7070' : '#7090ff';
      const flagW = 36;
      const flagH = 26;
      const flagTop = y - 36;
      const segments = 5;
      const segW = flagW / segments;
      // Skugga
      ctx.fillStyle = colorDark;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + wave);
        else ctx.lineTo(px, flagTop + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Huvudfärg
      ctx.fillStyle = color;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + 1.5 + wave);
        else ctx.lineTo(px, flagTop + 1.5 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH - 1.5 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Top-highlight
      ctx.fillStyle = colorLight;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + 1.5 + wave);
        else ctx.lineTo(px, flagTop + 1.5 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + 6 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Stjärna i mitten
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 16px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000';
      ctx.shadowBlur = 2;
      const starWave = Math.sin(t / 180 + segments * 0.27) * 3;
      ctx.fillText('★', x + 2 + flagW * 0.5, flagTop + flagH * 0.5 + starWave);
      ctx.shadowBlur = 0;
      // Kant
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + wave);
        else ctx.lineTo(px, flagTop + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH + wave);
      }
      ctx.closePath();
      ctx.stroke();
    }
  };

  const drawDroppedFlag = (team, f) => {
    const x = f.x - cx, y = f.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    // Auto-return countdown ring (30s)
    const droppedAge = f.droppedAt ? (t - f.droppedAt) / 1000 : 0;
    const timeLeft = Math.max(0, 30 - droppedAge);
    const frac = timeLeft / 30;
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.arc(x, y, 18, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
    // Pulserande glow
    const glowR = 14 + pulse * 4;
    const grad = ctx.createRadialGradient(x, y, 4, x, y, glowR);
    grad.addColorStop(0, team === 'red' ? 'rgba(255,90,90,0.8)' : 'rgba(90,170,255,0.8)');
    grad.addColorStop(1, team === 'red' ? 'rgba(255,90,90,0)' : 'rgba(90,170,255,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, glowR, 0, Math.PI * 2);
    ctx.fill();
    // Flag-emoji + tyg
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - 2, y - 8);
    ctx.lineTo(x + 12, y - 4);
    ctx.lineTo(x - 2, y);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = '#3a2a1a';
    ctx.fillRect(x - 3, y - 9, 2, 18);
  };

  const drawCarrierFlag = (team, carrierId) => {
    let carrier = null;
    if (carrierId === Coop.myId && state.player) carrier = state.player;
    else if (Coop.players && Coop.players.has(carrierId)) carrier = Coop.players.get(carrierId);
    if (!carrier || carrier.x === undefined) return;
    const x = carrier.x - cx, y = carrier.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    const wave = Math.sin(t / 150) * 3;
    // Flagga ovanför huvudet
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - 24);
    ctx.lineTo(x + 16 + wave, y - 20);
    ctx.lineTo(x, y - 16);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    // Stolpe
    ctx.fillStyle = '#3a2a1a';
    ctx.fillRect(x - 1, y - 26, 2, 14);
    // Trail (partiklar i lagets färg)
    if ((carrier._trailTimer === undefined || t - carrier._trailTimer > 80)) {
      carrier._trailTimer = t;
      if (state.particles && state.particles.length < 200) {
        state.particles.push({
          x: carrier.x, y: carrier.y + 8, vx: 0, vy: 0, life: 0.55,
          color: team === 'red' ? 'rgba(255,90,90,0.7)' : 'rgba(90,170,255,0.7)',
          r: 5, isBloodPool: true,
        });
      }
    }
  };

  // Stands (alltid rita) + dropped/carrier (per state)
  for (const team of ['red', 'blue']) {
    const f = flags[team];
    if (!f) continue;
    drawFlagStand(team, f);
    if (f.carrierId) drawCarrierFlag(team, f.carrierId);
    else if (!f.atBase) drawDroppedFlag(team, f);
  }
  ctx.restore();
}

// Helper: rita en rounded-rect path (canvas-roundRect-shim).
function drawRoundedRect(c, x, y, w, h, r) {
  if (typeof c.roundRect === 'function') {
    c.beginPath();
    c.roundRect(x, y, w, h, r);
    return;
  }
  c.beginPath();
  c.moveTo(x + r, y);
  c.lineTo(x + w - r, y);
  c.quadraticCurveTo(x + w, y, x + w, y + r);
  c.lineTo(x + w, y + h - r);
  c.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  c.lineTo(x + r, y + h);
  c.quadraticCurveTo(x, y + h, x, y + h - r);
  c.lineTo(x, y + r);
  c.quadraticCurveTo(x, y, x + r, y);
  c.closePath();
}

// PvP-pickups (HP-regen + shield-regen) — rita pulserande ikoner på arenan.
// Tillgängliga = full färg + pulse, otillgängliga = tonad ghost.
function drawPvpPickups() {
  const cx = state.camera.x, cy = state.camera.y;
  const t = performance.now();
  const pulse = 0.7 + Math.sin(t / 250) * 0.3;
  ctx.save();
  for (const id of Object.keys(state.pvpPickups)) {
    const pu = state.pvpPickups[id];
    const x = pu.x - cx, y = pu.y - cy;
    if (x < -30 || x > viewW + 30 || y < -30 || y > viewH + 30) continue;
    if (!pu.available) continue;
    const isHp = pu.type === 'hp';
    const isShield = pu.type === 'shield';
    const isGrenade = pu.type === 'grenade';
    // Glow-färg per typ
    let glowColor;
    if (isHp) glowColor = 'rgba(90,255,90,0.55)';
    else if (isShield) glowColor = 'rgba(58,202,255,0.55)';
    else if (isGrenade) glowColor = 'rgba(255,170,60,0.55)';
    else glowColor = 'rgba(180,180,180,0.55)';
    const glowR = 18 + pulse * 6;
    const grad = ctx.createRadialGradient(x, y, 4, x, y, glowR);
    grad.addColorStop(0, glowColor);
    grad.addColorStop(1, glowColor.replace(/0\.55\)/, '0)'));
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, glowR, 0, Math.PI * 2);
    ctx.fill();
    // v1.371: PROFESSIONELLA ikoner — gradient fill, rim, highlight, drop-shadow
    ctx.save();
    ctx.translate(x, y);
    // Ground-shadow (alla pickups)
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath();
    ctx.ellipse(0, 9, 11, 4, 0, 0, Math.PI * 2);
    ctx.fill();
    if (isHp) {
      // ============ MED-KIT — vit kropp med röd kors + gradient + glow ============
      // Outer rim (mörk röd outline)
      ctx.fillStyle = '#7a0a0a';
      drawRoundedRect(ctx, -11, -10, 22, 20, 4);
      ctx.fill();
      // Inner body (vit gradient)
      const bodyGrad = ctx.createLinearGradient(0, -8, 0, 8);
      bodyGrad.addColorStop(0, '#ffffff');
      bodyGrad.addColorStop(0.5, '#f0f0f0');
      bodyGrad.addColorStop(1, '#c8c8c8');
      ctx.fillStyle = bodyGrad;
      drawRoundedRect(ctx, -9, -8, 18, 16, 3);
      ctx.fill();
      // Topp-highlight (glansrand)
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      drawRoundedRect(ctx, -8, -7, 16, 5, 2);
      ctx.fill();
      // Röda kors med gradient
      const crossGrad = ctx.createLinearGradient(0, -7, 0, 7);
      crossGrad.addColorStop(0, '#ff4a4a');
      crossGrad.addColorStop(1, '#c81818');
      ctx.fillStyle = crossGrad;
      // Horizontal bar
      drawRoundedRect(ctx, -7, -2, 14, 4, 1);
      ctx.fill();
      // Vertical bar
      drawRoundedRect(ctx, -2, -7, 4, 14, 1);
      ctx.fill();
      // Kors-stroke (subtil mörkröd kantlinje)
      ctx.strokeStyle = 'rgba(120,0,0,0.6)';
      ctx.lineWidth = 0.8;
      drawRoundedRect(ctx, -7, -2, 14, 4, 1);
      ctx.stroke();
      drawRoundedRect(ctx, -2, -7, 4, 14, 1);
      ctx.stroke();
    } else if (isShield) {
      // ============ ENERGY-SHIELD — hexagonal kärna + glödande ring ============
      // Yttre glöd-ring
      ctx.strokeStyle = 'rgba(80,200,255,0.65)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, 12, 0, Math.PI * 2);
      ctx.stroke();
      // Shield-shape (klassisk pointed-bottom shield)
      ctx.beginPath();
      ctx.moveTo(0, -11);
      ctx.lineTo(9, -7);
      ctx.lineTo(9, 3);
      ctx.quadraticCurveTo(9, 9, 0, 12);
      ctx.quadraticCurveTo(-9, 9, -9, 3);
      ctx.lineTo(-9, -7);
      ctx.closePath();
      // Fyllning (blå gradient)
      const shieldGrad = ctx.createLinearGradient(0, -11, 0, 12);
      shieldGrad.addColorStop(0, '#7adcff');
      shieldGrad.addColorStop(0.45, '#3a9aff');
      shieldGrad.addColorStop(1, '#1a4ab8');
      ctx.fillStyle = shieldGrad;
      ctx.fill();
      // Outline
      ctx.strokeStyle = '#0a2a5a';
      ctx.lineWidth = 1.4;
      ctx.stroke();
      // Inner highlight (top-left bevel)
      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      ctx.beginPath();
      ctx.moveTo(-7, -7);
      ctx.lineTo(0, -9);
      ctx.lineTo(4, -6);
      ctx.lineTo(-3, -2);
      ctx.closePath();
      ctx.fill();
      // Center "energy-bolt"
      ctx.strokeStyle = 'rgba(255,255,255,0.95)';
      ctx.lineWidth = 1.4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(-2, -5);
      ctx.lineTo(2, -1);
      ctx.lineTo(-1, 1);
      ctx.lineTo(2, 6);
      ctx.stroke();
    } else if (isGrenade) {
      // ============ GRENADE — metallic body + glödande topp + pin ============
      // Body shadow base
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      ctx.beginPath();
      ctx.ellipse(0.5, 3, 7.5, 8.5, 0, 0, Math.PI * 2);
      ctx.fill();
      // Body (oval) med metallic radial gradient
      const bodyGrad = ctx.createRadialGradient(-2, -1, 1, 0, 2, 9);
      bodyGrad.addColorStop(0, '#5a7a4a');
      bodyGrad.addColorStop(0.5, '#3a5a30');
      bodyGrad.addColorStop(1, '#1a2a18');
      ctx.fillStyle = bodyGrad;
      ctx.beginPath();
      ctx.ellipse(0, 2, 7, 8, 0, 0, Math.PI * 2);
      ctx.fill();
      // Cross-hatch grooves (subtle)
      ctx.strokeStyle = 'rgba(20,30,15,0.65)';
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(-6, -1); ctx.lineTo(6, -1);
      ctx.moveTo(-6, 3); ctx.lineTo(6, 3);
      ctx.moveTo(-6, 7); ctx.lineTo(6, 7);
      ctx.stroke();
      // Body outline
      ctx.strokeStyle = '#0a1208';
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.ellipse(0, 2, 7, 8, 0, 0, Math.PI * 2);
      ctx.stroke();
      // Top highlight (glans på övre vänster)
      ctx.fillStyle = 'rgba(180,220,150,0.55)';
      ctx.beginPath();
      ctx.ellipse(-2.5, -2, 2.2, 3, -0.3, 0, Math.PI * 2);
      ctx.fill();
      // Metal cap (top)
      const capGrad = ctx.createLinearGradient(0, -8, 0, -5);
      capGrad.addColorStop(0, '#a08868');
      capGrad.addColorStop(1, '#4a3018');
      ctx.fillStyle = capGrad;
      drawRoundedRect(ctx, -3, -8.5, 6, 3.5, 1);
      ctx.fill();
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 0.8;
      drawRoundedRect(ctx, -3, -8.5, 6, 3.5, 1);
      ctx.stroke();
      // Pull-pin (metal ring + wire)
      ctx.strokeStyle = '#d8d8d8';
      ctx.lineWidth = 1.3;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-2.5, -7);
      ctx.quadraticCurveTo(-7, -9, -8.5, -11);
      ctx.stroke();
      ctx.strokeStyle = '#e8e8e8';
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.arc(-8.5, -11, 2, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }
  ctx.restore();
}

// PvP shield-bubble: rita runt spelare som är immuna. Visas för mig + alla
// partners som har aktiv shield. Renderas i alla PvP-lägen.
function drawPvpShieldBubbles() {
  const now = performance.now();
  const draw = (wx, wy) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) return;
    const pulse = 0.7 + Math.sin(now / 120) * 0.3;
    ctx.save();
    // Outer ring
    ctx.strokeStyle = `rgba(140,255,200,${0.55 * pulse})`;
    ctx.lineWidth = 3;
    ctx.shadowColor = '#5aff9a';
    ctx.shadowBlur = 18 * pulse;
    ctx.beginPath();
    ctx.arc(x, y, 26, 0, Math.PI * 2);
    ctx.stroke();
    // Inner glow
    const grad = ctx.createRadialGradient(x, y, 8, x, y, 26);
    grad.addColorStop(0, `rgba(140,255,200,${0.18 * pulse})`);
    grad.addColorStop(1, 'rgba(140,255,200,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, 26, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };
  if (state.player && state.player.pvpShieldUntil && now < state.player.pvpShieldUntil) {
    draw(state.player.x, state.player.y);
  }
  if (typeof Coop !== 'undefined' && Coop.players) {
    for (const [, p] of Coop.players) {
      if (p.pvpShieldUntil && now < p.pvpShieldUntil && p.x !== undefined) {
        draw(p.x, p.y);
      }
    }
  }
}

// CTF: rita hold-to-return progress-ring runt spelaren när de håller över egen dropped-flag
function drawCtfReturnHold() {
  const hold = state.ctfReturnHold;
  if (!hold || !state.player) return;
  const elapsed = performance.now() - hold.startAt;
  const frac = Math.min(1, elapsed / (hold.durationMs || 1000));
  const px = state.player.x - state.camera.x;
  const py = state.player.y - state.camera.y;
  const color = hold.team === 'red' ? '#ff5a5a' : '#5aaaff';
  ctx.save();
  // Outer ring (track)
  ctx.strokeStyle = 'rgba(255,255,255,0.18)';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(px, py, 26, 0, Math.PI * 2);
  ctx.stroke();
  // Progress arc
  ctx.strokeStyle = color;
  ctx.lineWidth = 4;
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.arc(px, py, 26, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
  ctx.stroke();
  // Label
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowBlur = 4;
  ctx.shadowColor = '#000';
  ctx.fillText('RETUR ' + Math.round(frac * 100) + '%', px, py - 38);
  ctx.restore();
}

// CTF: HUD-banner när FIENDEN bär min flagga (defenders behöver veta) + arrow mot carrier
function drawCtfStolenFlagAlert() {
  if (!state.ctfFlags || !Coop.ctfTeams) return;
  const myTeam = Coop.ctfTeams[Coop.myId];
  if (!myTeam) return;
  const myFlag = state.ctfFlags[myTeam];
  if (!myFlag || !myFlag.carrierId) return;
  const carrierId = myFlag.carrierId;
  let carrier = null;
  if (carrierId === Coop.myId && state.player) carrier = state.player;
  else if (Coop.players && Coop.players.has(carrierId)) carrier = Coop.players.get(carrierId);
  if (!carrier || carrier.x === undefined) return;
  const carrierName = (Coop.players.get(carrierId) && Coop.players.get(carrierId).name) || 'Fiende';
  const color = myTeam === 'red' ? '#ff5a5a' : '#5aaaff';

  ctx.save();
  // Banner top-center (just under score-bar)
  const bannerY = 84;
  const pulse = 0.85 + Math.sin(performance.now() / 180) * 0.15;
  ctx.globalAlpha = pulse;
  ctx.fillStyle = 'rgba(0,0,0,0.78)';
  const text = '⚠ ' + carrierName.toUpperCase() + ' STAL ER FLAGGA!';
  ctx.font = 'bold 13px sans-serif';
  const w = ctx.measureText(text).width + 24;
  ctx.fillRect(viewW / 2 - w / 2, bannerY, w, 26);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(viewW / 2 - w / 2, bannerY, w, 26);
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, viewW / 2, bannerY + 13);
  ctx.globalAlpha = 1;

  // Directional arrow mot carrier (om utanför skärm) — pekar från player mot carrier
  const px = state.player ? state.player.x - state.camera.x : viewW / 2;
  const py = state.player ? state.player.y - state.camera.y : viewH / 2;
  const cx = carrier.x - state.camera.x;
  const cy = carrier.y - state.camera.y;
  const offScreen = cx < 30 || cx > viewW - 30 || cy < 30 || cy > viewH - 30;
  if (offScreen && state.player) {
    const ang = Math.atan2(cy - py, cx - px);
    const r = Math.min(viewW, viewH) * 0.32;
    const ax = viewW / 2 + Math.cos(ang) * r;
    const ay = viewH / 2 + Math.sin(ang) * r;
    ctx.save();
    ctx.translate(ax, ay);
    ctx.rotate(ang);
    ctx.fillStyle = color;
    ctx.shadowColor = color;
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.moveTo(18, 0);
    ctx.lineTo(-8, -10);
    ctx.lineTo(-8, 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

// SIEGE — decorations använder samma renderer som CTF (samma data-format)
function drawSiegeDecorations() {
  if (!state.siegeDecorations || !state.siegeDecorations.length) return;
  // Tillfälligt swap state.ctfDecorations så vi kan återanvända drawCtfDecorations.
  // Try/finally så swap restoreas även om drawCtfDecorations throwar.
  const saved = state.ctfDecorations;
  state.ctfDecorations = state.siegeDecorations;
  try { drawCtfDecorations(); }
  finally { state.ctfDecorations = saved; }
}

// JUGGERNAUT-dedikerad decoration-render. Hanterar alla parking-garage-
// specifika dekoration-typer (flicker_light, puddle, fire_drum, drain,
// caution_tape, parking_lines, shopping_cart, abandoned_bag, warning_triangle).
// Sign + graffiti faller tillbaka till drawCtfDecorations.
function drawJuggernautDecorations(decos) {
  if (!decos || !decos.length) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  // Sortera så vi ritar markdekor (puddle/parking_lines/drain) FÖRE höjd-element
  // (fire_drum/shopping_cart) — annars hamnar pölar ovanpå objekt.
  const groundKinds = ['puddle', 'parking_lines', 'drain', 'caution_tape'];
  const ordered = [];
  for (const d of decos) if (groundKinds.indexOf(d.kind) >= 0) ordered.push(d);
  for (const d of decos) if (groundKinds.indexOf(d.kind) < 0) ordered.push(d);
  // CTF-decoration-fallback-kinds (sign + graffiti) — låt drawCtfDecorations
  // hantera dem. Vi behöver swappa in vår array kortvarigt.
  const ctfFallbackKinds = ['sign', 'graffiti', 'flag_decoration', 'lantern'];
  for (const d of ordered) {
    if (ctfFallbackKinds.indexOf(d.kind) >= 0) continue; // hanteras nedan
    const x = d.x - cx, y = d.y - cy;
    // Cull-check: ceiling_pipe + ceiling_pipe_v + cable_bundle har bredd/höjd
    // som sträcker sig långt från x/y, så bounds-check måste inkludera w/h.
    if (d.kind === 'ceiling_pipe') {
      const w = d.w || 1000;
      if (x + w < -50 || x > viewW + 50 || y < -50 || y > viewH + 50) continue;
    } else if (d.kind === 'ceiling_pipe_v') {
      const h = d.h || 1000;
      if (y + h < -50 || y > viewH + 50 || x < -50 || x > viewW + 50) continue;
    } else if (d.kind === 'cable_bundle') {
      const x2s = (d.x2 || d.x + 200) - cx;
      const y2s = (d.y2 || d.y) - cy;
      const minX = Math.min(x, x2s), maxX = Math.max(x, x2s);
      const minY = Math.min(y, y2s), maxY = Math.max(y, y2s);
      if (maxX < -50 || minX > viewW + 50 || maxY < -50 || minY > viewH + 50) continue;
    } else if (d.kind === 'ceiling_drip' || d.kind === 'pipe_valve') {
      // Renderingen sträcker sig från pipe-Y (kan vara 800+ px över d.y) ner
      // till puddle vid d.y. Pipe-crack är på pipeY — om puddle är off-screen
      // BELOW kan crack fortfarande vara visible. Använd generösa cull-bounds
      // åt båda håll så popping aldrig sker oavsett kamera-pan.
      if (x < -200 || x > viewW + 200 || y < -1500 || y > viewH + 1500) continue;
    } else {
      if (x < -200 || x > viewW + 200 || y < -200 || y > viewH + 200) continue;
    }
    ctx.save();

    if (d.kind === 'puddle') {
      // Vatten-pöl: mörk reflective fläck med oregelbunden kant + highlight
      const r = d.r || 60;
      const grad = ctx.createRadialGradient(x, y, 2, x, y, r);
      grad.addColorStop(0, 'rgba(40, 50, 80, 0.7)');
      grad.addColorStop(0.7, 'rgba(20, 25, 40, 0.55)');
      grad.addColorStop(1, 'rgba(20, 25, 40, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      // Oregelbunden bubble-form (8 punkter med deterministic variation)
      const seed = ((d.x * 13) | 0) + ((d.y * 7) | 0);
      for (let i = 0; i < 16; i++) {
        const a = (i / 16) * Math.PI * 2;
        const variation = 0.85 + (((seed >> i) & 0x1f) / 31) * 0.3;
        const px = x + Math.cos(a) * r * variation;
        const py = y + Math.sin(a) * r * 0.6 * variation; // mer oval
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fill();
      // Highlights (reflektion av lampor ovan)
      ctx.fillStyle = 'rgba(140, 180, 255, 0.4)';
      ctx.beginPath(); ctx.ellipse(x - r * 0.3, y - r * 0.2, r * 0.18, r * 0.05, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = 'rgba(200, 220, 255, 0.3)';
      ctx.beginPath(); ctx.ellipse(x + r * 0.2, y + r * 0.1, r * 0.12, r * 0.04, 0, 0, Math.PI*2); ctx.fill();
      // Subtle ripple-animation
      const ripplePulse = (t / 800 + (d.x * 0.001) + (d.y * 0.001)) % 1;
      if (ripplePulse < 0.5) {
        ctx.strokeStyle = `rgba(160, 200, 255, ${(0.5 - ripplePulse) * 0.6})`;
        ctx.lineWidth = 0.6;
        ctx.beginPath();
        ctx.ellipse(x, y, r * 0.4 * (0.3 + ripplePulse), r * 0.25 * (0.3 + ripplePulse), 0, 0, Math.PI*2);
        ctx.stroke();
      }

    } else if (d.kind === 'drain') {
      // Golvbrunn: mörk fyrkantig öppning med metall-galler (parallella streck)
      const w = 22, h = 22;
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(x - w/2, y - h/2, w, h);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - w/2 + 1, y - h/2 + 1, w - 2, h - 2);
      // Galler-stänger
      ctx.fillStyle = '#3a3a3a';
      for (let i = 0; i < 5; i++) {
        ctx.fillRect(x - w/2 + 2 + i * 4, y - h/2 + 2, 2, h - 4);
      }
      // Highlight på galler-toppen
      ctx.fillStyle = '#5a5a5a';
      for (let i = 0; i < 5; i++) {
        ctx.fillRect(x - w/2 + 2 + i * 4, y - h/2 + 2, 2, 0.5);
      }
      // Mörk skugga runt
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x - w/2 - 1, y - h/2 - 1, w + 2, h + 2);

    } else if (d.kind === 'parking_lines') {
      // Vita parkeringsstreck: rader av streck längs en horisontell linje
      const count = d.count || 5;
      const dir = d.dir || 'h';
      const lineLen = 60, spacing = 70;
      ctx.fillStyle = 'rgba(220, 220, 200, 0.75)';
      ctx.strokeStyle = 'rgba(140, 140, 120, 0.4)';
      ctx.lineWidth = 0.5;
      if (dir === 'h') {
        for (let i = 0; i < count; i++) {
          const lx = x + i * spacing;
          if (lx < -lineLen || lx > viewW) continue;
          // Streck — något slitet med subtil fade
          ctx.fillRect(lx, y - 2, lineLen, 4);
          ctx.strokeRect(lx, y - 2, lineLen, 4);
          // Slitage-fläckar (utspridda mörkare prickar för worn look)
          ctx.fillStyle = 'rgba(60, 60, 50, 0.25)';
          const wear = ((d.x * 13 + i * 17) | 0);
          for (let j = 0; j < 3; j++) {
            const wx = lx + ((wear * (j + 1)) & 0x3f);
            ctx.fillRect(wx, y - 1, 4, 2);
          }
          ctx.fillStyle = 'rgba(220, 220, 200, 0.75)';
        }
      }

    } else if (d.kind === 'caution_tape') {
      // OUT OF ORDER-tape: gul-svart diagonalt streck-mönster
      const w = d.w || 80, h = 8;
      ctx.save();
      ctx.translate(x, y);
      if (d.rot) ctx.rotate(d.rot);
      // Gul bas
      ctx.fillStyle = '#ffd54a';
      ctx.fillRect(-w / 2, -h / 2, w, h);
      // Svarta diagonaler
      ctx.fillStyle = '#1a1a1a';
      for (let i = 0; i < w / 6; i++) {
        ctx.beginPath();
        ctx.moveTo(-w / 2 + i * 6, -h / 2);
        ctx.lineTo(-w / 2 + i * 6 - h, h / 2);
        ctx.lineTo(-w / 2 + i * 6 + 3 - h, h / 2);
        ctx.lineTo(-w / 2 + i * 6 + 3, -h / 2);
        ctx.closePath(); ctx.fill();
      }
      // Mörk kant
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 0.6;
      ctx.strokeRect(-w / 2, -h / 2, w, h);
      // "CAUTION"-text liten
      ctx.fillStyle = '#1a1a1a';
      ctx.font = 'bold 6px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('CAUTION', 0, 0);
      ctx.restore();

    } else if (d.kind === 'fire_drum') {
      // Brinnande oljefat: stor cylinder + flammor + ljuspöl
      const color = d.color || '#ff7a30';
      // Ljuspöl på golvet runt fat (varmt orange glow)
      const lightR = 80;
      const lightGrad = ctx.createRadialGradient(x, y + 6, 4, x, y + 6, lightR);
      const flicker = 0.85 + Math.sin(t / 80) * 0.15;
      lightGrad.addColorStop(0, `rgba(255, 140, 50, ${0.35 * flicker})`);
      lightGrad.addColorStop(0.6, `rgba(255, 100, 30, ${0.12 * flicker})`);
      lightGrad.addColorStop(1, 'rgba(255, 80, 20, 0)');
      ctx.fillStyle = lightGrad;
      ctx.fillRect(x - lightR, y - lightR + 6, lightR * 2, lightR * 2);
      // Fat-skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 12, 14, 4, 0, 0, Math.PI*2); ctx.fill();
      // Fat-kropp (rostig mörk metall)
      ctx.fillStyle = '#2a1a0a';
      ctx.fillRect(x - 11, y - 8, 22, 20);
      // Fat-highlight (vänster sida)
      ctx.fillStyle = '#4a2a1a';
      ctx.fillRect(x - 11, y - 8, 3, 20);
      // Fat-rim top
      ctx.fillStyle = '#3a2418';
      ctx.fillRect(x - 11, y - 8, 22, 2);
      // 2 horisontella band runt fatet
      ctx.strokeStyle = '#1a1208';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x - 11, y - 2); ctx.lineTo(x + 11, y - 2);
      ctx.moveTo(x - 11, y + 6); ctx.lineTo(x + 11, y + 6);
      ctx.stroke();
      // Rost-fläckar
      ctx.fillStyle = '#6a3818';
      ctx.fillRect(x - 8, y + 1, 3, 2);
      ctx.fillRect(x + 3, y - 4, 2, 1.5);
      ctx.fillRect(x - 5, y + 8, 2, 1);
      // FLAMMAN (fladdrar, multiple layers)
      const flameH = 22 + Math.sin(t / 70) * 4;
      // Yttre orange flame
      ctx.fillStyle = `rgba(255, 100, 30, ${0.7 * flicker})`;
      ctx.beginPath();
      ctx.moveTo(x - 8, y - 8);
      ctx.quadraticCurveTo(x - 6 + Math.sin(t / 100) * 2, y - flameH * 0.6, x - 2, y - flameH * 0.9);
      ctx.quadraticCurveTo(x + Math.sin(t / 80) * 3, y - flameH, x + 2, y - flameH * 0.9);
      ctx.quadraticCurveTo(x + 6 + Math.sin(t / 90) * 2, y - flameH * 0.6, x + 8, y - 8);
      ctx.closePath(); ctx.fill();
      // Mid yellow flame
      ctx.fillStyle = `rgba(255, 200, 60, ${0.85 * flicker})`;
      ctx.beginPath();
      ctx.moveTo(x - 5, y - 8);
      ctx.quadraticCurveTo(x - 3 + Math.sin(t / 90) * 1.5, y - flameH * 0.5, x - 1, y - flameH * 0.75);
      ctx.quadraticCurveTo(x + Math.sin(t / 70) * 2, y - flameH * 0.85, x + 1, y - flameH * 0.75);
      ctx.quadraticCurveTo(x + 3 + Math.sin(t / 95) * 1.5, y - flameH * 0.5, x + 5, y - 8);
      ctx.closePath(); ctx.fill();
      // Inner white-hot core
      ctx.fillStyle = `rgba(255, 250, 220, ${0.9 * flicker})`;
      ctx.beginPath();
      ctx.ellipse(x + Math.sin(t / 60) * 1, y - flameH * 0.4, 2, 5, 0, 0, Math.PI*2); ctx.fill();
      // Glow ovanpå
      ctx.shadowColor = '#ff7030'; ctx.shadowBlur = 18 * flicker;
      ctx.fillStyle = `rgba(255, 180, 50, ${0.4 * flicker})`;
      ctx.beginPath(); ctx.arc(x, y - 12, 3, 0, Math.PI*2); ctx.fill();
      ctx.shadowBlur = 0;
      // Random sparks som flyger uppåt
      const sparkSeed = Math.floor(t / 100);
      for (let i = 0; i < 3; i++) {
        const sphase = (t / 800 + i * 0.33) % 1;
        const sx = x + Math.sin((sparkSeed + i) * 13) * 6;
        const sy = y - 8 - sphase * 35;
        ctx.fillStyle = `rgba(255, ${150 + i * 30}, 50, ${1 - sphase})`;
        ctx.beginPath(); ctx.arc(sx, sy, 1 + (1 - sphase) * 0.6, 0, Math.PI*2); ctx.fill();
      }

    } else if (d.kind === 'flicker_light') {
      // Trasigt lysrör i tak: ljusrektangel + flackerande sken-pöl nedanför
      const color = d.color || '#a8d0ff';
      const flickerHz = d.flickerHz || 4;
      // Flackerings-mönster (deterministic + pseudo-random)
      const flickerSeed = ((d.x * 17 + d.y * 23) | 0);
      const flickerPhase = (t / 1000) * flickerHz + flickerSeed * 0.1;
      const flickerNoise = Math.sin(flickerPhase * 7.3) * Math.cos(flickerPhase * 11.7);
      const isOn = flickerNoise > -0.3; // ofta på, ibland av
      const intensity = isOn ? (0.75 + Math.sin(flickerPhase * 3.2) * 0.25) : (Math.random() < 0.1 ? 0.3 : 0);
      // Ljus-pöl på golvet
      const poolR = 90;
      if (intensity > 0.1) {
        const poolGrad = ctx.createRadialGradient(x, y + 12, 4, x, y + 12, poolR);
        poolGrad.addColorStop(0, `rgba(200, 220, 255, ${0.32 * intensity})`);
        poolGrad.addColorStop(0.5, `rgba(170, 200, 255, ${0.15 * intensity})`);
        poolGrad.addColorStop(1, 'rgba(170, 200, 255, 0)');
        ctx.fillStyle = poolGrad;
        ctx.fillRect(x - poolR, y + 12 - poolR, poolR * 2, poolR * 2);
      }
      // Lampskärm (rektangulär, tak-mounted, med skugga)
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(x - 17, y - 6, 34, 8);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 16, y - 5, 32, 7);
      // Lysrör inside (when on: white-blue glow)
      if (intensity > 0.05) {
        ctx.fillStyle = `rgba(220, 240, 255, ${intensity})`;
        ctx.shadowColor = color; ctx.shadowBlur = 12 * intensity;
        ctx.fillRect(x - 14, y - 3, 28, 3);
        ctx.shadowBlur = 0;
        // Vit kärn-streak
        ctx.fillStyle = `rgba(255, 255, 255, ${intensity * 0.7})`;
        ctx.fillRect(x - 14, y - 2.5, 28, 0.8);
      } else {
        // Av — mörkt insida
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(x - 14, y - 3, 28, 3);
      }
      // Skärm-skruv-detaljer
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(x - 15, y - 4, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 15, y - 4, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x - 15, y + 1, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 15, y + 1, 0.6, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'shopping_cart') {
      // Övergiven shopping-cart: silver-gitter-korg + 4 hjul + handle
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 9, 14, 3, 0, 0, Math.PI*2); ctx.fill();
      // Korg (silver-mesh-style)
      ctx.fillStyle = '#7a7a82';
      ctx.fillRect(x - 12, y - 6, 24, 14);
      // Mesh-pattern (vertical + horizontal grid)
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 0.4;
      for (let i = -10; i <= 10; i += 3) {
        ctx.beginPath();
        ctx.moveTo(x + i, y - 6); ctx.lineTo(x + i, y + 8);
        ctx.stroke();
      }
      for (let i = -4; i <= 6; i += 3) {
        ctx.beginPath();
        ctx.moveTo(x - 12, y + i); ctx.lineTo(x + 12, y + i);
        ctx.stroke();
      }
      // Korg-rim (mörkare metall-ram)
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 1;
      ctx.strokeRect(x - 12, y - 6, 24, 14);
      // Handle (silver-stång)
      ctx.fillStyle = '#9a9aa2';
      ctx.fillRect(x - 13, y - 9, 26, 1.5);
      ctx.fillStyle = '#cccfd5';
      ctx.fillRect(x - 13, y - 9, 26, 0.5);
      // Handle-grepp (svart plast)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 11, y - 9.5, 22, 2);
      // 4 hjul
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x - 9, y + 9, 2, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9, y + 9, 2, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x - 9, y + 5, 1.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9, y + 5, 1.5, 0, Math.PI*2); ctx.fill();
      // Hjul-highlights
      ctx.fillStyle = '#5a5a60';
      ctx.beginPath(); ctx.arc(x - 9.5, y + 8.5, 0.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 8.5, y + 8.5, 0.5, 0, Math.PI*2); ctx.fill();
      // Subtle rost (orange-brun fläck på kanten)
      ctx.fillStyle = 'rgba(140, 70, 30, 0.5)';
      ctx.fillRect(x + 10, y, 2, 4);

    } else if (d.kind === 'abandoned_bag') {
      // Övergiven väska/kasse: mörk taske med strap + zip
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 1, y + 7, 11, 2, 0, 0, Math.PI*2); ctx.fill();
      // Body (mörk brun/grön)
      ctx.fillStyle = '#3a2818';
      ctx.beginPath();
      ctx.moveTo(x - 9, y - 4);
      ctx.lineTo(x - 9, y + 6);
      ctx.lineTo(x + 9, y + 6);
      ctx.lineTo(x + 9, y - 4);
      ctx.quadraticCurveTo(x, y - 8, x - 9, y - 4);
      ctx.fill();
      // Highlight
      ctx.fillStyle = '#5a4028';
      ctx.fillRect(x - 9, y - 4, 18, 1);
      // Strap-handle ovanpå
      ctx.strokeStyle = '#2a1808';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x, y - 5, 4, Math.PI, 0, false);
      ctx.stroke();
      // Zip-detaljer
      ctx.strokeStyle = '#1a1208';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      ctx.moveTo(x - 8, y - 1); ctx.lineTo(x + 8, y - 1);
      ctx.stroke();
      // Zip-puller (liten metall-bit)
      ctx.fillStyle = '#9a9a9a';
      ctx.fillRect(x - 1, y - 1.5, 2, 1);

    } else if (d.kind === 'floor_marking') {
      // Stor målad text på golvet (parking P, EXIT-arrow etc.) — slitet
      const text = d.text || 'P';
      const size = d.size || 80;
      const color = d.color || '#ffd54a';
      ctx.font = 'bold ' + size + 'px Impact, "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      // Slitet utseende: 3 lager med fade + chips
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillText(text, x + 2, y + 2);
      ctx.fillStyle = color;
      ctx.globalAlpha = 0.72;
      ctx.fillText(text, x, y);
      // Slitage-chips (random svarta fläckar inom texten)
      ctx.globalAlpha = 1;
      ctx.fillStyle = 'rgba(20, 20, 24, 0.55)';
      const wearSeed = ((d.x * 13) ^ (d.y * 17)) | 0;
      for (let i = 0; i < 8; i++) {
        const wx = x + ((wearSeed * (i + 1) * 23) % size) - size * 0.5;
        const wy = y + ((wearSeed * (i + 3) * 31) % size) - size * 0.5;
        const wsz = 2 + ((wearSeed >> i) & 0x3);
        ctx.fillRect(wx, wy, wsz, wsz * 0.6);
      }
      // Subtle dark outline
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1.5;
      ctx.strokeText(text, x, y);

    } else if (d.kind === 'ceiling_pipe') {
      // Horisontellt tak-rör — bred mörk balk med highlight + shadow
      // Clamp rendering till visible-region för perf — varje pipe är 4800px
      const w = d.w || 1000;
      const dia = d.dia || 14;
      const color = d.color || '#5a4030';
      // Visible-range i screen-coord
      const drawLeft = Math.max(x, -20);
      const drawRight = Math.min(x + w, viewW + 20);
      const drawW = drawRight - drawLeft;
      if (drawW <= 0) { ctx.restore(); continue; }
      // Skugga på golvet (halvtransparent, lite offset)
      ctx.fillStyle = 'rgba(0,0,0,0.18)';
      ctx.fillRect(drawLeft, y + dia * 0.8, drawW, dia * 0.4);
      // Pipe-body (med skuggning) — gradient bara i visible-region
      const grad = ctx.createLinearGradient(0, y, 0, y + dia);
      grad.addColorStop(0, '#1a1a1e');
      grad.addColorStop(0.3, color);
      grad.addColorStop(0.7, color);
      grad.addColorStop(1, '#0a0a0e');
      ctx.fillStyle = grad;
      ctx.globalAlpha = 0.82;
      ctx.fillRect(drawLeft, y, drawW, dia);
      // Highlight-streak ovanpå
      ctx.fillStyle = '#ffffff';
      ctx.globalAlpha = 0.15;
      ctx.fillRect(drawLeft, y + dia * 0.15, drawW, 1);
      // Pipe-joints/brackets (var 250px i world-coord, starting från d.x).
      // Använd CEIL för end-index så vi inkluderar sista joint vid pipe-änden
      // även om den ligger något off-screen (ex. nära world-edge).
      ctx.globalAlpha = 1;
      const jointSpacing = 250;
      const firstK = Math.max(0, Math.ceil((-20 - x) / jointSpacing));
      const lastK = Math.min(Math.floor(w / jointSpacing), Math.ceil((viewW + 20 - x) / jointSpacing));
      for (let k = firstK; k <= lastK; k++) {
        const jx = x + k * jointSpacing;
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(jx - 2, y, 4, dia);
        ctx.fillStyle = '#3a3a3a';
        ctx.fillRect(jx - 2, y, 4, 1);
      }
      // Rust-streaks (vertical drips ned från pipe — deterministic world-coord)
      ctx.fillStyle = 'rgba(140, 70, 30, 0.35)';
      const rustSeed = ((d.x * 7) ^ (d.y * 11)) | 0;
      const rustCount = Math.min(8, Math.floor(w / 200));
      for (let i = 0; i < rustCount; i++) {
        const worldRx = d.x + ((rustSeed * (i + 1) * 19) & 0x7fff) % w;
        const sx = worldRx - cx;
        if (sx < -5 || sx > viewW + 5) continue;
        ctx.fillRect(sx, y + dia, 1, 8);
      }
      ctx.globalAlpha = 1;
      // BLINKANDE LED-LAMPOR på piper (var 200px i world-coord, alternating
      // röd/orange med deterministic blink-fas per pos så de inte synkar)
      if (d.leds) {
        const ledSpacing = 200;
        const ledStartK = Math.max(0, Math.ceil((-15 - x) / ledSpacing));
        const ledEndK = Math.min(Math.floor(w / ledSpacing), Math.ceil((viewW + 15 - x) / ledSpacing));
        for (let k = ledStartK; k <= ledEndK; k++) {
          const lx = x + k * ledSpacing;
          // Per-LED blink-fas (deterministic från world-pos)
          const ledSeed = ((d.x + k * 200) * 11) | 0;
          const blinkPhase = (t / 600 + (ledSeed & 0xff) / 255) % 1;
          const isOn = blinkPhase < 0.5;
          const ledColor = (k % 2 === 0) ? 'red' : 'orange';
          // LED-housing (liten mörk square OVANPÅ pipe)
          ctx.fillStyle = '#1a1a1a';
          ctx.fillRect(lx - 1.5, y - 2.5, 3, 2.5);
          // LED-lampa
          if (isOn) {
            ctx.fillStyle = ledColor === 'red' ? '#ff3030' : '#ff8a30';
            ctx.shadowColor = ledColor === 'red' ? '#ff3030' : '#ff8a30';
            ctx.shadowBlur = 6;
            ctx.beginPath(); ctx.arc(lx, y - 1.2, 1.2, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
            // Bright center-dot
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(lx, y - 1.2, 0.4, 0, Math.PI*2); ctx.fill();
          } else {
            // Av — mörk LED
            ctx.fillStyle = ledColor === 'red' ? '#5a1010' : '#5a3010';
            ctx.beginPath(); ctx.arc(lx, y - 1.2, 1.2, 0, Math.PI*2); ctx.fill();
          }
        }
      }

    } else if (d.kind === 'ceiling_pipe_v') {
      // Vertikalt tak-rör — clamp till visible-region som horisontell
      const h = d.h || 1000;
      const dia = d.dia || 10;
      const color = d.color || '#4a4a55';
      const drawTop = Math.max(y, -20);
      const drawBot = Math.min(y + h, viewH + 20);
      const drawH = drawBot - drawTop;
      if (drawH <= 0) { ctx.restore(); continue; }
      ctx.fillStyle = 'rgba(0,0,0,0.18)';
      ctx.fillRect(x + dia * 0.8, drawTop, dia * 0.4, drawH);
      const grad = ctx.createLinearGradient(x, 0, x + dia, 0);
      grad.addColorStop(0, '#1a1a1e');
      grad.addColorStop(0.3, color);
      grad.addColorStop(0.7, color);
      grad.addColorStop(1, '#0a0a0e');
      ctx.fillStyle = grad;
      ctx.globalAlpha = 0.78;
      ctx.fillRect(x, drawTop, dia, drawH);
      // Highlight
      ctx.fillStyle = '#ffffff';
      ctx.globalAlpha = 0.13;
      ctx.fillRect(x + dia * 0.15, drawTop, 1, drawH);
      ctx.globalAlpha = 1;
      // Joints var 250px — CEIL för end-index så sista joint vid pipe-änden tas med
      const jointSpacing = 250;
      const firstK = Math.max(0, Math.ceil((-20 - y) / jointSpacing));
      const lastK = Math.min(Math.floor(h / jointSpacing), Math.ceil((viewH + 20 - y) / jointSpacing));
      for (let k = firstK; k <= lastK; k++) {
        const jy = y + k * jointSpacing;
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(x, jy - 2, dia, 4);
        ctx.fillStyle = '#3a3a3a';
        ctx.fillRect(x, jy - 2, 1, 4);
      }
      // BLINKANDE LED-LAMPOR på vertikal pipe (var 200px)
      if (d.leds) {
        const ledSpacing = 200;
        const ledStartK = Math.max(0, Math.ceil((-15 - y) / ledSpacing));
        const ledEndK = Math.min(Math.floor(h / ledSpacing), Math.ceil((viewH + 15 - y) / ledSpacing));
        for (let k = ledStartK; k <= ledEndK; k++) {
          const ly = y + k * ledSpacing;
          const ledSeed = ((d.y + k * 200) * 11) | 0;
          const blinkPhase = (t / 600 + (ledSeed & 0xff) / 255) % 1;
          const isOn = blinkPhase < 0.5;
          const ledColor = (k % 2 === 0) ? 'red' : 'orange';
          ctx.fillStyle = '#1a1a1a';
          ctx.fillRect(x - 2.5, ly - 1.5, 2.5, 3);
          if (isOn) {
            ctx.fillStyle = ledColor === 'red' ? '#ff3030' : '#ff8a30';
            ctx.shadowColor = ledColor === 'red' ? '#ff3030' : '#ff8a30';
            ctx.shadowBlur = 6;
            ctx.beginPath(); ctx.arc(x - 1.2, ly, 1.2, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(x - 1.2, ly, 0.4, 0, Math.PI*2); ctx.fill();
          } else {
            ctx.fillStyle = ledColor === 'red' ? '#5a1010' : '#5a3010';
            ctx.beginPath(); ctx.arc(x - 1.2, ly, 1.2, 0, Math.PI*2); ctx.fill();
          }
        }
      }

    } else if (d.kind === 'cable_bundle') {
      // Hängande kabel-knippe — flera kurviga linjer mellan 2 punkter
      const x2 = (d.x2 || d.x + 200) - cx;
      const y2 = (d.y2 || d.y) - cy;
      // Skugga
      ctx.strokeStyle = 'rgba(0,0,0,0.22)';
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y + 6);
      const sagY = (y + y2) / 2 + 18;
      ctx.quadraticCurveTo((x + x2) / 2, sagY + 4, x2, y2 + 6);
      ctx.stroke();
      // 3 kabelfärger som hänger ihop i ett knippe
      const cableColors = ['#1a1a1a', '#2a2018', '#181820'];
      for (let i = 0; i < 3; i++) {
        ctx.strokeStyle = cableColors[i];
        ctx.lineWidth = 2.5 - i * 0.5;
        ctx.beginPath();
        ctx.moveTo(x, y + i * 1.5);
        ctx.quadraticCurveTo((x + x2) / 2, sagY + i * 1.2, x2, y2 + i * 1.5);
        ctx.stroke();
      }
      // Cable-clamps (mörka punkter där kablarna sitter fast i taket)
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(x - 3, y - 2, 6, 5);
      ctx.fillRect(x2 - 3, y2 - 2, 6, 5);
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 3, y - 2, 6, 1);
      ctx.fillRect(x2 - 3, y2 - 2, 6, 1);

    } else if (d.kind === 'ceiling_drip') {
      // BRUSTET RÖR — anslutet till befintligt ceiling_pipe-system. Söker
      // nearest horisontell pipe-y och placerar sprickan PÅ den. Vatten
      // cascadar från sprickan ner till puddle vid d.y.
      const breakSeed = ((d.x * 13) ^ (d.y * 19)) | 0;
      const sprayPhase = (t / 280) % 1;
      // Hitta nearest ceiling_pipe (måste vara OVANFÖR drippen så vattnet kan
      // cascada nedåt). Om ingen pipe ovanför hittas, fallback.
      let nearestPipeY = d.y - 55; // fallback
      let nearestPipeDia = 14;
      let nearestDist = Infinity;
      for (const pd of decos) {
        if (pd.kind !== 'ceiling_pipe') continue;
        if (pd.y >= d.y) continue; // bara pipes OVANFÖR drippen
        const dist = d.y - pd.y;
        if (dist < nearestDist) {
          nearestDist = dist;
          nearestPipeY = pd.y;
          nearestPipeDia = pd.dia || 14;
        }
      }
      // Convert pipe-y till screen-coord (cy är från outer scope)
      const pipeY = nearestPipeY - cy;
      const pipeDia = nearestPipeDia;

      // 1) STOR våt mörk fläck på golvet (där vattnet samlas)
      const poolR = 22;
      const poolGrad = ctx.createRadialGradient(x, y, 2, x, y, poolR);
      poolGrad.addColorStop(0, 'rgba(20, 40, 70, 0.85)');
      poolGrad.addColorStop(0.6, 'rgba(15, 30, 50, 0.5)');
      poolGrad.addColorStop(1, 'rgba(15, 30, 50, 0)');
      ctx.fillStyle = poolGrad;
      ctx.beginPath();
      for (let i = 0; i < 16; i++) {
        const a = (i / 16) * Math.PI * 2;
        const variation = 0.7 + (((breakSeed >> i) & 0x1f) / 31) * 0.6;
        const px = x + Math.cos(a) * poolR * variation;
        const py = y + Math.sin(a) * poolR * 0.55 * variation;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fill();
      // Vit reflektion-streak på pölen
      ctx.fillStyle = 'rgba(160, 200, 240, 0.4)';
      ctx.beginPath(); ctx.ellipse(x - 3, y - 1, 6, 1.5, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = 'rgba(200, 220, 250, 0.3)';
      ctx.beginPath(); ctx.ellipse(x + 4, y + 2, 4, 1, 0, 0, Math.PI*2); ctx.fill();
      // Concentric ripple from continuous drip impact
      const rippleA = (t / 600 + (d.x * 0.001)) % 1;
      ctx.strokeStyle = `rgba(160, 200, 240, ${(1 - rippleA) * 0.5})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.ellipse(x, y, 4 + rippleA * 12, 1.5 + rippleA * 4, 0, 0, Math.PI*2);
      ctx.stroke();

      // 2) Vatten-cascade från sprickan på pipe ner till puddle (variabel längd)
      const cascadeLen = y - pipeY - pipeDia / 2;
      if (cascadeLen > 5) {
        // Mid-streak (bred, halvtransparent)
        ctx.strokeStyle = 'rgba(150, 200, 240, 0.55)';
        ctx.lineWidth = 2.2;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x - 1, pipeY + pipeDia / 2);
        const segs = Math.max(6, Math.floor(cascadeLen / 10));
        for (let s = 0; s < segs; s++) {
          const sy = pipeY + pipeDia / 2 + s * (cascadeLen / segs);
          const sx = x - 1 + Math.sin(t / 90 + s * 1.2 + breakSeed) * 1.2;
          ctx.lineTo(sx, sy);
        }
        ctx.stroke();
        // Smal detalj-stream
        ctx.strokeStyle = 'rgba(180, 220, 250, 0.65)';
        ctx.lineWidth = 0.9;
        ctx.beginPath();
        ctx.moveTo(x + 1, pipeY + pipeDia / 2);
        for (let s = 0; s < segs; s++) {
          const sy = pipeY + pipeDia / 2 + s * (cascadeLen / segs);
          const sx = x + 1 + Math.sin(t / 110 + s * 0.9 + breakSeed * 0.3) * 1.5;
          ctx.lineTo(sx, sy);
        }
        ctx.stroke();
        // Individuella droppar (3 st olika phaser)
        for (let i = 0; i < 3; i++) {
          const phase = (sprayPhase + i * 0.33) % 1;
          const dropY = pipeY + pipeDia / 2 + phase * cascadeLen;
          const dropX = x + Math.sin(i + breakSeed * 0.1) * 2;
          ctx.fillStyle = `rgba(190, 220, 250, ${0.9 - phase * 0.3})`;
          ctx.beginPath();
          ctx.ellipse(dropX, dropY, 1.1, 2.2, 0, 0, Math.PI*2); ctx.fill();
        }
      }

      // 3) Side-spray (droppar spritter åt sidorna från sprickan på pipe)
      for (let i = 0; i < 4; i++) {
        const sphase = (t / 400 + i * 0.25 + breakSeed * 0.01) % 1;
        const sa = ((breakSeed >> (i * 3)) & 0x7) / 7 * Math.PI - Math.PI / 2;
        const sdist = sphase * 18;
        const sx = x + Math.cos(sa) * sdist;
        const sy = pipeY + pipeDia / 2 + Math.sin(sa) * sdist + sphase * sphase * 18;
        ctx.fillStyle = `rgba(170, 210, 240, ${(1 - sphase) * 0.7})`;
        ctx.beginPath(); ctx.arc(sx, sy, 0.8, 0, Math.PI*2); ctx.fill();
      }

      // 4) CRACK-OVERLAY på befintliga pipe (renderas ovanpå existerande pipe-pixel)
      // Pipens rendering ligger redan i decoration-loopen — vi overlay:ar bara
      // crack-detaljer + dent-zone + rost-halo på ON-PIPE-positionen.
      // Bent metal-flaps som böjts ut från sprickan
      ctx.fillStyle = '#3a3a40';
      ctx.beginPath();
      ctx.moveTo(x - 5, pipeY); ctx.lineTo(x - 7, pipeY - 2); ctx.lineTo(x - 3, pipeY + 1);
      ctx.closePath(); ctx.fill();
      ctx.beginPath();
      ctx.moveTo(x + 2, pipeY); ctx.lineTo(x + 6, pipeY - 2); ctx.lineTo(x + 3, pipeY + 1);
      ctx.closePath(); ctx.fill();
      // Bright bent-edge highlight (metallisk reflektion på böjda kanter)
      ctx.strokeStyle = '#9aa0a8';
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(x - 5, pipeY); ctx.lineTo(x - 7, pipeY - 2);
      ctx.moveTo(x + 2, pipeY); ctx.lineTo(x + 6, pipeY - 2);
      ctx.stroke();
      // SPRICKA — oregelbunden mörk öppning DIREKT på pipe
      ctx.fillStyle = '#000';
      ctx.beginPath();
      ctx.moveTo(x - 4, pipeY - 1);
      ctx.lineTo(x - 2, pipeY + 2);
      ctx.lineTo(x - 3, pipeY + pipeDia - 1);
      ctx.lineTo(x + 1, pipeY + pipeDia - 2);
      ctx.lineTo(x + 3, pipeY + pipeDia);
      ctx.lineTo(x + 4, pipeY + 3);
      ctx.lineTo(x + 2, pipeY - 1);
      ctx.closePath(); ctx.fill();
      // Inner highlight på spricka (svag silver inuti)
      ctx.strokeStyle = '#5a5a62';
      ctx.lineWidth = 0.4;
      ctx.stroke();
      // Rost-corona runt sprickan (corrosion-halo)
      ctx.strokeStyle = 'rgba(140, 70, 30, 0.5)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.ellipse(x, pipeY + pipeDia / 2, 9, 6, 0, 0, Math.PI*2);
      ctx.stroke();
      // Rost-fläckar fortlöpande från sprickan utåt
      ctx.fillStyle = 'rgba(120, 60, 25, 0.55)';
      ctx.fillRect(x - 8, pipeY + 1, 2, 2);
      ctx.fillRect(x + 6, pipeY + pipeDia - 3, 2, 2);
      // Steam/mist ovanför pipe (där vattnet träffar luften)
      ctx.fillStyle = `rgba(180, 200, 220, ${0.15 + Math.sin(t / 250) * 0.05})`;
      ctx.beginPath(); ctx.arc(x - 1, pipeY - 5, 5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 2, pipeY - 8, 3, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'rubble') {
      // Concrete-chunks (krossad betong)
      const rubbleSeed = ((d.x * 17) ^ (d.y * 23)) | 0;
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 7, 16, 3, 0, 0, Math.PI*2); ctx.fill();
      // 5-7 chunks i en hög
      const chunkCount = 5 + (rubbleSeed & 0x3);
      for (let i = 0; i < chunkCount; i++) {
        const h = rubbleSeed >> (i * 4);
        const cxOff = ((h & 0x1f) - 16) * 0.6;
        const cyOff = (((h >> 5) & 0x1f) - 16) * 0.4;
        const cSz = 3 + ((h >> 10) & 0x7);
        // Chunk-grays
        ctx.fillStyle = i % 2 === 0 ? '#4a4a4e' : '#5a5a5e';
        ctx.fillRect(x + cxOff, y + cyOff, cSz, cSz * 0.7);
        // Mörk skugga på en sida
        ctx.fillStyle = '#1a1a1e';
        ctx.fillRect(x + cxOff, y + cyOff + cSz * 0.5, cSz, cSz * 0.2);
        // Highlight
        ctx.fillStyle = '#7a7a82';
        ctx.fillRect(x + cxOff, y + cyOff, cSz, 0.6);
      }
      // Exponerad rebar (rostig pinne sticker ut)
      ctx.strokeStyle = '#7a4828';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(x + 2, y - 4);
      ctx.lineTo(x + 4, y + 4);
      ctx.stroke();
      // Dust-haze runt högen
      ctx.fillStyle = 'rgba(160, 150, 140, 0.12)';
      ctx.beginPath(); ctx.arc(x, y + 2, 14, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'traffic_cone') {
      // Orange varningskona med vita reflexer
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 1, y + 8, 8, 2, 0, 0, Math.PI*2); ctx.fill();
      // Bas (svart kvadrat)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 7, y + 5, 14, 3);
      // Bas-highlight
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 7, y + 5, 14, 0.6);
      // Kon-kropp (orange triangel ovanifrån — vy från sidan)
      ctx.fillStyle = '#ff6a20';
      ctx.beginPath();
      ctx.moveTo(x - 5, y + 5);
      ctx.lineTo(x, y - 8);
      ctx.lineTo(x + 5, y + 5);
      ctx.closePath(); ctx.fill();
      // Mörkare orange skugga (höger sida)
      ctx.fillStyle = '#c04a10';
      ctx.beginPath();
      ctx.moveTo(x, y - 8);
      ctx.lineTo(x + 5, y + 5);
      ctx.lineTo(x + 1, y + 5);
      ctx.closePath(); ctx.fill();
      // Vita reflex-band (2 horisontella ringar)
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.moveTo(x - 3.5, y - 1); ctx.lineTo(x + 3.5, y - 1);
      ctx.lineTo(x + 3, y + 0.5); ctx.lineTo(x - 3, y + 0.5);
      ctx.closePath(); ctx.fill();
      ctx.beginPath();
      ctx.moveTo(x - 2, y - 4.5); ctx.lineTo(x + 2, y - 4.5);
      ctx.lineTo(x + 1.6, y - 3.5); ctx.lineTo(x - 1.6, y - 3.5);
      ctx.closePath(); ctx.fill();
      // Mörk outline
      ctx.strokeStyle = '#0a0a0a';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(x - 5, y + 5); ctx.lineTo(x, y - 8); ctx.lineTo(x + 5, y + 5);
      ctx.stroke();

    } else if (d.kind === 'pallet') {
      // Trä-pallet (lämnad på golvet)
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillRect(x - 14, y - 8, 30, 18);
      // Bas-planka (mörkbrun trä)
      ctx.fillStyle = '#5a3a20';
      ctx.fillRect(x - 14, y - 9, 30, 18);
      // Top-plankor (3 horisontella med gap)
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x - 14, y - 9, 30, 4);
      ctx.fillRect(x - 14, y - 3, 30, 4);
      ctx.fillRect(x - 14, y + 3, 30, 4);
      // Trä-grain på top-plankor (subtila streck)
      ctx.strokeStyle = '#3a2010';
      ctx.lineWidth = 0.3;
      for (let i = 0; i < 3; i++) {
        const py = y - 8 + i * 6;
        ctx.beginPath();
        ctx.moveTo(x - 13, py); ctx.lineTo(x + 13, py + 0.5);
        ctx.moveTo(x - 13, py + 2); ctx.lineTo(x + 13, py + 2.5);
        ctx.stroke();
      }
      // Bottom-stöd (3 vertikala block)
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x - 14, y + 7, 4, 3);
      ctx.fillRect(x - 2, y + 7, 4, 3);
      ctx.fillRect(x + 10, y + 7, 4, 3);
      // Spik-detaljer (små mörka prickar i hörnen)
      ctx.fillStyle = '#1a0808';
      const nails = [[-13, -8], [13, -8], [-13, 8], [13, 8], [0, -8], [0, 8]];
      for (const [nx, ny] of nails) {
        ctx.beginPath(); ctx.arc(x + nx, y + ny, 0.5, 0, Math.PI*2); ctx.fill();
      }
      // Yttre outline
      ctx.strokeStyle = '#1a0a05';
      ctx.lineWidth = 0.7;
      ctx.strokeRect(x - 14, y - 9, 30, 18);

    } else if (d.kind === 'broken_glass') {
      // Spritt glas-skärvor
      const glassSeed = ((d.x * 19) ^ (d.y * 29)) | 0;
      // 8-12 skärvor i en oregelbunden spridning
      const shardCount = 8 + (glassSeed & 0x7);
      for (let i = 0; i < shardCount; i++) {
        const h = glassSeed >> (i * 2);
        const sx = ((h & 0x1f) - 16) * 1.5;
        const sy = (((h >> 5) & 0x1f) - 16) * 1.0;
        const sSz = 1 + ((h >> 10) & 0x3);
        const angle = ((h >> 13) & 0x7) / 7 * Math.PI;
        ctx.save();
        ctx.translate(x + sx, y + sy);
        ctx.rotate(angle);
        // Skärva (triangulär)
        ctx.fillStyle = 'rgba(180, 210, 230, 0.8)';
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(sSz, sSz * 0.3); ctx.lineTo(sSz * 0.4, sSz * 0.8);
        ctx.closePath(); ctx.fill();
        // Highlight-streak
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, sSz * 0.6, 0.4);
        // Mörk skugga-kant
        ctx.strokeStyle = 'rgba(80, 100, 120, 0.6)';
        ctx.lineWidth = 0.3;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(sSz, sSz * 0.3); ctx.lineTo(sSz * 0.4, sSz * 0.8);
        ctx.closePath(); ctx.stroke();
        ctx.restore();
      }

    } else if (d.kind === 'trash_pile') {
      // Skräp-hög: pappers + flaskor + plast
      const trashSeed = ((d.x * 11) ^ (d.y * 13)) | 0;
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 6, 14, 3, 0, 0, Math.PI*2); ctx.fill();
      // Tidnings-papper (vita rektanglar med text-illusion)
      ctx.fillStyle = '#d0c8b8';
      ctx.fillRect(x - 8, y - 2, 8, 5);
      ctx.fillRect(x + 2, y, 7, 4);
      ctx.fillStyle = '#5a5040';
      // Fake text-lines
      for (let i = 0; i < 4; i++) {
        ctx.fillRect(x - 7, y - 1 + i, 6, 0.3);
        ctx.fillRect(x + 3, y + 0.5 + i * 0.8, 5, 0.2);
      }
      // Bottle/can (mörk cirkel)
      ctx.fillStyle = '#3a5a30';
      ctx.fillRect(x - 3, y + 2, 3, 5);
      ctx.fillStyle = '#1a3a10';
      ctx.fillRect(x - 3, y + 6, 3, 1);
      // Aluminum-can (silver)
      ctx.fillStyle = '#9a9aa0';
      ctx.fillRect(x + 5, y - 4, 2.5, 5);
      ctx.fillStyle = '#5a5a60';
      ctx.fillRect(x + 5, y - 4, 2.5, 0.6);
      // Plast-bit (genomskinlig)
      ctx.fillStyle = 'rgba(200, 200, 220, 0.5)';
      ctx.beginPath();
      ctx.moveTo(x - 9, y + 1); ctx.lineTo(x - 6, y + 4);
      ctx.lineTo(x - 4, y + 1); ctx.lineTo(x - 6, y - 2);
      ctx.closePath(); ctx.fill();
      // Random small dots (smuts)
      ctx.fillStyle = 'rgba(40, 30, 20, 0.5)';
      for (let i = 0; i < 6; i++) {
        const h = trashSeed >> (i * 3);
        const dx = ((h & 0x1f) - 16) * 0.7;
        const dy = (((h >> 5) & 0x1f) - 16) * 0.4;
        ctx.fillRect(x + dx, y + dy, 1, 1);
      }

    } else if (d.kind === 'fire_hydrant') {
      // Brandpost — röd metall med caps, valve-handle, "FH"-stamp
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 1, y + 7, 8, 2.5, 0, 0, Math.PI*2); ctx.fill();
      // Bas-fot (svart sockel)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 5, y + 5, 10, 3);
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 5, y + 5, 10, 0.6);
      // Bolts på fot (4 st)
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(x - 4, y + 6, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 4, y + 6, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x - 4, y + 7.5, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 4, y + 7.5, 0.6, 0, Math.PI*2); ctx.fill();
      // Huvud-kropp (röd, klassisk brandpost-form)
      ctx.fillStyle = '#aa1818';
      ctx.fillRect(x - 4, y - 6, 8, 11);
      // Mid-bredning (utbuktning där sido-kapsen är)
      ctx.fillStyle = '#cc2020';
      ctx.fillRect(x - 5, y - 3, 10, 5);
      // Body-highlight (vänster sida)
      ctx.fillStyle = '#ff4040';
      ctx.fillRect(x - 4, y - 6, 1, 11);
      ctx.fillRect(x - 5, y - 3, 1.5, 5);
      // Body-shadow (höger sida)
      ctx.fillStyle = '#7a0a0a';
      ctx.fillRect(x + 3, y - 6, 1, 11);
      ctx.fillRect(x + 3.5, y - 3, 1.5, 5);
      // Topp-cap (rund mörk dome ovanpå)
      ctx.fillStyle = '#7a0a0a';
      ctx.beginPath(); ctx.ellipse(x, y - 7, 4.5, 2, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#aa1818';
      ctx.beginPath(); ctx.ellipse(x, y - 7.5, 4, 1.5, 0, 0, Math.PI*2); ctx.fill();
      // Valve-handle (femkantig ratt på toppen)
      ctx.fillStyle = '#5a5a5a';
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
        const px = x + Math.cos(a) * 2;
        const py = y - 8.5 + Math.sin(a) * 2;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#7a7a7a';
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
        const px = x - 0.3 + Math.cos(a) * 1.4;
        const py = y - 8.8 + Math.sin(a) * 1.4;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x, y - 8.5, 0.5, 0, Math.PI*2); ctx.fill();
      // Side-caps (2 mässings-mynningar på sidorna)
      ctx.fillStyle = '#8a6020';
      ctx.beginPath(); ctx.arc(x - 5, y - 1, 1.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 5, y - 1, 1.6, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#bb8030';
      ctx.beginPath(); ctx.arc(x - 5.3, y - 1.3, 0.7, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 4.7, y - 1.3, 0.7, 0, Math.PI*2); ctx.fill();
      // Side-cap chain (liten kedja från side-cap)
      ctx.strokeStyle = '#3a3a3a';
      ctx.lineWidth = 0.4;
      ctx.beginPath();
      ctx.moveTo(x - 5, y); ctx.lineTo(x - 4, y + 3);
      ctx.moveTo(x + 5, y); ctx.lineTo(x + 4, y + 3);
      ctx.stroke();
      // "FH"-stamp
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 4px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('FH', x, y + 1);
      // Rost-fläckar
      ctx.fillStyle = '#5a3018';
      ctx.fillRect(x - 4, y + 3, 2, 1);
      ctx.fillRect(x + 2, y + 4, 1.5, 1);

    } else if (d.kind === 'overturned_cart') {
      // Välta shopping-cart — på sidan, ena hjulet sticker upp
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(d.rot || (Math.PI / 6));
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(2, 8, 16, 3, 0, 0, Math.PI*2); ctx.fill();
      // Korg (silver-mesh) — på sidan
      ctx.fillStyle = '#7a7a82';
      ctx.fillRect(-14, -10, 28, 14);
      // Mesh-pattern (rotated så den ligger korrekt)
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 0.4;
      for (let i = -12; i <= 12; i += 3) {
        ctx.beginPath();
        ctx.moveTo(i, -10); ctx.lineTo(i, 4);
        ctx.stroke();
      }
      for (let i = -8; i <= 2; i += 3) {
        ctx.beginPath();
        ctx.moveTo(-14, i); ctx.lineTo(14, i);
        ctx.stroke();
      }
      // Korg-rim
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 1;
      ctx.strokeRect(-14, -10, 28, 14);
      // Handle (silver-stång — på sidan, sticker bortåt)
      ctx.fillStyle = '#9a9aa2';
      ctx.fillRect(-15, -13, 30, 1.5);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(-13, -13.5, 26, 2);
      // 4 hjul — 2 sticker UPP eftersom carten är välta, 2 är dolda
      // Övre 2 hjul (sticker upp åt taket från perspektivet)
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(-10, -15, 2.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(10, -15, 2.5, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#3a3a40';
      ctx.beginPath(); ctx.arc(-10, -15, 1.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(10, -15, 1.5, 0, Math.PI*2); ctx.fill();
      // Hjul-axlar (synliga eftersom carten är på sidan)
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(-10, -15); ctx.lineTo(-10, -10);
      ctx.moveTo(10, -15); ctx.lineTo(10, -10);
      ctx.stroke();
      // Krasch-skada (svart streck på korgen där den slagit i)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(-5, -3, 4, 1);
      ctx.fillRect(3, -7, 3, 1);
      // Rost-fläckar
      ctx.fillStyle = 'rgba(120, 60, 25, 0.5)';
      ctx.fillRect(-13, -8, 2, 1);
      ctx.fillRect(8, -2, 2, 1);
      ctx.restore();

    } else if (d.kind === 'parking_sign') {
      // Liten skylt på stolpe (P-skylt eller pil)
      const signText = d.text || 'P';
      const signColor = d.color || '#1a3a8a';
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(x + 1, y + 14, 2.5, 4);
      // Stolpe (silver)
      ctx.fillStyle = '#7a7a82';
      ctx.fillRect(x - 0.8, y - 6, 1.6, 22);
      // Stolpe-highlight
      ctx.fillStyle = '#9a9aa2';
      ctx.fillRect(x - 0.8, y - 6, 0.4, 22);
      // Stolpe-bas (mörk platta vid golvet)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 2, y + 14, 4, 2);
      // Skylt-bakgrund (vit ram)
      ctx.fillStyle = '#fff';
      ctx.fillRect(x - 8, y - 14, 16, 12);
      // Skylt-inner-färg (blå P-skylt eller röd förbud-skylt)
      ctx.fillStyle = signColor;
      ctx.fillRect(x - 7, y - 13, 14, 10);
      // Skylt-höglight (top edge)
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.fillRect(x - 7, y - 13, 14, 1.5);
      // Text/symbol (vit "P" eller pil)
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(signText, x, y - 7.5);
      // Skylt-skugga
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.fillRect(x - 7, y - 4, 14, 1);
      // Yttre outline
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 0.6;
      ctx.strokeRect(x - 8, y - 14, 16, 12);
      // Stolpe-skruvar (där skylten fästs)
      ctx.fillStyle = '#3a3a3a';
      ctx.beginPath(); ctx.arc(x, y - 11, 0.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x, y - 5, 0.5, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'wheel_stop') {
      // Wheel-stop — liten betong-block vid parkerings-ruta
      const len = d.len || 50;
      const isHorizontal = d.dir !== 'v';
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      if (isHorizontal) ctx.fillRect(x + 1, y + 3, len, 2);
      else ctx.fillRect(x + 3, y + 1, 2, len);
      // Bas (mörk betong)
      ctx.fillStyle = '#3a3a3a';
      if (isHorizontal) {
        ctx.fillRect(x, y - 2, len, 6);
        // Top-highlight
        ctx.fillStyle = '#5a5a5a';
        ctx.fillRect(x, y - 2, len, 1);
        // Front-edge dark
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(x, y + 3, len, 1);
        // Slitage-färg på topp (gul markering)
        ctx.fillStyle = 'rgba(220, 180, 60, 0.65)';
        ctx.fillRect(x + 2, y - 1.5, len - 4, 0.8);
        // Slitage-chips (random mörka prickar)
        ctx.fillStyle = '#1a1a1a';
        for (let i = 0; i < 3; i++) {
          ctx.fillRect(x + 6 + i * (len / 3), y - 1, 1.5, 0.6);
        }
      } else {
        ctx.fillRect(x - 2, y, 6, len);
        ctx.fillStyle = '#5a5a5a';
        ctx.fillRect(x - 2, y, 1, len);
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(x + 3, y, 1, len);
        ctx.fillStyle = 'rgba(220, 180, 60, 0.65)';
        ctx.fillRect(x - 1.5, y + 2, 0.8, len - 4);
      }
      // Yttre outline
      ctx.strokeStyle = '#0a0a0a';
      ctx.lineWidth = 0.6;
      if (isHorizontal) ctx.strokeRect(x + 0.5, y - 1.5, len - 1, 5);
      else ctx.strokeRect(x - 1.5, y + 0.5, 5, len - 1);

    } else if (d.kind === 'pipe_valve') {
      // Pipe-valve — rund hjul-ratt fastsatt på tak-rör
      // Hitta nearest pipe (samma logik som ceiling_drip)
      let valvePipeY = d.y;
      let nearestDist = Infinity;
      for (const pd of decos) {
        if (pd.kind !== 'ceiling_pipe') continue;
        const dist = Math.abs(pd.y - d.y);
        if (dist < nearestDist) { nearestDist = dist; valvePipeY = pd.y; }
      }
      const vy = valvePipeY - cy;
      // Connecting-stem (kort vertikal pipe-anslutning från huvud-pipe ned)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 1.5, vy + 8, 3, 6);
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 1.5, vy + 8, 0.8, 6);
      // Valve-housing (rektangulär mörk box)
      ctx.fillStyle = '#2a2a2a';
      ctx.fillRect(x - 4, vy + 14, 8, 4);
      ctx.fillStyle = '#5a5a5a';
      ctx.fillRect(x - 4, vy + 14, 8, 0.6);
      // Bolts på housing
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(x - 3, vy + 15, 0.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 3, vy + 15, 0.5, 0, Math.PI*2); ctx.fill();
      // Valve-stem (sticker ut nedanför housing)
      ctx.fillStyle = '#5a5a5a';
      ctx.fillRect(x - 0.8, vy + 18, 1.6, 3);
      // Hjul-ratt (rund med ekrar)
      const wheelR = 5;
      const wy = vy + 23;
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 1, wy + 2, wheelR, 2, 0, 0, Math.PI*2); ctx.fill();
      // Ring (yttre)
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x, wy, wheelR, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#cc3030';
      ctx.beginPath(); ctx.arc(x, wy, wheelR - 0.7, 0, Math.PI*2); ctx.fill();
      // Inner cutout (där handen håller)
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x, wy, wheelR * 0.45, 0, Math.PI*2); ctx.fill();
      // Ekrar (3-4 spokes)
      ctx.strokeStyle = '#cc3030';
      ctx.lineWidth = 1.4;
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(a) * wheelR * 0.45, wy + Math.sin(a) * wheelR * 0.45);
        ctx.lineTo(x + Math.cos(a) * (wheelR - 0.7), wy + Math.sin(a) * (wheelR - 0.7));
        ctx.stroke();
      }
      // Highlight på ring
      ctx.strokeStyle = '#ff6060';
      ctx.lineWidth = 0.6;
      ctx.beginPath(); ctx.arc(x, wy, wheelR - 0.2, Math.PI * 1.1, Math.PI * 1.7); ctx.stroke();
      // Center-hub
      ctx.fillStyle = '#5a5a5a';
      ctx.beginPath(); ctx.arc(x, wy, 0.9, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'parking_number') {
      // Stort målat "P-XX" på golvet (smaller än floor_marking)
      const text = d.text || 'P-12';
      const size = d.size || 28;
      ctx.font = 'bold ' + size + 'px Impact, "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      // Slitet utseende
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.fillText(text, x + 1, y + 1);
      ctx.fillStyle = 'rgba(220, 220, 200, 0.7)';
      ctx.fillText(text, x, y);
      // Slitage
      const wearSeed = ((d.x * 13) ^ (d.y * 17)) | 0;
      ctx.fillStyle = 'rgba(20, 20, 24, 0.5)';
      for (let i = 0; i < 5; i++) {
        const wx = x + ((wearSeed * (i + 1) * 23) % size) - size * 0.4;
        const wy = y + ((wearSeed * (i + 3) * 31) % size) - size * 0.4;
        ctx.fillRect(wx, wy, 2, 1.5);
      }

    } else if (d.kind === 'warning_triangle') {
      // Röd-vit varningstriangel (vanlig vägmarkering)
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.moveTo(x + 1, y + 9); ctx.lineTo(x - 9, y + 9); ctx.lineTo(x + 1, y + 8);
      ctx.closePath(); ctx.fill();
      // Triangel-bas (svart kant)
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath();
      ctx.moveTo(x, y - 10); ctx.lineTo(x - 11, y + 8); ctx.lineTo(x + 11, y + 8);
      ctx.closePath(); ctx.fill();
      // Triangel inner (röd)
      ctx.fillStyle = '#ff3030';
      ctx.beginPath();
      ctx.moveTo(x, y - 8); ctx.lineTo(x - 9, y + 6); ctx.lineTo(x + 9, y + 6);
      ctx.closePath(); ctx.fill();
      // Vit inner
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.moveTo(x, y - 5); ctx.lineTo(x - 7, y + 5); ctx.lineTo(x + 7, y + 5);
      ctx.closePath(); ctx.fill();
      // Utropstecken
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 0.8, y - 3, 1.6, 5);
      ctx.beginPath(); ctx.arc(x, y + 4, 0.9, 0, Math.PI*2); ctx.fill();
      // Bas-block (rektangulär fot)
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 5, y + 8, 10, 2);
    }

    ctx.restore();
  }
  // Sign + graffiti → drawCtfDecorations
  const fallback = decos.filter(d => ctfFallbackKinds.indexOf(d.kind) >= 0);
  if (fallback.length) {
    const saved = state.ctfDecorations;
    state.ctfDecorations = fallback;
    try { drawCtfDecorations(); } finally { state.ctfDecorations = saved; }
  }
}

// SIEGE: capture-bases — pulsande cirklar med owner-färg + capture-progress-ring
function drawKothZone() {
  if (!state.kothZones || state.kothActiveZoneIdx == null) return;
  const z = state.kothZones[state.kothActiveZoneIdx];
  if (!z) return;
  // KRITISKT: rendera i skärm-koords genom att subtrahera kameran. Render-loopen
  // använder INTE ctx.translate(-camera) globalt — varje draw-funktion subtraherar
  // själv. Glömd subtraktion = zonen ritas långt utanför skärmen.
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const sx = z.x - cx, sy = z.y - cy;
  // Viewport-cull: om hela cirkeln är utanför skärmen, skippa
  if (sx + z.r < -20 || sx - z.r > viewW + 20 || sy + z.r < -20 || sy - z.r > viewH + 20) return;
  const t = performance.now() / 1000;
  // Snabbare puls + röd-tint under warning-fas (5s före byte)
  const warningActive = state._kothWarningUntil && performance.now() < state._kothWarningUntil;
  const pulse = warningActive ? (0.4 + Math.sin(t * 12) * 0.6) : (0.85 + Math.sin(t * 2.4) * 0.15);
  ctx.save();
  // Gold ring + glow
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = 4;
  ctx.shadowColor = '#ffd54a';
  ctx.shadowBlur = 18 * pulse;
  ctx.globalAlpha = 0.75;
  ctx.beginPath();
  ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
  ctx.stroke();
  // Inner fill
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255, 213, 74, 0.10)';
  ctx.fill();
  // Crown emblem i mitten
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold 32px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = 0.55 + pulse * 0.4;
  ctx.fillText('👑', sx, sy);
  // Zone-namn under
  ctx.font = 'bold 13px sans-serif';
  ctx.fillStyle = '#ffd54a';
  ctx.globalAlpha = 0.85;
  ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
  ctx.fillText(z.name || 'HILL', sx, sy + 28);
  // Countdown till nästa zone-byte (om vi har info)
  if (state.kothNextRotateAt) {
    const sec = Math.max(0, Math.ceil((state.kothNextRotateAt - Date.now()) / 1000));
    ctx.font = 'bold 11px sans-serif';
    ctx.fillStyle = '#fff';
    ctx.shadowBlur = 3;
    ctx.fillText('byter om ' + sec + 's', sx, sy + 46);
  }
  // Contested-banner (>1 spelare i zonen) ovanför zone
  if (state._kothContestedUntil && performance.now() < state._kothContestedUntil) {
    ctx.font = 'bold 14px sans-serif';
    ctx.fillStyle = '#ff5a3a';
    ctx.globalAlpha = 0.95;
    ctx.shadowColor = '#000'; ctx.shadowBlur = 5;
    ctx.fillText('⏸ CONTESTED (' + (state._kothContestedCount || 2) + ')', sx, sy - 50);
  }
  ctx.restore();
}

// BATTLE ROYALE — om spelaren är utanför zonen, rita pulserande röd vignett +
// pil mot zonens centrum. Tydlig feedback att de tar dmg + var de ska gå.
function drawBrOutsideWarning() {
  if (!state.battleroyaleActive || !state.battleroyaleZone) return;
  if (!state.player || state.player.spectating) return;
  const phaseCfg = state.battleroyalePhases && state.battleroyalePhases[state.battleroyalePhase];
  if (!phaseCfg || phaseCfg.outsideDmg <= 0) return;
  const z = state.battleroyaleZone;
  const dx = state.player.x - z.x;
  const dy = state.player.y - z.y;
  const d2 = dx * dx + dy * dy;
  if (d2 <= z.r * z.r) return; // i zonen — safe
  // Spelaren är UTANFÖR — pulserande röd kant-frame (PERF: kant istället för full
  // screen-gradient. 4 tunna rects = ~20% av en full-screen-fill i kostnad).
  const t = performance.now() / 1000;
  const pulse = 0.4 + Math.sin(t * 4) * 0.3;
  ctx.save();
  const edgeAlpha = 0.55 * pulse;
  const edgeW = 60; // tjocklek på röd kant
  ctx.fillStyle = 'rgba(220, 30, 30, ' + edgeAlpha + ')';
  // Top
  ctx.fillRect(0, 0, viewW, edgeW);
  // Bottom
  ctx.fillRect(0, viewH - edgeW, viewW, edgeW);
  // Left
  ctx.fillRect(0, edgeW, edgeW, viewH - 2 * edgeW);
  // Right
  ctx.fillRect(viewW - edgeW, edgeW, edgeW, viewH - 2 * edgeW);
  // Inre fade-band (subtil — bara en liten rect på vardera kant)
  ctx.fillStyle = 'rgba(220, 30, 30, ' + (edgeAlpha * 0.3) + ')';
  const fadeW = 30;
  ctx.fillRect(0, edgeW, viewW, fadeW);
  ctx.fillRect(0, viewH - edgeW - fadeW, viewW, fadeW);
  ctx.fillRect(edgeW, edgeW + fadeW, fadeW, viewH - 2 * (edgeW + fadeW));
  ctx.fillRect(viewW - edgeW - fadeW, edgeW + fadeW, fadeW, viewH - 2 * (edgeW + fadeW));
  // Pil mot närmaste edge på zonen (inte centrum — annars går spelaren längre än nödvändigt)
  const cx = viewW / 2, cy = viewH / 2;
  const camX = Math.round(state.camera.x), camY = Math.round(state.camera.y);
  // Närmaste punkt på zonens omkrets från spelaren (i world-koord)
  const playerToZoneX = z.x - state.player.x;
  const playerToZoneY = z.y - state.player.y;
  const dToZone = Math.hypot(playerToZoneX, playerToZoneY) || 1;
  // Edge-punkt = zone-centrum minus radius i riktning mot spelaren
  const edgeWorldX = z.x - (playerToZoneX / dToZone) * z.r;
  const edgeWorldY = z.y - (playerToZoneY / dToZone) * z.r;
  const zoneScreenX = edgeWorldX - camX, zoneScreenY = edgeWorldY - camY;
  // Om edge-punkten inte är synlig på skärmen — visa pil mot den
  if (zoneScreenX < 0 || zoneScreenX > viewW || zoneScreenY < 0 || zoneScreenY > viewH) {
    const angToZone = Math.atan2(zoneScreenY - cy, zoneScreenX - cx);
    const arrowR = Math.min(viewW, viewH) * 0.35;
    const ax = cx + Math.cos(angToZone) * arrowR;
    const ay = cy + Math.sin(angToZone) * arrowR;
    // PERF: ingen shadowBlur på arrow — bara strokad utlinje för "glow"
    ctx.fillStyle = '#3acaff';
    ctx.beginPath();
    ctx.moveTo(ax + Math.cos(angToZone) * 30, ay + Math.sin(angToZone) * 30);
    ctx.lineTo(ax + Math.cos(angToZone + 2.5) * 20, ay + Math.sin(angToZone + 2.5) * 20);
    ctx.lineTo(ax + Math.cos(angToZone - 2.5) * 20, ay + Math.sin(angToZone - 2.5) * 20);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.stroke();
    // "→ ZON HÄR"-text — använd dubbel-fill (outline-effect) istället för shadow
    ctx.font = 'bold 14px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const txtX = cx + Math.cos(angToZone) * (arrowR - 35);
    const txtY = cy + Math.sin(angToZone) * (arrowR - 35);
    ctx.fillStyle = '#000';
    ctx.fillText('→ ZON', txtX + 1, txtY + 1); // skugga
    ctx.fillStyle = '#fff';
    ctx.fillText('→ ZON', txtX, txtY);
  }
  // Top-center varning — dubbel-fill istället för shadow
  ctx.font = 'bold 18px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.globalAlpha = 0.6 + pulse * 0.4;
  ctx.fillStyle = '#000';
  ctx.fillText('⚠ UTANFÖR ZONEN — ' + phaseCfg.outsideDmg + ' HP/SEK', cx + 1, 81);
  ctx.fillStyle = '#ff5050';
  ctx.fillText('⚠ UTANFÖR ZONEN — ' + phaseCfg.outsideDmg + ' HP/SEK', cx, 80);
  ctx.restore();
}

// BATTLE ROYALE — shrinking safe-zone + next-zone preview + outside-red-tint
function drawBrZone() {
  if (!state.battleroyaleZone) return;
  // SMOOTH INTERPOLATION: server skickar zone-state ~1Hz vilket gör att zonen
  // hoppar abrupt mellan frames. Lerp:a render-zone mot target-zone så det blir
  // mjukt även när server-uppdateringar kommer sällan.
  if (!state.battleroyaleZoneRender) {
    state.battleroyaleZoneRender = { x: state.battleroyaleZone.x, y: state.battleroyaleZone.y, r: state.battleroyaleZone.r };
  }
  if (!state.battleroyaleNextZoneRender && state.battleroyaleNextZone) {
    state.battleroyaleNextZoneRender = { x: state.battleroyaleNextZone.x, y: state.battleroyaleNextZone.y, r: state.battleroyaleNextZone.r };
  }
  const r = state.battleroyaleZoneRender;
  const target = state.battleroyaleZone;
  const lerp = 0.12; // smooth-faktor per frame (~60Hz → ~7% step/frame)
  r.x += (target.x - r.x) * lerp;
  r.y += (target.y - r.y) * lerp;
  r.r += (target.r - r.r) * lerp;
  // Snap om mycket nära target (undviker eviga mikro-rörelser)
  if (Math.abs(target.x - r.x) < 0.5) r.x = target.x;
  if (Math.abs(target.y - r.y) < 0.5) r.y = target.y;
  if (Math.abs(target.r - r.r) < 0.5) r.r = target.r;
  // Next-zone också
  if (state.battleroyaleNextZone) {
    if (!state.battleroyaleNextZoneRender) {
      state.battleroyaleNextZoneRender = { x: state.battleroyaleNextZone.x, y: state.battleroyaleNextZone.y, r: state.battleroyaleNextZone.r };
    }
    const nr = state.battleroyaleNextZoneRender;
    const nt = state.battleroyaleNextZone;
    nr.x += (nt.x - nr.x) * lerp;
    nr.y += (nt.y - nr.y) * lerp;
    nr.r += (nt.r - nr.r) * lerp;
  } else {
    state.battleroyaleNextZoneRender = null;
  }
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const z = r; // använd render-zone (lerpad)
  const sx = z.x - cx, sy = z.y - cy;
  const t = performance.now() / 1000;
  ctx.save();
  // PERF: ta bort full-viewport evenodd-fill (var stor flaskhals — 2M pixlar/frame).
  // Outside-feedback hanteras nu av drawBrOutsideWarning (mer effektiv kant-frame).
  // 1. Zone ring (cyan, pulserande, INGEN shadowBlur — var dyrt)
  const pulse = 0.85 + Math.sin(t * 2.5) * 0.15;
  ctx.strokeStyle = '#3acaff';
  ctx.lineWidth = 5;
  ctx.globalAlpha = 0.85 + 0.1 * pulse;
  ctx.beginPath();
  ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
  ctx.stroke();
  // Inre svag-fill (visar tydligt vad som är "safe") — billig
  if (state.battleroyalePhase > 0) {
    ctx.fillStyle = 'rgba(58, 202, 255, 0.04)';
    ctx.beginPath();
    ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // 2. Next-zone preview (gold dashed circle) — warning-fas, INGEN shadowBlur
  if (state.battleroyaleNextZoneRender) {
    const nz = state.battleroyaleNextZoneRender;
    const nsx = nz.x - cx, nsy = nz.y - cy;
    ctx.strokeStyle = '#ffd54a';
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.9;
    ctx.setLineDash([14, 8]);
    ctx.beginPath();
    ctx.arc(nsx, nsy, nz.r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    // (Tidigare streckad pil över world från current-center → next-center borttagen
    //  — den synliga linjen drogs över hus/objekt vilket såg fel ut. Den gula
    //  next-zone cirkeln + minimapen räcker som indikation.)
  }
  ctx.restore();
}

// ============================================================
// CASTLE DEFENSE — render functions (v1.397 rewamp)
// ============================================================
// Lager-ordning per frame (botten upp):
//   1. drawCastleDefenseGround       — gräs + stenvägar + plaza
//   2. drawCastleDefenseDecorations  — torsorna under spelare (träd-skugga, klippor)
//   3. drawCastleDefenseWalls         — (tomt, ingen pre-built)
//   4. drawCastleDefenseBuildings    — auto/man-turret + traps + stations
//   5. drawCastleDefenseCore          — obelisk-shrine i mitten
//   6. drawCastleDefenseDecorationsTop — träd-kronor (ovanpå spelare)
//   7. drawCastleDefenseSpawnMarkers — pulser vid spawn-punkter
//   8. drawCdBuildGhost                — placement-preview
// ============================================================
// SURVIVORS-RUN ÖDESLAND-arena (v1.529)
// ============================================================
// Post-apokalyptisk askfält. Mörk askfärg + glödande sprickor + brända träd
// + ruin-fragment. Procedurellt placerade dekorationer (deterministisk seed).
// Pulserande central altar istället för CD's obelisk.

// Deterministic RNG från en seed (samma karta varje gång)
function _survRng(seed) {
  let s = (seed * 2654435761) | 0;
  return function() {
    s = (s * 1664525 + 1013904223) | 0;
    return ((s >>> 0) % 100000) / 100000;
  };
}

// Cache decorations + cracks så vi inte recomputerar varje frame
function _ensureSurvivorsArenaCache() {
  if (state._survArenaCache) return state._survArenaCache;
  const rng = _survRng(42); // fixed seed = samma ÖDESLAND varje match
  const cx = 2000, cy = 2000; // CD-arena center
  const cache = {
    // v1.578: cracks BORTA (användaren gillar inte "strecken")
    walls: [],       // taktiska bunker-walls (renamed från ruins, mer detaljrika)
    vehicles: [],    // 8 fordon-wrak
    pillars: [],     // 15 betong-pelare
    sandbags: [],    // 20 sandbag-bunkers
    burntTrees: [],
    rubble: [],
    torches: [],
    obstacles: [],   // unified list för collision (alla blocking obstacles)
  };
  // v1.578: 70 taktiska väggar i KLUSTER så det blir riktiga gömställen
  // Kluster: ett "bunker"-läge har 2-4 väggar i L/U/T-form
  const clusterCount = 22;
  for (let ci = 0; ci < clusterCount; ci++) {
    // Hitta giltig plats för kluster (undvik center 320px + andra kluster 200px)
    let bx, by;
    let tries = 0;
    do {
      bx = 200 + rng() * 3600;
      by = 200 + rng() * 3600;
      const dx = bx - cx, dy = by - cy;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d < 320) { tries++; continue; }
      // Check overlap med existing kluster
      let overlap = false;
      for (const w of cache.walls) {
        const ddx = w.x - bx, ddy = w.y - by;
        if (ddx * ddx + ddy * ddy < 200 * 200) { overlap = true; break; }
      }
      if (!overlap) break;
      tries++;
    } while (tries < 30);
    // Bestäm cluster-shape (L, U, eller line)
    const shape = Math.floor(rng() * 3); // 0=L, 1=U, 2=line
    const rot = rng() * Math.PI * 2;
    const baseLen = 60 + rng() * 50;
    const wallH = 20 + rng() * 6;
    const segments = shape === 0 ? 2 : (shape === 1 ? 3 : (2 + Math.floor(rng() * 2)));
    for (let s = 0; s < segments; s++) {
      // L-form: 2 walls i 90° vinkel. U-form: 3 walls. Line: 2-3 i rad.
      let sx, sy, sRot;
      if (shape === 0) {
        // L-form
        const armA = s * Math.PI / 2;
        sx = bx + Math.cos(rot + armA) * baseLen * 0.5;
        sy = by + Math.sin(rot + armA) * baseLen * 0.5;
        sRot = rot + armA + Math.PI / 2;
      } else if (shape === 1) {
        // U-form
        if (s === 0) { sx = bx; sy = by; sRot = rot; }
        else if (s === 1) { sx = bx + Math.cos(rot + Math.PI/2) * baseLen; sy = by + Math.sin(rot + Math.PI/2) * baseLen; sRot = rot + Math.PI; }
        else { sx = bx + Math.cos(rot - Math.PI/2) * baseLen; sy = by + Math.sin(rot - Math.PI/2) * baseLen; sRot = rot + Math.PI; }
      } else {
        // Line
        sx = bx + Math.cos(rot) * (s - segments / 2) * (baseLen + 10);
        sy = by + Math.sin(rot) * (s - segments / 2) * (baseLen + 10);
        sRot = rot + Math.PI / 2;
      }
      const wallW = baseLen + rng() * 20;
      cache.walls.push({
        x: sx, y: sy,
        w: wallW,
        h: wallH,
        rot: sRot,
        decay: 0.6 + rng() * 0.4,
        seed: rng(),
      });
      // v1.605: obstacle matchar visual rect + rot (OBB-collision i _survResolveCollision)
      cache.obstacles.push({ kind: 'wall', x: sx, y: sy, w: wallW, h: wallH, rot: sRot });
    }
  }
  // v1.578: 8 fordon-wrak (jeepar, lastbil-vrak)
  for (let i = 0; i < 8; i++) {
    let vx, vy, d;
    let tries = 0;
    do {
      vx = 300 + rng() * 3400;
      vy = 300 + rng() * 3400;
      const dx = vx - cx, dy = vy - cy;
      d = Math.sqrt(dx * dx + dy * dy);
      tries++;
    } while (d < 380 && tries < 20);
    const isLarge = rng() > 0.5;
    const vehW = isLarge ? 70 : 50;
    const vehH = isLarge ? 36 : 28;
    const vehRot = rng() * Math.PI * 2;
    cache.vehicles.push({
      x: vx, y: vy,
      w: vehW,
      h: vehH,
      rot: vehRot,
      kind: isLarge ? 'truck' : 'jeep',
      burn: rng() > 0.3,
      flamePhase: rng() * Math.PI * 2,
      seed: rng(),
    });
    cache.obstacles.push({ kind: 'vehicle', x: vx, y: vy, w: vehW, h: vehH, rot: vehRot });
  }
  // v1.578: 15 betong-pelare (cylindriska, hårda att gå förbi)
  for (let i = 0; i < 15; i++) {
    let px, py, d;
    let tries = 0;
    do {
      px = 250 + rng() * 3500;
      py = 250 + rng() * 3500;
      const dx = px - cx, dy = py - cy;
      d = Math.sqrt(dx * dx + dy * dy);
      tries++;
    } while (d < 340 && tries < 20);
    const r = 14 + rng() * 8;
    cache.pillars.push({ x: px, y: py, r: r, cracks: rng(), seed: rng() });
    cache.obstacles.push({ kind: 'pillar', x: px, y: py, w: r * 2, h: r * 2, r: r + 4, isCircle: true });
  }
  // v1.578: 20 sandbag-bunkers (kort vägg, taktiskt cover)
  for (let i = 0; i < 20; i++) {
    let sx, sy, d;
    let tries = 0;
    do {
      sx = 300 + rng() * 3400;
      sy = 300 + rng() * 3400;
      const dx = sx - cx, dy = sy - cy;
      d = Math.sqrt(dx * dx + dy * dy);
      tries++;
    } while (d < 360 && tries < 20);
    const len = 28 + rng() * 30;
    const sbRot = rng() * Math.PI * 2;
    cache.sandbags.push({
      x: sx, y: sy,
      len: len,
      h: 16,
      rot: sbRot,
      bags: 3 + Math.floor(rng() * 3),
      seed: rng(),
    });
    cache.obstacles.push({ kind: 'sandbag', x: sx, y: sy, w: len, h: 16, rot: sbRot });
  }
  // 35 brända träd
  for (let i = 0; i < 35; i++) {
    let x, y, d;
    let tries = 0;
    do {
      x = rng() * 4000;
      y = rng() * 4000;
      const dx = x - cx, dy = y - cy;
      d = Math.sqrt(dx * dx + dy * dy);
      tries++;
    } while (d < 320 && tries < 20);
    cache.burntTrees.push({
      x: x,
      y: y,
      h: 25 + rng() * 35,
      lean: (rng() - 0.5) * 0.4,
      brokenAt: 0.4 + rng() * 0.5,
    });
  }
  // 80 sten-skräp
  for (let i = 0; i < 80; i++) {
    cache.rubble.push({
      x: rng() * 4000,
      y: rng() * 4000,
      r: 3 + rng() * 6,
      shade: rng() * 0.3,
    });
  }
  // 8 torch-stativ runt plaza (vid 250px radius)
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    cache.torches.push({
      x: cx + Math.cos(a) * 250,
      y: cy + Math.sin(a) * 250,
      flamePhase: i * 0.7,
    });
  }
  state._survArenaCache = cache;
  return cache;
}

// v1.605: COLLISION med OBB (Oriented Bounding Box) — walls/sandbags/vehicles
// kan vara roterade och rendering matchar collision-shape nu.
// Push-out görs i obstaclets lokala (roterade) frame, sen translateras tillbaka.
function _survResolveCollision(ent, entR, obstacles) {
  for (let pass = 0; pass < 3; pass++) {
    let anyOverlap = false;
    for (const ob of obstacles) {
      if (ob.isCircle) {
        const dx = ent.x - ob.x, dy = ent.y - ob.y;
        const d = Math.sqrt(dx * dx + dy * dy);
        const minD = ob.r + entR;
        if (d < minD) {
          anyOverlap = true;
          if (d > 0.01) {
            ent.x = ob.x + (dx / d) * minD;
            ent.y = ob.y + (dy / d) * minD;
          } else {
            ent.x = ob.x + minD;
          }
        }
      } else {
        // OBB — transformera entity till obstaclets lokala frame
        const rot = ob.rot || 0;
        const dx = ent.x - ob.x, dy = ent.y - ob.y;
        const cs = Math.cos(-rot), sn = Math.sin(-rot);
        const lx = dx * cs - dy * sn;
        const ly = dx * sn + dy * cs;
        const halfW = ob.w / 2;
        const halfH = ob.h / 2;
        // Overlap-check i lokal frame
        if (lx + entR < -halfW || lx - entR > halfW ||
            ly + entR < -halfH || ly - entR > halfH) continue;
        anyOverlap = true;
        // Per-axis push-out i lokal frame
        const pushRight = halfW - (lx - entR);
        const pushLeft  = (lx + entR) - (-halfW);
        const pushBot   = halfH - (ly - entR);
        const pushTop   = (ly + entR) - (-halfH);
        const minPush = Math.min(pushLeft, pushRight, pushTop, pushBot);
        let nlx = lx, nly = ly;
        if (minPush === pushLeft)       nlx = lx - pushLeft;
        else if (minPush === pushRight) nlx = lx + pushRight;
        else if (minPush === pushTop)   nly = ly - pushTop;
        else                            nly = ly + pushBot;
        // Rotera tillbaka till world
        const cs2 = Math.cos(rot), sn2 = Math.sin(rot);
        ent.x = ob.x + nlx * cs2 - nly * sn2;
        ent.y = ob.y + nlx * sn2 + nly * cs2;
      }
    }
    if (!anyOverlap) break;
  }
}

function _survPointInObstacle(x, y, obstacles) {
  for (const ob of obstacles) {
    if (ob.isCircle) {
      const dx = x - ob.x, dy = y - ob.y;
      if (dx * dx + dy * dy < ob.r * ob.r) return true;
    } else {
      const rot = ob.rot || 0;
      const dx = x - ob.x, dy = y - ob.y;
      const cs = Math.cos(-rot), sn = Math.sin(-rot);
      const lx = dx * cs - dy * sn;
      const ly = dx * sn + dy * cs;
      if (Math.abs(lx) <= ob.w / 2 && Math.abs(ly) <= ob.h / 2) return true;
    }
  }
  return false;
}

function applySurvivorsObstacleCollision() {
  if (!state.survivorsActive) return;
  // v1.579: Eager-init cache om den inte är skapad än — annars körs collision
  // före första render-frame och obstacles[] är tom = enemies går igenom
  if (!state._survArenaCache && typeof _ensureSurvivorsArenaCache === 'function') {
    _ensureSurvivorsArenaCache();
  }
  if (!state._survArenaCache) return;
  const obstacles = state._survArenaCache.obstacles;
  if (!obstacles || obstacles.length === 0) return;
  // v1.580: DEBUG counter — visas i diag-overlay så vi ser om funktionen körs
  state._survCollisionStats = state._survCollisionStats || { calls: 0, obstacleCount: 0, enemiesResolved: 0, bulletsBlocked: 0 };
  state._survCollisionStats.calls++;
  state._survCollisionStats.obstacleCount = obstacles.length;
  // Player
  if (state.player && !state.player.dead) {
    _survResolveCollision(state.player, state.player.r || 14, obstacles);
  }
  // Coop partners
  if (typeof Coop !== 'undefined' && Coop.players) {
    for (const [, partner] of Coop.players) {
      if (partner && typeof partner.x === 'number' && partner.hp > 0) {
        _survResolveCollision(partner, 14, obstacles);
      }
    }
  }
  // v1.602: ENEMIES går nu genom obstacles — de fastnade och samlades vid walls.
  // Endast player + bullets blockas. Player får cover, enemies attackerar fritt.
  // Bullets — blockas av obstacles (både player + hostile)
  if (state.bullets) {
    for (const b of state.bullets) {
      if (!b || b.dead) continue;
      if (_survPointInObstacle(b.x, b.y, obstacles)) {
        b.dead = true;
        state._survCollisionStats.bulletsBlocked++;
        // Spawn liten impact-sparks för feedback
        if (typeof spawnSparks === 'function') {
          spawnSparks(b.x, b.y, b.color || '#888', 3, 80);
        }
      }
    }
  }
}

function drawSurvivorsArenaGround() {
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const centerX = 2000, centerY = 2000;
  const plazaR = 200;
  const now = performance.now();
  const t = now / 1000;
  const cache = _ensureSurvivorsArenaCache();
  ctx.save();

  // === BAS-MARK (organisk, ej rutig) — v1.579 ===
  // Grundlager: mörk askfärg
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(0, 0, viewW, viewH);
  // ORGANISK noise via ELLIPSER med random storlek/position (inte rutor)
  // Flera lager för depth. Hash-baserat seed så det är deterministiskt per worldpos.
  // Stora dimma-fläckar (mjuka, transparenta)
  ctx.fillStyle = 'rgba(50, 38, 30, 0.22)';
  const blobSize = 180;
  const blobOffX = Math.floor(cx / blobSize) * blobSize - cx - blobSize;
  const blobOffY = Math.floor(cy / blobSize) * blobSize - cy - blobSize;
  for (let bx = blobOffX; bx < viewW + blobSize * 2; bx += blobSize) {
    for (let by = blobOffY; by < viewH + blobSize * 2; by += blobSize) {
      const wx = bx + cx, wy = by + cy;
      // 2 hash-värden för x/y-jitter + storlek/skip
      const h1 = ((wx * 73856093) ^ (wy * 19349663)) >>> 0;
      const h2 = ((wx * 83492791) ^ (wy * 49979693)) >>> 0;
      if ((h1 & 0xff) > 180) continue; // skip ~30% för spridning
      const jx = ((h1 >> 8) & 0xff) / 255 * blobSize * 0.8 - blobSize * 0.4;
      const jy = ((h2 >> 8) & 0xff) / 255 * blobSize * 0.8 - blobSize * 0.4;
      const r1 = 50 + ((h1 >> 16) & 0xff) / 255 * 80;
      const r2 = 40 + ((h2 >> 16) & 0xff) / 255 * 70;
      ctx.beginPath();
      ctx.ellipse(bx + jx, by + jy, r1, r2, ((h1 >> 24) & 0xff) / 255 * Math.PI, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // Mindre ljusare prickar (sten-fragment, ash-partiklar)
  ctx.fillStyle = 'rgba(80, 65, 50, 0.18)';
  const dotSize = 60;
  const dotOffX = Math.floor(cx / dotSize) * dotSize - cx;
  const dotOffY = Math.floor(cy / dotSize) * dotSize - cy;
  for (let dx = dotOffX; dx < viewW + dotSize; dx += dotSize) {
    for (let dy = dotOffY; dy < viewH + dotSize; dy += dotSize) {
      const wx = dx + cx, wy = dy + cy;
      const h = ((wx * 41281 + wy * 73529) ^ ((wx + wy) * 13)) >>> 0;
      if ((h & 0xff) > 90) continue;
      const jx = ((h >> 8) & 0xff) / 255 * dotSize - dotSize / 2;
      const jy = ((h >> 16) & 0xff) / 255 * dotSize - dotSize / 2;
      const r = 4 + ((h >> 24) & 0x1f) / 31 * 8;
      ctx.beginPath();
      ctx.arc(dx + jx, dy + jy, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // Mörka skugg-fläckar för djup
  ctx.fillStyle = 'rgba(8, 5, 3, 0.30)';
  const shadowSize = 220;
  const shOffX = Math.floor(cx / shadowSize) * shadowSize - cx - shadowSize;
  const shOffY = Math.floor(cy / shadowSize) * shadowSize - cy - shadowSize;
  for (let sx = shOffX; sx < viewW + shadowSize * 2; sx += shadowSize) {
    for (let sy = shOffY; sy < viewH + shadowSize * 2; sy += shadowSize) {
      const wx = sx + cx, wy = sy + cy;
      const h = ((wx * 31379 + wy * 51217) ^ ((wx - wy) * 19)) >>> 0;
      if ((h & 0xff) > 70) continue;
      const jx = ((h >> 8) & 0xff) / 255 * shadowSize * 0.6 - shadowSize * 0.3;
      const jy = ((h >> 16) & 0xff) / 255 * shadowSize * 0.6 - shadowSize * 0.3;
      const r1 = 70 + ((h >> 24) & 0x7f) / 127 * 60;
      const r2 = 60 + (((h >> 12) & 0x7f)) / 127 * 50;
      ctx.beginPath();
      ctx.ellipse(sx + jx, sy + jy, r1, r2, h / 100 * Math.PI, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // v1.578: glödande sprickor BORTA (användaren gillade inte strecken)

  // === PLAZA (obsidian-platta) ===
  const plazaScreenX = centerX - cx, plazaScreenY = centerY - cy;
  // Yttre ring: glödande ornament
  const outerPulse = 0.6 + 0.4 * Math.sin(t * 0.8);
  const outerGrad = ctx.createRadialGradient(plazaScreenX, plazaScreenY, plazaR - 20, plazaScreenX, plazaScreenY, plazaR + 25);
  outerGrad.addColorStop(0, 'rgba(60, 40, 30, 0)');
  outerGrad.addColorStop(0.6, `rgba(255, 120, 50, ${0.3 * outerPulse})`);
  outerGrad.addColorStop(1, 'rgba(255, 100, 30, 0)');
  ctx.fillStyle = outerGrad;
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, plazaR + 30, 0, Math.PI * 2);
  ctx.fill();
  // Huvud-plaza (mörk obsidian)
  ctx.fillStyle = '#1a0e0a';
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, plazaR, 0, Math.PI * 2);
  ctx.fill();
  // Obsidian-tekstur: röda ådror som radial linjer
  ctx.strokeStyle = 'rgba(120, 40, 20, 0.7)';
  ctx.lineWidth = 1.5;
  for (let i = 0; i < 16; i++) {
    const a = i * Math.PI / 8 + t * 0.05;
    const r1 = 30 + (i % 3) * 25;
    const r2 = plazaR - 10 + (i % 5) * 4;
    ctx.beginPath();
    ctx.moveTo(plazaScreenX + Math.cos(a) * r1, plazaScreenY + Math.sin(a) * r1);
    ctx.lineTo(plazaScreenX + Math.cos(a) * r2, plazaScreenY + Math.sin(a) * r2);
    ctx.stroke();
  }
  // Inner concentric cracks
  ctx.strokeStyle = 'rgba(80, 25, 10, 0.6)';
  ctx.lineWidth = 1;
  for (let r = 50; r < plazaR - 20; r += 40) {
    ctx.beginPath();
    ctx.arc(plazaScreenX, plazaScreenY, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  // Central altar-glow (pulserande)
  const altarPulse = 0.7 + 0.3 * Math.sin(t * 2);
  const altarGrad = ctx.createRadialGradient(plazaScreenX, plazaScreenY, 0, plazaScreenX, plazaScreenY, 80);
  altarGrad.addColorStop(0, `rgba(255, 200, 90, ${0.85 * altarPulse})`);
  altarGrad.addColorStop(0.4, `rgba(255, 130, 40, ${0.5 * altarPulse})`);
  altarGrad.addColorStop(1, 'rgba(255, 60, 10, 0)');
  ctx.fillStyle = altarGrad;
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, 80, 0, Math.PI * 2);
  ctx.fill();
  // Cracked altar-platta i mitten
  ctx.fillStyle = '#3a1a0a';
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, 35, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = `rgba(255, 180, 60, ${altarPulse})`;
  ctx.lineWidth = 2;
  // Pentagram-spår på altaret
  for (let i = 0; i < 5; i++) {
    const a = i * 2 * Math.PI / 5 - Math.PI / 2;
    const x1 = plazaScreenX + Math.cos(a) * 28;
    const y1 = plazaScreenY + Math.sin(a) * 28;
    const a2 = ((i + 2) % 5) * 2 * Math.PI / 5 - Math.PI / 2;
    const x2 = plazaScreenX + Math.cos(a2) * 28;
    const y2 = plazaScreenY + Math.sin(a2) * 28;
    ctx.beginPath();
    ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // === STEN-SKRÄP (sprid över marken) ===
  for (const r of cache.rubble) {
    const x = r.x - cx, y = r.y - cy;
    if (x < -20 || x > viewW + 20 || y < -20 || y > viewH + 20) continue;
    ctx.fillStyle = `rgba(${50 + r.shade * 60}, ${40 + r.shade * 40}, ${30 + r.shade * 30}, 0.85)`;
    ctx.beginPath();
    ctx.arc(x, y, r.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.lineWidth = 0.5;
    ctx.stroke();
  }

  // === v1.578: TAKTISKA VÄGGAR (concrete bunker-walls, gömställen) ===
  for (const r of cache.walls) {
    const x = r.x - cx, y = r.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(r.rot);
    // Skugga (mjuk, off-set)
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.fillRect(-r.w / 2 + 4, -r.h / 2 + 5, r.w, r.h);
    // Bas-betong (gradient mörk → ljus topp)
    const grad = ctx.createLinearGradient(0, -r.h / 2, 0, r.h / 2);
    grad.addColorStop(0, '#7a7268');
    grad.addColorStop(0.4, '#5a5048');
    grad.addColorStop(1, '#3a3028');
    ctx.fillStyle = grad;
    ctx.fillRect(-r.w / 2, -r.h / 2, r.w, r.h);
    // Top highlight (ljust kant)
    ctx.fillStyle = '#8a8278';
    ctx.fillRect(-r.w / 2, -r.h / 2, r.w, 2);
    // Riv-skår (vertikala mörka linjer)
    ctx.fillStyle = 'rgba(20, 12, 8, 0.7)';
    const stripes = Math.floor(r.w / 14);
    for (let s = 0; s < stripes; s++) {
      const sx = -r.w / 2 + s * 14 + 4;
      ctx.fillRect(sx, -r.h / 2, 0.8, r.h);
    }
    // Skotthål (random baserat på seed)
    ctx.fillStyle = '#1a1008';
    for (let h = 0; h < 4; h++) {
      const hx = ((r.seed * 7 + h * 13) % 1) * r.w - r.w / 2;
      const hy = ((r.seed * 11 + h * 17) % 1) * r.h - r.h / 2;
      ctx.beginPath();
      ctx.arc(hx, hy, 1.5 + ((r.seed * 3 + h) % 1) * 1.5, 0, Math.PI * 2);
      ctx.fill();
    }
    // Decay edge — irregular top (krossade kant-segment)
    ctx.fillStyle = '#1a1208';
    const segments = 5;
    for (let s = 0; s < segments; s++) {
      const sx = -r.w / 2 + s * (r.w / segments);
      const sw = r.w / segments;
      const sh = (1 - r.decay) * 7 + ((r.seed * 5 + s) % 1) * 3;
      ctx.fillRect(sx, -r.h / 2 - sh, sw - 1, sh);
    }
    // Highlight på krossade kanten
    ctx.fillStyle = 'rgba(140, 130, 120, 0.5)';
    for (let s = 0; s < segments; s++) {
      const sx = -r.w / 2 + s * (r.w / segments);
      const sw = r.w / segments;
      const sh = (1 - r.decay) * 7 + ((r.seed * 5 + s) % 1) * 3;
      ctx.fillRect(sx, -r.h / 2 - sh, sw - 1, 1);
    }
    ctx.restore();
  }

  // === v1.578: FORDON-WRAK (jeepar + lastbilar, brinnande) ===
  for (const v of cache.vehicles) {
    const x = v.x - cx, y = v.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(v.rot);
    // Skugga
    ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
    ctx.fillRect(-v.w / 2 + 4, -v.h / 2 + 5, v.w, v.h);
    // Chassi (mörk metallisk olivgrön)
    const chassiGrad = ctx.createLinearGradient(0, -v.h / 2, 0, v.h / 2);
    chassiGrad.addColorStop(0, '#3a3a28');
    chassiGrad.addColorStop(0.5, '#2a2a18');
    chassiGrad.addColorStop(1, '#1a1a0a');
    ctx.fillStyle = chassiGrad;
    ctx.fillRect(-v.w / 2, -v.h / 2, v.w, v.h);
    // Brända marker (mörka fläckar)
    ctx.fillStyle = '#0a0a08';
    ctx.fillRect(-v.w / 2 + 4, -v.h / 4, v.w * 0.3, v.h * 0.5);
    ctx.fillRect(v.w * 0.15, -v.h / 3, v.w * 0.2, v.h * 0.4);
    // Hjul (svarta cirklar vid kanter)
    ctx.fillStyle = '#0a0a0a';
    const wheelR = v.h * 0.18;
    ctx.beginPath(); ctx.arc(-v.w * 0.35, -v.h / 2, wheelR, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(v.w * 0.35, -v.h / 2, wheelR, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(-v.w * 0.35, v.h / 2, wheelR, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(v.w * 0.35, v.h / 2, wheelR, 0, Math.PI * 2); ctx.fill();
    // Kabin (i mitten, ljusare för relief)
    ctx.fillStyle = '#4a4a3a';
    if (v.kind === 'truck') {
      ctx.fillRect(-v.w * 0.45, -v.h * 0.35, v.w * 0.25, v.h * 0.7);
    } else {
      ctx.fillRect(-v.w * 0.15, -v.h * 0.32, v.w * 0.3, v.h * 0.64);
    }
    // Trasiga fönster (svart)
    ctx.fillStyle = '#000';
    if (v.kind === 'truck') {
      ctx.fillRect(-v.w * 0.42, -v.h * 0.28, v.w * 0.18, v.h * 0.20);
    } else {
      ctx.fillRect(-v.w * 0.10, -v.h * 0.25, v.w * 0.20, v.h * 0.18);
    }
    // Rost-streck
    ctx.strokeStyle = '#5a3a18';
    ctx.lineWidth = 0.8;
    for (let l = 0; l < 4; l++) {
      const ly = -v.h / 2 + ((v.seed * 7 + l * 5) % 1) * v.h;
      ctx.beginPath();
      ctx.moveTo(-v.w / 2, ly);
      ctx.lineTo(-v.w / 2 + 8 + ((v.seed * 3 + l) % 1) * 12, ly);
      ctx.stroke();
    }
    ctx.restore();
    // Brinnande effect ovanpå (om burning)
    if (v.burn) {
      const flame = 0.7 + 0.3 * Math.sin(t * 5 + v.flamePhase);
      const flameH = 18 * flame;
      const flameGrad = ctx.createRadialGradient(x, y - flameH * 0.3, 0, x, y - flameH * 0.3, 30);
      flameGrad.addColorStop(0, `rgba(255, 200, 80, ${0.7 * flame})`);
      flameGrad.addColorStop(0.5, `rgba(255, 100, 30, ${0.4 * flame})`);
      flameGrad.addColorStop(1, 'rgba(255, 50, 10, 0)');
      ctx.fillStyle = flameGrad;
      ctx.beginPath();
      ctx.arc(x, y - flameH * 0.3, 30, 0, Math.PI * 2);
      ctx.fill();
      // Rök ovanpå
      ctx.fillStyle = `rgba(50, 40, 35, ${0.35 * flame})`;
      ctx.beginPath();
      ctx.arc(x + Math.sin(t * 0.4 + v.flamePhase) * 4, y - flameH - 8, 16, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // === v1.578: BETONG-PELARE (cylindriska, hard cover) ===
  for (const p of cache.pillars) {
    const x = p.x - cx, y = p.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) continue;
    // Skugga (ellipse på marken)
    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.beginPath();
    ctx.ellipse(x + 4, y + 5, p.r * 1.1, p.r * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();
    // Pelarkropp (cirkel med gradient)
    const pillarGrad = ctx.createRadialGradient(x - p.r * 0.3, y - p.r * 0.3, 0, x, y, p.r);
    pillarGrad.addColorStop(0, '#a89888');
    pillarGrad.addColorStop(0.6, '#685848');
    pillarGrad.addColorStop(1, '#382818');
    ctx.fillStyle = pillarGrad;
    ctx.beginPath();
    ctx.arc(x, y, p.r, 0, Math.PI * 2);
    ctx.fill();
    // Dark outline
    ctx.strokeStyle = '#1a1008';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // Sprickor (radial linjer)
    ctx.strokeStyle = 'rgba(30, 20, 10, 0.7)';
    ctx.lineWidth = 0.8;
    for (let cr = 0; cr < 3; cr++) {
      const ang = (cr / 3) * Math.PI * 2 + p.seed * Math.PI;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(ang) * p.r * 0.4, y + Math.sin(ang) * p.r * 0.4);
      ctx.lineTo(x + Math.cos(ang + 0.3) * p.r * 0.9, y + Math.sin(ang + 0.3) * p.r * 0.9);
      ctx.stroke();
    }
    // Topp-highlight (subtle inner cirkel)
    ctx.fillStyle = 'rgba(180, 170, 160, 0.3)';
    ctx.beginPath();
    ctx.arc(x - p.r * 0.25, y - p.r * 0.25, p.r * 0.3, 0, Math.PI * 2);
    ctx.fill();
  }

  // === v1.578: SANDBAG-BUNKERS (taktiska kort-cover) ===
  for (const sb of cache.sandbags) {
    const x = sb.x - cx, y = sb.y - cy;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) continue;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(sb.rot);
    // Skugga
    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.fillRect(-sb.len / 2 + 3, -sb.h / 2 + 4, sb.len, sb.h);
    // Rita varje sandbag (säck) i raden
    const bagW = sb.len / sb.bags;
    for (let b = 0; b < sb.bags; b++) {
      const bx = -sb.len / 2 + b * bagW + bagW / 2;
      // Säck (rundad rektangel via 2 cirklar + rect)
      ctx.fillStyle = '#8a7050';
      ctx.beginPath();
      ctx.ellipse(bx, 0, bagW * 0.45, sb.h * 0.5, 0, 0, Math.PI * 2);
      ctx.fill();
      // Highlight top
      ctx.fillStyle = '#a89070';
      ctx.beginPath();
      ctx.ellipse(bx - bagW * 0.15, -sb.h * 0.2, bagW * 0.25, sb.h * 0.25, 0, 0, Math.PI * 2);
      ctx.fill();
      // Söm-linje
      ctx.strokeStyle = '#5a4028';
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(bx - bagW * 0.4, -sb.h * 0.05);
      ctx.lineTo(bx + bagW * 0.4, -sb.h * 0.05);
      ctx.stroke();
      // Random dirty patches
      if ((sb.seed * 7 + b * 3) % 1 > 0.5) {
        ctx.fillStyle = 'rgba(50, 35, 20, 0.5)';
        ctx.beginPath();
        ctx.arc(bx + (((sb.seed * 5 + b) % 1) - 0.5) * bagW * 0.5, sb.h * 0.1, 2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    // Andra raden ovanpå (lite mindre)
    if (sb.bags >= 3) {
      const bagW2 = sb.len * 0.7 / (sb.bags - 1);
      for (let b = 0; b < sb.bags - 1; b++) {
        const bx = -sb.len * 0.35 + b * bagW2 + bagW2 / 2;
        ctx.fillStyle = '#7a6042';
        ctx.beginPath();
        ctx.ellipse(bx, -sb.h * 0.6, bagW2 * 0.4, sb.h * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#9a8060';
        ctx.beginPath();
        ctx.ellipse(bx - bagW2 * 0.1, -sb.h * 0.75, bagW2 * 0.18, sb.h * 0.18, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  // === BRÄNDA TRÄD ===
  for (const tree of cache.burntTrees) {
    const x = tree.x - cx, y = tree.y - cy;
    if (x < -30 || x > viewW + 30 || y < -50 || y > viewH + 30) continue;
    // Skugga
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.beginPath();
    ctx.ellipse(x + 5, y + 5, tree.h * 0.3, tree.h * 0.15, 0, 0, Math.PI * 2);
    ctx.fill();
    // Stamm (broken at brokenAt)
    const trunkH = tree.h * tree.brokenAt;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tree.lean);
    ctx.fillStyle = '#1a0e05';
    ctx.fillRect(-2, -trunkH, 4, trunkH);
    // Charred highlight
    ctx.fillStyle = '#3a200a';
    ctx.fillRect(-2, -trunkH, 1.5, trunkH);
    // Top broken edge
    ctx.fillStyle = '#5a3015';
    ctx.beginPath();
    ctx.moveTo(-2, -trunkH);
    ctx.lineTo(0, -trunkH - 3);
    ctx.lineTo(2, -trunkH);
    ctx.closePath();
    ctx.fill();
    // Brutna gren-stubbar
    if (tree.brokenAt > 0.5) {
      ctx.fillStyle = '#1a0e05';
      ctx.fillRect(-5, -trunkH + 5, 3, 1.5);
      ctx.fillRect(2, -trunkH + 10, 3, 1.5);
    }
    ctx.restore();
  }

  // === TORCH-STATIV (övergivna brinnande facklor runt plaza) ===
  for (const torch of cache.torches) {
    const x = torch.x - cx, y = torch.y - cy;
    if (x < -30 || x > viewW + 30 || y < -50 || y > viewH + 30) continue;
    // Stativ-stång
    ctx.fillStyle = '#2a1a10';
    ctx.fillRect(x - 1.5, y - 14, 3, 16);
    // Bowl
    ctx.fillStyle = '#3a2a18';
    ctx.beginPath();
    ctx.ellipse(x, y - 15, 5, 2.5, 0, 0, Math.PI * 2);
    ctx.fill();
    // Flame (animerad)
    const flame = 0.8 + 0.2 * Math.sin(t * 6 + torch.flamePhase);
    const flameH = 12 * flame;
    // Outer red glow
    const flameGrad = ctx.createRadialGradient(x, y - 15 - flameH * 0.4, 0, x, y - 15 - flameH * 0.4, 20);
    flameGrad.addColorStop(0, `rgba(255, 200, 90, ${0.7 * flame})`);
    flameGrad.addColorStop(0.5, `rgba(255, 100, 30, ${0.3 * flame})`);
    flameGrad.addColorStop(1, 'rgba(255, 50, 10, 0)');
    ctx.fillStyle = flameGrad;
    ctx.beginPath();
    ctx.arc(x, y - 15 - flameH * 0.4, 20, 0, Math.PI * 2);
    ctx.fill();
    // Flame-shape (teardrop)
    ctx.fillStyle = `rgba(255, 180, 60, ${flame})`;
    ctx.beginPath();
    ctx.moveTo(x, y - 15);
    ctx.quadraticCurveTo(x - 3, y - 15 - flameH * 0.5, x, y - 15 - flameH);
    ctx.quadraticCurveTo(x + 3, y - 15 - flameH * 0.5, x, y - 15);
    ctx.fill();
    // Inner hot core
    ctx.fillStyle = `rgba(255, 250, 200, ${0.9 * flame})`;
    ctx.beginPath();
    ctx.ellipse(x, y - 15 - flameH * 0.4, 1.5, flameH * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
  // v1.580: DEBUG — rita röda rektanglar runt alla obstacles när diag är aktiv
  // så användaren ser exakt var collision-boxar är + om de finns på kartan
  if (window._pixiDiag && cache.obstacles) {
    ctx.save();
    ctx.strokeStyle = 'rgba(255, 80, 80, 0.7)';
    ctx.lineWidth = 1.5;
    for (const ob of cache.obstacles) {
      const ox = ob.x - cx, oy = ob.y - cy;
      if (ox < -60 || ox > viewW + 60 || oy < -60 || oy > viewH + 60) continue;
      if (ob.isCircle) {
        ctx.beginPath();
        ctx.arc(ox, oy, ob.r, 0, Math.PI * 2);
        ctx.stroke();
      } else {
        ctx.strokeRect(ox - ob.w / 2, oy - ob.h / 2, ob.w, ob.h);
      }
    }
    ctx.restore();
  }
}

// v1.533: Mini-boss-indicator (pekande pil mot off-screen boss i 4s)
function drawSurvivorsBossIndicator() {
  if (!state.survivorsActive || !state.survivorsBossIndicator) return;
  const indicator = state.survivorsBossIndicator;
  const elapsed = performance.now() - indicator.startT;
  if (elapsed > 4000) { state.survivorsBossIndicator = null; return; }
  const fade = 1 - (elapsed / 4000);
  // Boss-pos i screen-coords
  const bx = indicator.x - state.camera.x;
  const by = indicator.y - state.camera.y;
  // Beräkna vinkel från center till boss
  const cx = viewW / 2, cy = viewH / 2;
  const ang = Math.atan2(by - cy, bx - cx);
  // Place arrow vid skärm-edge (offset från center i ang-direction, max ~70% av halv-screen)
  const margin = 60;
  const halfW = viewW / 2 - margin;
  const halfH = viewH / 2 - margin;
  const cosA = Math.cos(ang), sinA = Math.sin(ang);
  const scale = Math.min(halfW / Math.abs(cosA || 0.001), halfH / Math.abs(sinA || 0.001));
  const ax = cx + cosA * scale;
  const ay = cy + sinA * scale;
  // Rita pil
  ctx.save();
  ctx.translate(ax, ay);
  ctx.rotate(ang);
  ctx.globalAlpha = fade * (0.7 + 0.3 * Math.sin(performance.now() / 100));
  // Pulserande röd pil
  ctx.fillStyle = '#ff3a3a';
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(20, 0);
  ctx.lineTo(-12, -12);
  ctx.lineTo(-6, 0);
  ctx.lineTo(-12, 12);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  // Text "BOSS" under pilen
  ctx.rotate(-ang); // un-rotate så text är horisontell
  ctx.fillStyle = '#ff5a5a';
  ctx.font = '900 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('⚠️ ' + indicator.name, 0, 30);
  ctx.restore();
}

// Ash particles + vignette — kallas EFTER spelare/enemies (top layer)
function drawSurvivorsArenaAmbient() {
  if (!state.survivorsActive) return;
  const t = performance.now() / 1000;
  ctx.save();
  // v1.533: THORNS visuell aura — pulserande röd ring runt spelaren när perk aktiv
  if (typeof getSurvivorsPerkSum === 'function' && state.player && state.player.hp > 0) {
    const thornsDps = getSurvivorsPerkSum('thorns');
    if (thornsDps > 0) {
      const px = state.player.x - state.camera.x;
      const py = state.player.y - state.camera.y;
      const pulse = 0.5 + 0.3 * Math.sin(t * 4);
      // Outer fading ring
      const auraGrad = ctx.createRadialGradient(px, py, 70, px, py, 105);
      auraGrad.addColorStop(0, 'rgba(255, 60, 60, 0)');
      auraGrad.addColorStop(0.7, `rgba(255, 80, 50, ${0.18 * pulse})`);
      auraGrad.addColorStop(1, 'rgba(255, 50, 30, 0)');
      ctx.fillStyle = auraGrad;
      ctx.beginPath();
      ctx.arc(px, py, 105, 0, Math.PI * 2);
      ctx.fill();
      // Inner ring outline
      ctx.strokeStyle = `rgba(255, 80, 80, ${0.4 * pulse})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(px, py, 100, 0, Math.PI * 2);
      ctx.stroke();
    }
  }
  // Fallande aska — semi-transparent particles ovanpå allt
  // 30 deterministisk-positionerade snöflingor som drifter ner
  const cache = state._survArenaCache;
  if (cache) {
    if (!cache.ash) {
      const rng = _survRng(1337);
      cache.ash = [];
      for (let i = 0; i < 60; i++) {
        cache.ash.push({
          x: rng() * viewW,
          y: rng() * (viewH + 40),
          r: 0.7 + rng() * 1.4,
          speed: 6 + rng() * 12,
          phase: rng() * Math.PI * 2,
        });
      }
    }
    ctx.fillStyle = 'rgba(180, 150, 130, 0.45)';
    for (const a of cache.ash) {
      const yPos = ((a.y + t * a.speed) % (viewH + 40));
      const xWobble = Math.sin(t * 0.8 + a.phase) * 12;
      ctx.beginPath();
      ctx.arc(a.x + xWobble, yPos, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // Vignette: mörkare hörn för "post-apocalyptic" feel
  const vignette = ctx.createRadialGradient(viewW / 2, viewH / 2, viewH * 0.4, viewW / 2, viewH / 2, viewH * 0.8);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0)');
  vignette.addColorStop(1, 'rgba(20, 5, 0, 0.55)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, viewW, viewH);
  ctx.restore();
}

function drawCastleDefenseGround() {
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const centerX = (state.castledefenseCore && state.castledefenseCore.x) || 2000;
  const centerY = (state.castledefenseCore && state.castledefenseCore.y) || 2000;
  const plazaR = state.castledefensePlazaRadius || 220;
  const pathColor = state.castledefensePathColor || '#6a5a48';
  const plazaColor = state.castledefensePlazaColor || '#5a5450';
  ctx.save();
  // === STENVÄGAR från enemy-spawnar mot center ===
  // Linjer drawn med soft falloff så de inte ser tråkiga ut. 60px breda.
  if (state.castledefenseEnemySpawns) {
    ctx.strokeStyle = pathColor;
    ctx.lineWidth = 60;
    ctx.lineCap = 'round';
    ctx.globalAlpha = 0.45;
    ctx.beginPath();
    for (const sp of state.castledefenseEnemySpawns) {
      const sx = sp.x - cx, sy = sp.y - cy;
      const ex = centerX - cx, ey = centerY - cy;
      // Begränsa till plaza-edge (annars överlappar plaza)
      const dx = ex - sx, dy = ey - sy;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d > plazaR) {
        const t = (d - plazaR + 30) / d;
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx + dx * t, sy + dy * t);
      }
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  // === PLAZA (cirkulär sten-yta runt core) ===
  const plazaScreenX = centerX - cx, plazaScreenY = centerY - cy;
  // Yttre ring: ornament-band
  ctx.fillStyle = '#3a3530';
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, plazaR + 8, 0, Math.PI * 2);
  ctx.fill();
  // Huvud-plaza
  ctx.fillStyle = plazaColor;
  ctx.beginPath();
  ctx.arc(plazaScreenX, plazaScreenY, plazaR, 0, Math.PI * 2);
  ctx.fill();
  // Tile-mönster: koncentriska cirklar + 8 radiella linjer
  ctx.strokeStyle = 'rgba(40,35,30,0.5)';
  ctx.lineWidth = 1.5;
  for (let r = 40; r < plazaR; r += 40) {
    ctx.beginPath();
    ctx.arc(plazaScreenX, plazaScreenY, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    ctx.beginPath();
    ctx.moveTo(plazaScreenX, plazaScreenY);
    ctx.lineTo(plazaScreenX + Math.cos(a) * plazaR, plazaScreenY + Math.sin(a) * plazaR);
    ctx.stroke();
  }
  // === BUILD-GRID OVERLAY (subtle) ===
  if (state.cdBuildMode && state.castledefenseBuildGridSize) {
    // Visa grid bara när i build-mode (annars distrahering)
    const grid = state.castledefenseBuildGridSize;
    const startX = Math.floor(cx / grid) * grid - cx;
    const startY = Math.floor(cy / grid) * grid - cy;
    ctx.strokeStyle = 'rgba(255, 200, 100, 0.15)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = startX; x < viewW + grid; x += grid) {
      ctx.moveTo(x + 0.5, 0);
      ctx.lineTo(x + 0.5, viewH);
    }
    for (let y = startY; y < viewH + grid; y += grid) {
      ctx.moveTo(0, y + 0.5);
      ctx.lineTo(viewW, y + 0.5);
    }
    ctx.stroke();
  }
  ctx.restore();
}

// Dekorationer på marken (under spelare): rock-shadows, grass-tufts, banner-base
function drawCastleDefenseDecorationsGround() {
  if (!state.castledefenseDecorations) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (const d of state.castledefenseDecorations) {
    const x = d.x - cx, y = d.y - cy;
    if (x < -100 || x > viewW + 100 || y < -100 || y > viewH + 100) continue;
    if (d.kind === 'rock') {
      const r = d.r || 22;
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.ellipse(x + 3, y + 3, r, r * 0.85, 0, 0, Math.PI * 2);
      ctx.fill();
      // Sten
      ctx.fillStyle = '#7a7a7a';
      ctx.beginPath();
      ctx.ellipse(x, y, r, r * 0.85, 0, 0, Math.PI * 2);
      ctx.fill();
      // Mörkare nedre del
      ctx.fillStyle = '#5a5a5a';
      ctx.beginPath();
      ctx.ellipse(x, y + r * 0.3, r * 0.9, r * 0.4, 0, 0, Math.PI * 2);
      ctx.fill();
      // Highlight
      ctx.fillStyle = '#aaaaaa';
      ctx.beginPath();
      ctx.ellipse(x - r * 0.3, y - r * 0.3, r * 0.4, r * 0.25, 0, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'grass_tuft') {
      ctx.strokeStyle = '#5aaa3a';
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(a) * 6, y - Math.abs(Math.sin(a)) * 8);
        ctx.stroke();
      }
    } else if (d.kind === 'banner') {
      // Stolp-skugga (banner-render i top-layer)
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillRect(x - 2 + 2, y - 4 + 2, 4, 8);
    } else if (d.kind === 'torch') {
      // Torch-bas (top är flammen)
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(x, y + 2, 10, 4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#4a3520';
      ctx.fillRect(x - 3, y - 8, 6, 12);
      ctx.fillStyle = '#2a1810';
      ctx.fillRect(x - 4, y - 10, 8, 3);
    } else if (d.kind === 'tree') {
      // Bara trunken här (kronan ovanpå spelare)
      const r = d.r || 24;
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.beginPath();
      ctx.ellipse(x + 3, y + r * 0.7, r * 0.9, r * 0.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3a2515';
      ctx.fillRect(x - 4, y - 2, 8, r * 0.7);
    }
  }
  ctx.restore();
}

// Dekorationer ovanpå spelare: träd-kronor, fackel-flammor, banderoller
function drawCastleDefenseDecorationsTop() {
  if (!state.castledefenseDecorations) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now() / 1000;
  ctx.save();
  for (const d of state.castledefenseDecorations) {
    const x = d.x - cx, y = d.y - cy;
    if (x < -100 || x > viewW + 100 || y < -100 || y > viewH + 100) continue;
    if (d.kind === 'tree') {
      const r = d.r || 24;
      // Krona (3 lager) — grön med skugga
      ctx.fillStyle = '#1a3a1a';
      ctx.beginPath();
      ctx.arc(x + 2, y - r * 0.4 + 2, r * 1.05, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#2a6a2a';
      ctx.beginPath();
      ctx.arc(x, y - r * 0.4, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3a8a3a';
      ctx.beginPath();
      ctx.arc(x - r * 0.25, y - r * 0.55, r * 0.6, 0, Math.PI * 2);
      ctx.fill();
      // Highlight
      ctx.fillStyle = '#5aaa5a';
      ctx.beginPath();
      ctx.arc(x - r * 0.35, y - r * 0.65, r * 0.25, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'torch') {
      // Flamma (animerad)
      const flicker = 1 + Math.sin(t * 12 + d.x) * 0.15;
      ctx.fillStyle = 'rgba(255,160,40,0.5)';
      ctx.beginPath();
      ctx.arc(x, y - 14, 14 * flicker, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffaa30';
      ctx.beginPath();
      ctx.ellipse(x, y - 14, 4 * flicker, 8 * flicker, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffd060';
      ctx.beginPath();
      ctx.ellipse(x, y - 15, 2 * flicker, 5 * flicker, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffffaa';
      ctx.beginPath();
      ctx.arc(x, y - 16, 1.5, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'banner') {
      // Stolpe
      ctx.fillStyle = '#3a2510';
      ctx.fillRect(x - 1, y - 22, 2, 26);
      // Tygduk (vajande)
      const sway = Math.sin(t * 2 + d.x * 0.01) * 1.5;
      ctx.fillStyle = d.color || '#aa3030';
      ctx.beginPath();
      ctx.moveTo(x + 1, y - 22);
      ctx.lineTo(x + 14 + sway, y - 22);
      ctx.lineTo(x + 12 + sway, y - 6);
      ctx.lineTo(x + 1, y - 6);
      ctx.closePath();
      ctx.fill();
      // Detalj på duk: vit symbol
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fillRect(x + 5 + sway / 2, y - 16, 4, 4);
    }
  }
  ctx.restore();
}

function drawCastleDefenseWalls() {
  // v1.397: inga pre-built walls. Player-built walls ritas via drawCastleDefenseBuildings.
  // Kvar för bakåtkompatibilitet (om ev. legacy walls finns från äldre cd_started-event).
  if (!state.castledefenseWalls || state.castledefenseWalls.length === 0) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (const w of state.castledefenseWalls) {
    if (w.hp <= 0) continue;
    const x = w.x - cx, y = w.y - cy;
    if (x + w.w < 0 || x > viewW || y + w.h < 0 || y > viewH) continue;
    ctx.fillStyle = '#7a6a5a';
    ctx.fillRect(x, y, w.w, w.h);
    ctx.strokeStyle = '#3a2a1a';
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, w.w - 1, w.h - 1);
  }
  ctx.restore();
}

function drawCastleDefenseWalls() {
  if (!state.castledefenseWalls) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (const w of state.castledefenseWalls) {
    if (w.hp <= 0) {
      // Förstörd — rita ruiner (mörk sten + sprickor)
      const x = w.x - cx, y = w.y - cy;
      if (x + w.w < 0 || x > viewW || y + w.h < 0 || y > viewH) continue;
      ctx.fillStyle = '#2a1e14';
      ctx.fillRect(x, y, w.w, w.h);
      ctx.strokeStyle = '#1a0e08';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w.w - 1, w.h - 1);
      continue;
    }
    const x = w.x - cx, y = w.y - cy;
    if (x + w.w < 0 || x > viewW || y + w.h < 0 || y > viewH) continue;
    // HP-procent → färg lerping (full=sten-grå, halvt=brun, lågt=röd-brun)
    const hpPct = w.hp / w.maxHp;
    let fillColor = '#6a5a4a';      // full = stengrå
    let strokeColor = '#3a2a1a';
    if (hpPct < 0.66) fillColor = '#5a4030';
    if (hpPct < 0.33) { fillColor = '#5a2020'; strokeColor = '#2a0808'; }
    ctx.fillStyle = fillColor;
    ctx.fillRect(x, y, w.w, w.h);
    // Sten-textur: mörka linjer för "stenblock"-skarvar
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, w.w - 1, w.h - 1);
    // Block-skarvar (varje 40px ungefär)
    if (w.w > w.h) {
      // Horisontell wall — vertikala skarvar
      for (let xx = 40; xx < w.w; xx += 40) {
        ctx.beginPath();
        ctx.moveTo(x + xx + 0.5, y);
        ctx.lineTo(x + xx + 0.5, y + w.h);
        ctx.stroke();
      }
    } else {
      // Vertikal wall — horisontella skarvar
      for (let yy = 40; yy < w.h; yy += 40) {
        ctx.beginPath();
        ctx.moveTo(x, y + yy + 0.5);
        ctx.lineTo(x + w.w, y + yy + 0.5);
        ctx.stroke();
      }
    }
    // HP-bar ovanför wall (om skadad)
    if (hpPct < 1.0) {
      const barW = Math.max(28, w.w * 0.4);
      const barX = x + w.w / 2 - barW / 2;
      const barY = y - 8;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(barX, barY, barW, 4);
      ctx.fillStyle = hpPct > 0.5 ? '#5aff5a' : (hpPct > 0.25 ? '#ffd54a' : '#ff5a5a');
      ctx.fillRect(barX, barY, barW * hpPct, 4);
    }
  }
  ctx.restore();
}

// v1.397: BASEN = ancient obelisk-shrine. Stor + iconisk + animerad.
// Lager (botten upp):
//  - Glow-aura (radial gradient)
//  - Octagonal platform (mörk sten)
//  - Yttre ring (sten + ornament-band)
//  - Rune-cirkel (rotating glyphs i blå)
//  - Obelisk-projektion (vertikal sten-skugga)
//  - Kristall-core i mitten (pulsing gold/orange)
//  - HP-bar med namn ovanför
//  - Particle-sparks som flyger upp
function drawCastleDefenseCore() {
  if (!state.castledefenseCore) return;
  const core = state.castledefenseCore;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const x = core.x - cx, y = core.y - cy;
  if (x < -200 || x > viewW + 200 || y < -200 || y > viewH + 200) return;
  ctx.save();
  const t = performance.now() / 1000;
  const hpPct = core.hp / core.maxHp;
  const R = core.r;                   // 80px base radius
  // === LAYER 1: Glow-aura (outer) ===
  const pulse = 0.7 + Math.sin(t * 2) * 0.3;
  const glowR = R * 2.4;
  const glowGrad = ctx.createRadialGradient(x, y, R * 0.5, x, y, glowR);
  const glowColor = hpPct > 0.5 ? '255,224,140' : (hpPct > 0.25 ? '255,170,80' : '255,80,80');
  glowGrad.addColorStop(0, 'rgba(' + glowColor + ',' + (0.4 * pulse) + ')');
  glowGrad.addColorStop(0.5, 'rgba(' + glowColor + ',' + (0.18 * pulse) + ')');
  glowGrad.addColorStop(1, 'rgba(' + glowColor + ',0)');
  ctx.fillStyle = glowGrad;
  ctx.beginPath();
  ctx.arc(x, y, glowR, 0, Math.PI * 2);
  ctx.fill();
  // === LAYER 2: Octagonal stone platform (basen) ===
  function drawOctagon(cxLocal, cyLocal, radius) {
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const ang = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const px = cxLocal + Math.cos(ang) * radius;
      const py = cyLocal + Math.sin(ang) * radius;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }
  // Plattform-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  drawOctagon(x + 3, y + 5, R * 1.2);
  ctx.fill();
  // Yttre platform-ring (mörk granit)
  ctx.fillStyle = '#2a2520';
  drawOctagon(x, y, R * 1.2);
  ctx.fill();
  // Inner platform-ring (ljusare sten)
  ctx.fillStyle = '#4a4540';
  drawOctagon(x, y, R * 1.05);
  ctx.fill();
  // Ornament-detaljer på platform (8 punkter vid hörn)
  ctx.fillStyle = '#1a1510';
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2 + Math.PI / 8;
    const px = x + Math.cos(ang) * (R * 1.08);
    const py = y + Math.sin(ang) * (R * 1.08);
    ctx.beginPath();
    ctx.arc(px, py, 4, 0, Math.PI * 2);
    ctx.fill();
  }
  // === LAYER 3: Rune-cirkel (roterar långsamt) ===
  const runeRot = t * 0.3;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(runeRot);
  ctx.strokeStyle = 'rgba(90,202,255,' + (0.6 * pulse) + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, 0, R * 0.9, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 0, R * 0.7, 0, Math.PI * 2);
  ctx.stroke();
  // Glyphs runt rune-cirkeln (kors-symbol var 45°)
  ctx.fillStyle = 'rgba(140,220,255,' + (0.8 * pulse) + ')';
  ctx.font = 'bold 14px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const glyphs = ['✦', '✧', '⟁', '◈', '✦', '✧', '⟁', '◈'];
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2;
    const gx = Math.cos(ang) * R * 0.8;
    const gy = Math.sin(ang) * R * 0.8;
    ctx.fillText(glyphs[i], gx, gy);
  }
  ctx.restore();
  // === LAYER 4: Center crystal cluster ===
  // Stora crystal-spikes i mitten (4 st)
  const crystalCol = hpPct > 0.5 ? '#ffd060' : (hpPct > 0.25 ? '#ff9050' : '#ff5040');
  const crystalCore = hpPct > 0.5 ? '#fff8d0' : (hpPct > 0.25 ? '#ffd060' : '#ff8050');
  ctx.fillStyle = crystalCol;
  ctx.strokeStyle = '#1a0a04';
  ctx.lineWidth = 2;
  // Outer cluster ring
  for (let i = 0; i < 6; i++) {
    const ang = (i / 6) * Math.PI * 2 + t * 0.5;
    const spX = x + Math.cos(ang) * R * 0.45;
    const spY = y + Math.sin(ang) * R * 0.45;
    const tipX = x + Math.cos(ang) * R * 0.65;
    const tipY = y + Math.sin(ang) * R * 0.65;
    const widthAng = 0.25;
    ctx.beginPath();
    ctx.moveTo(x + Math.cos(ang - widthAng) * R * 0.3, y + Math.sin(ang - widthAng) * R * 0.3);
    ctx.lineTo(tipX, tipY);
    ctx.lineTo(x + Math.cos(ang + widthAng) * R * 0.3, y + Math.sin(ang + widthAng) * R * 0.3);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
  // Central crystal-orb
  const orbR = R * 0.32;
  const orbGrad = ctx.createRadialGradient(x - orbR * 0.3, y - orbR * 0.3, 0, x, y, orbR);
  orbGrad.addColorStop(0, '#ffffff');
  orbGrad.addColorStop(0.4, crystalCore);
  orbGrad.addColorStop(1, crystalCol);
  ctx.fillStyle = orbGrad;
  ctx.beginPath();
  ctx.arc(x, y, orbR, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#1a0a04';
  ctx.lineWidth = 2;
  ctx.stroke();
  // Inner shine
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.beginPath();
  ctx.arc(x - orbR * 0.35, y - orbR * 0.35, orbR * 0.3, 0, Math.PI * 2);
  ctx.fill();
  // === LAYER 5: Particle-sparks som stiger upp (3-4 vid varje tick) ===
  state._cdCoreSparks = state._cdCoreSparks || [];
  if (Math.random() < 0.4 && state._cdCoreSparks.length < 40) {
    const ang = Math.random() * Math.PI * 2;
    const sr = orbR + Math.random() * 8;
    state._cdCoreSparks.push({
      x: core.x + Math.cos(ang) * sr,
      y: core.y + Math.sin(ang) * sr,
      vx: (Math.random() - 0.5) * 8,
      vy: -20 - Math.random() * 30,
      life: 1.0 + Math.random() * 0.8,
      maxLife: 1.0 + Math.random() * 0.8,
      color: crystalCore,
    });
  }
  // Update + render sparks
  for (let i = state._cdCoreSparks.length - 1; i >= 0; i--) {
    const s = state._cdCoreSparks[i];
    s.life -= 0.016;
    s.x += s.vx * 0.016;
    s.y += s.vy * 0.016;
    s.vy += 8 * 0.016;
    if (s.life <= 0) {
      state._cdCoreSparks.splice(i, 1);
      continue;
    }
    const sa = s.life / s.maxLife;
    ctx.fillStyle = s.color;
    ctx.globalAlpha = sa;
    ctx.beginPath();
    ctx.arc(s.x - cx, s.y - cy, 2, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  // === LAYER 6: HP-bar + namn ovanför ===
  const barW = 140, barH = 10;
  const barX = x - barW / 2, barY = y - R - 32;
  // Namn-label
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 3;
  ctx.fillText('🏛 BASEN', x, barY - 4);
  ctx.shadowBlur = 0;
  // HP-bar bakgrund
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(barX - 2, barY - 2, barW + 4, barH + 4);
  // HP-fill
  const barCol = hpPct > 0.5 ? '#5aff5a' : (hpPct > 0.25 ? '#ffd54a' : '#ff5a5a');
  ctx.fillStyle = barCol;
  ctx.fillRect(barX, barY, barW * hpPct, barH);
  // Segment-lines (var 25%)
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.lineWidth = 1;
  for (let i = 1; i < 4; i++) {
    const sx = barX + (barW * i / 4);
    ctx.beginPath();
    ctx.moveTo(sx, barY);
    ctx.lineTo(sx, barY + barH);
    ctx.stroke();
  }
  // HP-text
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 9px monospace';
  ctx.fillText(Math.ceil(core.hp) + ' / ' + core.maxHp, x, barY + barH - 1);
  ctx.restore();
}

// layer: 'ground' (flat traps) | 'tall' (walls/turrets/stations) | undefined (all — legacy)
// v1.416: Tier-bracket från level (1-4) för progressiva visuals
function cdBuildingTier(level) {
  if (level >= 7) return 4; // EPIC (level 8-10)
  if (level >= 4) return 3; // HIGH (level 5-7)
  if (level >= 2) return 2; // MID (level 3-4)
  return 1;                 // BASIC (level 1-2)
}
// v1.416: Tier-färger för accent + glow
function cdTierAccent(tier) {
  if (tier === 4) return { glow: '#ffd54a', accent: '#ffe080', particle: 'rgba(255,213,74,0.5)' };
  if (tier === 3) return { glow: '#aa5aff', accent: '#cc88ff', particle: 'rgba(180,90,255,0.5)' };
  if (tier === 2) return { glow: '#5acaff', accent: '#8addff', particle: 'rgba(90,200,255,0.4)' };
  return { glow: null, accent: null, particle: null };
}

function drawCastleDefenseBuildings(layer) {
  if (!state.castledefenseBuildings || !state.castledefenseBuildings.length) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now() / 1000;
  ctx.save();
  for (const b of state.castledefenseBuildings) {
    if (b.hp <= 0) continue;
    // v1.411: walls flyttade till ground-layer så de ritas UNDER players.
    // Collision oförändrad — enemies blockas fortfarande av walls.
    const isGroundLayer = (b.kind === 'spike_trap' || b.kind === 'slow_trap' || b.kind === 'wall');
    if (layer === 'ground' && !isGroundLayer) continue;
    if (layer === 'tall' && isGroundLayer) continue;
    const x = b.x - cx, y = b.y - cy;
    if (x + b.w < 0 || x > viewW || y + b.h < 0 || y > viewH) continue;
    const bcx = x + b.w / 2, bcy = y + b.h / 2;
    const hpPct = b.hp / b.maxHp;
    // Drop-shadow (skippa för flat traps — de är redan på marken).
    // v1.413: wall får drop-shadow trots ground-layer så den ser SOLID ut.
    if (!isGroundLayer || b.kind === 'wall') {
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.fillRect(x + 2, y + 3, b.w, b.h);
    }
    // v1.416: Tier-bracket från level (1-4) för progressiva visuals
    const tier = cdBuildingTier(b.level || 0);
    const tierA = cdTierAccent(tier);
    // v1.419: Range-ring visas när player står PÅ byggnaden (strikt AABB)
    let showRangeRing = false;
    if (state.player) {
      const px = state.player.x, py = state.player.y;
      if (px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h) showRangeRing = true;
    }
    // === Per-kind sprite (detaljerade v1.397, tier-progressiv v1.416) ===
    if (b.kind === 'wall') {
      // Stenblock med crenellation (battlements) på top + mortar-linjer
      // Tier-progression: 1=grå sten, 2=metallisk blå, 3=mörk lila-glow, 4=guld-ornament
      let baseCol, shadowCol, highlightCol;
      if (tier === 4) {
        baseCol = '#aa8a4a'; shadowCol = '#6a4a18'; highlightCol = '#ffd580';
      } else if (tier === 3) {
        baseCol = '#5a4a6a'; shadowCol = '#2a1a3a'; highlightCol = '#9a7aba';
      } else if (tier === 2) {
        baseCol = '#6a7a8a'; shadowCol = '#3a4a5a'; highlightCol = '#8a9aaa';
      } else {
        baseCol = hpPct > 0.5 ? '#8a7a68' : (hpPct > 0.25 ? '#7a6048' : '#6a4030');
        shadowCol = hpPct > 0.5 ? '#5a4a38' : (hpPct > 0.25 ? '#4a3018' : '#3a1810');
        highlightCol = hpPct > 0.5 ? '#a89a88' : (hpPct > 0.25 ? '#988068' : '#886050');
      }
      // Main block
      ctx.fillStyle = baseCol;
      ctx.fillRect(x, y, b.w, b.h);
      // Top highlight (3px)
      ctx.fillStyle = highlightCol;
      ctx.fillRect(x, y, b.w, 3);
      // Bottom shadow (3px)
      ctx.fillStyle = shadowCol;
      ctx.fillRect(x, y + b.h - 3, b.w, 3);
      // Mortar pattern: 2 horisontella + 1 vertikal split
      ctx.fillStyle = shadowCol;
      ctx.fillRect(x, y + 10, b.w, 1);
      ctx.fillRect(x, y + 20, b.w, 1);
      ctx.fillRect(x + 15, y, 1, 10);
      ctx.fillRect(x + 8, y + 10, 1, 10);
      ctx.fillRect(x + 22, y + 10, 1, 10);
      ctx.fillRect(x + 15, y + 20, 1, 10);
      // Outline
      ctx.strokeStyle = '#1a0808';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, b.w - 1, b.h - 1);
      // v1.416: Tier 3+ glow-aura. Tier 4 har guld-crown ornament.
      if (tier >= 3) {
        const glowPulse = 0.3 + Math.sin(t * 3) * 0.2;
        ctx.fillStyle = tierA.glow ? (tierA.particle || 'rgba(255,200,80,' + glowPulse + ')') : 'rgba(255,200,80,' + glowPulse + ')';
        ctx.fillRect(x - 1, y - 1, b.w + 2, 2); // top-glow-band
      }
    } else if (b.kind === 'auto_turret') {
      // === AUTO-TURRET — stenas med cannon-tower ===
      // Stenbas (oktagonal)
      ctx.fillStyle = '#3a3530';
      ctx.beginPath();
      ctx.arc(bcx, bcy, b.w / 2 - 1, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#1a1510';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      // Inre platta
      ctx.fillStyle = '#4a4540';
      ctx.beginPath();
      ctx.arc(bcx, bcy, b.w / 2 - 4, 0, Math.PI * 2);
      ctx.fill();
      // Hitta närmsta enemy för aim
      let aimAng = -Math.PI / 2;
      if (state.enemies && state.enemies.length) {
        let bestD = (b.range || 280) * (b.range || 280);
        for (const e of state.enemies) {
          const dx = e.x - (b.x + b.w / 2), dy = e.y - (b.y + b.h / 2);
          const d2 = dx * dx + dy * dy;
          if (d2 < bestD) { bestD = d2; aimAng = Math.atan2(dy, dx); }
        }
      }
      // Turret-housing (lägre, oval)
      ctx.save();
      ctx.translate(bcx, bcy);
      ctx.rotate(aimAng);
      // Yttre cannon-housing
      ctx.fillStyle = '#5a5a6a';
      ctx.beginPath();
      ctx.ellipse(0, 0, b.w / 2 - 3, b.w / 3, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#2a2a3a';
      ctx.lineWidth = 1;
      ctx.stroke();
      // Cannon barrel
      ctx.fillStyle = '#3a3a4a';
      ctx.fillRect(-2, -3, 18, 6);
      ctx.fillStyle = '#1a1a2a';
      ctx.fillRect(14, -2, 4, 4);
      // Crystal eye (glödande)
      const pulseCrystal = 0.7 + Math.sin(t * 4) * 0.3;
      ctx.fillStyle = '#3acaff';
      ctx.globalAlpha = pulseCrystal;
      ctx.beginPath();
      ctx.arc(-3, 0, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#aaeaff';
      ctx.beginPath();
      ctx.arc(-3, 0, 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      // v1.416: Tier 2+ chrome-ring runt bas. Tier 3+ glow-aura. Tier 4 floating crown.
      if (tier >= 2) {
        ctx.strokeStyle = tierA.accent;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.w / 2 - 1, 0, Math.PI * 2);
        ctx.stroke();
      }
      if (tier >= 3) {
        const auraGrad = ctx.createRadialGradient(bcx, bcy, b.w / 2, bcx, bcy, b.w / 2 + 12);
        const pulseT = 0.3 + Math.sin(t * 3 + b.x * 0.01) * 0.2;
        auraGrad.addColorStop(0, tierA.particle);
        auraGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = auraGrad;
        ctx.globalAlpha = pulseT;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.w / 2 + 12, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      // v1.417: Range-ring när player står på tornet
      if (showRangeRing && b.range) {
        ctx.strokeStyle = 'rgba(90,200,255,0.5)';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([6, 4]);
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.range, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
      }
      // v1.415: Muzzle-flash från cd_turret_fired event
      const flash = state._cdTurretFlash && state._cdTurretFlash[b.id];
      if (flash && performance.now() < flash.until) {
        const flashAlpha = (flash.until - performance.now()) / 90;
        ctx.save();
        ctx.translate(bcx, bcy);
        ctx.rotate(flash.ang || aimAng);
        // Bright flash-cone at barrel-tip
        const flashGrad = ctx.createRadialGradient(b.w / 2 + 6, 0, 0, b.w / 2 + 6, 0, 14);
        flashGrad.addColorStop(0, 'rgba(255,255,180,' + (flashAlpha * 0.95) + ')');
        flashGrad.addColorStop(0.4, 'rgba(255,200,80,' + (flashAlpha * 0.6) + ')');
        flashGrad.addColorStop(1, 'rgba(255,160,40,0)');
        ctx.fillStyle = flashGrad;
        ctx.beginPath();
        ctx.arc(b.w / 2 + 6, 0, 14, 0, Math.PI * 2);
        ctx.fill();
        // Inner-bright core
        ctx.fillStyle = 'rgba(255,255,255,' + (flashAlpha * 0.9) + ')';
        ctx.beginPath();
        ctx.arc(b.w / 2 + 4, 0, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    } else if (b.kind === 'man_turret') {
      // === MAN-TURRET — stor ballista med säte ===
      ctx.fillStyle = '#3a2a18';
      ctx.beginPath();
      ctx.arc(bcx, bcy, b.w / 2 - 1, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#1a0a04';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      // Wood-frame square
      ctx.fillStyle = '#6a4a28';
      ctx.fillRect(x + 5, y + 5, b.w - 10, b.h - 10);
      ctx.strokeStyle = '#3a2a18';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 5.5, y + 5.5, b.w - 11, b.h - 11);
      // Aim mot närmsta enemy
      let aimAng = -Math.PI / 2;
      if (state.enemies && state.enemies.length) {
        let bestD = (b.range || 400) * (b.range || 400);
        for (const e of state.enemies) {
          const dx = e.x - (b.x + b.w / 2), dy = e.y - (b.y + b.h / 2);
          const d2 = dx * dx + dy * dy;
          if (d2 < bestD) { bestD = d2; aimAng = Math.atan2(dy, dx); }
        }
      }
      ctx.save();
      ctx.translate(bcx, bcy);
      ctx.rotate(aimAng);
      // Ballista-bolt (stor pil)
      ctx.fillStyle = '#1a1410';
      ctx.fillRect(-4, -1, 20, 2);
      // Pilens fjäder
      ctx.fillStyle = '#aa8a30';
      ctx.fillRect(-6, -3, 4, 6);
      // Pilspets
      ctx.fillStyle = '#cccccc';
      ctx.beginPath();
      ctx.moveTo(16, 0);
      ctx.lineTo(13, -3);
      ctx.lineTo(13, 3);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      // Seat-marker (hjul-pattern i hörn)
      ctx.fillStyle = b.occupiedByPid ? '#ffd54a' : '#5a3a2a';
      ctx.beginPath();
      ctx.arc(x + 6, y + 6, 3, 0, Math.PI * 2);
      ctx.fill();
      // v1.417: Range-ring när player står på tornet
      if (showRangeRing && b.range) {
        ctx.strokeStyle = 'rgba(255,200,80,0.5)';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([6, 4]);
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.range, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    } else if (b.kind === 'spike_trap') {
      // === SPIKE TRAP — sten-tile med iron-spikes ===
      ctx.fillStyle = '#1a1410';
      ctx.fillRect(x, y, b.w, b.h);
      ctx.fillStyle = '#2a2018';
      ctx.fillRect(x + 1, y + 1, b.w - 2, b.h - 2);
      // 9 spikes i 3x3 grid (iron, sharp triangles)
      ctx.fillStyle = '#aaaaaa';
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
          const sx = x + 7 + i * 8, sy = y + 7 + j * 8;
          ctx.beginPath();
          ctx.moveTo(sx, sy + 6);
          ctx.lineTo(sx + 3, sy - 1);
          ctx.lineTo(sx + 6, sy + 6);
          ctx.closePath();
          ctx.fill();
          ctx.fillStyle = '#dddddd';
          ctx.beginPath();
          ctx.moveTo(sx + 3, sy - 1);
          ctx.lineTo(sx + 2, sy + 2);
          ctx.lineTo(sx + 4, sy + 2);
          ctx.closePath();
          ctx.fill();
          ctx.fillStyle = '#aaaaaa';
        }
      }
      // Blood-stain visas BARA om traps har använts (hp < maxHp = first kill triggat)
      if (hpPct < 0.99) {
        const bloodAlpha = Math.min(0.5, 0.15 + (1 - hpPct) * 0.5);
        ctx.fillStyle = 'rgba(120,30,30,' + bloodAlpha + ')';
        ctx.beginPath();
        ctx.arc(bcx + 3, bcy + 4, 4, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (b.kind === 'slow_trap') {
      // === FROST TOWER — AOE aura + magic ice rune (v1.414) ===
      // v1.419: Aura visas BARA när player står PÅ tornet (matchar turret range-ring).
      if (b.radius && showRangeRing) {
        // Tier-based aura color
        let auraColor = '140,220,255'; // tier 1 base: ice blue
        let ringColor = 'rgba(140,220,255,0.4)';
        if (tier === 2) { auraColor = '90,200,255'; ringColor = 'rgba(90,200,255,0.6)'; }
        else if (tier === 3) { auraColor = '170,90,255'; ringColor = 'rgba(170,90,255,0.65)'; }
        else if (tier === 4) { auraColor = '255,213,74'; ringColor = 'rgba(255,213,74,0.7)'; }
        const pulseF = 0.12 + Math.sin(t * 2.5) * 0.08;
        const auraGrad = ctx.createRadialGradient(bcx, bcy, 0, bcx, bcy, b.radius);
        auraGrad.addColorStop(0, 'rgba(' + auraColor + ',' + pulseF + ')');
        auraGrad.addColorStop(1, 'rgba(' + auraColor + ',0)');
        ctx.fillStyle = auraGrad;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.radius, 0, Math.PI * 2);
        ctx.fill();
        // Frost-ring outline (tier-färgad)
        ctx.strokeStyle = ringColor;
        ctx.lineWidth = tier >= 3 ? 2 : 1;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.radius, 0, Math.PI * 2);
        ctx.stroke();
      }
      // Frosted base
      ctx.fillStyle = '#2a4a6a';
      ctx.fillRect(x, y, b.w, b.h);
      ctx.strokeStyle = '#1a3a5a';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, b.w - 1, b.h - 1);
      // Glödande rune-cirkel
      const pulseSlow = 0.6 + Math.sin(t * 2) * 0.4;
      ctx.strokeStyle = 'rgba(170,230,255,' + pulseSlow + ')';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(bcx, bcy, b.w / 2 - 4, 0, Math.PI * 2);
      ctx.stroke();
      // Inre rune (rotating)
      ctx.save();
      ctx.translate(bcx, bcy);
      ctx.rotate(t * 1.2);
      ctx.strokeStyle = 'rgba(255,255,255,' + pulseSlow + ')';
      ctx.lineWidth = 1.5;
      // 6-spike snowflake
      for (let i = 0; i < 6; i++) {
        ctx.beginPath();
        ctx.moveTo(0, 0);
        const a = (i / 6) * Math.PI * 2;
        ctx.lineTo(Math.cos(a) * 9, Math.sin(a) * 9);
        ctx.stroke();
        // Side-branches
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * 5, Math.sin(a) * 5);
        ctx.lineTo(Math.cos(a) * 5 + Math.cos(a + 0.5) * 3, Math.sin(a) * 5 + Math.sin(a + 0.5) * 3);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * 5, Math.sin(a) * 5);
        ctx.lineTo(Math.cos(a) * 5 + Math.cos(a - 0.5) * 3, Math.sin(a) * 5 + Math.sin(a - 0.5) * 3);
        ctx.stroke();
      }
      ctx.restore();
      // Center crystal
      ctx.fillStyle = '#aaeeff';
      ctx.beginPath();
      ctx.arc(bcx, bcy, 2.5, 0, Math.PI * 2);
      ctx.fill();
    } else if (b.kind === 'repair_stn') {
      // === REPAIR STATION — anvil + green aura ===
      // v1.419: Aura visas BARA när player står PÅ stn (konsistens m. turret/frost)
      if (b.radius && showRangeRing) {
        const pulseR = 0.12 + Math.sin(t * 3) * 0.08;
        const auraGrad = ctx.createRadialGradient(bcx, bcy, 0, bcx, bcy, b.radius);
        auraGrad.addColorStop(0, 'rgba(90,255,90,' + pulseR + ')');
        auraGrad.addColorStop(1, 'rgba(90,255,90,0)');
        ctx.fillStyle = auraGrad;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.radius, 0, Math.PI * 2);
        ctx.fill();
      }
      // Stenbas
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x, y, b.w, b.h);
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, b.w - 1, b.h - 1);
      // Anvil (svart järn)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x + 6, y + 10, b.w - 12, 8);
      ctx.fillRect(x + 3, y + 14, b.w - 6, 4);
      // Anvil-highlight
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x + 6, y + 10, b.w - 12, 2);
      // Hammer floating above
      const hammerY = Math.sin(t * 2) * 2;
      ctx.fillStyle = '#6a4a28';
      ctx.fillRect(bcx - 1, y + 3 + hammerY, 2, 6);
      ctx.fillStyle = '#aaaaaa';
      ctx.fillRect(bcx - 4, y + 1 + hammerY, 8, 4);
      // Green spark
      ctx.fillStyle = '#5aff5a';
      ctx.globalAlpha = 0.4 + Math.sin(t * 5) * 0.4;
      ctx.beginPath();
      ctx.arc(bcx + 5, y + 4 + hammerY, 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    } else if (b.kind === 'health_stn') {
      // === HEALTH STATION — red cross banner ===
      // v1.419: Aura visas BARA när player står PÅ stn (konsistens m. turret/frost)
      if (b.radius && showRangeRing) {
        const pulseH = 0.15 + Math.sin(t * 2.5) * 0.1;
        const auraGrad = ctx.createRadialGradient(bcx, bcy, 0, bcx, bcy, b.radius);
        auraGrad.addColorStop(0, 'rgba(255,90,90,' + pulseH + ')');
        auraGrad.addColorStop(1, 'rgba(255,90,90,0)');
        ctx.fillStyle = auraGrad;
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.radius, 0, Math.PI * 2);
        ctx.fill();
      }
      // Stenbas
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x, y, b.w, b.h);
      ctx.strokeStyle = '#1a1a1a';
      ctx.strokeRect(x + 0.5, y + 0.5, b.w - 1, b.h - 1);
      // White banner background
      ctx.fillStyle = '#f8f8f0';
      ctx.fillRect(x + 5, y + 4, b.w - 10, b.h - 9);
      // Red cross
      ctx.fillStyle = '#cc2020';
      ctx.fillRect(bcx - 2, y + 7, 4, b.h - 14);
      ctx.fillRect(x + 8, bcy - 2, b.w - 16, 4);
      // Banner-edges
      ctx.strokeStyle = '#aa3030';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 5.5, y + 4.5, b.w - 11, b.h - 10);
      // Healing particles rising
      if (Math.random() < 0.3) {
        state._cdHealParticles = state._cdHealParticles || [];
        if (state._cdHealParticles.length < 60) {
          state._cdHealParticles.push({
            x: b.x + b.w / 2 + (Math.random() - 0.5) * b.w,
            y: b.y + b.h / 2,
            life: 1.2,
          });
        }
      }
    } else {
      // Fallback (okänd kind)
      ctx.fillStyle = '#3a8a4a';
      ctx.fillRect(x, y, b.w, b.h);
      ctx.strokeStyle = '#1a4a2a';
      ctx.strokeRect(x + 0.5, y + 0.5, b.w - 1, b.h - 1);
    }
    // v1.416: GENERIC tier-overlay för man_turret/repair_stn/health_stn/slow_trap
    // (wall + auto_turret har redan tier-specifika overlays ovan).
    if (tier >= 2 && (b.kind === 'man_turret' || b.kind === 'repair_stn' || b.kind === 'health_stn' || b.kind === 'slow_trap')) {
      // Tier 2+: accent-ring runt
      ctx.strokeStyle = tierA.accent;
      ctx.lineWidth = 2;
      ctx.strokeRect(x - 1, y - 1, b.w + 2, b.h + 2);
      if (tier >= 3) {
        // Pulserande glow
        const pulseT = 0.25 + Math.sin(t * 3 + b.x * 0.013) * 0.15;
        ctx.fillStyle = tierA.particle;
        ctx.globalAlpha = pulseT;
        ctx.fillRect(x - 4, y - 4, b.w + 8, b.h + 8);
        ctx.globalAlpha = 1;
      }
      if (tier === 4) {
        // Tier 4: sparkles runt byggnaden (ingen krona — user-feedback)
        if (Math.random() < 0.3) {
          const ang = Math.random() * Math.PI * 2;
          const dist = b.w / 2 + 6 + Math.random() * 6;
          ctx.fillStyle = '#fff8c0';
          ctx.fillRect(bcx + Math.cos(ang) * dist, bcy + Math.sin(ang) * dist, 2, 2);
        }
      }
    }
    // HP-bar — ALLTID synlig men diskret (v1.400). När full = mer transparent.
    const barW = Math.max(20, b.w * 0.7);
    const barX = x + b.w / 2 - barW / 2;
    const barY = y - 5;
    const isFull = hpPct >= 0.99;
    ctx.globalAlpha = isFull ? 0.2 : 0.95;
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(barX, barY, barW, 2);
    ctx.fillStyle = hpPct > 0.5 ? '#5aff5a' : (hpPct > 0.25 ? '#ffd54a' : '#ff5a5a');
    ctx.fillRect(barX, barY, barW * hpPct, 2);
    ctx.globalAlpha = 1;
    // v1.407: level-display (top-right corner av byggnaden) — bara om level > 0 och kind är upgradable
    if ((b.level || 0) > 0 && b.kind !== 'spike_trap') {
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'bold 9px monospace';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'top';
      ctx.shadowColor = 'rgba(0,0,0,0.9)';
      ctx.shadowBlur = 2;
      ctx.fillText('L' + (b.level + 1), x + b.w - 2, y + 1);
      ctx.shadowBlur = 0;
    }
  }
  ctx.restore();
  // v1.423: Range-rings overlay PASS — ritas EFTER all bygg-render så andra
  // torn inte täcker ringen (siege/man_turret range = 300 → många walls inom
  // räckhåll). Bara för det torn player står PÅ (strict AABB).
  if (layer === 'tall' && state.player) {
    const px = state.player.x, py = state.player.y;
    let onBuilding = null;
    for (const b of state.castledefenseBuildings) {
      if (b.hp <= 0) continue;
      if (px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h) {
        onBuilding = b;
        break;
      }
    }
    if (onBuilding) {
      const b = onBuilding;
      const bcx = (b.x - cx) + b.w / 2;
      const bcy = (b.y - cy) + b.h / 2;
      ctx.save();
      // Range-ring för turrets (auto_turret cyan, man_turret yellow)
      if (b.range > 0 && (b.kind === 'auto_turret' || b.kind === 'man_turret')) {
        const ringCol = b.kind === 'man_turret' ? 'rgba(255,200,80,0.65)' : 'rgba(90,200,255,0.65)';
        ctx.strokeStyle = ringCol;
        ctx.lineWidth = 2;
        ctx.setLineDash([7, 5]);
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.range, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
        // Inre transparent fill för bättre synlighet
        ctx.fillStyle = b.kind === 'man_turret' ? 'rgba(255,200,80,0.06)' : 'rgba(90,200,255,0.06)';
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.range, 0, Math.PI * 2);
        ctx.fill();
      }
      // Aura-ring för stations (radius-baserade)
      if (b.radius > 0 && (b.kind === 'repair_stn' || b.kind === 'health_stn' || b.kind === 'slow_trap')) {
        let auraCol = 'rgba(140,220,255,0.5)';
        if (b.kind === 'repair_stn') auraCol = 'rgba(90,255,150,0.55)';
        else if (b.kind === 'health_stn') auraCol = 'rgba(255,90,200,0.55)';
        ctx.strokeStyle = auraCol;
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 4]);
        ctx.beginPath();
        ctx.arc(bcx, bcy, b.radius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.restore();
    }
  }
}

function drawCastleDefenseSpawnMarkers() {
  // Pulser vid enemy-spawn-punkter under "between"-fas. Tydlig "hot zone"-känsla.
  if (!state.castledefenseEnemySpawns || state.castledefenseWaveState !== 'between') return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now() / 1000;
  const pulse = 0.4 + Math.sin(t * 3) * 0.4;
  ctx.save();
  for (const sp of state.castledefenseEnemySpawns) {
    const x = sp.x - cx, y = sp.y - cy;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) continue;
    // Outer pulse
    ctx.fillStyle = 'rgba(255,80,80,' + (0.25 * pulse) + ')';
    ctx.beginPath();
    ctx.arc(x, y, 36 + 10 * pulse, 0, Math.PI * 2);
    ctx.fill();
    // Inner glow
    ctx.fillStyle = 'rgba(255,160,160,' + (0.5 * pulse) + ')';
    ctx.beginPath();
    ctx.arc(x, y, 14, 0, Math.PI * 2);
    ctx.fill();
    // Warning-X symbol
    ctx.strokeStyle = '#ff3030';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x - 6, y - 6); ctx.lineTo(x + 6, y + 6);
    ctx.moveTo(x - 6, y + 6); ctx.lineTo(x + 6, y - 6);
    ctx.stroke();
  }
  ctx.restore();
}

// v1.421: visuell feedback för CD down-state. Ritar:
// 1. Röd vignette + "DOWN" overlay på spelaren själv när cdDowned
// 2. Bleed-out countdown (sekunder kvar tills död)
// 3. Revive-progress bar (0→4s)
// 4. "BLED OUT — vänta nästa våg" overlay vid cdDownDead
// 5. Partner-marker över downed lagkamrat (röd ! + namn + revive-progress)
function drawCastleDefenseDownStateUI() {
  if (!state.castledefenseActive || !state.player) return;
  const t = performance.now();
  // === EGEN SPELARE — DOWN-STATE OVERLAY ===
  if (state.player.cdDowned) {
    // Röd vignette runt skärm-edge
    const pulse = 0.45 + Math.sin(t / 280) * 0.15;
    const grad = ctx.createRadialGradient(viewW / 2, viewH / 2, Math.min(viewW, viewH) * 0.3,
                                          viewW / 2, viewH / 2, Math.max(viewW, viewH) * 0.7);
    grad.addColorStop(0, 'rgba(180,0,0,0)');
    grad.addColorStop(1, 'rgba(180,0,0,' + pulse + ')');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, viewW, viewH);
    // "DOWN" text top-center
    const headerY = 90;
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.75)';
    ctx.fillRect(viewW / 2 - 130, headerY - 24, 260, 48);
    ctx.strokeStyle = '#ff3030';
    ctx.lineWidth = 2;
    ctx.strokeRect(viewW / 2 - 130, headerY - 24, 260, 48);
    ctx.fillStyle = '#ff5a5a';
    ctx.font = 'bold 22px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    ctx.fillText('💀 DOWN — VÄNTA HJÄLP', viewW / 2, headerY);
    ctx.restore();
    // Bleed-out countdown — räknat lokalt från cdDownStartedAt
    const arena = (typeof CASTLEDEFENSE_ARENA !== 'undefined') ? CASTLEDEFENSE_ARENA : null;
    const bleedSec = arena ? (arena.downBleedoutSec || 25) : 25;
    const elapsed = state.player.cdDownStartedAt ? (Date.now() - state.player.cdDownStartedAt) / 1000 : 0;
    const remaining = Math.max(0, bleedSec - elapsed);
    const bleedBarY = headerY + 38;
    const barW = 240, barH = 14;
    const bx = viewW / 2 - barW / 2;
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(bx, bleedBarY, barW, barH);
    const bleedPct = Math.max(0, remaining / bleedSec);
    ctx.fillStyle = bleedPct > 0.5 ? '#ff5a5a' : (bleedPct > 0.25 ? '#ffa030' : '#ff2020');
    ctx.fillRect(bx, bleedBarY, barW * bleedPct, barH);
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(bx, bleedBarY, barW, barH);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
    ctx.fillText('BLEED-OUT ' + remaining.toFixed(1) + 's', viewW / 2, bleedBarY + barH / 2);
    ctx.restore();
    // Revive-progress bar (visas när någon räddar)
    const revP = state.player.cdReviveProgress || 0;
    if (revP > 0) {
      const reviveBarY = bleedBarY + barH + 8;
      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(bx, reviveBarY, barW, barH);
      const greenPulse = 0.7 + Math.sin(t / 150) * 0.3;
      ctx.fillStyle = 'rgba(90,255,90,' + greenPulse + ')';
      ctx.fillRect(bx, reviveBarY, barW * Math.min(1, revP), barH);
      ctx.strokeStyle = '#5aff5a';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(bx, reviveBarY, barW, barH);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
      ctx.fillText('💚 RÄDDAS ' + Math.round(revP * 100) + '%', viewW / 2, reviveBarY + barH / 2);
      ctx.restore();
    }
  }
  // === EGEN SPELARE — BLED OUT (vänta nästa våg) ===
  if (state.player.cdDownDead) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, viewW, viewH);
    ctx.fillStyle = '#ff2020';
    ctx.font = 'bold 32px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 8;
    ctx.fillText('💀 BLED OUT', viewW / 2, viewH / 2 - 18);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText('Respawn vid nästa våg', viewW / 2, viewH / 2 + 12);
    ctx.restore();
  }
  // === PARTNER-MARKER över downed lagkamrater ===
  if (typeof Coop !== 'undefined' && Coop.players) {
    const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
    for (const [pid, partner] of Coop.players) {
      if (!partner || pid === Coop.myId) continue;
      if (!partner.cdDowned || partner.x === undefined) continue;
      const sx = partner.x - cx, sy = partner.y - cy;
      if (sx < -60 || sx > viewW + 60 || sy < -60 || sy > viewH + 60) continue;
      ctx.save();
      // Pulserande röd ring runt downed partner
      const ringPulse = 0.6 + Math.sin(t / 200) * 0.4;
      ctx.strokeStyle = 'rgba(255,40,40,' + ringPulse + ')';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(sx, sy, 24 + Math.sin(t / 250) * 3, 0, Math.PI * 2);
      ctx.stroke();
      // "DOWN" label ovan
      ctx.fillStyle = 'rgba(0,0,0,0.8)';
      ctx.fillRect(sx - 32, sy - 50, 64, 18);
      ctx.fillStyle = '#ff5a5a';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('💀 DOWN', sx, sy - 41);
      // Revive-progress bar under label
      const revP2 = partner.cdReviveProgress || 0;
      if (revP2 > 0) {
        ctx.fillStyle = 'rgba(0,0,0,0.8)';
        ctx.fillRect(sx - 32, sy - 30, 64, 6);
        ctx.fillStyle = '#5aff5a';
        ctx.fillRect(sx - 32, sy - 30, 64 * Math.min(1, revP2), 6);
      }
      ctx.restore();
    }
  }
}

// v1.419: ghost-preview för pin-drag — ritar pin-cursor vid finger-position
// medan användaren håller pin-knappen + drar. Klart visuell feedback om var
// pinnen kommer landa.
function drawCastleDefensePinGhost() {
  if (!state.castledefenseActive) return;
  const d = state._cdPinDrag;
  if (!d || !d.moved) return;
  ctx.save();
  const t = performance.now() / 1000;
  const pulse = 0.5 + Math.sin(t * 4) * 0.3;
  // Yttre ring
  ctx.strokeStyle = 'rgba(90,255,210,' + pulse + ')';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.arc(d.x, d.y, 22, 0, Math.PI * 2);
  ctx.stroke();
  // Inre fyllning
  ctx.fillStyle = 'rgba(90,200,255,0.45)';
  ctx.beginPath();
  ctx.arc(d.x, d.y, 9, 0, Math.PI * 2);
  ctx.fill();
  // Pin-emoji centrerad
  ctx.font = 'bold 18px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#fff';
  ctx.shadowColor = '#000';
  ctx.shadowBlur = 4;
  ctx.fillText('📍', d.x, d.y);
  ctx.shadowBlur = 0;
  ctx.restore();
}

// v1.416: Ping-markers — pulserande ring + sender-namn, auto-expire 5s
function drawCastleDefensePings() {
  if (!state.castledefensePings || !state.castledefensePings.length) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const now = performance.now();
  ctx.save();
  for (let i = state.castledefensePings.length - 1; i >= 0; i--) {
    const p = state.castledefensePings[i];
    const elapsed = now - p.createdAt;
    if (elapsed > p.life) { state.castledefensePings.splice(i, 1); continue; }
    const lifePct = 1 - elapsed / p.life;
    const x = p.x - cx, y = p.y - cy;
    if (x < -100 || x > viewW + 100 || y < -100 || y > viewH + 100) continue;
    // Pulserande ring som expanderar
    const t = elapsed / 1000;
    const pulseR = 18 + (t % 0.8) * 50;
    const pulseAlpha = Math.max(0, 0.7 - (t % 0.8) / 0.8) * lifePct;
    ctx.strokeStyle = 'rgba(90,200,255,' + pulseAlpha + ')';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(x, y, pulseR, 0, Math.PI * 2);
    ctx.stroke();
    // Statisk inre ring
    ctx.fillStyle = 'rgba(90,200,255,' + (0.5 * lifePct) + ')';
    ctx.beginPath();
    ctx.arc(x, y, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#5acaff';
    ctx.lineWidth = 2;
    ctx.stroke();
    // Sender-namn-label
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(x - 40, y - 30, 80, 16);
    ctx.fillStyle = '#5acaff';
    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('📍 ' + p.senderName, x, y - 22);
  }
  ctx.restore();
}

// Heal-particles från health_stn — stiger upp + faded
function drawCastleDefenseHealParticles() {
  if (!state._cdHealParticles || !state._cdHealParticles.length) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (let i = state._cdHealParticles.length - 1; i >= 0; i--) {
    const p = state._cdHealParticles[i];
    p.y -= 0.6;                 // stigning
    p.life -= 0.016;
    if (p.life <= 0) {
      state._cdHealParticles.splice(i, 1);
      continue;
    }
    const a = p.life / 1.2;
    ctx.fillStyle = 'rgba(255,150,150,' + a + ')';
    ctx.beginPath();
    ctx.arc(p.x - cx, p.y - cy, 2.5, 0, Math.PI * 2);
    ctx.fill();
    // Cross-symbol om life > 0.7 (start)
    if (a > 0.7) {
      ctx.fillStyle = 'rgba(255,255,255,' + (a - 0.5) + ')';
      ctx.fillRect(p.x - cx - 0.5, p.y - cy - 2, 1, 4);
      ctx.fillRect(p.x - cx - 2, p.y - cy - 0.5, 4, 1);
    }
  }
  ctx.restore();
}

// BATTLE ROYALE — loot på marken. Olika färger/ikoner per tier + kind.
function drawBrLoot() {
  if (!state.battleroyaleLoot) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now() / 1000;
  const pulse = 0.7 + Math.sin(t * 3) * 0.3;
  ctx.save();
  const nowMs = Date.now();
  // PERF: for...in är snabbare än Object.keys (ingen array-allokering per frame)
  for (const id in state.battleroyaleLoot) {
    const lo = state.battleroyaleLoot[id];
    if (!lo.available) continue;
    const x = lo.x - cx, y = lo.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) continue;
    // Locked? (center-loot första 30s)
    const isLocked = lo.unlockAt && nowMs < lo.unlockAt;
    // Tier-färg: grå/grön/blå/lila per user-spec
    let tierColor = '#ffffff', glowColor = '#999';
    if (lo.tier === 'common')      { tierColor = '#cccccc'; glowColor = '#cccccc'; } // GRÅ
    else if (lo.tier === 'uncommon') { tierColor = '#5fd95f'; glowColor = '#3aff5a'; } // GRÖN
    else if (lo.tier === 'rare')     { tierColor = '#3a7aff'; glowColor = '#5a90ff'; } // BLÅ
    else if (lo.tier === 'legendary') { tierColor = '#bb3aff'; glowColor = '#cc6aff'; } // LILA
    else if (lo.tier === 'corpse')   { tierColor = '#ff8aff'; glowColor = '#ff8aff'; } // rosa
    if (isLocked) { tierColor = '#666'; glowColor = '#444'; }
    // GLOW för ALLA tier-färger nu (user vill se lysande loot oavsett tier)
    const useShadow = !isLocked;
    if (useShadow) {
      ctx.shadowColor = glowColor;
      // Mindre glow för common, mer för legendary
      const blurAmount = (lo.tier === 'legendary') ? 18 : (lo.tier === 'rare') ? 14 : (lo.tier === 'uncommon') ? 10 : 7;
      ctx.shadowBlur = blurAmount * pulse;
    } else {
      ctx.shadowBlur = 0;
    }
    // Bas-cirkel (ground-shadow) — kort fyllning utan shadow
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath();
    ctx.arc(x, y + 4, 11, 0, Math.PI * 2);
    ctx.fill();
    // v1.371: PROFESSIONELLA pickups — tier-färg gradient + glow + ikoner
    if (lo.kind === 'weapon') {
      // ============ VAPEN-CHEST — metallisk låda + tier-glödande gem-lock ============
      ctx.shadowBlur = 0; // shadowBlur off för crisp chest-edge
      const lw = 22, lh = 18;
      // Lock-shadow under chesten
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      drawRoundedRect(ctx, x - lw / 2 + 1, y - lh / 2 + 2, lw, lh, 3);
      ctx.fill();
      // Chest-body — mörk-metallisk vertikal gradient
      const chestGrad = ctx.createLinearGradient(0, y - lh / 2, 0, y + lh / 2);
      chestGrad.addColorStop(0, '#5a4a30');
      chestGrad.addColorStop(0.5, '#3a2a18');
      chestGrad.addColorStop(1, '#1a1208');
      ctx.fillStyle = chestGrad;
      drawRoundedRect(ctx, x - lw / 2, y - lh / 2, lw, lh, 3);
      ctx.fill();
      // Topp-band (lock) i tier-färg gradient
      const lockH = 6;
      const lockGrad = ctx.createLinearGradient(0, y - lh / 2, 0, y - lh / 2 + lockH);
      const tcr = tierColor;
      // Bright top
      lockGrad.addColorStop(0, tcr);
      lockGrad.addColorStop(1, '#1a1208');
      ctx.fillStyle = lockGrad;
      drawRoundedRect(ctx, x - lw / 2, y - lh / 2, lw, lockH, 3);
      ctx.fill();
      // Metallic edge-highlight (top)
      ctx.strokeStyle = 'rgba(255,255,255,0.45)';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x - lw / 2 + 2, y - lh / 2 + 1.5);
      ctx.lineTo(x + lw / 2 - 2, y - lh / 2 + 1.5);
      ctx.stroke();
      // Side-rivets (4 hörn)
      ctx.fillStyle = '#8a7a50';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.5;
      const rivelPos = [
        [x - lw / 2 + 2, y - lh / 2 + 9],
        [x + lw / 2 - 2, y - lh / 2 + 9],
        [x - lw / 2 + 2, y + lh / 2 - 2],
        [x + lw / 2 - 2, y + lh / 2 - 2],
      ];
      for (const [rx, ry] of rivelPos) {
        ctx.beginPath();
        ctx.arc(rx, ry, 1.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
      // Center lock-gem (tier-färg, glödande)
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = 8 * pulse;
      const gemGrad = ctx.createRadialGradient(x, y + 1, 1, x, y + 1, 4);
      gemGrad.addColorStop(0, '#ffffff');
      gemGrad.addColorStop(0.4, tcr);
      gemGrad.addColorStop(1, tcr);
      ctx.fillStyle = gemGrad;
      ctx.beginPath();
      // Diamond-gem shape
      ctx.moveTo(x, y - 2.5);
      ctx.lineTo(x + 3.5, y + 1);
      ctx.lineTo(x, y + 4.5);
      ctx.lineTo(x - 3.5, y + 1);
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
      // Gem-rim
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x, y - 2.5);
      ctx.lineTo(x + 3.5, y + 1);
      ctx.lineTo(x, y + 4.5);
      ctx.lineTo(x - 3.5, y + 1);
      ctx.closePath();
      ctx.stroke();
      // Outer chest-outline
      ctx.strokeStyle = 'rgba(0,0,0,0.85)';
      ctx.lineWidth = 1.2;
      drawRoundedRect(ctx, x - lw / 2, y - lh / 2, lw, lh, 3);
      ctx.stroke();
    } else if (lo.kind === 'hp_small' || lo.kind === 'hp_big') {
      // ============ MED-KIT — vit kropp + röd kors + gradient ============
      ctx.shadowBlur = 0;
      const big = lo.kind === 'hp_big';
      const W = big ? 24 : 18, H = big ? 22 : 16;
      // Drop-shadow
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.ellipse(x, y + H / 2 + 2, W / 2 + 1, 3, 0, 0, Math.PI * 2);
      ctx.fill();
      // Outer mörk-röd rim
      ctx.fillStyle = '#7a0a0a';
      drawRoundedRect(ctx, x - W / 2, y - H / 2, W, H, 4);
      ctx.fill();
      // Inner body — vit gradient
      const bodyGrad = ctx.createLinearGradient(0, y - H / 2 + 2, 0, y + H / 2 - 2);
      bodyGrad.addColorStop(0, '#ffffff');
      bodyGrad.addColorStop(0.5, '#f0f0f0');
      bodyGrad.addColorStop(1, '#c8c8c8');
      ctx.fillStyle = bodyGrad;
      drawRoundedRect(ctx, x - W / 2 + 2, y - H / 2 + 2, W - 4, H - 4, 3);
      ctx.fill();
      // Topp-highlight (glansrand)
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      drawRoundedRect(ctx, x - W / 2 + 3, y - H / 2 + 3, W - 6, 4, 2);
      ctx.fill();
      // Röda kors (gradient)
      const crossW = big ? 16 : 12, crossT = big ? 4.5 : 3.5;
      const crossGrad = ctx.createLinearGradient(0, y - crossW / 2, 0, y + crossW / 2);
      crossGrad.addColorStop(0, '#ff5050');
      crossGrad.addColorStop(1, '#c81818');
      ctx.fillStyle = crossGrad;
      drawRoundedRect(ctx, x - crossW / 2, y - crossT / 2, crossW, crossT, 1.2);
      ctx.fill();
      drawRoundedRect(ctx, x - crossT / 2, y - crossW / 2, crossT, crossW, 1.2);
      ctx.fill();
      // Big-size: "+" extra label nedanför
      if (big) {
        ctx.fillStyle = '#7a0a0a';
        ctx.font = 'bold 7px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('MAX', x, y + H / 2 - 3);
      }
    } else if (lo.kind === 'shield_small' || lo.kind === 'shield_big') {
      // ============ SHIELD-pickup — hexagonal sköld + energy-bolt ============
      ctx.shadowBlur = 0;
      const big = lo.kind === 'shield_big';
      const S = big ? 13 : 10;
      // Drop-shadow
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.ellipse(x, y + S + 1, S - 1, 2.5, 0, 0, Math.PI * 2);
      ctx.fill();
      // Yttre energy-ring
      ctx.strokeStyle = 'rgba(80,200,255,0.7)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x, y, S + 2, 0, Math.PI * 2);
      ctx.stroke();
      // Shield-shape (klassisk)
      ctx.beginPath();
      ctx.moveTo(x, y - S);
      ctx.lineTo(x + S * 0.85, y - S * 0.55);
      ctx.lineTo(x + S * 0.85, y + S * 0.3);
      ctx.quadraticCurveTo(x + S * 0.85, y + S, x, y + S);
      ctx.quadraticCurveTo(x - S * 0.85, y + S, x - S * 0.85, y + S * 0.3);
      ctx.lineTo(x - S * 0.85, y - S * 0.55);
      ctx.closePath();
      // Blå gradient
      const shGrad = ctx.createLinearGradient(0, y - S, 0, y + S);
      shGrad.addColorStop(0, '#7adcff');
      shGrad.addColorStop(0.45, '#3a9aff');
      shGrad.addColorStop(1, '#1a4ab8');
      ctx.fillStyle = shGrad;
      ctx.fill();
      ctx.strokeStyle = '#0a2a5a';
      ctx.lineWidth = 1.3;
      ctx.stroke();
      // Inner highlight bevel
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.beginPath();
      ctx.moveTo(x - S * 0.6, y - S * 0.55);
      ctx.lineTo(x, y - S * 0.85);
      ctx.lineTo(x + S * 0.35, y - S * 0.55);
      ctx.lineTo(x - S * 0.2, y - S * 0.15);
      ctx.closePath();
      ctx.fill();
      // Energy-bolt center
      ctx.strokeStyle = 'rgba(255,255,255,0.95)';
      ctx.lineWidth = big ? 1.7 : 1.4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      const bs = big ? 1.3 : 1;
      ctx.beginPath();
      ctx.moveTo(x - 2 * bs, y - 4 * bs);
      ctx.lineTo(x + 2 * bs, y);
      ctx.lineTo(x - 1 * bs, y + 1 * bs);
      ctx.lineTo(x + 2 * bs, y + 5 * bs);
      ctx.stroke();
      // Big-size: MAX label
      if (big) {
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 7px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowColor = '#000';
        ctx.shadowBlur = 2;
        ctx.fillText('MAX', x, y + S - 2.5);
        ctx.shadowBlur = 0;
      }
    } else if (lo.kind === 'ammo') {
      // ============ AMMO-CRATE — militär låda + gula kulor + label ============
      ctx.shadowBlur = 0;
      const W = 20, H = 16;
      // Drop-shadow
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.ellipse(x, y + H / 2 + 1, W / 2 - 1, 2.5, 0, 0, Math.PI * 2);
      ctx.fill();
      // Crate body (mörk-grön metallisk gradient)
      const crateGrad = ctx.createLinearGradient(0, y - H / 2, 0, y + H / 2);
      crateGrad.addColorStop(0, '#5a7038');
      crateGrad.addColorStop(0.5, '#3a4a20');
      crateGrad.addColorStop(1, '#1a2410');
      ctx.fillStyle = crateGrad;
      drawRoundedRect(ctx, x - W / 2, y - H / 2, W, H, 2);
      ctx.fill();
      // Side panels (3 vertikala bars)
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      ctx.fillRect(x - W / 2 + 3, y - H / 2 + 1, 1, H - 2);
      ctx.fillRect(x + W / 2 - 4, y - H / 2 + 1, 1, H - 2);
      // Topp-highlight
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.fillRect(x - W / 2 + 1, y - H / 2 + 1, W - 2, 2);
      // Gula bullets (3 st)
      const bulletGrad = ctx.createLinearGradient(0, y - 4, 0, y + 4);
      bulletGrad.addColorStop(0, '#ffe580');
      bulletGrad.addColorStop(0.6, '#ffb020');
      bulletGrad.addColorStop(1, '#a06010');
      ctx.fillStyle = bulletGrad;
      for (let bi = -1; bi <= 1; bi++) {
        drawRoundedRect(ctx, x + bi * 4 - 1.5, y - 4, 3, 7, 1);
        ctx.fill();
      }
      // Bullet-tips (silver)
      ctx.fillStyle = '#c0c0c0';
      for (let bi = -1; bi <= 1; bi++) {
        ctx.beginPath();
        ctx.moveTo(x + bi * 4 - 1.5, y - 4);
        ctx.lineTo(x + bi * 4, y - 5.5);
        ctx.lineTo(x + bi * 4 + 1.5, y - 4);
        ctx.closePath();
        ctx.fill();
      }
      // Crate outline
      ctx.strokeStyle = '#0a1408';
      ctx.lineWidth = 1.1;
      drawRoundedRect(ctx, x - W / 2, y - H / 2, W, H, 2);
      ctx.stroke();
    } else if (lo.kind === 'grenade') {
      // ============ GRENADE-pickup — riktig granat med pin ============
      ctx.shadowBlur = 0;
      // Drop-shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(x, y + 11, 9, 3, 0, 0, Math.PI * 2);
      ctx.fill();
      // Body (oval, metallic radial)
      const grBody = ctx.createRadialGradient(x - 2.5, y - 1, 1, x, y + 2, 11);
      grBody.addColorStop(0, '#6a8a48');
      grBody.addColorStop(0.5, '#3a5a30');
      grBody.addColorStop(1, '#1a2818');
      ctx.fillStyle = grBody;
      ctx.beginPath();
      ctx.ellipse(x, y + 2, 8.5, 10, 0, 0, Math.PI * 2);
      ctx.fill();
      // Cross-hatch grooves
      ctx.strokeStyle = 'rgba(15,25,12,0.7)';
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(x - 7, y - 2); ctx.lineTo(x + 7, y - 2);
      ctx.moveTo(x - 7, y + 2); ctx.lineTo(x + 7, y + 2);
      ctx.moveTo(x - 7, y + 6); ctx.lineTo(x + 7, y + 6);
      ctx.moveTo(x - 3, y - 6); ctx.lineTo(x - 3, y + 11);
      ctx.moveTo(x, y - 7); ctx.lineTo(x, y + 12);
      ctx.moveTo(x + 3, y - 6); ctx.lineTo(x + 3, y + 11);
      ctx.stroke();
      // Body outline
      ctx.strokeStyle = '#0a1408';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.ellipse(x, y + 2, 8.5, 10, 0, 0, Math.PI * 2);
      ctx.stroke();
      // Glans highlight
      ctx.fillStyle = 'rgba(190,230,160,0.55)';
      ctx.beginPath();
      ctx.ellipse(x - 3, y - 3, 2.5, 3.5, -0.3, 0, Math.PI * 2);
      ctx.fill();
      // Metal cap (top)
      const capGr = ctx.createLinearGradient(0, y - 10, 0, y - 6);
      capGr.addColorStop(0, '#a08868');
      capGr.addColorStop(1, '#4a3018');
      ctx.fillStyle = capGr;
      drawRoundedRect(ctx, x - 3.5, y - 10.5, 7, 4, 1);
      ctx.fill();
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 0.9;
      drawRoundedRect(ctx, x - 3.5, y - 10.5, 7, 4, 1);
      ctx.stroke();
      // Pull-pin ring
      ctx.strokeStyle = '#d8d8d8';
      ctx.lineWidth = 1.5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x - 3, y - 9);
      ctx.quadraticCurveTo(x - 8, y - 11, x - 10, y - 13);
      ctx.stroke();
      ctx.strokeStyle = '#e8e8e8';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(x - 10, y - 13, 2.3, 0, Math.PI * 2);
      ctx.stroke();
    } else {
      // Fallback: en kub
      ctx.fillStyle = tierColor;
      ctx.fillRect(x - 8, y - 8, 16, 16);
    }
    ctx.shadowBlur = 0;
    // Tier-färg-ring runtom (subtil)
    if (!isLocked && (lo.tier === 'rare' || lo.tier === 'legendary')) {
      ctx.strokeStyle = tierColor;
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.45 + pulse * 0.4;
      ctx.beginPath();
      ctx.arc(x, y, 16, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 1.0;
    }
    // Lås-overlay om låst (center-loot första 30s)
    if (isLocked) {
      const secLeft = Math.max(0, Math.ceil((lo.unlockAt - nowMs) / 1000));
      ctx.fillStyle = '#000';
      ctx.globalAlpha = 0.7;
      ctx.beginPath();
      ctx.arc(x, y, 18, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1.0;
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'bold 14px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('🔒', x, y - 2);
      ctx.font = 'bold 10px sans-serif';
      ctx.fillStyle = '#fff';
      ctx.fillText(secLeft + 's', x, y + 12);
    }
  }
  ctx.restore();
}

// ============================================================
// BATTLE ROYALE — SKOG-KARTA decoration-render
// ============================================================

// SEAMLESS SKOGSGOLV — solid bas + RADIAL GRADIENT blobs med SOFT FALLOFF.
// Kanten på varje blob fadar till alpha 0 → ingen synlig "cirkel-kontur".
// Plus pixel-noise för grain (massa små prickar) så ingen yta är "helt slätt".
function drawBrForestFloor() {
  if (!state.battleroyaleActive) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  // v1.380: när BR-kameran är zoomad ut (0.88) syns ~14% mer världen per axis.
  // Måste utöka fill + blob + grain bortom viewW/viewH annars syns seam
  // ("streck") vid 6%-bordern när spelaren springer (blobs/grain rör sig med
  // kamera, men border-fillen är statisk → mismatch). 15% padding för säkerhet.
  const ZOOM = (typeof getCameraZoom === 'function') ? getCameraZoom() : 1.0;
  const ZPAD = Math.max(0, (1 / ZOOM - 1) * 0.5 + 0.05); // 0.118 för zoom=0.88
  const padX = Math.ceil(viewW * ZPAD);
  const padY = Math.ceil(viewH * ZPAD);
  // 1. Solid bas över viewporten + zoom-padding (täcker zoom-bordern smooth)
  ctx.fillStyle = '#1e2a14';
  ctx.fillRect(-padX, -padY, viewW + 2 * padX, viewH + 2 * padY);
  // 2. Stora soft-falloff blobs (radial gradient → fade to 0 vid kanten)
  const ANCHOR = 220;
  const startAx = Math.floor((state.camera.x - padX) / ANCHOR) - 1;
  const startAy = Math.floor((state.camera.y - padY) / ANCHOR) - 1;
  const endAx = Math.floor((state.camera.x + viewW + padX) / ANCHOR) + 1;
  const endAy = Math.floor((state.camera.y + viewH + padY) / ANCHOR) + 1;
  const palette = [
    { r: 40,  g: 70,  b: 30 },  // mörkare grön
    { r: 70,  g: 105, b: 40 },  // ljusare grön
    { r: 55,  g: 85,  b: 30 },  // mid grön
    { r: 100, g: 70,  b: 30 },  // brunlöv
    { r: 60,  g: 90,  b: 40 },  // mossy
    { r: 45,  g: 75,  b: 25 },  // mörk mossy
    { r: 80,  g: 110, b: 50 },  // ljus grön
    { r: 35,  g: 60,  b: 25 },  // djup-grön
  ];
  for (let ay = startAy; ay <= endAy; ay++) {
    for (let ax = startAx; ax <= endAx; ax++) {
      const seed = ((ax * 73) ^ (ay * 137)) | 0;
      const blobsHere = 1 + ((seed >> 2) & 1);
      for (let i = 0; i < blobsHere; i++) {
        const subSeed = (seed * (i + 7)) | 0;
        const ox = ((subSeed * 23) & 0xff) / 256;
        const oy = ((subSeed * 31) & 0xff) / 256;
        const bx = ax * ANCHOR + ox * ANCHOR - cx;
        const by = ay * ANCHOR + oy * ANCHOR - cy;
        const r = 130 + ((subSeed * 17) & 0x7f);
        const colorIdx = (subSeed >>> 0) & 0x7;
        const col = palette[colorIdx];
        // Radial gradient: solid i centrum → alpha 0 vid kanten
        const grad = ctx.createRadialGradient(bx, by, 0, bx, by, r);
        grad.addColorStop(0, 'rgba(' + col.r + ',' + col.g + ',' + col.b + ',0.35)');
        grad.addColorStop(0.6, 'rgba(' + col.r + ',' + col.g + ',' + col.b + ',0.15)');
        grad.addColorStop(1, 'rgba(' + col.r + ',' + col.g + ',' + col.b + ',0)');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(bx, by, r, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
  // 3. PIXEL-GRAIN ovanpå — massa små noise-prickar så ingen yta är helt slätt
  //    Deterministisk per world-tile (40×40 micro-tiles) → ingen flimmer
  //    Iteration utökad med padX/padY så grain täcker zoom-borden också
  const MICRO = 40;
  const mStartX = Math.floor((state.camera.x - padX) / MICRO);
  const mStartY = Math.floor((state.camera.y - padY) / MICRO);
  const mEndX = Math.floor((state.camera.x + viewW + padX) / MICRO);
  const mEndY = Math.floor((state.camera.y + viewH + padY) / MICRO);
  for (let my = mStartY; my <= mEndY; my++) {
    for (let mx = mStartX; mx <= mEndX; mx++) {
      const ms = ((mx * 1093) ^ (my * 1471)) >>> 0;
      // 3-4 prickar per micro-tile
      for (let i = 0; i < 3; i++) {
        const s = (ms * (i + 11)) >>> 0;
        const px = mx * MICRO + (s & 0x3f) * (MICRO / 64) - cx;
        const py = my * MICRO + ((s >> 6) & 0x3f) * (MICRO / 64) - cy;
        const intensity = (s >> 12) & 7;
        if (intensity === 0) {
          ctx.fillStyle = 'rgba(40, 60, 25, 0.5)';
          ctx.fillRect(px, py, 1, 1);
        } else if (intensity === 1) {
          ctx.fillStyle = 'rgba(80, 110, 50, 0.35)';
          ctx.fillRect(px, py, 1, 1);
        } else if (intensity === 2) {
          ctx.fillStyle = 'rgba(60, 90, 35, 0.4)';
          ctx.fillRect(px, py, 1, 1);
        } else if (intensity === 3) {
          ctx.fillStyle = 'rgba(100, 75, 30, 0.3)';
          ctx.fillRect(px, py, 1, 1);
        }
        // resterande intensity-värden: ingen prick = mer naturlig fördelning
      }
    }
  }
}

// GROUND-decorations: stigar, sjö, bäck, gläntor, garden — RITAS UNDER walls
// (forest_floor är legacy, hanteras av drawBrForestFloor — seamless tile-noise)
function drawBrGroundDecorations(decos) {
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (const d of decos) {
    if (d.kind === 'forest_floor') {
      continue; // hanteras av drawBrForestFloor()
    } else if (d.kind === 'tar_pit') {
      // v1.377: tar_pit är NU ground-decoration (under player), tidigare ovan.
      const x = d.x - cx, y = d.y - cy;
      const r = d.r || 40;
      if (x + r < -10 || x - r > viewW || y + r < -10 || y - r > viewH) continue;
      ctx.fillStyle = '#0a0408';
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      // Reflektion
      ctx.fillStyle = 'rgba(80, 50, 30, 0.5)';
      ctx.beginPath();
      ctx.ellipse(x - r * 0.2, y - r * 0.2, r * 0.4, r * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      // Bubblar (animerade)
      const t = performance.now() / 1000;
      for (let i = 0; i < 4; i++) {
        const phase = ((t * 0.6) + i * 0.3) % 1;
        const bx = x + Math.cos(i) * r * 0.5;
        const by = y + Math.sin(i) * r * 0.5;
        if (phase < 0.7) {
          ctx.fillStyle = 'rgba(40, 30, 20, 0.7)';
          ctx.beginPath();
          ctx.arc(bx, by, 2 + phase * 4, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    } else if (d.kind === 'dirt_floor') {
      // Jord-fläck (kyrkogård etc) — mjuka kanter via radial gradient (ingen
      // synlig rektangulär kant mot omgivande skog).
      const x = d.x - cx, y = d.y - cy;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      const ccx = x + d.w / 2, ccy = y + d.h / 2;
      const rx = d.w / 2, ry = d.h / 2;
      // Använd ellips-clip så fill bara hamnar inom rundade kanter
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(ccx, ccy, rx, ry, 0, 0, Math.PI * 2);
      ctx.clip();
      // Bas (mörk brun) med radial fade
      const grad = ctx.createRadialGradient(ccx, ccy, 0, ccx, ccy, Math.max(rx, ry));
      grad.addColorStop(0, 'rgba(58, 40, 24, 0.95)');
      grad.addColorStop(0.7, 'rgba(58, 40, 24, 0.85)');
      grad.addColorStop(1, 'rgba(58, 40, 24, 0)');
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, d.w, d.h);
      // Texture-prickar (mer jord-känsla)
      const seed = ((d.x * 17) ^ (d.y * 23)) | 0;
      ctx.fillStyle = 'rgba(90, 60, 30, 0.4)';
      for (let i = 0; i < d.w / 8; i++) {
        const px = x + ((seed * (i + 1) * 13) & 0x3ff) % d.w;
        const py = y + ((seed * (i + 3) * 17) & 0x3ff) % d.h;
        ctx.fillRect(px, py, 2, 2);
      }
      // Ljusare patches
      ctx.fillStyle = 'rgba(120, 80, 40, 0.25)';
      for (let i = 0; i < 6; i++) {
        const px = x + ((seed * (i + 7) * 23) & 0x3ff) % d.w;
        const py = y + ((seed * (i + 11) * 29) & 0x3ff) % d.h;
        ctx.beginPath();
        ctx.ellipse(px, py, 18, 10, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      // Mörka skugg-patches (ojämn jord)
      ctx.fillStyle = 'rgba(20, 12, 6, 0.35)';
      for (let i = 0; i < 5; i++) {
        const px = x + ((seed * (i + 13) * 31) & 0x3ff) % d.w;
        const py = y + ((seed * (i + 17) * 37) & 0x3ff) % d.h;
        ctx.beginPath();
        ctx.ellipse(px, py, 14, 8, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    } else if (d.kind === 'alien_transition') {
      // v1.371: alien_floor hanterar nu sin egen soft fade (square+gradient).
      // alien_transition rendrar inget längre — skapade tidigare "streak" mellan
      // grön och lila genom att tinta hela 5500×5500-zonen lila.
      continue;
    } else if (d.kind === 'alien_floor') {
      // ALIEN-MARK (v1.371): SOLID LILA SQUARE som matchar minimapen (7900-10000),
      // med smooth fade NW (7500-7900) för mjuk blend mot skogen — INGEN streak.
      const x = d.x - cx, y = d.y - cy;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      const t = performance.now() / 1000;
      const pulse = 0.5 + Math.sin(t * 0.8) * 0.25;
      const seed = ((d.x * 19) ^ (d.y * 23)) | 0;
      // Solid lila zon (matchar minimap-rektangeln)
      const SX0 = 7900, SY0 = 7900, SX1 = 10000, SY1 = 10000;
      const FADE = 450; // soft blend mot NW
      const PURPLE_BASE_R = 42, PURPLE_BASE_G = 24, PURPLE_BASE_B = 56;
      const purpleStr = (a) => 'rgba(' + PURPLE_BASE_R + ',' + PURPLE_BASE_G + ',' + PURPLE_BASE_B + ',' + a + ')';
      // alphaAt: 1 inom square, smooth cubic falloff utåt i fade-zonen
      const alphaAt = (wx, wy) => {
        if (wx >= SX0 && wy >= SY0 && wx <= SX1 && wy <= SY1) return 1;
        let dx = 0, dy = 0;
        if (wx < SX0) dx = SX0 - wx; else if (wx > SX1) dx = wx - SX1;
        if (wy < SY0) dy = SY0 - wy; else if (wy > SY1) dy = wy - SY1;
        const dist = Math.hypot(dx, dy);
        if (dist >= FADE) return 0;
        const f = 1 - dist / FADE;
        return f * f; // cubic-ish falloff — smooth blend
      };
      // ============ LAYER 1: Solid square + 3 fade-bands ============
      // 1A: Solid lila (alpha=1) ut till map-edge i SE
      ctx.fillStyle = purpleStr(1);
      ctx.fillRect(SX0 - cx, SY0 - cy, SX1 - SX0, SY1 - SY0);
      // Gradient color-stop helper — matchar f*f curve
      const addSmoothStops = (g, dir) => {
        // dir=1 = 0 → 1 (alpha grows toward end), dir=-1 = 1 → 0
        const stops = [[0.00, 0.00], [0.30, 0.09], [0.55, 0.30], [0.75, 0.56], [0.90, 0.81], [1.00, 1.00]];
        for (const [t, a] of stops) {
          const pos = dir === 1 ? t : 1 - t;
          g.addColorStop(pos, purpleStr(a));
        }
      };
      // 1B: N fade band — ovanför square, linjär gradient ner
      const ngrad = ctx.createLinearGradient(0, (SY0 - FADE) - cy, 0, SY0 - cy);
      addSmoothStops(ngrad, 1);
      ctx.fillStyle = ngrad;
      ctx.fillRect(SX0 - cx, (SY0 - FADE) - cy, SX1 - SX0, FADE);
      // 1C: W fade band — vänster om square, linjär gradient höger
      const wgrad = ctx.createLinearGradient((SX0 - FADE) - cx, 0, SX0 - cx, 0);
      addSmoothStops(wgrad, 1);
      ctx.fillStyle = wgrad;
      ctx.fillRect((SX0 - FADE) - cx, SY0 - cy, FADE, SY1 - SY0);
      // 1D: NW corner — radial från (SX0, SY0) ut till FADE
      const cnx = SX0 - cx, cny = SY0 - cy;
      const cgrad = ctx.createRadialGradient(cnx, cny, 0, cnx, cny, FADE);
      addSmoothStops(cgrad, -1);
      ctx.fillStyle = cgrad;
      ctx.fillRect((SX0 - FADE) - cx, (SY0 - FADE) - cy, FADE, FADE);
      // ============ LAYER 2: Sotfläckar (alpha-aware) ============
      ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
      const RANGE_X = (SX1 - SX0) + FADE;
      const RANGE_Y = (SY1 - SY0) + FADE;
      for (let i = 0; i < 60; i++) {
        const pxw = (SX0 - FADE) + ((seed * (i + 7) * 19) & 0xffff) % RANGE_X;
        const pyw = (SY0 - FADE) + ((seed * (i + 11) * 23) & 0xffff) % RANGE_Y;
        const a = alphaAt(pxw, pyw);
        if (a <= 0.05) continue;
        const px = pxw - cx, py = pyw - cy;
        ctx.globalAlpha = 0.55 * a;
        ctx.beginPath();
        ctx.ellipse(px, py, 18 + ((seed * i) % 14), 11 + ((seed * i) % 8), (seed * i) % 6, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
      // ============ LAYER 3: Glödande röda sprickor ============
      const zoneKey = SX0 + '_' + SY0 + '_' + SX1 + '_' + SY1;
      if (!state._alienCracks || state._alienCracks.key !== zoneKey) {
        const crackCount = 80;
        const cracks = [];
        for (let i = 0; i < crackCount; i++) {
          const cxw = (SX0 - FADE) + ((seed * (i + 1) * 71) & 0xffff) % RANGE_X;
          const cyw = (SY0 - FADE) + ((seed * (i + 5) * 113) & 0xffff) % RANGE_Y;
          const ang0 = ((seed * (i + 3) * 73) % 6283) / 1000;
          const length = 60 + ((seed * (i + 7) * 17) & 0x7f);
          const path = [];
          const segs = 4 + (i % 3);
          for (let s = 0; s <= segs; s++) {
            const f = s / segs;
            const wobble = ((seed * (i + 1) * (s + 11) * 41) % 200 - 100) * 0.001;
            const ang = ang0 + wobble;
            path.push({ x: cxw + Math.cos(ang) * length * f, y: cyw + Math.sin(ang) * length * f });
          }
          cracks.push(path);
        }
        state._alienCracks = { key: zoneKey, cracks };
      }
      const cracks = state._alienCracks.cracks;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      const drawCrackLayer = (strokeStyle, lineWidth, alphaMul) => {
        ctx.lineWidth = lineWidth;
        for (const path of cracks) {
          const mid = path[Math.floor(path.length / 2)];
          const a = alphaAt(mid.x, mid.y);
          if (a <= 0.05) continue;
          ctx.globalAlpha = a * alphaMul;
          ctx.strokeStyle = strokeStyle;
          ctx.beginPath();
          ctx.moveTo(path[0].x - cx, path[0].y - cy);
          for (let s = 1; s < path.length; s++) ctx.lineTo(path[s].x - cx, path[s].y - cy);
          ctx.stroke();
        }
      };
      drawCrackLayer('rgb(255, 30, 40)', 11, 0.30);
      drawCrackLayer('rgb(255, 90, 50)', 5, 0.55);
      drawCrackLayer('rgb(255, 140, 70)', 2.5, 0.78);
      drawCrackLayer('rgb(255, 230, 150)', 1.3, 0.95);
      ctx.globalAlpha = 1;
      // ============ LAYER 4: Pulserande lila glow-prickar ============
      for (let i = 0; i < 40; i++) {
        const pxw = (SX0 - FADE) + ((seed * (i + 23) * 41) & 0xffff) % RANGE_X;
        const pyw = (SY0 - FADE) + ((seed * (i + 29) * 47) & 0xffff) % RANGE_Y;
        const a = alphaAt(pxw, pyw);
        if (a <= 0.05) continue;
        const px = pxw - cx, py = pyw - cy;
        const radius = 5 + ((seed * (i + 7)) % 7);
        ctx.globalAlpha = 0.42 * pulse * a;
        ctx.fillStyle = 'rgb(180, 70, 230)';
        ctx.beginPath();
        ctx.ellipse(px, py, radius * 1.3, radius * 0.8, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
      // ============ LAYER 5: Gröna alien-energi-prickar ============
      for (let i = 0; i < 60; i++) {
        const pxw = (SX0 - FADE) + ((seed * (i + 13) * 29) & 0xffff) % RANGE_X;
        const pyw = (SY0 - FADE) + ((seed * (i + 17) * 31) & 0xffff) % RANGE_Y;
        const a = alphaAt(pxw, pyw);
        if (a <= 0.05) continue;
        const px = pxw - cx, py = pyw - cy;
        ctx.globalAlpha = 0.5 * pulse * a;
        ctx.fillStyle = 'rgb(120, 255, 150)';
        ctx.fillRect(px, py, 2.5, 2.5);
      }
      ctx.globalAlpha = 1;
    } else if (d.kind === 'bridge_deco') {
      // Bro som decoration — passabel, ritas på marken/vattnet
      const x = d.x - cx, y = d.y - cy;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(x + 2, y + 3, d.w, d.h);
      // Bas (mörk-brun trä)
      ctx.fillStyle = '#3a2818';
      ctx.fillRect(x, y, d.w, d.h);
      // Plankor
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1.2;
      const plankW = 12;
      if (d.w > d.h) {
        for (let i = plankW; i < d.w; i += plankW) {
          ctx.beginPath();
          ctx.moveTo(x + i, y); ctx.lineTo(x + i, y + d.h);
          ctx.stroke();
        }
      } else {
        for (let i = plankW; i < d.h; i += plankW) {
          ctx.beginPath();
          ctx.moveTo(x, y + i); ctx.lineTo(x + d.w, y + i);
          ctx.stroke();
        }
      }
      // Räcken (sidor med små stolpar)
      ctx.fillStyle = '#5a3818';
      if (d.w > d.h) {
        ctx.fillRect(x, y - 4, d.w, 3); // top räcke
        ctx.fillRect(x, y + d.h + 1, d.w, 3); // bottom räcke
        // Stolpar var 80px
        ctx.fillStyle = '#3a2010';
        for (let i = 10; i < d.w; i += 80) {
          ctx.fillRect(x + i, y - 8, 3, 6);
          ctx.fillRect(x + i, y + d.h + 3, 3, 6);
        }
      } else {
        ctx.fillRect(x - 4, y, 3, d.h);
        ctx.fillRect(x + d.w + 1, y, 3, d.h);
        ctx.fillStyle = '#3a2010';
        for (let i = 10; i < d.h; i += 80) {
          ctx.fillRect(x - 8, y + i, 6, 3);
          ctx.fillRect(x + d.w + 3, y + i, 6, 3);
        }
      }
    } else if (d.kind === 'sightseeing_deck') {
      // Avlång promenadbrygga framför vattenfallet
      const x = d.x - cx, y = d.y - cy;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(x + 3, y + 4, d.w, d.h);
      // Trädäck (ljus-brun)
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x, y, d.w, d.h);
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x + 2, y + 2, d.w - 4, d.h - 4);
      // Plankor
      ctx.strokeStyle = '#3a2008';
      ctx.lineWidth = 1;
      for (let i = 14; i < d.w; i += 14) {
        ctx.beginPath();
        ctx.moveTo(x + i, y + 4); ctx.lineTo(x + i, y + d.h - 4);
        ctx.stroke();
      }
      // Räcke mot vattenfall (norra sidan)
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y - 5, d.w, 4);
      // Stolpar
      for (let i = 6; i < d.w; i += 40) {
        ctx.fillRect(x + i, y - 10, 3, 8);
      }
      // "OBSERVATIONS-DÄCK" skylt-text
      ctx.fillStyle = 'rgba(255, 213, 74, 0.6)';
      ctx.font = 'bold 9px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('OBSERVATIONS-DÄCK', x + d.w / 2, y + d.h / 2);
    } else if (d.kind === 'glade') {
      // Ljus glänta — ljusare gräs-cirkel där solljus tränger in
      const x = d.x - cx, y = d.y - cy;
      const r = d.r || 150;
      if (x + r < -20 || x - r > viewW + 20 || y + r < -20 || y - r > viewH + 20) continue;
      // Gradient — ljus i mitten, fadar mot kanterna
      const grad = ctx.createRadialGradient(x, y, 10, x, y, r);
      grad.addColorStop(0, 'rgba(140, 170, 70, 0.45)');
      grad.addColorStop(0.6, 'rgba(90, 130, 60, 0.25)');
      grad.addColorStop(1, 'rgba(60, 100, 40, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'lake_water_polygon') {
      // Sjö som organic polygon
      if (!d.points || d.points.length < 3) continue;
      ctx.beginPath();
      const firstX = d.points[0][0] - cx;
      const firstY = d.points[0][1] - cy;
      ctx.moveTo(firstX, firstY);
      for (let i = 1; i < d.points.length; i++) {
        const px = d.points[i][0] - cx;
        const py = d.points[i][1] - cy;
        // Bezier curve mellan punkter (mjukare kant)
        const prevX = d.points[i - 1][0] - cx;
        const prevY = d.points[i - 1][1] - cy;
        const midX = (prevX + px) / 2;
        const midY = (prevY + py) / 2;
        ctx.quadraticCurveTo(prevX, prevY, midX, midY);
      }
      ctx.closePath();
      // Gradient-fyllning
      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
      for (const p of d.points) {
        if (p[0] - cx < minX) minX = p[0] - cx;
        if (p[0] - cx > maxX) maxX = p[0] - cx;
        if (p[1] - cy < minY) minY = p[1] - cy;
        if (p[1] - cy > maxY) maxY = p[1] - cy;
      }
      const grad = ctx.createRadialGradient(
        (minX + maxX) / 2, (minY + maxY) / 2, 20,
        (minX + maxX) / 2, (minY + maxY) / 2, Math.max(maxX - minX, maxY - minY) / 2
      );
      grad.addColorStop(0, '#1a3858');
      grad.addColorStop(0.6, '#2a5878');
      grad.addColorStop(1, '#3a7898');
      ctx.fillStyle = grad;
      ctx.fill();
      // Strand-kant
      ctx.strokeStyle = 'rgba(120, 90, 50, 0.7)';
      ctx.lineWidth = 6;
      ctx.stroke();
      // Inre kant (ljusare blå)
      ctx.strokeStyle = 'rgba(180, 220, 240, 0.25)';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Vågor (animerade horisontella streck)
      const t = performance.now() / 1000;
      ctx.strokeStyle = 'rgba(200, 230, 255, 0.18)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 6; i++) {
        const wy = minY + (i + 1) * (maxY - minY) / 7 + Math.sin(t * 0.4 + i) * 3;
        ctx.beginPath();
        ctx.moveTo(minX + 20, wy);
        ctx.lineTo(maxX - 20, wy);
        ctx.stroke();
      }
    } else if (d.kind === 'lake_water') {
      const x = d.x - cx, y = d.y - cy;
      // Skippa om en organic polygon redan har ritats (transparent fallback)
      if (d._opacity === 0) continue;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      // Sjö med radial gradient (djupare i mitten)
      const grad = ctx.createRadialGradient(
        x + d.w / 2, y + d.h / 2, 20,
        x + d.w / 2, y + d.h / 2, Math.max(d.w, d.h) / 2
      );
      grad.addColorStop(0, '#1a3858');
      grad.addColorStop(0.6, '#2a5878');
      grad.addColorStop(1, '#3a7898');
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, d.w, d.h);
    } else if (d.kind === 'grass_open') {
      const x = d.x - cx, y = d.y - cy;
      if (x + d.w < -50 || x > viewW + 50 || y + d.h < -50 || y > viewH + 50) continue;
      // Mjuka kanter via ellips-clip + radial fade (ingen synlig rektangulär kant)
      const ccx = x + d.w / 2, ccy = y + d.h / 2;
      const rx = d.w / 2, ry = d.h / 2;
      ctx.save();
      ctx.beginPath();
      ctx.ellipse(ccx, ccy, rx, ry, 0, 0, Math.PI * 2);
      ctx.clip();
      // Ljus-grön gräsmatta med radial-fade mot kanten
      const grad = ctx.createRadialGradient(ccx, ccy, 0, ccx, ccy, Math.max(rx, ry));
      grad.addColorStop(0, 'rgba(58, 90, 40, 0.9)');
      grad.addColorStop(0.6, 'rgba(58, 90, 40, 0.65)');
      grad.addColorStop(0.85, 'rgba(58, 90, 40, 0.30)');
      grad.addColorStop(1, 'rgba(58, 90, 40, 0)');
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, d.w, d.h);
      // Subtle grass-textur (mörkare prickar)
      ctx.fillStyle = 'rgba(40, 70, 25, 0.4)';
      const seed = ((d.x * 11) ^ (d.y * 17)) | 0;
      for (let i = 0; i < 28; i++) {
        const gx = x + ((seed * (i + 1) * 19) & 0xfff) % d.w;
        const gy = y + ((seed * (i + 3) * 23) & 0xfff) % d.h;
        ctx.fillRect(gx, gy, 3, 1);
      }
      // Ljusare gräs-tussar (varmare gröna fläckar) för djup
      ctx.fillStyle = 'rgba(110, 150, 60, 0.20)';
      for (let i = 0; i < 14; i++) {
        const gx = x + ((seed * (i + 7) * 29) & 0xfff) % d.w;
        const gy = y + ((seed * (i + 11) * 31) & 0xfff) % d.h;
        ctx.beginPath();
        ctx.ellipse(gx, gy, 25, 14, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    } else if (d.kind === 'stream') {
      // Bäck — linje från (x,y) till (x2,y2) i ljus-blå
      const x1 = d.x - cx, y1 = d.y - cy;
      const x2 = d.x2 - cx, y2 = d.y2 - cy;
      ctx.strokeStyle = '#3a7898';
      ctx.lineWidth = d.w || 18;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
      // Ljusare highlight i mitten
      ctx.strokeStyle = 'rgba(180, 220, 240, 0.35)';
      ctx.lineWidth = (d.w || 18) * 0.5;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    } else if (d.kind === 'dirt_path') {
      // Stig — brun linje från (x,y) till (x2,y2)
      const x1 = d.x - cx, y1 = d.y - cy;
      const x2 = d.x2 - cx, y2 = d.y2 - cy;
      ctx.strokeStyle = '#5a4028';
      ctx.lineWidth = d.w || 30;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
      // Mid-tone highlight
      ctx.strokeStyle = '#7a5838';
      ctx.lineWidth = (d.w || 30) * 0.6;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
      // Liten centrumlinje (slitage)
      ctx.strokeStyle = '#3a2818';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    } else if (d.kind === 'garden_patch') {
      const x = d.x - cx, y = d.y - cy;
      // Mörk-brun jord
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y, d.w, d.h);
      // Rader (linjer)
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1.5;
      for (let i = 8; i < d.h; i += 12) {
        ctx.beginPath();
        ctx.moveTo(x + 3, y + i); ctx.lineTo(x + d.w - 3, y + i);
        ctx.stroke();
      }
      // Grönsaker (små gröna prickar)
      ctx.fillStyle = '#5a8a30';
      for (let yy = 8; yy < d.h; yy += 12) {
        for (let xx = 8; xx < d.w; xx += 14) {
          ctx.beginPath();
          ctx.arc(x + xx, y + yy, 2, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
  }
  ctx.restore();
}

// TOP-decorations: blommor, svampar, kottar, fallen logs, skyltar, lanterns, etc.
function drawBrTopDecorations(decos) {
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  ctx.save();
  for (const d of decos) {
    if (d.kind === 'forest_floor' || d.kind === 'grass_open' || d.kind === 'lake_water'
        || d.kind === 'lake_water_polygon' || d.kind === 'glade'
        || d.kind === 'stream' || d.kind === 'dirt_path' || d.kind === 'garden_patch'
        || d.kind === 'dirt_floor' || d.kind === 'alien_floor'
        || d.kind === 'bridge_deco' || d.kind === 'sightseeing_deck'
        || d.kind === 'alien_transition' || d.kind === 'tar_pit'
        || d.kind === 'smoke') continue; // hanteras separat (tar_pit nu i ground)
    const x = d.x - cx, y = d.y - cy;
    // Viewport-cull med bbox (objekt-storlek inkluderat så stora objekt inte
    // försvinner när deras top-left är utanför viewporten).
    const objW = d.w || 0, objH = d.h || 0;
    if (x + objW + 60 < 0 || x - 60 > viewW || y + objH + 60 < 0 || y - 60 > viewH) {
      if (!d.x2) continue;
      const x2 = d.x2 - cx, y2 = d.y2 - cy;
      if ((x < -60 || x > viewW + 60) && (x2 < -60 || x2 > viewW + 60)) continue;
    }
    if (d.kind === 'fallen_log') {
      ctx.save();
      ctx.translate(x + d.w / 2, y + d.h / 2);
      ctx.rotate(d.rot || 0);
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(-d.w / 2 + 1, -d.h / 2 + 2, d.w, d.h);
      // Stock-bas (mörk-brun)
      ctx.fillStyle = '#3a2818';
      ctx.fillRect(-d.w / 2, -d.h / 2, d.w, d.h);
      // Ljus-rand (top highlight)
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(-d.w / 2, -d.h / 2 + 2, d.w, d.h / 3);
      // Årsringar (vid ändar)
      ctx.strokeStyle = '#5a3818';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(-d.w / 2 + 4, 0, d.h / 2 - 2, 0, Math.PI * 2);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(d.w / 2 - 4, 0, d.h / 2 - 2, 0, Math.PI * 2);
      ctx.stroke();
      // Mossa
      ctx.fillStyle = 'rgba(60, 100, 40, 0.5)';
      ctx.fillRect(-d.w / 3, -d.h / 2 - 1, d.w / 4, 3);
      ctx.restore();
    } else if (d.kind === 'flowers') {
      const count = d.count || 5;
      const colors = ['#ff6080', '#ffd040', '#a060ff', '#ffffff', '#ff8030'];
      const seed = ((d.x * 7) ^ (d.y * 13)) | 0;
      for (let i = 0; i < count; i++) {
        const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
        const dist = ((seed * (i + 3) * 17) & 0xff) / 255 * 40 + 5;
        const fx = x + Math.cos(ang) * dist;
        const fy = y + Math.sin(ang) * dist;
        // Stjälk (grön)
        ctx.strokeStyle = '#3a7a3a';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(fx, fy); ctx.lineTo(fx, fy + 4);
        ctx.stroke();
        // Blomma
        ctx.fillStyle = colors[i % colors.length];
        ctx.beginPath();
        ctx.arc(fx, fy, 2.5, 0, Math.PI * 2);
        ctx.fill();
        // Centrum
        ctx.fillStyle = '#ffd040';
        ctx.beginPath();
        ctx.arc(fx, fy, 1, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'mushrooms') {
      const count = d.count || 4;
      const seed = ((d.x * 11) ^ (d.y * 17)) | 0;
      for (let i = 0; i < count; i++) {
        const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
        const dist = ((seed * (i + 3) * 19) & 0xff) / 255 * 30 + 5;
        const mx = x + Math.cos(ang) * dist;
        const my = y + Math.sin(ang) * dist;
        // Stam (vit)
        ctx.fillStyle = '#e0d8c0';
        ctx.fillRect(mx - 1, my - 1, 2, 4);
        // Hatt (röd med vita prickar)
        ctx.fillStyle = '#cc2020';
        ctx.beginPath();
        ctx.arc(mx, my - 1, 3, 0, Math.PI);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(mx - 1, my - 1.5, 0.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(mx + 1, my - 1, 0.5, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'pine_cones') {
      const count = d.count || 5;
      const seed = ((d.x * 13) ^ (d.y * 19)) | 0;
      for (let i = 0; i < count; i++) {
        const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
        const dist = ((seed * (i + 3) * 17) & 0xff) / 255 * 35 + 5;
        const px = x + Math.cos(ang) * dist;
        const py = y + Math.sin(ang) * dist;
        // Brun oval
        ctx.fillStyle = '#5a3018';
        ctx.beginPath();
        ctx.ellipse(px, py, 2, 3, 0, 0, Math.PI * 2);
        ctx.fill();
        // Fjäll-texture (mörk centrum-streck)
        ctx.fillStyle = '#3a1808';
        ctx.fillRect(px - 0.5, py - 2, 1, 4);
      }
    } else if (d.kind === 'sign_wooden') {
      // Trä-skylt på pinne (vertikal)
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x + d.w / 2 - 2, y + d.h, 4, 14); // pinne
      // Skylt
      ctx.fillStyle = d.color || '#5a3a18';
      ctx.fillRect(x, y, d.w, d.h);
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, d.w - 1, d.h - 1);
      // Text
      if (d.text) {
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(d.text, x + d.w / 2, y + d.h / 2);
      }
    } else if (d.kind === 'tire_swing') {
      // Däck-gunga hängande från träd
      ctx.strokeStyle = '#3a2818';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(x, y - 20); ctx.lineTo(x, y);
      ctx.stroke();
      // Däck (svart cirkel med hål)
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath();
      ctx.arc(x, y, 12, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3a3028';
      ctx.beginPath();
      ctx.arc(x, y, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#666';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(x, y, 12, 0, Math.PI * 2);
      ctx.stroke();
    } else if (d.kind === 'clothes_line') {
      // Tvättlina mellan punkter
      const x2 = d.x2 - cx, y2 = d.y2 - cy;
      ctx.strokeStyle = '#888';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y); ctx.lineTo(x2, y2);
      ctx.stroke();
      // Kläder (3 färgade rektanglar)
      const colors = ['#aa3030', '#3a5a8a', '#ddaa30'];
      for (let i = 1; i <= 3; i++) {
        const f = i / 4;
        const cx2 = x + (x2 - x) * f;
        const cy2 = y + (y2 - y) * f;
        ctx.fillStyle = colors[i - 1];
        ctx.fillRect(cx2 - 4, cy2 + 1, 8, 12);
      }
    } else if (d.kind === 'mailbox') {
      // Brevlåda på pinne
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x - 1, y, 2, 16); // pinne
      // Box (röd metallisk)
      ctx.fillStyle = '#aa3030';
      ctx.fillRect(x - 6, y - 4, 12, 8);
      ctx.strokeStyle = '#1a0a04';
      ctx.lineWidth = 0.8;
      ctx.strokeRect(x - 5.5, y - 3.5, 11, 7);
      // Flag (gul)
      ctx.fillStyle = '#ffd040';
      ctx.fillRect(x + 6, y - 4, 2, 4);
    } else if (d.kind === 'reeds') {
      // Vass (gröna streck)
      const w = d.w || 100;
      ctx.strokeStyle = '#3a7a3a';
      ctx.lineWidth = 1;
      for (let i = 0; i < w / 4; i++) {
        const rx = x + i * 4;
        const ry = y + (i % 3) * 2;
        ctx.beginPath();
        ctx.moveTo(rx, ry); ctx.lineTo(rx, ry - 10);
        ctx.stroke();
        // Topp-blomma
        ctx.fillStyle = '#9a7a30';
        ctx.fillRect(rx - 0.5, ry - 12, 1.5, 3);
      }
    } else if (d.kind === 'lily_pad') {
      // Näckros (grön disc + vit blomma)
      ctx.fillStyle = '#3a7a3a';
      ctx.beginPath();
      ctx.arc(x, y, 8, 0, Math.PI * 2);
      ctx.fill();
      // Mörkare ring
      ctx.fillStyle = '#1a4a1a';
      ctx.beginPath();
      ctx.arc(x - 3, y - 3, 1.5, 0, Math.PI * 2);
      ctx.fill();
      // Blomma (vit)
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(x + 2, y, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffd040';
      ctx.beginPath();
      ctx.arc(x + 2, y, 1, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'animal_track') {
      // Djurspår (3-4 små bruna prickar i linje)
      ctx.fillStyle = 'rgba(60, 40, 20, 0.7)';
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.arc(x + i * 8, y + (i % 2) * 4, 2, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'bush') {
      // Buske (organisk grön cluster)
      ctx.fillStyle = '#1a3a1a';
      ctx.beginPath();
      ctx.arc(x, y, 14, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3a7a3a';
      ctx.beginPath();
      ctx.arc(x - 3, y - 2, 8, 0, Math.PI * 2);
      ctx.arc(x + 5, y - 1, 7, 0, Math.PI * 2);
      ctx.arc(x + 1, y + 4, 7, 0, Math.PI * 2);
      ctx.fill();
      // Bär (röda prickar)
      ctx.fillStyle = '#cc2020';
      ctx.beginPath();
      ctx.arc(x - 2, y, 1.5, 0, Math.PI * 2);
      ctx.arc(x + 3, y - 3, 1.5, 0, Math.PI * 2);
      ctx.arc(x + 4, y + 2, 1.5, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'waterfall') {
      // SOLID CASCADING vattenfall — som riktig vattenmassa, inte regn-streck.
      // 3-lager design: bakre mörk vattenmassa, ljusare mid-vatten, vit skum-front
      const t = performance.now() / 1000;
      // 1. BAS — solid blå vattenmassa över hela ytan (mörk-blå)
      const grad = ctx.createLinearGradient(x, y, x, y + d.h);
      grad.addColorStop(0, '#5a90c8');   // ljus topp (där vattnet kommer från)
      grad.addColorStop(0.3, '#3a7098');
      grad.addColorStop(0.8, '#1a4878');
      grad.addColorStop(1, '#0a2858');   // mörk botten
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, d.w, d.h);
      // 2. VERTIKALA FLOW-band (subtila ljusare striper för rörelse-känsla)
      // Inte tunna streck — bredare band så det ser ut som CASCADE
      const bandCount = 5;
      for (let i = 0; i < bandCount; i++) {
        const bx = x + (i + 0.5) * (d.w / bandCount);
        const bw = d.w / bandCount * 0.6;
        const phaseOff = i * 0.4;
        // Subtila rörelse-shimmer
        const alpha = 0.15 + 0.1 * Math.sin(t * 3 + phaseOff);
        ctx.fillStyle = 'rgba(180, 220, 255, ' + alpha + ')';
        ctx.fillRect(bx - bw / 2, y, bw, d.h);
      }
      // 3. VIT SKUM-FRONT (toppen där vattnet börjar falla)
      ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
      ctx.fillRect(x, y, d.w, 6);
      ctx.fillStyle = 'rgba(220, 240, 255, 0.6)';
      ctx.fillRect(x, y + 6, d.w, 4);
      // 4. FLOWING WHITE STREAKS — diagonala vita streck som "flödar" nedåt
      // Bredare och mer SOLID än tidigare regn-streck
      ctx.fillStyle = 'rgba(240, 250, 255, 0.45)';
      for (let i = 0; i < 4; i++) {
        const sx = x + (i + 0.5) * (d.w / 4);
        const phase = ((t * 1.5) + i * 0.25) % 1;
        const yOff = phase * d.h;
        const streakH = Math.min(40, d.h - yOff);
        if (streakH > 0) {
          ctx.fillRect(sx - 3, y + yOff, 6, streakH);
        }
      }
      // 5. BUBBLOR och DROPPAR i underkanten (vatten möter sjön)
      ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
      for (let i = 0; i < 8; i++) {
        const bx = x + (i + 0.5) * (d.w / 8);
        const by = y + d.h - 10 + Math.sin(t * 4 + i) * 4;
        const r = 2 + Math.sin(t * 5 + i * 0.7) * 1;
        ctx.beginPath();
        ctx.arc(bx, by, r, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'water_splash') {
      // Skum vid foten av vattenfalls
      const t = performance.now() / 1000;
      for (let i = 0; i < 8; i++) {
        const ang = (i / 8) * Math.PI * 2;
        const dist = 8 + Math.sin(t * 4 + i) * 3;
        const sx = x + Math.cos(ang) * dist;
        const sy = y + Math.sin(ang) * dist;
        ctx.fillStyle = 'rgba(220, 240, 255, ' + (0.6 + Math.sin(t * 5 + i) * 0.2) + ')';
        ctx.beginPath();
        ctx.arc(sx, sy, 3 + Math.sin(t * 3 + i) * 1, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'cave_entrance') {
      // Grotta-öppning (mörk båglik ingång)
      ctx.fillStyle = '#0a0408';
      ctx.beginPath();
      ctx.arc(x + d.w / 2, y + d.h * 0.6, d.w / 2, Math.PI, 0);
      ctx.fillRect(x, y + d.h * 0.6, d.w, d.h * 0.4);
      ctx.fill();
      // Yttre stenram
      ctx.strokeStyle = '#3a3028';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(x + d.w / 2, y + d.h * 0.6, d.w / 2, Math.PI, 0);
      ctx.stroke();
    } else if (d.kind === 'light_shaft') {
      // Diagonal ljus-stråle (gult genom skogen)
      const length = d.length || 200;
      const ang = d.ang || 0;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(ang);
      const grad = ctx.createLinearGradient(0, 0, length, 0);
      grad.addColorStop(0, 'rgba(255, 240, 180, 0)');
      grad.addColorStop(0.4, 'rgba(255, 240, 180, 0.2)');
      grad.addColorStop(0.6, 'rgba(255, 240, 180, 0.2)');
      grad.addColorStop(1, 'rgba(255, 240, 180, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(length, -10);
      ctx.lineTo(length, 10);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    } else if (d.kind === 'fallen_leaves') {
      const count = d.count || 12;
      const colors = ['#a04020', '#c06030', '#d0a030', '#a06010', '#704818'];
      const seed = ((d.x * 11) ^ (d.y * 19)) | 0;
      for (let i = 0; i < count; i++) {
        const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
        const dist = ((seed * (i + 3) * 17) & 0xff) / 255 * 50;
        const lx = x + Math.cos(ang) * dist;
        const ly = y + Math.sin(ang) * dist;
        ctx.save();
        ctx.translate(lx, ly);
        ctx.rotate(((seed * (i + 5)) & 0xff) / 255 * Math.PI);
        ctx.fillStyle = colors[i % colors.length];
        ctx.beginPath();
        ctx.ellipse(0, 0, 3, 5, 0, 0, Math.PI * 2);
        ctx.fill();
        // Löv-åder
        ctx.strokeStyle = 'rgba(40, 20, 10, 0.5)';
        ctx.lineWidth = 0.4;
        ctx.beginPath();
        ctx.moveTo(0, -4); ctx.lineTo(0, 4);
        ctx.stroke();
        ctx.restore();
      }
    } else if (d.kind === 'moss_patch') {
      // Mossig grön patch
      ctx.fillStyle = 'rgba(50, 90, 35, 0.5)';
      ctx.beginPath();
      ctx.ellipse(x + d.w / 2, y + d.h / 2, d.w / 2, d.h / 2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(80, 120, 55, 0.4)';
      ctx.beginPath();
      ctx.ellipse(x + d.w / 2 - 3, y + d.h / 2 - 2, d.w / 3, d.h / 3, 0, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'moose_skeleton') {
      // Älg-skelett (uppifrån — kranium + revben + ben)
      ctx.fillStyle = '#e0d8c0';
      // Skalle
      ctx.beginPath();
      ctx.ellipse(x, y - 18, 8, 10, 0, 0, Math.PI * 2);
      ctx.fill();
      // Hornen (stora älghorn)
      ctx.strokeStyle = '#9a8060';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x - 6, y - 24); ctx.lineTo(x - 14, y - 30);
      ctx.moveTo(x - 14, y - 30); ctx.lineTo(x - 12, y - 36);
      ctx.moveTo(x - 14, y - 30); ctx.lineTo(x - 20, y - 32);
      ctx.moveTo(x + 6, y - 24); ctx.lineTo(x + 14, y - 30);
      ctx.moveTo(x + 14, y - 30); ctx.lineTo(x + 12, y - 36);
      ctx.moveTo(x + 14, y - 30); ctx.lineTo(x + 20, y - 32);
      ctx.stroke();
      // Ryggrad
      ctx.strokeStyle = '#c0b890';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x, y - 10); ctx.lineTo(x, y + 25);
      ctx.stroke();
      // Revben (6 par)
      ctx.lineWidth = 1.2;
      for (let i = 0; i < 6; i++) {
        const ry = y - 5 + i * 5;
        ctx.beginPath();
        ctx.moveTo(x, ry); ctx.lineTo(x - 8, ry + 1);
        ctx.moveTo(x, ry); ctx.lineTo(x + 8, ry + 1);
        ctx.stroke();
      }
      // Ben (4 utstickande)
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x - 7, y); ctx.lineTo(x - 15, y + 8);
      ctx.moveTo(x + 7, y); ctx.lineTo(x + 15, y + 8);
      ctx.moveTo(x - 5, y + 20); ctx.lineTo(x - 12, y + 28);
      ctx.moveTo(x + 5, y + 20); ctx.lineTo(x + 12, y + 28);
      ctx.stroke();
    } else if (d.kind === 'tar_pit') {
      // Mörk-svart pöl med bubblar
      const r = d.r || 40;
      ctx.fillStyle = '#0a0408';
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      // Reflektion
      ctx.fillStyle = 'rgba(80, 50, 30, 0.5)';
      ctx.beginPath();
      ctx.ellipse(x - r * 0.2, y - r * 0.2, r * 0.4, r * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      // Animerade bubblar
      const t = performance.now() / 1000;
      for (let i = 0; i < 4; i++) {
        const phase = ((t * 0.6) + i * 0.3) % 1;
        const bx = x + Math.cos(i) * r * 0.5;
        const by = y + Math.sin(i) * r * 0.5;
        if (phase < 0.7) {
          ctx.fillStyle = 'rgba(40, 30, 20, 0.7)';
          ctx.beginPath();
          ctx.arc(bx, by, 2 + phase * 4, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    } else if (d.kind === 'bird_flock') {
      // Liten flock fåglar (V-formation animerad)
      const t = performance.now() / 1000;
      const offset = Math.sin(t * 0.5) * 30;
      for (let i = 0; i < 5; i++) {
        const bx = x + offset + (i - 2) * 12;
        const by = y - Math.abs(i - 2) * 4;
        // V-form fågel
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(bx - 4, by + 2); ctx.lineTo(bx, by); ctx.lineTo(bx + 4, by + 2);
        ctx.stroke();
      }
    } else if (d.kind === 'crop_circle') {
      // Alien crop-circle (cirkulärt mönster — pulserande grön)
      const t = performance.now() / 1000;
      const pulse = 0.5 + Math.sin(t * 1.2) * 0.3;
      ctx.strokeStyle = 'rgba(120, 255, 150, ' + (0.6 * pulse) + ')';
      ctx.lineWidth = 2;
      // Yttre cirkel
      ctx.beginPath();
      ctx.arc(x, y, 35, 0, Math.PI * 2);
      ctx.stroke();
      // Inner cirkel
      ctx.beginPath();
      ctx.arc(x, y, 18, 0, Math.PI * 2);
      ctx.stroke();
      // 4 radial lines
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 4; i++) {
        const ang = i * Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(ang) * 18, y + Math.sin(ang) * 18);
        ctx.lineTo(x + Math.cos(ang) * 35, y + Math.sin(ang) * 35);
        ctx.stroke();
      }
      // Centrum-prick
      ctx.fillStyle = 'rgba(180, 255, 200, ' + pulse + ')';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    } else if (d.kind === 'glow_mushrooms') {
      // Glödande svampar (lila/grön glöd, pulserande)
      const count = d.count || 5;
      const seed = ((d.x * 11) ^ (d.y * 17)) | 0;
      const t = performance.now() / 1000;
      for (let i = 0; i < count; i++) {
        const ang = ((seed * (i + 1) * 13) & 0xff) / 255 * Math.PI * 2;
        const dist = ((seed * (i + 3) * 19) & 0xff) / 255 * 35;
        const mx = x + Math.cos(ang) * dist;
        const my = y + Math.sin(ang) * dist;
        const pulse = 0.6 + Math.sin(t * 1.5 + i * 0.7) * 0.4;
        // Glöd
        const gradGlow = ctx.createRadialGradient(mx, my, 0, mx, my, 12);
        gradGlow.addColorStop(0, 'rgba(140, 80, 220, ' + (0.5 * pulse) + ')');
        gradGlow.addColorStop(1, 'rgba(140, 80, 220, 0)');
        ctx.fillStyle = gradGlow;
        ctx.beginPath();
        ctx.arc(mx, my, 12, 0, Math.PI * 2);
        ctx.fill();
        // Stam (vit)
        ctx.fillStyle = '#e0d8c0';
        ctx.fillRect(mx - 1, my, 2, 5);
        // Hatt (lila glödande)
        ctx.fillStyle = 'rgba(180, 100, 230, ' + (0.85 + pulse * 0.15) + ')';
        ctx.beginPath();
        ctx.arc(mx, my - 1, 4, 0, Math.PI);
        ctx.fill();
        // Spots
        ctx.fillStyle = 'rgba(255, 230, 255, ' + pulse + ')';
        ctx.beginPath();
        ctx.arc(mx - 1, my - 1.5, 0.7, 0, Math.PI * 2);
        ctx.arc(mx + 1.5, my - 1, 0.7, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (d.kind === 'alien_track') {
      // Alien-spår — 3 udda 3-tå fotspår i grön
      const t = performance.now() / 1000;
      const pulse = 0.4 + Math.sin(t * 1.5) * 0.2;
      ctx.fillStyle = 'rgba(120, 255, 150, ' + pulse + ')';
      for (let i = 0; i < 3; i++) {
        const fx = x + i * 12;
        const fy = y + (i % 2) * 6;
        // Centrum-prick + 3 tår
        ctx.beginPath();
        ctx.ellipse(fx, fy, 3, 4, 0, 0, Math.PI * 2);
        ctx.fill();
        for (let j = 0; j < 3; j++) {
          const tx = fx + (j - 1) * 2.5;
          const ty = fy - 5;
          ctx.beginPath();
          ctx.arc(tx, ty, 1.2, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    } else if (d.kind === 'sign' || d.kind === 'graffiti' || d.kind === 'lantern' || d.kind === 'caution_tape') {
      // Fallback: använd drawDecorationItem
      if (typeof drawDecorationItem === 'function') {
        drawDecorationItem(d, cx, cy);
      }
    }
  }
  ctx.restore();
}

// SMOKE — animerade röksväpor som svävar uppåt och fadar ut
function drawBrSmoke(decos) {
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now() / 1000;
  ctx.save();
  for (const d of decos) {
    if (d.kind !== 'smoke') continue;
    const x = d.x - cx, y = d.y - cy;
    if (x < -80 || x > viewW + 80 || y < -200 || y > viewH + 80) continue;
    const scale = d.scale || 1;
    const isDark = d.color === 'dark';
    // 4 wisps per smoke-källa, var med olika fas
    for (let i = 0; i < 4; i++) {
      const offset = i * 0.6; // varje wisp 0.6s isär
      const phase = ((t + offset) % 2.4) / 2.4; // 2.4s cycle, normaliserat 0-1
      const yOff = -phase * 80 * scale; // går upp 80px * scale
      const xOff = Math.sin((t + offset) * 1.3) * 8 * phase; // svängar lite
      const alpha = (1 - phase) * 0.45;
      const radius = (6 + phase * 16) * scale;
      ctx.fillStyle = isDark
        ? 'rgba(40, 40, 40, ' + alpha + ')'
        : 'rgba(120, 120, 120, ' + (alpha * 0.7) + ')';
      ctx.beginPath();
      ctx.arc(x + xOff, y + yOff, radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // Lite eld-glöd vid basen (för dark smoke = brand)
    if (isDark) {
      const flicker = 0.5 + Math.sin(t * 8) * 0.3;
      ctx.fillStyle = 'rgba(255, 100, 30, ' + (0.3 * flicker) + ')';
      ctx.beginPath();
      ctx.arc(x, y, 8 * scale, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

// CABINS — splittas i två faser:
//   drawBrCabinInteriors() — körs FÖRE player. Ritar golv + items i stugan jag är inne i,
//     så spelaren ritas OVANPÅ golvet (inte under det).
//   drawBrCabinRoofs() — körs EFTER player. Ritar tak ovanpå spelare för stugor jag är ute i
//     (fog-of-war: fiende inne i stuga är dold för mig).
//   drawCabinDoorMarker — ritas EFTER player. Markerar tydligt entré.

// Helper: hämta cabin spelaren är inne i (eller null)
function _brCabinPlayerIsIn() {
  if (!state.battleroyaleCabins || !state.player) return null;
  const px = state.player.x, py = state.player.y;
  for (const cabin of state.battleroyaleCabins) {
    const b = cabin.bounds;
    if (px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h) return cabin;
  }
  return null;
}

// Körs FÖRE player — ritar BARA golvet i stugan jag är inne i (om någon)
function drawBrCabinInteriors() {
  const cabin = _brCabinPlayerIsIn();
  if (!cabin) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const b = cabin.bounds;
  const sx = b.x - cx, sy = b.y - cy;
  ctx.save();
  drawCabinInterior(cabin, sx, sy, cx, cy);
  ctx.restore();
}

// Körs EFTER player — ritar tak för alla stugor jag INTE är inne i (fog-of-war)
function drawBrCabinRoofs() {
  if (!state.battleroyaleCabins || !state.battleroyaleCabins.length) return;
  if (!state.player) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const px = state.player.x, py = state.player.y;
  ctx.save();
  for (const cabin of state.battleroyaleCabins) {
    const b = cabin.bounds;
    const sx = b.x - cx, sy = b.y - cy;
    if (sx + b.w < -50 || sx > viewW + 50 || sy + b.h < -50 || sy > viewH + 50) continue;
    const iAmInside = px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h;
    if (!iAmInside) {
      drawCabinRoof(cabin, sx, sy);
    }
    // Dörrmarkör för ALLA stugor (även den jag är inne i — så jag ser entréerna)
    drawCabinDoorMarker(cabin, sx, sy);
  }
  ctx.restore();
}

// Bakåtkompatibilitet — använd inte direkt, anropa drawBrCabinInteriors + drawBrCabinRoofs
function drawBrCabins() {
  drawBrCabinInteriors();
  drawBrCabinRoofs();
}

// DÖRR-MARKÖR — tydlig entré: dörrmatta + arrow + hängande lampa
function drawCabinDoorMarker(cabin, sx, sy) {
  if (!cabin.door) return;
  // Containers: bara visuell dörröppning, INGEN dörrmatta (per user-spec)
  if (cabin._isContainer) {
    const b = cabin.bounds;
    const door = cabin.door;
    const T = 12;
    let dx, dy, dw, dh;
    if (door.side === 'north') { dx = sx + door.offset; dy = sy; dw = door.width; dh = T; }
    else if (door.side === 'south') { dx = sx + door.offset; dy = sy + b.h - T; dw = door.width; dh = T; }
    else if (door.side === 'east') { dx = sx + b.w - T; dy = sy + door.offset; dw = T; dh = door.width; }
    else { dx = sx; dy = sy + door.offset; dw = T; dh = door.width; }
    // Bara svart dörröppning (visuell)
    ctx.fillStyle = '#1a0e04';
    ctx.fillRect(dx, dy, dw, dh);
    return;
  }
  const b = cabin.bounds;
  const door = cabin.door;
  // Räkna ut dörr-positionen (yttre kant + matta utåt)
  const T = 12; // wall-tjocklek
  let dx, dy, dw, dh; // door-rektangel
  let outX, outY; // matta-position UTANFÖR dörren
  let mw, mh; // matta-storlek
  if (door.side === 'north') {
    dx = sx + door.offset; dy = sy; dw = door.width; dh = T;
    outX = dx; outY = dy - 24; mw = door.width; mh = 18;
  } else if (door.side === 'south') {
    dx = sx + door.offset; dy = sy + b.h - T; dw = door.width; dh = T;
    outX = dx; outY = dy + T + 6; mw = door.width; mh = 18;
  } else if (door.side === 'east') {
    dx = sx + b.w - T; dy = sy + door.offset; dw = T; dh = door.width;
    outX = dx + T + 6; outY = dy; mw = 18; mh = door.width;
  } else { // west
    dx = sx; dy = sy + door.offset; dw = T; dh = door.width;
    outX = dx - 24; outY = dy; mw = 18; mh = door.width;
  }
  // 1. Dörrmatta utanför (brun rektangel med "WELCOME"-look)
  ctx.fillStyle = '#5a3018';
  ctx.fillRect(outX, outY, mw, mh);
  ctx.fillStyle = '#7a4828';
  ctx.fillRect(outX + 2, outY + 2, mw - 4, mh - 4);
  // Trådmönster
  ctx.strokeStyle = '#3a2010';
  ctx.lineWidth = 0.6;
  for (let i = 4; i < mw; i += 4) {
    ctx.beginPath();
    ctx.moveTo(outX + i, outY + 2); ctx.lineTo(outX + i, outY + mh - 2);
    ctx.stroke();
  }
  for (let i = 4; i < mh; i += 4) {
    ctx.beginPath();
    ctx.moveTo(outX + 2, outY + i); ctx.lineTo(outX + mw - 2, outY + i);
    ctx.stroke();
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 1;
  ctx.strokeRect(outX + 0.5, outY + 0.5, mw - 1, mh - 1);
  // 2. Visuell dörr (öppen — visa trä-ram + svart inre)
  ctx.fillStyle = '#1a0e04';
  ctx.fillRect(dx, dy, dw, dh);
  // Trä-ram runt
  ctx.strokeStyle = '#5a3018';
  ctx.lineWidth = 2;
  ctx.strokeRect(dx + 0.5, dy + 0.5, dw - 1, dh - 1);
  // (Pilen borttagen — bara dörrmatta + visuell dörr räcker som markering)
}

function drawCabinInterior(cabin, sx, sy, cx, cy) {
  const b = cabin.bounds;
  // Golv (overlay innanför wall-segmenten)
  ctx.fillStyle = cabin.floor || '#6a4828';
  ctx.fillRect(sx + 12, sy + 12, b.w - 24, b.h - 24);
  // Plank-mönster
  ctx.strokeStyle = 'rgba(20, 14, 4, 0.4)';
  ctx.lineWidth = 1;
  for (let i = 20; i < b.h - 12; i += 20) {
    ctx.beginPath();
    ctx.moveTo(sx + 13, sy + 12 + i);
    ctx.lineTo(sx + b.w - 13, sy + 12 + i);
    ctx.stroke();
  }
  // Items
  if (cabin.interior) {
    for (const item of cabin.interior) {
      drawCabinInteriorItem(item, cx, cy);
    }
  }
}

function drawCabinRoof(cabin, sx, sy) {
  const b = cabin.bounds;
  const r = cabin.roof || { color: '#5a3818', accent: '#2a1808', style: 'tile' };
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(sx + 6, sy + 8, b.w, b.h);
  // Tak-bas
  ctx.fillStyle = r.color;
  ctx.fillRect(sx, sy, b.w, b.h);
  // Clip ALL tile/shingle/thatch-pattern till tak-rektangeln så inga linjer
  // sträcker sig utanför takets kant (bug-fix för tidigare över-fyllda rader).
  ctx.save();
  ctx.beginPath();
  ctx.rect(sx, sy, b.w, b.h);
  ctx.clip();
  // Tak-stil
  ctx.strokeStyle = r.accent;
  ctx.lineWidth = 1.2;
  if (r.style === 'tile') {
    // Tegelpannor (fish-scale)
    const tileW = 22;
    const tileH = 14;
    for (let yy = 0; yy < b.h; yy += tileH) {
      const xOff = (yy / tileH) % 2 === 0 ? 0 : tileW / 2;
      for (let xx = xOff; xx < b.w; xx += tileW) {
        ctx.beginPath();
        ctx.arc(sx + xx + tileW / 2, sy + yy, tileW / 2, 0, Math.PI);
        ctx.stroke();
      }
    }
  } else if (r.style === 'wood_shingle') {
    // Träsindlade (rektangulära plattor)
    const tileW = 26;
    const tileH = 18;
    for (let yy = 0; yy < b.h; yy += tileH) {
      const xOff = (yy / tileH) % 2 === 0 ? 0 : tileW / 2;
      for (let xx = xOff; xx < b.w; xx += tileW) {
        ctx.strokeRect(sx + xx + 0.5, sy + yy + 0.5, tileW - 1, tileH - 1);
      }
    }
  } else if (r.style === 'thatch') {
    // Halmtak — vertikala streck
    for (let xx = 0; xx < b.w; xx += 6) {
      ctx.beginPath();
      ctx.moveTo(sx + xx, sy + 2); ctx.lineTo(sx + xx, sy + b.h - 2);
      ctx.stroke();
    }
    ctx.strokeStyle = r.accent;
    ctx.lineWidth = 2;
    for (let yy = 18; yy < b.h; yy += 22) {
      ctx.beginPath();
      ctx.moveTo(sx + 2, sy + yy); ctx.lineTo(sx + b.w - 2, sy + yy);
      ctx.stroke();
    }
  } else if (r.style === 'container') {
    // Container-tak: korrugerade ribbor + container-kod
    const isHoriz = b.w > b.h;
    ctx.strokeStyle = r.accent;
    ctx.lineWidth = 1;
    if (isHoriz) {
      for (let i = 12; i < b.w; i += 12) {
        ctx.beginPath();
        ctx.moveTo(sx + i, sy + 3); ctx.lineTo(sx + i, sy + b.h - 3);
        ctx.stroke();
      }
      // Top + bottom band
      ctx.fillStyle = r.accent;
      ctx.fillRect(sx, sy, b.w, 4);
      ctx.fillRect(sx, sy + b.h - 4, b.w, 4);
    } else {
      for (let i = 12; i < b.h; i += 12) {
        ctx.beginPath();
        ctx.moveTo(sx + 3, sy + i); ctx.lineTo(sx + b.w - 3, sy + i);
        ctx.stroke();
      }
      ctx.fillStyle = r.accent;
      ctx.fillRect(sx, sy, 4, b.h);
      ctx.fillRect(sx + b.w - 4, sy, 4, b.h);
    }
  }
  // Restore clip innan skorsten + yttre kant
  ctx.restore();
  // Skorsten BARA på riktiga stugor (inte containers) — får sticka upp ovanför taket
  if (r.style !== 'container') {
    const chimneyX = sx + b.w * 0.7;
    const chimneyY = sy + 6;
    ctx.fillStyle = '#3a3028';
    ctx.fillRect(chimneyX, chimneyY, 14, 18);
    ctx.fillStyle = '#1a1408';
    ctx.fillRect(chimneyX + 2, chimneyY, 10, 4);
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0e04';
  ctx.lineWidth = 2;
  ctx.strokeRect(sx + 1, sy + 1, b.w - 2, b.h - 2);
}

function drawCabinInteriorItem(item, cx, cy) {
  const x = item.x - cx, y = item.y - cy;
  const w = item.w || 0, h = item.h || 0, r = item.r || 0;
  switch (item.kind) {
    case 'bed': {
      // Mörk träram
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y, w, h);
      // Madrass (vit-grå)
      ctx.fillStyle = '#d4c8b0';
      ctx.fillRect(x + 2, y + 2, w - 4, h - 4);
      // Filt (random färg)
      ctx.fillStyle = '#5a8090';
      ctx.fillRect(x + 2, y + h * 0.4, w - 4, h * 0.55);
      // Kudde
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(x + 4, y + 4, w - 8, h * 0.2);
      ctx.strokeStyle = '#5a4830';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'table_round': {
      ctx.fillStyle = '#7a5028';
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#5a3818';
      ctx.beginPath();
      ctx.arc(x, y, r * 0.85, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#3a2008';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.stroke();
      // Föremål på bordet (mugg)
      ctx.fillStyle = '#aaaaaa';
      ctx.fillRect(x - 3, y - 2, 5, 5);
      break;
    }
    case 'table_long': {
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x + 2, y + 2, w - 4, h - 4);
      ctx.strokeStyle = '#3a2008';
      ctx.lineWidth = 1.2;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      // Föremål (tallrikar)
      ctx.fillStyle = '#ddd';
      ctx.beginPath();
      ctx.arc(x + 12, y + h / 2, 4, 0, Math.PI * 2);
      ctx.arc(x + w - 12, y + h / 2, 4, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'chair': {
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x - 6, y - 6, 12, 12);
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x - 5, y - 5, 10, 10);
      // Ryggstöd
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x - 6, y - 12, 12, 4);
      break;
    }
    case 'rug': {
      // Mönstrad matta
      ctx.fillStyle = '#7a2828';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#aa3030';
      ctx.fillRect(x + 4, y + 4, w - 8, h - 8);
      // Mönster (rombs)
      ctx.fillStyle = '#5a1010';
      for (let xx = 8; xx < w - 4; xx += 16) {
        for (let yy = 8; yy < h - 4; yy += 16) {
          ctx.beginPath();
          ctx.moveTo(x + xx, y + yy + 4);
          ctx.lineTo(x + xx + 4, y + yy);
          ctx.lineTo(x + xx + 8, y + yy + 4);
          ctx.lineTo(x + xx + 4, y + yy + 8);
          ctx.closePath();
          ctx.fill();
        }
      }
      // Fransar (kant-streck)
      ctx.strokeStyle = '#3a1808';
      ctx.lineWidth = 0.6;
      for (let xx = 2; xx < w; xx += 3) {
        ctx.beginPath();
        ctx.moveTo(x + xx, y); ctx.lineTo(x + xx, y - 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(x + xx, y + h); ctx.lineTo(x + xx, y + h + 2);
        ctx.stroke();
      }
      break;
    }
    case 'oil_lamp': {
      // Pinne + lampa
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x - 1, y, 2, 6);
      ctx.fillStyle = '#7a5828';
      ctx.fillRect(x - 4, y, 8, 3);
      // Lampskugga
      ctx.fillStyle = 'rgba(255, 200, 80, 0.4)';
      ctx.beginPath();
      ctx.arc(x, y - 2, 8, 0, Math.PI * 2);
      ctx.fill();
      // Låga
      const t = performance.now() / 1000;
      ctx.fillStyle = 'rgba(255, 220, 80, ' + (0.85 + Math.sin(t * 6) * 0.15) + ')';
      ctx.beginPath();
      ctx.ellipse(x, y - 2, 2, 3, 0, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'bookshelf': {
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y, w, h);
      // Bok-rygg (random färger)
      const colors = ['#aa3030', '#3a5a8a', '#5a8a3a', '#aa7030', '#8a3a7a'];
      const seed = ((item.x * 7) ^ (item.y * 13)) | 0;
      const rows = Math.floor(h / 8);
      for (let r = 0; r < rows; r++) {
        const ry = y + r * 8 + 1;
        for (let xx = 1; xx < w; xx += 3) {
          ctx.fillStyle = colors[((seed * (xx + r * 7)) & 0xff) % colors.length];
          ctx.fillRect(x + xx, ry, 2, 6);
        }
      }
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 0.8;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'fireplace': {
      // Stenformat
      ctx.fillStyle = '#3a3028';
      ctx.fillRect(x, y, w, h);
      // Stenmönster
      ctx.strokeStyle = '#1a1408';
      ctx.lineWidth = 0.8;
      for (let xx = 0; xx < w; xx += 10) {
        ctx.beginPath();
        ctx.moveTo(x + xx, y); ctx.lineTo(x + xx, y + h);
        ctx.stroke();
      }
      // Eld inuti (animerat)
      const t = performance.now() / 1000;
      const flicker = 0.7 + Math.sin(t * 8) * 0.3;
      ctx.fillStyle = '#1a0a04';
      ctx.fillRect(x + 4, y + 8, w - 8, h - 12);
      ctx.fillStyle = 'rgba(255, 100, 30, ' + (0.7 * flicker) + ')';
      ctx.fillRect(x + 6, y + 12, w - 12, h - 16);
      ctx.fillStyle = 'rgba(255, 220, 80, ' + (0.9 * flicker) + ')';
      ctx.fillRect(x + 8, y + 14, w - 16, h - 18);
      // Yttre kant
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1.2;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'kitchen_counter': {
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#9a7a48';
      ctx.fillRect(x, y, w, h * 0.3);
      // Diskbänk (silver-rektangel)
      ctx.fillStyle = '#aaaaaa';
      ctx.fillRect(x + w * 0.3, y + 2, w * 0.4, h - 4);
      ctx.strokeStyle = '#3a2008';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'dresser': {
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x, y, 40, 30);
      // 3 lådor
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y + 10); ctx.lineTo(x + 40, y + 10);
      ctx.moveTo(x, y + 20); ctx.lineTo(x + 40, y + 20);
      ctx.stroke();
      // Handtag
      ctx.fillStyle = '#9a7038';
      ctx.fillRect(x + 18, y + 4, 4, 1);
      ctx.fillRect(x + 18, y + 14, 4, 1);
      ctx.fillRect(x + 18, y + 24, 4, 1);
      ctx.strokeRect(x + 0.5, y + 0.5, 39, 29);
      break;
    }
    case 'wall_painting': {
      // Tavla (guldram + mörk bild)
      ctx.fillStyle = '#aa7030';
      ctx.fillRect(x, y, 28, 22);
      ctx.fillStyle = '#1a3050';
      ctx.fillRect(x + 2, y + 2, 24, 18);
      // Måleri (silhuett av träd)
      ctx.fillStyle = '#3a5a3a';
      ctx.fillRect(x + 4, y + 12, 4, 8);
      ctx.fillRect(x + 14, y + 10, 4, 10);
      ctx.beginPath();
      ctx.arc(x + 6, y + 11, 3, 0, Math.PI * 2);
      ctx.arc(x + 16, y + 9, 3, 0, Math.PI * 2);
      ctx.fill();
      break;
    }
    case 'animal_skull': {
      // Vit benstruktur
      ctx.fillStyle = '#e0d8c0';
      ctx.beginPath();
      ctx.ellipse(x, y, 6, 8, 0, 0, Math.PI * 2);
      ctx.fill();
      // Ögon (mörk)
      ctx.fillStyle = '#1a1408';
      ctx.beginPath();
      ctx.arc(x - 2, y - 1, 1.2, 0, Math.PI * 2);
      ctx.arc(x + 2, y - 1, 1.2, 0, Math.PI * 2);
      ctx.fill();
      // Hörn
      ctx.strokeStyle = '#9a8060';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x - 5, y - 6); ctx.lineTo(x - 8, y - 10);
      ctx.moveTo(x + 5, y - 6); ctx.lineTo(x + 8, y - 10);
      ctx.stroke();
      break;
    }
    case 'haystack_inside': {
      ctx.fillStyle = '#c09040';
      ctx.fillRect(x, y, w, h);
      ctx.strokeStyle = 'rgba(120, 80, 20, 0.7)';
      ctx.lineWidth = 0.8;
      for (let i = 0; i < 15; i++) {
        const sx = x + ((i * 13) % w);
        const sy = y + ((i * 17) % h);
        ctx.beginPath();
        ctx.moveTo(sx, sy); ctx.lineTo(sx + 6, sy - 4);
        ctx.stroke();
      }
      break;
    }
    case 'woodpile_inside': {
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y, w, h);
      for (let xx = 4; xx < w; xx += 8) {
        ctx.fillStyle = '#7a5028';
        ctx.beginPath();
        ctx.arc(x + xx, y + h / 2, 3.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#3a2010';
        ctx.beginPath();
        ctx.arc(x + xx, y + h / 2, 1, 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    }
    case 'workbench': {
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x, y, w, 4);
      // Verktyg
      ctx.fillStyle = '#666';
      ctx.fillRect(x + 4, y + 8, 12, 3);
      ctx.fillStyle = '#aaaaaa';
      ctx.fillRect(x + w - 18, y + 6, 14, 4);
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'rope_coil': {
      ctx.strokeStyle = '#7a5828';
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.arc(x, y, 3 + i, 0, Math.PI * 2);
        ctx.stroke();
      }
      break;
    }
    case 'pitchfork': {
      ctx.strokeStyle = '#3a2010';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x, y); ctx.lineTo(x, y - 20);
      ctx.stroke();
      ctx.strokeStyle = '#aaa';
      ctx.lineWidth = 1.5;
      for (let i = -3; i <= 3; i += 3) {
        ctx.beginPath();
        ctx.moveTo(x + i, y - 18); ctx.lineTo(x + i, y - 25);
        ctx.stroke();
      }
      break;
    }
    case 'shovel': {
      ctx.strokeStyle = '#3a2010';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x, y); ctx.lineTo(x, y - 22);
      ctx.stroke();
      ctx.fillStyle = '#999';
      ctx.beginPath();
      ctx.moveTo(x - 4, y - 18);
      ctx.lineTo(x + 4, y - 18);
      ctx.lineTo(x + 2, y - 26);
      ctx.lineTo(x - 2, y - 26);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'desk': {
      ctx.fillStyle = '#5a3818';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x, y, w, 4);
      // Papper på bordet
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(x + 6, y + 6, 18, 14);
      ctx.fillStyle = '#000';
      ctx.fillRect(x + 8, y + 8, 14, 1);
      ctx.fillRect(x + 8, y + 11, 12, 1);
      ctx.fillRect(x + 8, y + 14, 14, 1);
      // Penna
      ctx.fillStyle = '#ffd040';
      ctx.fillRect(x + 30, y + 8, 1.5, 8);
      ctx.strokeStyle = '#1a0e04';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'map_on_wall': {
      ctx.fillStyle = '#d4c8a0';
      ctx.fillRect(x, y, 30, 22);
      ctx.strokeStyle = '#5a3818';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, 29, 21);
      // Kartlinjer (squiggly)
      ctx.strokeStyle = '#5a3818';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      ctx.moveTo(x + 4, y + 6);
      ctx.bezierCurveTo(x + 10, y + 4, x + 18, y + 12, x + 26, y + 8);
      ctx.moveTo(x + 5, y + 14);
      ctx.bezierCurveTo(x + 12, y + 18, x + 22, y + 14, x + 27, y + 18);
      ctx.stroke();
      // Röd X
      ctx.strokeStyle = '#cc2020';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x + 14, y + 10); ctx.lineTo(x + 18, y + 14);
      ctx.moveTo(x + 18, y + 10); ctx.lineTo(x + 14, y + 14);
      ctx.stroke();
      break;
    }
    case 'bathtub': {
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#c0e8f8';
      ctx.fillRect(x + 3, y + 3, w - 6, h - 6);
      ctx.strokeStyle = '#5a7088';
      ctx.lineWidth = 1.2;
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
      break;
    }
    case 'rifle_rack': {
      ctx.fillStyle = '#3a2010';
      ctx.fillRect(x, y, 40, 5);
      // 3 gevär
      ctx.fillStyle = '#5a3818';
      for (let i = 0; i < 3; i++) {
        ctx.fillRect(x + 4 + i * 12, y - 12, 1.5, 14);
        ctx.fillRect(x + 3 + i * 12, y - 14, 3, 3);
      }
      break;
    }
    default: {
      // Fallback: liten brun ruta
      ctx.fillStyle = '#7a5028';
      ctx.fillRect(x - 5, y - 5, 10, 10);
    }
  }
}

function drawSiegeBases() {
  if (!state.siegeBases) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeBases)) {
    const b = state.siegeBases[id];
    const x = b.x - cx, y = b.y - cy;
    if (x < -200 || x > viewW + 200 || y < -200 || y > viewH + 200) continue;
    let baseColor, baseRgb;
    if (b.owner === 'red') { baseColor = 'rgba(255,60,60,'; baseRgb = '255,60,60'; }
    else if (b.owner === 'blue') { baseColor = 'rgba(60,140,255,'; baseRgb = '60,140,255'; }
    else { baseColor = 'rgba(200,200,200,'; baseRgb = '200,200,200'; }  // ljus-grå för neutral
    const pulse = 0.7 + Math.sin(t / 500) * 0.3;
    ctx.save();
    // STARK inner-fyllning (mycket synligare än tidigare 0.15 alpha)
    const grad = ctx.createRadialGradient(x, y, 4, x, y, b.r);
    grad.addColorStop(0, baseColor + (0.55 * pulse) + ')');
    grad.addColorStop(0.7, baseColor + (0.25 * pulse) + ')');
    grad.addColorStop(1, baseColor + '0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(x, y, b.r, 0, Math.PI * 2); ctx.fill();
    // Tjock yttre dashed ring + GLOW
    ctx.strokeStyle = baseColor + (0.95 * pulse) + ')';
    ctx.lineWidth = 5;
    ctx.shadowColor = 'rgb(' + baseRgb + ')';
    ctx.shadowBlur = 14 * pulse;
    ctx.setLineDash([14, 8]);
    ctx.beginPath(); ctx.arc(x, y, b.r, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);
    ctx.shadowBlur = 0;
    // Capture-progress-ring med fas-färg
    if (b.captureProgress > 0 && b.captureSide) {
      // 'neutralize'-fas = gul-orange (rensar enemy-bas), 'capture'-fas = lag-färg
      let ringColor;
      if (b.phase === 'neutralize') ringColor = '#ffaa30';
      else ringColor = b.captureSide === 'red' ? '#ff5a5a' : '#5aaaff';
      ctx.strokeStyle = ringColor;
      ctx.lineWidth = 5;
      ctx.shadowColor = ringColor; ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(x, y, b.r + 8, -Math.PI / 2, -Math.PI / 2 + b.captureProgress * Math.PI * 2);
      ctx.stroke();
      ctx.shadowBlur = 0;
      // Procent + fas-label
      ctx.fillStyle = ringColor;
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
      const label = b.phase === 'neutralize'
        ? 'NEUTRAL ' + Math.round(b.captureProgress * 100) + '%'
        : 'CAPTURE ' + Math.round(b.captureProgress * 100) + '%';
      ctx.fillText(label, x, y - b.r - 20);
      ctx.shadowBlur = 0;
    }
    // Contested-badge: visa "R vs B"-count om båda lagen står på basen
    const redOn = b.redOn || 0;
    const blueOn = b.blueOn || 0;
    if (redOn > 0 && blueOn > 0) {
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
      ctx.fillText('⏸ ' + redOn + ' vs ' + blueOn + ' — CONTESTED', x, y - b.r - 6);
      ctx.shadowBlur = 0;
    } else if (redOn > 0 || blueOn > 0) {
      // Visa antal capturers när en sida har basen
      const c = redOn || blueOn;
      const color = redOn ? '#ff8080' : '#80aaff';
      ctx.fillStyle = color;
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
      ctx.fillText('×' + c, x, y - b.r - 6);
      ctx.shadowBlur = 0;
    }
    // Centrum-emblem (⬢)
    ctx.fillStyle = b.owner === 'red' ? '#ff8080' : (b.owner === 'blue' ? '#80aaff' : '#999');
    ctx.font = 'bold 22px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    ctx.fillText('⬢', x, y);
    ctx.shadowBlur = 0;
    ctx.restore();
  }
}

// SIEGE: cores — stor blinkande HP-bar + symbol över core-byggnaden
function drawSiegeCores() {
  if (!state.siegeCores) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeCores)) {
    const c = state.siegeCores[id];
    const x = c.x - cx, y = c.y - cy;
    if (x + c.w < -100 || x > viewW + 100 || y + c.h < -100 || y > viewH + 100) continue;
    ctx.save();
    if (c.destroyed) {
      // Förstörd: röd skugga + flickering eld
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(x + 30, y + 30, c.w - 60, c.h - 60);
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.7})`;
      ctx.fillRect(x + c.w * 0.3, y + c.h * 0.3, c.w * 0.4, c.h * 0.4);
      if (state.particles && state.particles.length < 200 && Math.random() < 0.4) {
        state.particles.push({
          x: c.x + c.w / 2 + (Math.random() - 0.5) * c.w,
          y: c.y + c.h / 2 + (Math.random() - 0.5) * c.h,
          vx: (Math.random() - 0.5) * 30,
          vy: -50 - Math.random() * 40,
          life: 1.5 + Math.random(),
          color: 'rgba(80,80,80,0.5)',
          r: 10 + Math.random() * 5,
          isExplosion: true,
        });
      }
    } else {
      // Aktiv core: pulsande inner-light + emblem
      const pulse = 0.6 + Math.sin(t / 400) * 0.3;
      const teamColor = c.team === 'red' ? 'rgba(255,90,90,' : 'rgba(90,170,255,';
      ctx.fillStyle = teamColor + (0.25 * pulse) + ')';
      ctx.fillRect(x + 30, y + 30, c.w - 60, c.h - 60);
      // Stor team-emblem
      ctx.fillStyle = c.team === 'red' ? '#ff8080' : '#88aaff';
      ctx.font = 'bold 60px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 8;
      ctx.fillText('🛡', x + c.w / 2, y + c.h / 2);
      ctx.shadowBlur = 0;
      // HP-bar ovanför core
      const bw = c.w - 40;
      const hpFrac = Math.max(0, c.hp / c.maxHp);
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(x + 20 - 2, y - 22, bw + 4, 12);
      ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
      ctx.fillRect(x + 20, y - 20, bw * hpFrac, 8);
      // HP-text
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 9px sans-serif';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 2;
      ctx.fillText(Math.round(c.hp) + ' / ' + c.maxHp, x + c.w / 2, y - 16);
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  }
}

// SIEGE: turrets — reuse CTF turret-rendering pattern men för siege state
function drawSiegeTurrets() {
  if (!state.siegeTurrets) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeTurrets)) {
    const tur = state.siegeTurrets[id];
    const x = tur.x - cx, y = tur.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    const teamColor = tur.team === 'red' ? '#ff5a5a' : '#5aaaff';
    if (tur.destroyed) {
      ctx.fillStyle = '#222';
      ctx.beginPath(); ctx.arc(x, y, 24, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#444'; ctx.lineWidth = 2; ctx.stroke();
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.6})`;
      ctx.beginPath(); ctx.arc(x, y, 8 + Math.random() * 4, 0, Math.PI * 2); ctx.fill();
      // Rebuild-progress-ring
      const p = tur.rebuildProgress || 0;
      if (p > 0) {
        ctx.lineWidth = 4;
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.beginPath(); ctx.arc(x, y, 32, 0, Math.PI * 2); ctx.stroke();
        ctx.strokeStyle = '#5aff5a';
        ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(x, y, 32, -Math.PI / 2, -Math.PI / 2 + p * Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        const sLeft = Math.ceil((1 - p) * 20);
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(sLeft + 's', x, y - 40);
      }
    } else {
      ctx.fillStyle = '#333';
      ctx.beginPath(); ctx.arc(x, y, tur.r, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = teamColor; ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = '#555';
      ctx.beginPath(); ctx.arc(x, y, tur.r * 0.65, 0, Math.PI * 2); ctx.fill();
      // Pipa
      ctx.strokeStyle = '#222'; ctx.lineWidth = 8; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (tur.team === 'red' ? 1 : -1) * (tur.r + 10), y);
      ctx.stroke();
      ctx.lineCap = 'butt';
      if (tur.occupantId) {
        const pulse = 0.6 + Math.sin(t / 200) * 0.4;
        ctx.fillStyle = `rgba(255,213,74,${pulse})`;
        ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
      }
      if (tur.hp < tur.maxHp) {
        const bw = 50;
        const hpFrac = Math.max(0, tur.hp / tur.maxHp);
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(x - bw / 2 - 1, y - tur.r - 16, bw + 2, 7);
        ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
        ctx.fillRect(x - bw / 2, y - tur.r - 15, bw * hpFrac, 5);
      }
    }
    ctx.restore();
  }
}

function drawCoopPartner() {
  if (!Coop.active || Coop.inLobby) return;
  const now = performance.now();
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    const x = p.x - state.camera.x;
    const y = p.y - state.camera.y;
    // Detect movement för walk-animation
    if (p._prevX === undefined) { p._prevX = p.x; p._prevY = p.y; p._walkPhase = 0; }
    const moved = Math.hypot(p.x - p._prevX, p.y - p._prevY);
    p._walkPhase = (p._walkPhase || 0) + (moved > 0.5 ? 0.22 : 0.04);
    p._prevX = p.x; p._prevY = p.y;

    // JUGGERNAUT: detektera om partnern är JUG via BÅDE p.isJug-flag OCH
    // state.juggernautPid (defensiv fallback om flagga inte hunnit synkas).
    const partnerIsJugFromPid = state.juggernautActive && state.juggernautPid && state.juggernautPid === pid;
    const partnerIsJug = !!(p.isJug || partnerIsJugFromPid) && state.juggernautActive;
    if (partnerIsJug && !p.isJug) {
      // Lazy-set så efterföljande logik (HP-bar, scale, glow) funkar
      p.isJug = true;
      p.scaleMul = (Coop.juggernautScale || 1.4);
      p.maxHp = Coop.juggernautHpMax || 500;
    }
    // Off-screen check (rita pil mot dem istället).
    // Regel: man ska BARA se pil till TEAMMATES, inte till motståndare.
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) {
      // Hunters ska INTE se pil mot JUG (bara minimap-puls var 5s).
      const skipJugArrow = partnerIsJug && state.player && !state.player.isJug;
      // BR: FFA — ingen pil mot någon motståndare.
      const skipBrArrow = state.battleroyaleActive;
      // Gungame + KOTH: FFA — ingen pil mot någon motståndare.
      const skipFfaArrow = state.gungameActive || state.kothActive;
      // CTF/TDM/Siege: TEAM-MODES — pil bara mot SAMMA team
      let isEnemyTeam = false;
      if (state.ctfActive && Coop.ctfTeams) {
        const myT = Coop.ctfTeams[Coop.myId];
        const theirT = Coop.ctfTeams[pid];
        if (myT && theirT && myT !== theirT) isEnemyTeam = true;
      } else if (state.tdmActive && Coop.tdmTeams) {
        const myT = Coop.tdmTeams[Coop.myId];
        const theirT = Coop.tdmTeams[pid];
        if (myT && theirT && myT !== theirT) isEnemyTeam = true;
      } else if (state.siegeActive && Coop.siegeTeams) {
        const myT = Coop.siegeTeams[Coop.myId];
        const theirT = Coop.siegeTeams[pid];
        if (myT && theirT && myT !== theirT) isEnemyTeam = true;
      }
      if (!skipJugArrow && !skipBrArrow && !skipFfaArrow && !isEnemyTeam) {
        drawOffscreenPartner(p, x, y);
      }
      continue;
    }
    const color = PLAYER_COLORS[p.colorIdx % PLAYER_COLORS.length];
    const isDead = p.hp !== undefined && p.hp <= 0;

    // Om död — rita liggande kropp + revive-indikator
    if (isDead) {
      ctx.save();
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 4, y + 8, 22, 8, 0, 0, Math.PI*2); ctx.fill();
      // Liggande kropp (oval)
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.ellipse(x, y, 18, 11, 0.3, 0, Math.PI*2); ctx.fill();
      // Blod
      ctx.fillStyle = 'rgba(120,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x - 2, y + 3, 14, 6, 0.3, 0, Math.PI*2); ctx.fill();
      // Revive-indikator (synkat med dead player's reviveTimer)
      if (p.reviveTimer && p.reviveTimer > 0) {
        const frac = Math.min(1, p.reviveTimer / 5);
        ctx.strokeStyle = '#5aff5a';
        ctx.lineWidth = 3;
        ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(x, y, 28, -Math.PI/2, -Math.PI/2 + frac * Math.PI*2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(Math.ceil(5 - p.reviveTimer) + 's', x, y - 36);
      } else {
        ctx.fillStyle = '#ff5a5a';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
        ctx.fillText('💀 ' + p.name, x, y - 16);
        ctx.shadowBlur = 0;
      }
      ctx.restore();
      continue;
    }

    // Levande — rita karaktär likt drawPlayer (förenklad)
    const r = 14;
    const phase = p._walkPhase;
    const moving = moved > 0.5;
    const bob = moving ? Math.abs(Math.sin(phase)) * 1.6 : Math.sin(phase) * 0.4;

    // Skugga (mjuk oval)
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.beginPath(); ctx.ellipse(x + 2, y + r * 1.1, r * 1.3, r * 0.45, 0, 0, Math.PI*2); ctx.fill();

    // Färg-aura under
    ctx.fillStyle = color + '22';
    ctx.beginPath(); ctx.arc(x, y, r * 1.6, 0, Math.PI*2); ctx.fill();

    ctx.save();
    ctx.translate(x, y + bob);
    // v1.441: Sprite ritas UTAN rotation (alltid upprätt). Bara vapnet roterar.
    const _partnerIsJug = partnerIsJug;
    const _partnerJugScale = (_partnerIsJug && (p.scaleMul || Coop.juggernautScale)) ? (p.scaleMul || Coop.juggernautScale || 1.4) : 1;
    if (_partnerJugScale !== 1) ctx.scale(_partnerJugScale, _partnerJugScale);

    // v1.437/v1.441: PIXEL-ART partner-rendering med mirror + tilt
    ctx.imageSmoothingEnabled = false;
    // v1.480: Bygg partnerCos från p.wardrobe om tillgängligt så partner får
    // shoes/hair/hat/glasses/bandana/shirt/pants/facialHair/eyes/scars-overlays.
    let partnerCos;
    if (!_partnerIsJug && p.wardrobe) {
      const pw = p.wardrobe;
      const _po = (cat, id) => (WARDROBE[cat] && WARDROBE[cat].find(o => o.id === id)) || (WARDROBE[cat] && WARDROBE[cat][0]);
      const _skinO = _po('skin', pw.skin);
      const _hairO = _po('hair', pw.hair);
      const _shirtO = _po('shirt', pw.shirt);
      const _pantsO = _po('pants', pw.pants);
      const _bandanaO = _po('bandana', pw.bandana);
      const _glassesO = pw.glasses ? _po('glasses', pw.glasses) : null;
      const _hatO = pw.hat ? _po('hat', pw.hat) : null;
      const _shoesO = pw.shoes ? _po('shoes', pw.shoes) : null;
      const _facialO = pw.facialHair ? _po('facialHair', pw.facialHair) : null;
      const _eyesO = pw.eyes ? _po('eyes', pw.eyes) : null;
      const _scarsO = pw.scars ? _po('scars', pw.scars) : null;
      partnerCos = {
        skin: (_skinO && _skinO.color) || '#d4a574',
        shirt: _shirtO ? _shirtO.color : color,
        bandana: _bandanaO ? _bandanaO.color : color,
        accent: '#ffd54a',
        pants: _pantsO ? _pantsO.color : '#3a3528',
        hairStyle: _hairO ? _hairO.style : 'bald',
        hairColor: _hairO ? _hairO.color : '#1a0a08',
        glasses: _glassesO,
        hat: _hatO,
        shoes: _shoesO,
        facialHair: _facialO,
        eyes: _eyesO,
        scars: _scarsO,
        shirtBrand: (_shirtO && _shirtO.brand) || null, // v1.489: brand-logo support
        mascot: (_shirtO && _shirtO.mascot) || null,    // v1.489: mascot dispatch
      };
    } else {
      partnerCos = {
        skin: _partnerIsJug ? '#4a7a3a' : '#d4a574',
        shirt: _partnerIsJug ? '#1a1a14' : color,
        bandana: color,
        accent: '#ffd54a',
        pants: _partnerIsJug ? '#2a1a0a' : '#3a3528',
        hairColor: '#1a0a08',
      };
    }
    // Pick walk-frame for partner (use partner phase)
    const partnerAimAngle = p.aimAngle || 0;
    const pAimX = Math.cos(partnerAimAngle);
    const pAimY = Math.sin(partnerAimAngle);
    const pFacingLeft = pAimX < -0.05;
    const partnerMoving = moved > 0.5;
    let partnerFrame = PLAYER_SPRITE_IDLE;
    if (partnerMoving) {
      const wc = Math.floor(phase / Math.PI) % 2;
      partnerFrame = wc === 0 ? PLAYER_SPRITE_WALK_A : PLAYER_SPRITE_WALK_B;
    }
    // v1.464: Partner body följer AIM-direction (samma som player)
    const _pAimXVal = Math.cos(partnerAimAngle);
    if (Math.abs(_pAimXVal) > 0.15) {
      p._bodyFacingLeft = _pAimXVal < 0;
    }
    if (p._bodyFacingLeft === undefined) {
      p._bodyFacingLeft = pFacingLeft;
    }
    const _pBodyFacingLeft = p._bodyFacingLeft;
    // v1.480: Partner CAPE (om equippad) bakom allt annat
    if (p.wardrobe && p.wardrobe.cape && p.wardrobe.cape !== 'none') {
      const _pCapeOpt = WARDROBE.cape && WARDROBE.cape.find(o => o.id === p.wardrobe.cape);
      if (_pCapeOpt && _pCapeOpt.style !== 'none') {
        ctx.save();
        if (_pBodyFacingLeft) ctx.scale(-1, 1);
        drawCapeOnUprightBody(ctx, _pCapeOpt.style, _pCapeOpt.color, false, performance.now(), partnerMoving);
        ctx.restore();
      }
    }
    // v1.518: Skip arms ENDAST för mascots med egna armar (mcdonalds, cashew, etc).
    // Övriga mascots ska ha synliga armar (en hängande + en skjutande).
    const PARTNER_MASCOTS_WITH_OWN_ARMS = new Set(['mcdonalds', 'cashew', 'genie', 'gnome', 'bear', 'tiger']);
    const _pSkipArms = !!partnerCos.mascot && PARTNER_MASCOTS_WITH_OWN_ARMS.has(partnerCos.mascot);
    const _pScaledMascot = !!partnerCos.mascot && partnerCos.mascot !== 'mcdonalds' && !_pSkipArms;
    // v1.468: Partner — hanging arm + arm shaft BEHIND body, hand AFTER body
    if (!_pSkipArms) {
      if (_pScaledMascot) { ctx.save(); ctx.translate(0, 6); ctx.scale(1.4, 1.4); }
      drawHangingArm(ctx, partnerCos, false, _pBodyFacingLeft);
      if (_pScaledMascot) { ctx.restore(); }
    }
    // Partner shooting arm SHAFT (behind body) — v1.484 med sleeve
    if (!_pSkipArms) {
      const _pShoulderXShaft = _pBodyFacingLeft ? -3 : 3;
      ctx.save();
      if (_pScaledMascot) { ctx.translate(0, 6); ctx.scale(1.4, 1.4); }
      ctx.translate(_pShoulderXShaft, -3);
      ctx.rotate(partnerAimAngle);
      if (pFacingLeft) ctx.scale(1, -1);
      // v1.519: Mascot-style override.
      const _pmStyle = partnerCos.mascot && MASCOT_ARM_STYLES[partnerCos.mascot];
      const _paBase = _pmStyle ? _pmStyle.base : (partnerCos.skin || '#c08860');
      const _paLight = _pmStyle ? _pmStyle.light : lighten(_paBase, 0.22);
      const _paShadow = _pmStyle ? _pmStyle.dark : darken(_paBase, 0.30);
      const _paDeep = _pmStyle ? darken(_pmStyle.dark, 0.35) : darken(_paBase, 0.55);
      const _paOutline = _pmStyle ? _pmStyle.outline : '#0a0a0e';
      const _pSleeveSrc = _pmStyle ? _pmStyle.sleeve : partnerCos.shirt;
      const _pHasShirt = _pSleeveSrc != null;
      const _pSleeveLen = 8;
      if (_pHasShirt) {
        const _psCol = _pSleeveSrc;
        const _psLight = lighten(_pSleeveSrc, 0.20);
        const _psShadow = darken(_pSleeveSrc, 0.35);
        const _psDark = darken(_pSleeveSrc, 0.55);
        ctx.fillStyle = _psShadow;
        ctx.fillRect(0, -3, _pSleeveLen, 6);
        ctx.fillStyle = _psCol;
        ctx.fillRect(0, -3, _pSleeveLen, 5);
        ctx.fillStyle = _psLight;
        ctx.fillRect(0, -3, _pSleeveLen, 2);
        ctx.fillStyle = _psDark;
        ctx.fillRect(_pSleeveLen - 0.6, -3, 0.6, 6);
        // Forearm skin
        ctx.fillStyle = _paShadow;
        ctx.fillRect(_pSleeveLen, -3, 13 - _pSleeveLen, 6);
        ctx.fillStyle = _paBase;
        ctx.fillRect(_pSleeveLen, -3, 13 - _pSleeveLen, 5);
        ctx.fillStyle = _paLight;
        ctx.fillRect(_pSleeveLen, -3, 13 - _pSleeveLen, 2);
      } else {
        ctx.fillStyle = _paShadow;
        ctx.fillRect(0, -3, 13, 6);
        ctx.fillStyle = _paBase;
        ctx.fillRect(0, -3, 13, 5);
        ctx.fillStyle = _paLight;
        ctx.fillRect(0, -3, 13, 2);
        ctx.fillStyle = _paDeep;
        ctx.fillRect(7, 1, 6, 1);
      }
      ctx.strokeStyle = _paOutline;
      ctx.lineWidth = 1;
      ctx.strokeRect(0, -3, 13, 6);
      ctx.restore();
    }
    // Partner body (covers arm where they overlap)
    ctx.save();
    if (_pBodyFacingLeft) ctx.scale(-1, 1);
    drawNakedBody(ctx, partnerCos, false, p._walkPhase || 0, partnerMoving);
    ctx.restore();
    // v1.468: Partner HAND (after body, proper hand)
    ctx.save();
    if (_pScaledMascot) { ctx.translate(0, 6); ctx.scale(1.4, 1.4); }
    const _pShoulderX = _pBodyFacingLeft ? -3 : 3;
    ctx.translate(_pShoulderX, -3);
    ctx.rotate(partnerAimAngle);
    if (pFacingLeft) ctx.scale(1, -1);
    ctx.translate(_pSkipArms ? 5 : 13, 0);
    drawHand(ctx, partnerCos, false);
    ctx.restore();
    // v1.520: Wrap weapon-transform i save/restore så ackumulerad scale inte
    // läcker till framtida draw-calls (latent risk noterat i coop-review).
    ctx.save();
    if (_pScaledMascot) { ctx.translate(0, 6); ctx.scale(1.4, 1.4); }
    ctx.rotate(partnerAimAngle);
    if (pFacingLeft) ctx.scale(1, -1);
    /* === GAMMAL CANVAS-PRIMITIVE PARTNER-BODY (v1.436) — DEAD CODE ===
    const skin = _partnerIsJug ? '#4a7a3a' : '#d4a574';
    const skinDark = _partnerIsJug ? '#2e5a26' : '#a07a52';
    const skinHighlight = _partnerIsJug ? '#6a9a5a' : '#e8c094';
    const vest = _partnerIsJug ? '#1a1a14' : color;
    const pants = _partnerIsJug ? '#2a1a0a' : '#3a3528';
    const lightWorldAng = -Math.PI * 0.75;
    const lightLocalAng = lightWorldAng - (p.aimAngle || 0);
    const lightLX = Math.cos(lightLocalAng);
    const lightLY = Math.sin(lightLocalAng);
    const OUTLINE_COLOR = '#0a0a0f';
    const W_THIN = 1.4, W_MED = 2.2, W_BOLD = 2.8;
    const fillStroke = (fc, lw, oc) => {
      ctx.fillStyle = fc;
      ctx.fill();
      ctx.strokeStyle = oc || OUTLINE_COLOR;
      ctx.lineWidth = lw || W_MED;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.stroke();
    };

    // ========== LEG-PARAMETERS ==========
    const legSwing = Math.sin(phase);
    const legLift = moved > 0.5 ? Math.max(0, Math.sin(phase)) * 1.4 : 0;
    const lLegX = -r * 0.30 - legSwing * r * 0.10;
    const rLegX = -r * 0.30 + legSwing * r * 0.10;
    const lLegY = -r * 0.55;
    const rLegY =  r * 0.55;

    // BÅDA BEN
    for (const [lx, ly] of [[lLegX, lLegY], [rLegX, rLegY]]) {
      drawRoundedRect(ctx, lx, ly - r * 0.20, r * 0.55, r * 0.40, r * 0.10);
      fillStroke(pants, W_BOLD);
      drawRoundedRect(ctx, lx + r * 0.10, ly - r * 0.10, r * 0.32, r * 0.20, r * 0.06);
      fillStroke(darken(pants, 0.7), W_THIN);
      drawRoundedRect(ctx, lx + r * 0.10, ly - r * 0.24, r * 0.36, r * 0.16, r * 0.08);
      fillStroke('#1a1a14', W_MED);
    }
    // BOOTS
    const lFootX = lLegX + r * 0.42;
    const rFootX = rLegX + r * 0.42;
    for (const [fx, fy] of [[lFootX, lLegY], [rFootX, rLegY]]) {
      drawRoundedRect(ctx, fx, fy - r * 0.20, r * 0.50, r * 0.40, r * 0.14);
      fillStroke('#0a0805', W_BOLD);
      drawRoundedRect(ctx, fx + r * 0.30, fy - r * 0.18, r * 0.20, r * 0.36, r * 0.10);
      fillStroke('#1a0e08', W_THIN);
    }

    // BÄLTE
    drawRoundedRect(ctx, -r * 0.55, -r * 0.65, r * 1.10, r * 0.20, r * 0.05);
    fillStroke('#1a0e06', W_MED);
    drawRoundedRect(ctx, -r * 0.55,  r * 0.45, r * 1.10, r * 0.20, r * 0.05);
    fillStroke('#1a0e06', W_MED);

    // TORSO V-FORMAD
    ctx.beginPath();
    ctx.moveTo(-r * 0.55, -r * 1.20);
    ctx.lineTo( r * 0.45, -r * 1.10);
    ctx.quadraticCurveTo(r * 0.55, -r * 0.70, r * 0.45, -r * 0.50);
    ctx.lineTo( r * 0.35,  r * 0.50);
    ctx.quadraticCurveTo(r * 0.55, r * 0.70, r * 0.45, r * 1.10);
    ctx.lineTo(-r * 0.55,  r * 1.20);
    ctx.quadraticCurveTo(-r * 0.90, 0, -r * 0.55, -r * 1.20);
    ctx.closePath();
    fillStroke(vest, W_BOLD);
    // Chest plate
    drawRoundedRect(ctx, -r * 0.30, -r * 0.40, r * 0.65, r * 0.80, r * 0.10);
    fillStroke(darken(vest, 0.75), W_MED);
    // Pouches
    for (let i = 0; i < 3; i++) {
      const py = -r * 0.30 + i * r * 0.22;
      drawRoundedRect(ctx, -r * 0.18, py, r * 0.30, r * 0.15, r * 0.04);
      fillStroke('#0a0805', W_THIN);
    }

    // SHOULDERS
    for (const [sx, sy] of [[-r * 0.05, -r * 1.10], [-r * 0.05, r * 1.10]]) {
      ctx.beginPath();
      ctx.arc(sx, sy, r * 0.40, 0, Math.PI * 2);
      fillStroke(darken(vest, 0.6), W_BOLD);
    }

    // ARMS (sleeves + underarms)
    drawRoundedRect(ctx, r * 0.10, -r * 1.30, r * 0.34, r * 0.40, r * 0.10);
    fillStroke(darken(vest, 0.75), W_MED);
    drawRoundedRect(ctx, r * 0.10,  r * 0.90, r * 0.34, r * 0.40, r * 0.10);
    fillStroke(darken(vest, 0.75), W_MED);
    drawRoundedRect(ctx, r * 0.42, -r * 0.95, r * 0.50, r * 0.30, r * 0.14);
    fillStroke(skin, W_MED);
    drawRoundedRect(ctx, r * 0.42,  r * 0.65, r * 0.50, r * 0.30, r * 0.14);
    fillStroke(skin, W_MED);

    // HANDS
    ctx.beginPath();
    ctx.ellipse(r * 1.00, -r * 0.50, r * 0.18, r * 0.15, 0.1, 0, Math.PI * 2);
    fillStroke(skin, W_MED);
    ctx.beginPath();
    ctx.ellipse(r * 0.85, r * 0.35, r * 0.16, r * 0.13, -0.1, 0, Math.PI * 2);
    fillStroke(skin, W_MED);

    // NECK
    drawRoundedRect(ctx, r * 0.18, -r * 0.28, r * 0.45, r * 0.56, r * 0.10);
    fillStroke(darken(skin, 0.55), W_MED);

    // HEAD (stort + outlined)
    const headR = r * 0.95;
    const headX = r * 0.75;
    ctx.beginPath();
    ctx.ellipse(headX, 0, headR, headR * 0.92, 0, 0, Math.PI * 2);
    fillStroke(skin, W_BOLD);
    // Head shadow
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(headX + lightLX * headR * 0.30, lightLY * headR * 0.30, headR * 0.70, headR * 0.65, 0, 0, Math.PI * 2);
    ctx.fillStyle = skinDark;
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.restore();
    // Head highlight
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(headX - lightLX * headR * 0.35, -lightLY * headR * 0.30, headR * 0.45, headR * 0.30, 0, 0, Math.PI * 2);
    ctx.fillStyle = skinHighlight;
    ctx.globalAlpha = 0.45;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.restore();
    // EARS
    for (const eySign of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(headX - headR * 0.30, eySign * headR * 0.85, r * 0.14, r * 0.20, 0, 0, Math.PI * 2);
      fillStroke(skin, W_THIN);
    }

    // BANDANA i partnerns färg (outlined)
    ctx.beginPath();
    ctx.ellipse(headX - headR * 0.15, 0, headR * 1.10, headR * 0.85, 0, -Math.PI * 0.50, Math.PI * 0.50);
    ctx.lineTo(headX - headR * 1.05, -headR * 0.50);
    ctx.quadraticCurveTo(headX - headR * 1.30, 0, headX - headR * 1.05, headR * 0.50);
    ctx.closePath();
    fillStroke(color, W_BOLD);
    // Accent-stripe
    drawRoundedRect(ctx, headX - headR * 0.20, -headR * 0.95, r * 0.18, headR * 1.90, r * 0.05);
    fillStroke(lighten(color, 0.30), W_THIN);
    // Bandana-knot
    ctx.beginPath();
    ctx.arc(headX - headR * 1.05, 0, r * 0.18, 0, Math.PI * 2);
    fillStroke(color, W_MED);
    // Bandana-tail
    const tailWaveP = Math.sin(now / 180) * r * 0.20;
    ctx.beginPath();
    ctx.moveTo(headX - headR * 1.00, -r * 0.18);
    ctx.lineTo(headX - r * 2.20, -r * 0.55 + tailWaveP);
    ctx.quadraticCurveTo(headX - r * 2.40, tailWaveP, headX - r * 2.25,  r * 0.60 + tailWaveP);
    ctx.lineTo(headX - headR * 1.00,  r * 0.18);
    ctx.closePath();
    fillStroke(color, W_MED);

    // FACE (eyes, brows, nose, mouth)
    const faceX = headX + headR * 0.40;
    // Eyebrows
    for (const ebSign of [-1, 1]) {
      ctx.save();
      ctx.translate(faceX - r * 0.05, ebSign * r * 0.30);
      ctx.rotate(ebSign * 0.35);
      ctx.beginPath();
      ctx.moveTo(-r * 0.10, 0);
      ctx.quadraticCurveTo(0, -r * 0.04, r * 0.14, -r * 0.02);
      ctx.lineTo(r * 0.14, r * 0.04);
      ctx.quadraticCurveTo(0, r * 0.02, -r * 0.10, r * 0.06);
      ctx.closePath();
      fillStroke('#0a0404', W_THIN);
      ctx.restore();
    }
    // Eyes (outlined)
    for (const eySign of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(faceX - r * 0.05, eySign * r * 0.22, r * 0.18, r * 0.14, 0, 0, Math.PI * 2);
      fillStroke('#fafafa', W_MED);
      ctx.beginPath();
      ctx.arc(faceX + r * 0.02, eySign * r * 0.22, r * 0.10, 0, Math.PI * 2);
      fillStroke('#4a6a8a', W_THIN);
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(faceX + r * 0.04, eySign * r * 0.22, r * 0.05, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(faceX + r * 0.06, eySign * r * 0.20, r * 0.025, 0, Math.PI * 2); ctx.fill();
    }
    // Nose
    ctx.beginPath();
    ctx.moveTo(faceX + r * 0.35, 0);
    ctx.lineTo(faceX + r * 0.10, -r * 0.07);
    ctx.lineTo(faceX + r * 0.10,  r * 0.07);
    ctx.closePath();
    fillStroke(skinDark, W_THIN);
    // Mouth
    ctx.beginPath();
    ctx.moveTo(faceX - r * 0.02, -r * 0.05);
    ctx.quadraticCurveTo(faceX + r * 0.05, r * 0.02, faceX + r * 0.15, -r * 0.03);
    ctx.lineTo(faceX + r * 0.15, r * 0.03);
    ctx.quadraticCurveTo(faceX + r * 0.05, r * 0.10, faceX - r * 0.02, r * 0.03);
    ctx.closePath();
    fillStroke('#3a1a0a', W_THIN);
    === SLUT GAMMAL CANVAS-PRIMITIVE PARTNER-BODY === */

    // VAPEN — enkelt, baserat på weaponId (overlay ovanpå sprite)
    const w = p.weaponId ? W_BY_ID[p.weaponId] : null;
    const wColor = w && w.color ? w.color : '#1a1a1a';
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(r * 0.6, -r * 0.18, r * 1.4, r * 0.22);
    ctx.fillStyle = wColor;
    ctx.fillRect(r * 0.6, -r * 0.10, r * 0.6, r * 0.10);
    ctx.restore();  // v1.520: stäng weapon-transform-save

    ctx.restore();

    // JUG-glow ring + crown om denna partner är JUG (använd partnerIsJug-fallback)
    if (partnerIsJug) {
      const now2 = performance.now();
      const pulse = 0.5 + Math.sin(now2 / 300) * 0.5;
      const ringR = r * (p.scaleMul || Coop.juggernautScale || 1.4) + 6;
      ctx.save();
      ctx.strokeStyle = `rgba(255, 213, 74, ${0.6 + 0.4 * pulse})`;
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(x, y, ringR, 0, Math.PI * 2); ctx.stroke();
      const grad = ctx.createRadialGradient(x, y, ringR * 0.7, x, y, ringR * 1.5);
      grad.addColorStop(0, `rgba(255, 213, 74, ${0.25 * pulse})`);
      grad.addColorStop(1, 'rgba(255, 213, 74, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(x, y, ringR * 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }

    // Namn-tag (🤖-prefix för bots så spelaren ser AI vs människor)
    ctx.fillStyle = partnerIsJug ? '#ffd54a' : color;
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    const _crown = partnerIsJug ? '👑 ' : '';
    const nameLabel = _crown + (p.isBot ? ('🤖 ' + p.name) : p.name);
    ctx.fillText(nameLabel, x, y - 28);
    ctx.shadowBlur = 0;
    // HP+shield som EN sammanhängande bar i PvP (shield blå ovanpå, HP grön
    // under — utan gap så det ser ut som en bar). Shield krymper först,
    // sedan HP. I story-coop: bara HP-bar.
    if (p.hp !== undefined) {
      const inPvP = state.tdmActive || state.ctfActive || state.siegeActive || state.gungameActive || state.kothActive || state.juggernautActive || state.battleroyaleActive || state.castledefenseActive;
      const maxShield = inPvP ? (p.maxShield || state.pvpShieldMax || 100) : 0;
      const hasShield = inPvP && maxShield > 0;
      // Samma barW för alla — JUG ska se ut som vanlig spelare-hp-bar
      const barW = 36;
      const hpY = y - 24;
      // HP-bar (grön/team-färg) — JUG har högre maxHp så bar-fraktionen
      // måste relatera till p.maxHp om det är satt.
      // Använd JUG maxHp som fallback om partner är JUG (anti-overflow)
      const _maxHp = partnerIsJug ? (p.maxHp || Coop.juggernautHpMax || 500)
                                  : ((p.maxHp && p.maxHp > 100) ? p.maxHp : 100);
      const hpFrac = Math.max(0, p.hp / _maxHp);
      ctx.fillStyle = '#5a0a0a';
      ctx.fillRect(x - barW/2, hpY, barW, 4);
      ctx.fillStyle = color;
      ctx.fillRect(x - barW/2, hpY, barW * hpFrac, 4);
      // Shield-bar DIREKT ovanpå (no gap) — bildar visuellt EN bar
      if (hasShield) {
        const shVal = (p.shield != null) ? p.shield : maxShield;
        const sFrac = Math.max(0, Math.min(1, shVal / maxShield));
        const shY = hpY - 3; // direkt ovanpå HP-bar (3px shield-höjd, no gap)
        ctx.fillStyle = 'rgba(15,30,55,0.85)';
        ctx.fillRect(x - barW/2, shY, barW, 3);
        if (sFrac > 0) {
          ctx.fillStyle = '#3acaff';
          ctx.shadowColor = '#3acaff';
          ctx.shadowBlur = 4;
          ctx.fillRect(x - barW/2, shY, barW * sFrac, 3);
          ctx.shadowBlur = 0;
        }
      }
    }
  }
}

function drawOffscreenPartner(p, sx, sy) {
  // Pil mot off-screen partner
  const cx = viewW/2, cy = viewH/2;
  const dx = sx - cx, dy = sy - cy;
  const ang = Math.atan2(dy, dx);
  const margin = 40;
  const halfW = viewW/2 - margin, halfH = viewH/2 - margin;
  let px, py;
  if (Math.abs(Math.tan(ang)) * halfW < halfH) {
    px = Math.cos(ang) > 0 ? cx + halfW : cx - halfW;
    py = cy + (px - cx) * Math.tan(ang);
  } else {
    py = Math.sin(ang) > 0 ? cy + halfH : cy - halfH;
    px = cx + (py - cy) / Math.tan(ang);
  }
  const color = PLAYER_COLORS[p.colorIdx % PLAYER_COLORS.length];
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(ang);
  ctx.fillStyle = color;
  ctx.shadowColor = color; ctx.shadowBlur = 6;
  ctx.beginPath();
  ctx.moveTo(0, 0); ctx.lineTo(-12, -8); ctx.lineTo(-12, 8);
  ctx.closePath(); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#000';
  ctx.font = 'bold 9px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText(p.name, -6, 3);
  ctx.restore();
}

function drawDrone() {
  if (!state.drone || !state.drone.alive) return;
  const d = state.drone;
  const x = d.x - state.camera.x, y = d.y - state.camera.y;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(d.angle * 2);
  // Drone body
  ctx.fillStyle = '#1a1a22';
  ctx.fillRect(-8, -8, 16, 16);
  ctx.fillStyle = '#3acaff';
  ctx.shadowColor = '#3acaff'; ctx.shadowBlur = 6;
  ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
  ctx.shadowBlur = 0;
  // Propellers
  ctx.fillStyle = '#3a3a44';
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI/2 + d.angle * 8;
    ctx.fillRect(Math.cos(a)*8 - 1, Math.sin(a)*8 - 1, 6, 2);
  }
  ctx.restore();
}

function updatePickups(dt) {
  if (!state.pickups || !state.player) return;
  const p = state.player;
  // Lista över alla spelare som kan grabba pickups
  const players = [{ ref: p, isLocal: true, pid: null }];
  if (Coop.active && Coop.isHost) {
    for (const [pid, partner] of Coop.players) {
      if (partner.hp > 0) players.push({ ref: partner, isLocal: false, pid });
    }
  }
  for (const pk of state.pickups) {
    pk.life -= dt;
    if (pk.life <= 0) { pk.dead = true; continue; }
    // Hitta närmsta spelare till denna pickup
    let nearest = null, nearestD = Infinity;
    for (const pl of players) {
      const dd = Math.hypot(pl.ref.x - pk.x, pl.ref.y - pk.y);
      if (dd < nearestD) { nearestD = dd; nearest = pl; }
    }
    if (!nearest) continue;
    const dx = nearest.ref.x - pk.x, dy = nearest.ref.y - pk.y;
    const d = nearestD;
    // Magnet mot närmsta spelare. MagnetJamlo-cheat = oändlig räckvidd
    // v1.527: SURVIVORS-RUN magnet-perk ökar pickup-radius
    const _survMagnetBonus = (state.survivorsActive ? (1 + getSurvivorsPerkSum('magnet')) : 1);
    const magnetRange = isCheatActive('magnet') ? 99999 : (110 * _survMagnetBonus);
    if (d < magnetRange) pk.magnetized = true;
    if (pk.magnetized && d > 0) {
      const speed = Math.min(600, 200 + (1 - d/magnetRange) * 300);
      pk.x += (dx/d) * speed * dt;
      pk.y += (dy/d) * speed * dt;
      // Magnet-trail: liten färgad prick bakom pickup som drar mot spelaren.
      // Throttle via _magnetTrailAccum så vi inte spammar pool vid flera pickups.
      state._magnetTrailAccum = (state._magnetTrailAccum || 0) + dt;
      if (state._magnetTrailAccum > 0.045 && state.particles.length < 220) {
        state._magnetTrailAccum = 0;
        const trailColors = { hp: '#5aff5a', shield: '#3acaff', ammo: '#ffae3a', gold: '#ffd54a', temp_dmg: '#ff5a3a' };
        state.particles.push({
          x: pk.x, y: pk.y, vx: 0, vy: 0,
          isTrail: true, color: trailColors[pk.type] || '#fff',
          r: 2.5, life: 0.22, fadeMul: 5,
        });
      }
    }
    if (d < (nearest.ref.r || 14) + 10) {
      pk.dead = true;
      Audio.goldPickup();
      // Pickup-collect burst — färgad shockwave + 4 sparks i samma färg
      const burstColor = pk.type === 'hp' ? '#5aff5a' : pk.type === 'shield' ? '#3acaff' : pk.type === 'ammo' ? '#ffae3a' : pk.type === 'gold' ? '#ffd54a' : '#ff5a3a';
      spawnShockwave(pk.x, pk.y, 6, 36, burstColor, 0.28, 2);
      spawnSparks(pk.x, pk.y, burstColor, 5, 220);
      // Om partner picked it up, skicka event
      if (!nearest.isLocal && nearest.pid) {
        Coop.sendPickupToPartner(nearest.pid, pk.type);
        continue;
      }
      if (pk.type === 'hp') {
        p.hp = Math.min(p.maxHp, p.hp + 30);
        showFloatingText(pk.x, pk.y, '+30 HP', '#5aff5a');
      } else if (pk.type === 'shield') {
        // v1.579: shield-pickup för survivors-mode (blå bar)
        const max = p.maxShield || 100;
        p.shield = Math.min(max, (p.shield || 0) + 35);
        showFloatingText(pk.x, pk.y, '+35 SHIELD', '#3acaff');
      } else if (pk.type === 'ammo') {
        const w = getWeapon(p.weaponId);
        if (w.mag) {
          p.ammo = effectiveMag(p.weaponId);
          p.reloading = false;
          showFloatingText(pk.x, pk.y, 'AMMO!', '#ffae3a');
        }
      } else if (pk.type === 'gold') {
        const bonus = 25 + Math.floor(Math.random() * 25);
        save.gold += bonus;
        state.goldThisRun += bonus;
        showFloatingText(pk.x, pk.y, '+' + bonus, '#ffd54a');
      } else if (pk.type === 'temp_dmg') {
        p.tempDmgUntil = performance.now() + 8000;
        showFloatingText(pk.x, pk.y, '×2 DMG 8s', '#ff5a3a');
      }
    }
  }
  state.pickups = state.pickups.filter(p => !p.dead);
}
function showFloatingText(x, y, text, color) {
  state.particles.push({
    x, y, vx: 0, vy: -80, life: 1.0, r: 0,
    color, isDamageNumber: true, text, size: 13,
  });
}
function drawPickups() {
  if (!state.pickups) return;
  const cx = state.camera.x, cy = state.camera.y;
  const t = performance.now();
  for (const pk of state.pickups) {
    const bob = Math.sin(t/200 + pk.x) * 2.5;
    const x = pk.x - cx, y = pk.y - cy + bob;
    const colors = { hp: '#5aff5a', ammo: '#ffae3a', gold: '#ffd54a', temp_dmg: '#ff5a3a' };
    const col = colors[pk.type] || '#fff';
    // Pulserande halo (yttre ring + glow)
    const pulse = 0.55 + Math.sin(t / 280 + pk.x * 0.1) * 0.45;
    ctx.save();
    ctx.shadowColor = col; ctx.shadowBlur = 14 * pulse;
    ctx.fillStyle = col + '44';
    ctx.beginPath(); ctx.arc(x, y, 16 + pulse * 3, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;
    // Inner glow disk
    ctx.fillStyle = col + '22';
    ctx.beginPath(); ctx.arc(x, y, 11, 0, Math.PI * 2); ctx.fill();
    // Rotating sparkle ring (4 prickar)
    const rot = t / 600;
    for (let i = 0; i < 4; i++) {
      const a = rot + i * Math.PI / 2;
      const sx = x + Math.cos(a) * 13, sy = y + Math.sin(a) * 13;
      ctx.fillStyle = '#fff';
      ctx.globalAlpha = 0.5 + Math.sin(t / 200 + i) * 0.4;
      ctx.beginPath(); ctx.arc(sx, sy, 1.5, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
    // Skugga under (gör att pickup känns flytande)
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath(); ctx.ellipse(x, y + 10 - bob * 0.5, 8, 3, 0, 0, Math.PI * 2); ctx.fill();
    // Ikon
    if (pk.type === 'hp') {
      ctx.fillStyle = '#5aff5a';
      ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 6;
      ctx.fillRect(x - 5, y - 2, 10, 4);
      ctx.fillRect(x - 2, y - 5, 4, 10);
      ctx.shadowBlur = 0;
    } else if (pk.type === 'shield') {
      // v1.579: shield-pickup ikon (blå sköld)
      ctx.fillStyle = '#3acaff';
      ctx.shadowColor = '#3acaff'; ctx.shadowBlur = 8;
      ctx.beginPath();
      ctx.moveTo(x, y - 7);
      ctx.lineTo(x + 5, y - 4);
      ctx.lineTo(x + 5, y + 2);
      ctx.quadraticCurveTo(x, y + 7, x, y + 7);
      ctx.quadraticCurveTo(x, y + 7, x - 5, y + 2);
      ctx.lineTo(x - 5, y - 4);
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
    } else if (pk.type === 'ammo') {
      ctx.fillStyle = '#ffae3a';
      ctx.shadowColor = '#ffae3a'; ctx.shadowBlur = 6;
      ctx.fillRect(x - 4, y - 6, 8, 12);
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#3a2a08';
      ctx.fillRect(x - 3, y - 5, 6, 3);
    } else if (pk.type === 'gold') {
      ctx.fillStyle = '#ffd54a';
      ctx.shadowColor = '#ffd54a'; ctx.shadowBlur = 8;
      ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI*2); ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#a07a18';
      ctx.font = 'bold 8px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText('$', x, y + 3);
    } else if (pk.type === 'temp_dmg') {
      ctx.fillStyle = '#ff5a3a';
      ctx.shadowColor = '#ff5a3a'; ctx.shadowBlur = 8;
      ctx.font = 'bold 14px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText('⚡', x, y + 5);
      ctx.shadowBlur = 0;
    }
    // Life-blink när < 5s kvar — nu mer aggressiv så spelaren ser brådskan
    if (pk.life < 5) {
      const blink = 0.5 + Math.sin(t / 80) * 0.5;
      ctx.strokeStyle = col; ctx.lineWidth = 2;
      ctx.globalAlpha = blink;
      ctx.beginPath(); ctx.arc(x, y, 16, 0, Math.PI*2); ctx.stroke();
      ctx.globalAlpha = 1;
    }
  }
}

