const W_BY_ID = Object.fromEntries(WEAPONS.map(w => [w.id, w]));

// Defensiv lookup: returnerar ALLTID ett vapen-objekt. Fallback till fists vid undefined/saknat id.
// Använd istället för rå W_BY_ID[...] när id kan komma från save-data, network, eller user-input.
function getWeapon(id) {
  return W_BY_ID[id] || W_BY_ID.fists;
}

// weaponStrength: numerisk styrka för pickup-jämförelse (auto-byte bara om
// nya är starkare). Använder DPS + pris för tie-break. Utility-vapen som
// timestop/mindcontrol/blackhole får bonus från price (deras värde är inte
// DPS-baserat). Melee räknas också (rate-baserad DPS).
function weaponStrength(w) {
  if (!w) return 0;
  const burst = w.burstCount || 1;
  const pellets = w.pellets || 1;
  const dmg = w.dmg || 0;
  const rate = w.rate || 500;
  // Bas-DPS (skott-skada per sekund)
  let dps = (dmg * pellets * burst * 1000) / rate;
  // Explosive: AoE räknas som ~50% av direct-damage extra
  if (w.explosive) dps += w.explosive * 0.5 * (1000 / rate);
  // Utility-vapen utan dmg (mindcontrol) — använd price som proxy så det inte är 0
  if (dps === 0 && w.price) dps = w.price / 30;
  // Price tie-break (för vapen med liknande DPS, högre pris vinner)
  return dps + (w.price || 0) * 0.01;
}

// WEAPON_ICONS + getWeaponIcon definieras längre ner (line ~5519)

// Per-weapon färg-tier för HUD weapon-name (visuell hierarki).
// Common (gratis) = grå, Uncommon (<400g) = grön, Rare (<1000g) = blå,
// Epic (<2000g) = lila, Legendary (2000+) = guld.
function getWeaponTierColor(id) {
  const w = W_BY_ID[id];
  if (!w) return '#aaa';
  const p = w.price || 0;
  if (p === 0) return '#aaa';
  if (p < 400) return '#9aff5a';
  if (p < 1000) return '#3acaff';
  if (p < 2000) return '#aa3aff';
  return '#ffd54a';
}

// Vapen-kategori (för shop-filter)
function weaponCategory(w) {
  const specials = ['flame', 'plasma', 'tesla', 'frost', 'sonic', 'lightsaber', 'energysword', 'railgun', 'blackhole'];
  if (specials.includes(w.id)) return 'special';
  return w.type === 'melee' ? 'melee' : 'gun';
}

// ============================================================
// SAVE / LOAD
// ============================================================
function loadSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return defaultSave();
    const s = JSON.parse(raw);
    if (!s || typeof s !== 'object') return defaultSave();
    if (!Array.isArray(s.owned) || !s.owned.includes('fists')) s.owned = ['fists'];
    if (!Array.isArray(s.perks)) s.perks = [];
    if (!Array.isArray(s.achievements)) s.achievements = [];
    if (typeof s.gold !== 'number' || s.gold < 0) s.gold = 0;
    if (!s.upgrades || typeof s.upgrades !== 'object') s.upgrades = {};
    if (s.audio && typeof s.audio !== 'object') s.audio = {};
    if (s.feedback && typeof s.feedback !== 'object') s.feedback = {};
    return s;
  } catch (e) {
    console.warn('Save corrupt, återställer:', e);
    return defaultSave();
  }
}
