  // SHIRT
  set('shirt', 'gold',    { tier: 'epic',  unlock: () => (save.stats && save.stats.totalGold >= 10000), lore: 'Guld-väst. Låst: samla 10k gold totalt.', vfx: 'shimmer-gold' });
