// v1.489: Validera ALLA wardrobe-presets + items vid script-load.
// Loggar varningar för dangling refs (preset.shirt='foo' men 'foo' saknas i WARDROBE.shirt).
(function _validateWardrobeAtLoad() {
  try {
    const errors = [];
    if (typeof WARDROBE_PRESETS !== 'undefined' && typeof WARDROBE !== 'undefined') {
      for (const p of WARDROBE_PRESETS) {
        for (const [cat, id] of Object.entries(p.wardrobe)) {
          if (id === 'none') continue;
          if (!WARDROBE[cat]) { errors.push(`[wardrobe] unknown category '${cat}' in preset '${p.id}'`); continue; }
          if (!WARDROBE[cat].find(o => o.id === id)) {
            errors.push(`[wardrobe] preset '${p.id}': ${cat}='${id}' not in WARDROBE.${cat}`);
          }
        }
      }
    }
    if (errors.length) {
      console.warn(`[wardrobe] ${errors.length} validation errors:`);
      for (const e of errors) console.warn('  ' + e);
    }
  } catch (e) { console.warn('[wardrobe] validation crashed:', e.message); }
})();
function ensureWardrobe() {
  if (!save.wardrobe) save.wardrobe = {};
  const w = save.wardrobe;
  if (!w.skin)    w.skin = 'tan';
  if (!w.hair)    w.hair = 'shortDark';
  if (!w.shirt)   w.shirt = 'black';
  if (!w.pants)   w.pants = 'khaki';
  if (!w.bandana) w.bandana = 'black';
  if (!w.glasses) w.glasses = 'none';
  if (!w.hat)     w.hat = 'none';
  if (!w.cape)    w.cape = 'none';
  if (!w.shoes)   w.shoes = 'none';
  if (!w.facialHair) w.facialHair = 'none';
  if (!w.eyes)    w.eyes = 'default';
  if (!w.scars)   w.scars = 'none';
  // v1.504: facial features — alla default 'classic' (matchar tidigare hardcoded look)
  if (!w.nose)     w.nose = 'classic';
  if (!w.eyeShape) w.eyeShape = 'classic';
  if (!w.eyebrows) w.eyebrows = 'classic';
  if (!w.mouth)    w.mouth = 'classic';
  if (!w.tints)   w.tints = { shirtHue: 0, pantsHue: 0 };
  // Lock-validation: om equippad item nu är låst (t.ex. NG+-reset eller achievement
  // wipe), defaulta tillbaka till första (alltid common, alltid unlocked).
  for (const cat of Object.keys(WARDROBE)) {
    const cur = w[cat];
    if (!cur) continue;
    const opt = WARDROBE[cat].find(o => o.id === cur);
    if (!opt) { w[cat] = WARDROBE[cat][0].id; continue; }
    if (!isWardrobeUnlocked(opt)) {
      w[cat] = WARDROBE[cat][0].id;
    }
  }
}
// Helper: kollar om wardrobe-option är unlockad. Respekterar save.wardrobeUnlockAll
// (cheat-flagga som låser upp ALLA items). Annars använd opt.unlock() om finns.
function isWardrobeUnlocked(opt) {
  if (!opt) return false;
  if (save && save.wardrobeUnlockAll) return true;
  if (typeof opt.unlock === 'function') return !!opt.unlock();
  return true; // ingen unlock-funktion = alltid tillgänglig
}

function getWardrobeOpt(cat, id) {
  return WARDROBE[cat].find(o => o.id === id) || WARDROBE[cat][0];
}

