// Synlig debug-toast för errors från onTap (rare path). Alltid PÅ — om en
// handler kraschar vill vi veta varför direkt på telefonen.
let _tapDebugEl = null;
function _showTapDebug(msg) {
  if (!_tapDebugEl) {
    _tapDebugEl = document.createElement('div');
    _tapDebugEl.style.cssText = 'position:fixed;top:max(10px, env(safe-area-inset-top, 10px));left:50%;transform:translateX(-50%);background:rgba(170,58,255,0.95);color:#fff;padding:8px 14px;border-radius:8px;font-size:12px;font-weight:900;letter-spacing:1px;z-index:99999;pointer-events:none;font-family:monospace;max-width:90%;text-align:center;box-shadow:0 4px 16px rgba(0,0,0,0.6);';
    document.body.appendChild(_tapDebugEl);
  }
  _tapDebugEl.textContent = msg;
  _tapDebugEl.style.opacity = '1';
  clearTimeout(_tapDebugEl._timer);
  _tapDebugEl._timer = setTimeout(() => { _tapDebugEl.style.opacity = '0'; }, 1800);
}

// Bot-namn — MÅSTE matcha server/sim/bots.js BOT_NAMES exakt. Client genererar
// en shuffle vid bot-aktivering så lobbyn visar samma namn som matchen får.
const BOT_NAMES = ['Hovigo', 'Jamlo', 'Kostefo', 'Wisämo', 'Salimius', 'Muzzius', 'Okanius'];
function generateBotNames(count) {
  const shuffled = [...BOT_NAMES].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

// Tap-helper — iOS PWA inuti `.overlay { overflow-y:auto }` hijackar touchen
// som potentiell scroll. Det gör att `click` OCH `pointerup` ALDRIG firar för
// dynamiskt skapade knappar. Joystick + fire-knapp i spelet använder `touchstart`
// och funkar perfekt — så vi gör samma sak.
//
// touchstart fires INSTANT innan iOS hinner bestämma "scroll vs tap". preventDefault
// hindrar synthetic mouse/click events. click = desktop-fallback (mus genererar
// ingen touchstart). 400ms dedupe stoppar dubbel-fire från touchstart+click på
// hybrid-devices (Android med mus/touch eller iPad med Magic Keyboard).
function onTap(el, fn) {
  if (!el) return;
  let _last = 0;
  const wrap = (e) => {
    const now = Date.now();
    if (now - _last < 400) return;
    _last = now;
    if (e && e.cancelable) e.preventDefault();
    try {
      fn(e);
    } catch (err) {
      // Visa errors så vi kan se buggar live (rare path — annars tyst)
      _showTapDebug('ERROR: ' + (err && err.message || err));
      throw err;
    }
  };
  el.addEventListener('touchstart', wrap, { passive: false });
  el.addEventListener('click', wrap);
}

// onTapScrollable — scroll-aware variant av onTap. Använd när elementet
// ligger i en scrollbar container (t.ex. JUG-pickerns kort-lista). Skiljer sig
// från onTap genom att INTE preventDefault på touchstart — annars dödas scroll
// innan den ens börjar. Fires bara om touchen släpps utan rörelse > 10px.
function onTapScrollable(el, fn) {
  if (!el) return;
  let _last = 0, _sx = 0, _sy = 0, _moved = false, _active = false;
  el.addEventListener('touchstart', (e) => {
    _active = true;
    _moved = false;
    const t = e.touches && e.touches[0];
    if (t) { _sx = t.clientX; _sy = t.clientY; }
  }, { passive: true });
  el.addEventListener('touchmove', (e) => {
    if (!_active) return;
    const t = e.touches && e.touches[0];
    if (!t) return;
    const dx = t.clientX - _sx, dy = t.clientY - _sy;
    if (dx * dx + dy * dy > 100) _moved = true; // 10px tröskel
  }, { passive: true });
  el.addEventListener('touchend', (e) => {
    if (!_active) return;
    _active = false;
    if (_moved) return;
    const now = Date.now();
    if (now - _last < 400) return;
    _last = now;
    if (e.cancelable) e.preventDefault(); // suppressa synthetic click
    try { fn(e); } catch (err) { _showTapDebug('ERROR: ' + (err && err.message || err)); throw err; }
  }, { passive: false });
  el.addEventListener('touchcancel', () => { _active = false; _moved = false; });
  el.addEventListener('click', (e) => {
    const now = Date.now();
    if (now - _last < 400) return;
    _last = now;
    try { fn(e); } catch (err) { _showTapDebug('ERROR: ' + (err && err.message || err)); throw err; }
  });
}

