let deferredInstallPrompt = null;
window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
  const banner = document.getElementById('install-banner');
  if (banner && !save.installDismissed && !window.matchMedia('(display-mode: standalone)').matches) {
    banner.classList.remove('hidden');
  }
});
const installBtn = document.getElementById('btn-install');
const installDismissBtn = document.getElementById('btn-install-dismiss');
if (installBtn) {
  installBtn.addEventListener('click', async () => {
    if (deferredInstallPrompt) {
      deferredInstallPrompt.prompt();
      await deferredInstallPrompt.userChoice;
      deferredInstallPrompt = null;
      document.getElementById('install-banner').classList.add('hidden');
    }
  });
}
if (installDismissBtn) {
  installDismissBtn.addEventListener('click', () => {
    save.installDismissed = true; persist();
    document.getElementById('install-banner').classList.add('hidden');
  });
}

// Auto-quality detection — mät FPS första 5 sekunderna
let _fpsFrames = 0, _fpsStart = 0, _fpsAdjusted = false;
function autoAdjustQuality(now) {
  if (!state.player) return;
  if (!_fpsStart) _fpsStart = now;
  _fpsFrames++;
  if (now - _fpsStart > 5000) {
    const fps = _fpsFrames * 1000 / (now - _fpsStart);
    if (fps < 25 && save.quality !== 'low') {
      save.quality = 'low';
      persist();
      showToast('🐢 Kvalitet sänkt → LÅG (' + Math.round(fps) + ' fps)');
    } else if (fps < 45 && save.quality === 'high') {
      save.quality = 'medium';
      persist();
      showToast('Kvalitet sänkt → MEDIUM (' + Math.round(fps) + ' fps)');
    } else if (fps > 55 && save.quality === 'low') {
      save.quality = 'medium';
      persist();
    }
    // Reset för nästa mätning (löpande, inte engångs)
    _fpsStart = now;
    _fpsFrames = 0;
  }
}

// Battery-saver — sänk kvalitet vid <20% batteri
if (navigator.getBattery) {
  navigator.getBattery().then(b => {
    function checkBattery() {
      if (b.level < 0.2 && !b.charging && save.quality !== 'low') {
        save.quality = 'low'; persist();
        showToast('Låg batteri — kvalitet sänkt');
      }
    }
    checkBattery();
    b.addEventListener('levelchange', checkBattery);
  }).catch(() => {});
}

// Pausa spel vid background (mobile-friendly)
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state.mode === 'playing') {
    openPause();
  }
});

// Förhindra context-menu vid long-press (mobile)
window.addEventListener('contextmenu', e => e.preventDefault());

// Mode / Difficulty knappar
const btnMode = document.getElementById('btn-mode');
const btnDifficulty = document.getElementById('btn-difficulty');
function refreshModeButtons() {
  let modeLabel = MODE_LABELS[getMode()] || 'STORY';
  const lvl = getNGPLevel();
  if (lvl === 1) modeLabel += ' (NG+)';
  else if (lvl === 2) modeLabel += ' (NG++)';
  else if (lvl >= 3) modeLabel += ' (NG' + '+'.repeat(lvl) + ')';
  // Mode-ikoner per läge
  const modeIcons = { story: '📖', endless: '♾️', bossrush: '👑', daily: '📅', sandbox: '🛠️', speedrun: '⚡', survive: '⏳', truck: '🚚' };
  const modeIcon = modeIcons[getMode()] || '🎮';
  btnMode.textContent = modeIcon + ' LÄGE: ' + modeLabel;
  // Difficulty-färg per nivå
  const diff = getDifficulty();
  const diffIcons = { casual: '🟢', veteran: '🟡', hardcore: '🟠', insane: '🔴' };
  btnDifficulty.textContent = (diffIcons[diff] || '🟡') + ' SVÅRIGHET: ' + (DIFF_LABELS[diff] || 'VETERAN');
  // Companions-knapp: visa 💀 om aktiv companion är död (persistent dead-state)
  // Knapp finns inte längre på hemskärm, men i shop visas via comp-tab
  const compBtn = document.getElementById('btn-companions');
  if (compBtn) {
    const dead = save.companions && save.companions.active &&
                 save.companions.dead && save.companions.dead[save.companions.active];
    compBtn.textContent = dead ? '💀 KOMPANJONER' : '🐕 KOMPANJONER';
  }
}
btnMode.addEventListener('click', () => {
  // v1.524: Endless/Bossrush locked-check borttagen — inga modes är låsta längre.
  const cur = getMode();
  let idx = GAME_MODES.indexOf(cur);
  idx = (idx + 1) % GAME_MODES.length;
  save.mode = GAME_MODES[idx];
  persist();
  refreshModeButtons();
  Audio.uiClick();
});
btnDifficulty.addEventListener('click', () => {
  const cur = getDifficulty();
  const idx = DIFFICULTIES.indexOf(cur);
  save.difficulty = DIFFICULTIES[(idx + 1) % DIFFICULTIES.length];
  persist();
  refreshModeButtons();
  Audio.uiClick();
});
refreshModeButtons();

