// Returnerar SVG-sträng om custom-design finns, annars emoji-fallback.
function getWeaponIconHTML(id) {
  return WEAPON_ICON_SVGS[id] || WEAPON_ICONS[id] || '🔫';
}

function updateFireButtonIcon() {
  if (!fireBtn || !state.player) return;
  // Bevara fire-button's nested struktur (fire-knob > fire-icon-wrap > fire-icon)
  // genom att bara uppdatera .fire-icon-span. Annars wipas ammo-display etc.
  const iconEl = fireBtn.querySelector('.fire-icon');
  if (iconEl) iconEl.innerHTML = getWeaponIconHTML(state.player.weaponId);
  else fireBtn.innerHTML = getWeaponIconHTML(state.player.weaponId);
}

function renderWeaponMenu() {
  weaponMenuGrid.innerHTML = '';
  // v1.611: SURVIVORS shop-integration — visa ALLA 15 GG-vapen som korten,
  // unowned → köp-knapp (server-authoritative buy), owned → equip vid klick.
  if (state.survivorsActive && typeof SURVIVORS_SHOP_WEAPONS !== 'undefined') {
    const matchGold = state.castledefenseGold || 0;
    state.survivorsOwnedWeapons = state.survivorsOwnedWeapons || ['pistol'];
    const equippedSurv = (state.player && state.player.weaponId) || 'pistol';
    // Gold-header
    const goldHeader = document.createElement('div');
    goldHeader.style.cssText = 'grid-column:1/-1;text-align:center;padding:8px;color:#ffd54a;font-weight:900;font-size:16px;letter-spacing:1px;border-bottom:1px solid rgba(170,58,255,0.3);margin-bottom:8px;';
    goldHeader.innerHTML = '💰 ' + matchGold + ' GOLD';
    weaponMenuGrid.appendChild(goldHeader);
    for (const sw of SURVIVORS_SHOP_WEAPONS) {
      const w = WEAPONS.find(x => x.id === sw.id);
      if (!w) continue;
      const cat = weaponCategory(w);
      const owned = state.survivorsOwnedWeapons.includes(sw.id) || sw.cost === 0;
      const equipped = equippedSurv === sw.id;
      const canAfford = matchGold >= sw.cost;
      const div = document.createElement('div');
      div.className = 'wmenu-item' + (equipped ? ' equipped' : '');
      if (!owned && !canAfford) div.style.opacity = '0.55';
      // stat-bars
      const dmgMax = w.type === 'melee' ? 100 : 200;
      const dmgPct = Math.min(1, w.dmg * (w.pellets || 1) / dmgMax);
      const fireRate = Math.min(1, (60000 / w.rate) / 12);
      const ros = w.type === 'melee' ? Math.min(1, (w.range || 40) / 100) : Math.min(1, (w.speed || 800) / 1500);
      const stats = '<div class="stat-bar"><span class="label">Skada</span><div class="bar"><div class="bar-fill" style="width:' + (dmgPct*100) + '%"></div></div></div>' +
        '<div class="stat-bar"><span class="label">Snabbhet</span><div class="bar"><div class="bar-fill" style="width:' + (fireRate*100) + '%"></div></div></div>' +
        '<div class="stat-bar"><span class="label">' + (w.type === 'melee' ? 'Räckv' : 'Hast') + '</span><div class="bar"><div class="bar-fill" style="width:' + (ros*100) + '%"></div></div></div>';
      const tags = [];
      if (w.pierce) tags.push('🎯');
      if (w.explosive) tags.push('💥');
      if (w.burn) tags.push('🔥');
      if (w.chain) tags.push('⚡');
      if (w.slow) tags.push('❄');
      if (w.knockback) tags.push('💢');
      let statusBadge = '';
      if (equipped) statusBadge = '<div class="equipped-badge">✓</div>';
      else if (owned) statusBadge = '<div style="position:absolute;top:6px;right:6px;background:#1a3a4a;color:#5aaaff;padding:2px 6px;border-radius:4px;font-size:9px;font-weight:900;">ÄGD</div>';
      else if (canAfford) statusBadge = '<div style="position:absolute;top:6px;right:6px;background:#3a1a5a;color:#d0a0ff;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:900;">💰 ' + sw.cost + '</div>';
      else statusBadge = '<div style="position:absolute;top:6px;right:6px;background:#2a1a1a;color:#7a5050;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:900;">🔒 ' + sw.cost + '</div>';
      div.innerHTML = statusBadge +
        '<div class="wname">' + (sw.label || w.name) + '</div>' +
        '<span class="wtype ' + cat + '">' + cat.toUpperCase() + '</span>' +
        stats +
        (tags.length ? '<div style="margin-top:6px;font-size:14px;letter-spacing:3px;">' + tags.join(' ') + '</div>' : '');
      div.addEventListener('click', () => {
        if (owned) {
          // Equipa
          if (state.player) state.player.weaponId = sw.id;
          if (typeof Audio !== 'undefined' && Audio.uiClick) Audio.uiClick();
          renderWeaponMenu();
          if (typeof updateHUD === 'function') updateHUD();
        } else if (canAfford) {
          // Köp via server
          if (typeof trySurvivorsWeaponBuy === 'function') {
            trySurvivorsWeaponBuy(sw.id, sw.cost);
            renderWeaponMenu();
          }
        } else {
          if (typeof showToast === 'function') showToast('🔒 OTILLRÄCKLIGT GOLD (' + matchGold + '/' + sw.cost + ')');
        }
      });
      weaponMenuGrid.appendChild(div);
    }
    return;
  }
  // bara ägda vapen, sorterade efter typ + pris
  const owned = WEAPONS.filter(w => save.owned.includes(w.id));
  owned.sort((a, b) => {
    if (a.type !== b.type) return a.type === 'melee' ? -1 : 1;
    return a.price - b.price;
  });
  for (const w of owned) {
    const cat = weaponCategory(w);
    const equipped = save.equipped === w.id;
    const div = document.createElement('div');
    div.className = 'wmenu-item' + (equipped ? ' equipped' : '');
    let stats = '';
    // stat-bars (skala 0-1 baserat på typiska max-värden)
    const dmgMax = w.type === 'melee' ? 100 : 200;
    const dmg = Math.min(1, w.dmg * (w.pellets || 1) / dmgMax);
    const rateMax = 1500;
    const fireRate = Math.min(1, (60000 / w.rate) / 12); // shots per sec normaliserad
    const rangeOrSpeed = w.type === 'melee' ? Math.min(1, (w.range || 40) / 100) : Math.min(1, (w.speed || 800) / 1500);
    stats = `
      <div class="stat-bar"><span class="label">Skada</span><div class="bar"><div class="bar-fill" style="width:${dmg*100}%"></div></div></div>
      <div class="stat-bar"><span class="label">Snabbhet</span><div class="bar"><div class="bar-fill" style="width:${fireRate*100}%"></div></div></div>
      <div class="stat-bar"><span class="label">${w.type === 'melee' ? 'Räckv' : 'Hast'}</span><div class="bar"><div class="bar-fill" style="width:${rangeOrSpeed*100}%"></div></div></div>
    `;
    const tags = [];
    if (w.pierce) tags.push('🎯');
    if (w.explosive) tags.push('💥');
    if (w.burn) tags.push('🔥');
    if (w.chain) tags.push('⚡');
    if (w.slow) tags.push('❄');
    if (w.knockback) tags.push('💢');
    div.innerHTML = `
      ${equipped ? '<div class="equipped-badge">✓</div>' : ''}
      <div class="wname">${w.name}</div>
      <span class="wtype ${cat}">${cat.toUpperCase()}</span>
      ${stats}
      ${tags.length ? '<div style="margin-top:6px;font-size:14px;letter-spacing:3px;">'+tags.join(' ')+'</div>' : ''}
    `;
    div.addEventListener('click', () => {
      equip(w.id);
      renderWeaponMenu();
    });
    weaponMenuGrid.appendChild(div);
  }
}

// ============================================================
// VAPEN-LOGIK
// ============================================================
function equip(id) {
  if (!save.owned.includes(id)) return;
  // GUNGAME: spelaren får inte byta vapen — server bestämmer via tier
  if (state.gungameActive) return;
  const wasEquipped = save.equipped;
  save.equipped = id;
  if (state.player) {
    state.player.weaponId = id;
    const magBonus = 1 + (save.upgrades.ammo || 0) * 0.20;
    const baseMag = getWeapon(id).mag || 0;
    state.player.ammo = Math.floor(baseMag * magBonus);
    state.player.reloading = false;
    // Weapon-switch VFX: snabbt flash på spelaren + sparks i nya vapnets färg
    if (wasEquipped && wasEquipped !== id) {
      const w = getWeapon(id);
      const c = (w && w.color) || '#ffd54a';
      spawnShockwave(state.player.x, state.player.y, state.player.r * 0.8, state.player.r * 2.2, c, 0.22, 2);
      spawnSparks(state.player.x, state.player.y, c, 4, 150);
      // CSS-flash på weapon-name HUD
      if (weaponName) {
        weaponName.classList.add('weapon-flash');
        setTimeout(() => weaponName.classList.remove('weapon-flash'), 350);
      }
    }
  }
  if (typeof updateFireButtonIcon === 'function') updateFireButtonIcon();
  updateHUD();
}
function effectiveMag(weaponId) {
  const baseMag = getWeapon(weaponId).mag || 0;
  const magBonus = 1 + (save.upgrades.ammo || 0) * 0.20;
  return Math.floor(baseMag * magBonus);
}

function switchWeapon(dir) {
  const owned = save.owned;
  if (owned.length <= 1) return;
  const i = owned.indexOf(save.equipped);
  const next = owned[(i + dir + owned.length) % owned.length];
  equip(next);
}

function startReload() {
  const p = state.player; if (!p) return;
  const w = getWeapon(p.weaponId);
  if (w.type !== 'gun' || p.reloading) return;
  if (p.ammo === effectiveMag(p.weaponId)) return;
  p.reloading = true;
  p.reloadStart = performance.now();
  Audio.reloadStart();
  // v1.387: haptic pulse vid reload-start ger spelaren omedelbar bekräftelse
  // att reload triggade. Innan: ingen feedback förrän reload-ring renderas
  // (~1 frame senare). Nu: instant respons via vibrationen.
  if (typeof triggerVibrate === 'function') triggerVibrate(8);
}

function tryShoot(now) {
  const p = state.player;
  // Truck-turret override: använd turretens vapen istället för spelarens
  const activeWeaponId = p._turretWeapon || p.weaponId;
  // SPECIAL: repair-turret laga trucken istället för att skjuta
  if (activeWeaponId === 'repair') {
    if (!state.truck || !state.truck.alive) return;
    if (now - p.lastShot < 200) return; // 5× per sekund max
    p.lastShot = now;
    const heal = 12;  // 5 × 12 = 60 HP/s — håller trucken vid liv men forcerar trade-offs
    state.truck.hp = Math.min(state.truck.maxHp, state.truck.hp + heal);
    spawnParticles(state.truck.x, state.truck.y, '#5aff5a', 4, 100);
    showFloatingText(state.truck.x, state.truck.y - 40, '+' + heal, '#5aff5a');
    Audio.purchase && Audio.purchase();
    return;
  }
  const w = getWeapon(activeWeaponId);
  // Stark-melee perk + Glas-kanon fire-rate bonus (15% snabbare alla vapen)
  const meleeMul = (w.type === 'melee' && hasPerk('fastmelee')) ? 0.70 : 1;
  const glasscannonMul = hasPerk('glasscannon') ? 0.85 : 1;
  // v1.527: SURVIVORS-RUN fire-rate-perks (stack-bara): rate-cooldown / (1 + sumOfRatePerks)
  const survRateMul = state.survivorsActive ? (1 / (1 + getSurvivorsPerkSum('rate'))) : 1;
  if (now - p.lastShot < w.rate * meleeMul * glasscannonMul * survRateMul) return;

  // Adrenalin perk
  const adrenaline = hasPerk('adrenalin') && p.hp < p.maxHp * 0.3;
  const tempDmg = (p.tempDmgUntil && performance.now() < p.tempDmgUntil) ? 2 : 1;
  const adrenalineDmg = (adrenaline ? 1.20 : 1) * tempDmg;
  // Tystgångare första-skott bonus
  const stealthBonus = (p.firstShotBonus && (p.shotsThisStage || 0) === 0) ? 1.5 : 1;
  if (p.firstShotBonus) p.shotsThisStage = (p.shotsThisStage || 0) + 1;

  if (w.type === 'melee') {
    p.lastShot = now;
    Audio.shootMelee();
    if (state.weaponsUsedThisStage) state.weaponsUsedThisStage.add(w.id);
    const ang = p.aimAngle;
    const reach = w.range * (p.mrangeMul || 1);
    for (const e of state.enemies) {
      const dx = e.x - p.x, dy = e.y - p.y;
      const d = Math.hypot(dx, dy);
      if (d > reach + e.r) continue;
      const a = Math.atan2(dy, dx);
      let diff = Math.abs(((a - ang + Math.PI*3) % (Math.PI*2)) - Math.PI);
      if (diff < 0.9) {
        const isCrit = isCheatActive('chozza') ? true : Math.random() < (p.critChance || 0);
        const isHead = hasPerk('headshot') && Math.random() < 0.15;
        const ultMul = isCheatActive('ultimate') ? 10 : 1;
        p.meleeComboTimer = 1.0;
        const comboCap = hasPerk('berserker') ? 20 : 10;
        p.meleeCombo = Math.min(comboCap, (p.meleeCombo || 0) + 1);
        const comboMul = 1 + p.meleeCombo * 0.08;
        const wLevelMul = weaponLevelDmgBonus(w.id);
        const dmg = w.dmg * (p.dmgMul || 1) * adrenalineDmg * stealthBonus * (isCrit ? 2 : 1) * (isHead ? 3 : 1) * ultMul * comboMul * wLevelMul;
        damageEnemy(e, dmg, isCrit || isHead);
        // melee knockback
        if (p.kbMul && p.kbMul > 1 && d > 0) {
          e.x += (dx/d) * 8 * (p.kbMul - 1);
          e.y += (dy/d) * 8 * (p.kbMul - 1);
        }
      }
    }
    spawnSlash(p.x, p.y, ang, reach, w.color);
    // Server-auth PvP: skicka sim_shoot även för melee så server gör PvP-hit-check
    // mot andra spelare. Story-mode skadar enemies lokalt ovan; PvP-mode har
    // tomma state.enemies så lokal damage är no-op och server tar över.
    if (Coop.serverSimActive && Coop.ws && Coop.ws.readyState === 1) {
      const wepLvlBonus = (typeof weaponLevelDmgBonus === 'function') ? weaponLevelDmgBonus(w.id) : 1;
      if (typeof _simDiag !== 'undefined') _simDiag.shotsSent++;
      Coop.ws.send(JSON.stringify({
        type: 'sim_shoot',
        weaponId: w.id,
        x: p.x, y: p.y, ang: p.aimAngle,
        dmgMul: (p.dmgMul || 1) * wepLvlBonus,
        critChance: p.critChance || 0,
        adrenalineDmg, stealthBonus,
        perks: { headshot: hasPerk('headshot') },
        cheats: {
          chozza: isCheatActive('chozza'),
          ultimate: isCheatActive('ultimate'),
          penetrera: isCheatActive('penetrera'),
        },
      }));
    }
    return;
  }

  // gun
  // Turret-vapen = oändlig ammo (infinite mounted ammo)
  const isTurret = !!p._turretWeapon;
  if (!isTurret && p.reloading) return;
  const dailyMod = state.dailyModifier ? state.dailyModifier.id : null;
  const ammoCost = w.ammoCost || 1;
  // Penetrera/Ultimate = ingen reload
  const noReloadCheat = isCheatActive('penetrera') || isCheatActive('ultimate');
  if (!isTurret && dailyMod !== 'no_reload' && !noReloadCheat) {
    if (p.ammo < ammoCost) { startReload(); return; }
    p.ammo -= ammoCost;
  }
  p.lastShot = now;
  // SFX per vapenkategori
  if (w.explosive || w.id === 'rocket' || w.id === 'sledge') Audio.shootHeavy();
  else if (w.style === 'plasma' || w.style === 'tesla' || w.style === 'frost' || w.style === 'flame' || w.style === 'sonic' || w.id === 'railgun' || w.id === 'blackhole') Audio.shootEnergy();
  else Audio.shootGun();
  state.weaponUsage = state.weaponUsage || {};
  state.weaponUsage[w.id] = (state.weaponUsage[w.id] || 0) + 1;
  if (state.weaponsUsedThisStage) state.weaponsUsedThisStage.add(w.id);
  let pellets = w.pellets || 1;
  // v1.527/v1.532: SURVIVORS-RUN multishot-perk. CAP +4 extra (balance-audit:
  // unbounded multishot + shotgun blir 12+ pellets = för OP).
  if (state.survivorsActive) {
    const extraPellets = Math.min(4, getSurvivorsPerkSum('multishot'));
    pellets += extraPellets;
  }
  const burstCount = w.burstCount || 1;
  const burstDelay = w.burstDelay || 0;
  // Burst-token: setTimeouts kollar att samma vapen fortfarande är equipped + samma run pågår.
  // Annars kunde delayed shots spawna efter weapon-switch eller player-death med fel weapon-stats.
  const burstWeaponId = w.id;
  const burstRunId = state.runStartTime;
  for (let burst = 0; burst < burstCount; burst++) {
    setTimeout(() => {
      if (!state.player || state.player.spectating) return;
      if (state.runStartTime !== burstRunId) return;  // ny run började
      const curWeapon = state.player._turretWeapon || state.player.weaponId;
      if (curWeapon !== burstWeaponId) return;        // vapen byttes
      spawnPlayerBullets(p, w, pellets, adrenalineDmg, stealthBonus);
    }, burst * burstDelay);
  }
  if (p.ammo <= 0) startReload();
  updateHUD();
}

function spawnPlayerBullets(p, w, pellets, adrenalineDmg, stealthBonus) {
  if (state.mode !== 'playing') return;
  // v1.387: camera-recoil — punch kameran ÖVERSTE motsatt fire-direction.
  // Skapar "feel" av tyngd vid skott. Latency-hiding-bonus: alla micro-delays
  // i bullet-spawning göms av camera-rörelsen.
  // Magnitude skalas med dmg: pistol ~1.5px, rifle ~2.5px, sniper ~5px, rocket ~5px.
  // Pellets (shotgun) ger bonus så det känns som "blast".
  if (w.dmg && typeof applyShootRecoil === 'function') {
    let recoilMag = Math.min(7, Math.max(1, w.dmg * 0.06));
    if (pellets > 1) recoilMag *= Math.sqrt(pellets); // shotgun-känsla
    applyShootRecoil(p.aimAngle, recoilMag);
  }
  // Drone-pistol summonar drone (max 1)
  if (w.summonsDrone && (!state.drone || state.drone.dead)) {
    state.drone = {
      x: p.x + 30, y: p.y, vx: 0, vy: 0,
      angle: 0, lastShot: 0, alive: true,
    };
  }
  // Time-stop pistol fryser fiender
  if (w.timeStopMs) {
    state.timeStopUntil = performance.now() + w.timeStopMs;
  }
  // Mind-control: skjut första närmsta fiende = blir alierad
  if (w.style === 'mindctrl') {
    let target = null, bestD = 999;
    for (const e of state.enemies) {
      if (e.dead || e.isBoss || e.mindControlled) continue;
      const d = Math.hypot(e.x - p.x, e.y - p.y);
      if (d < bestD) { bestD = d; target = e; }
    }
    if (target) {
      target.mindControlled = true;
      target.mindControlUntil = performance.now() + w.mindControlMs;
      target.color = '#ff5aff';
    }
    return;
  }
  // Shell ejection (för pistols/rifles, inte melee/explosiva)
  if (w.type === 'gun' && !['rocket','grenade','flame','minigun','railgun','blackhole','plasma'].includes(w.id)) {
    const ejAng = p.aimAngle + Math.PI/2 + (Math.random() - 0.5) * 0.5;
    const ejSpeed = 80 + Math.random() * 60;
    state.particles.push({
      x: p.x + Math.cos(p.aimAngle) * 4,
      y: p.y + Math.sin(p.aimAngle) * 4,
      vx: Math.cos(ejAng) * ejSpeed,
      vy: Math.sin(ejAng) * ejSpeed - 30,
      life: 0.6, color: '#dca838', r: 1.5,
    });
  }
  // Cheat-multipliers
  const cheatChozza = isCheatActive('chozza');
  const cheatPen = isCheatActive('penetrera');
  const cheatUlt = isCheatActive('ultimate');
  const speedBonus = (cheatPen ? 1.5 : 1) * (cheatUlt ? 1.5 : 1);
  const ultDmgMul = cheatUlt ? 10 : 1;
  const _coopShots = Coop.active ? [] : null;
  // Muzzle-offset: spawna bullets vid pip-mynning, inte mitt på spelaren.
  // Värden matchar drawPlayerWeapon's muzzle-position per vapen.
  const MUZZLE_OFFSETS = {
    pistol: 17, burstpistol: 22, shotgun: 26, smg: 24,
    rifle: 31, sniper: 36, revolver: 25, minigun: 27,
    plasma: 26, rocket: 23, sonic: 16, bow: 23,
    grenade: 18, flame: 16, tesla: 22, frost: 22,
    crossbow: 20, shuriken: 14, throwknife: 16,
    boomerang: 18, pullwhip: 16, railgun: 30, blackhole: 24,
    timestop: 16, mindcontrol: 16,
  };
  const muzzleOff = (w.type === 'gun') ? (MUZZLE_OFFSETS[w.id] || 20) : 0;

  // BR wall-check: RAYTRACE från player till spawn-pos. Om någon solid wall
  // är mellan player och muzzle, bullet stoppas (kan inte skjuta genom vägg).
  const _brSolidWalls = (state.battleroyaleActive && state.battleroyaleWalls)
    ? state.battleroyaleWalls.filter(w => !w.passThroughBullets)
    : null;
  const _isInsideBrWall = (bx, by) => {
    if (!_brSolidWalls) return false;
    for (let i = 0; i < _brSolidWalls.length; i++) {
      const wl = _brSolidWalls[i];
      if (bx >= wl.x && bx <= wl.x + wl.w && by >= wl.y && by <= wl.y + wl.h) return true;
    }
    return false;
  };
  // Raytrace: sampla 8-12 punkter mellan player och spawn — om någon inuti wall = blocked
  const _raycastBlocked = (px, py, sx, sy) => {
    if (!_brSolidWalls) return false;
    const dx = sx - px, dy = sy - py;
    const len = Math.hypot(dx, dy);
    const steps = Math.max(4, Math.ceil(len / 3));
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const tx = px + dx * t;
      const ty = py + dy * t;
      if (_isInsideBrWall(tx, ty)) return true;
    }
    return false;
  };

  for (let i = 0; i < pellets; i++) {
    const spread = (Math.random() - 0.5) * 2 * (w.spread || 0);
    const ang = p.aimAngle + spread;
    const speed = w.speed * (p.bspeedMul || 1) * speedBonus;
    // v1.527: SURVIVORS-RUN crit-perks (blue) adderas till base critChance.
    const _survCritBonus = state.survivorsActive ? getSurvivorsPerkSum('crit') : 0;
    const _totalCritChance = Math.min(0.95, (p.critChance || 0) + _survCritBonus);
    const isCrit = cheatChozza ? true : Math.random() < _totalCritChance;
    const isHead = hasPerk('headshot') && Math.random() < 0.15;
    // Spawn-position: pip-mynningen (player.r + muzzleOff) i aim-riktning.
    let spawnX = p.x + Math.cos(p.aimAngle) * (p.r + muzzleOff);
    let spawnY = p.y + Math.sin(p.aimAngle) * (p.r + muzzleOff);
    // BR wall-check (raytrace): om någon wall är MELLAN player och spawn-pos
    // (pip-mynningen sticker ut genom väggen), bullet stoppas.
    if (state.battleroyaleActive) {
      if (_raycastBlocked(p.x, p.y, spawnX, spawnY)) {
        // Försök kortare offset (player.r räcker oftast)
        spawnX = p.x + Math.cos(p.aimAngle) * p.r;
        spawnY = p.y + Math.sin(p.aimAngle) * p.r;
        if (_raycastBlocked(p.x, p.y, spawnX, spawnY)) continue; // skip
      }
      if (_isInsideBrWall(spawnX, spawnY)) continue; // skip om inuti wall
    }
    state.bullets.push({
      x: spawnX, y: spawnY,
      vx: Math.cos(ang)*speed, vy: Math.sin(ang)*speed,
      dmg: w.dmg * (p.dmgMul || 1) * adrenalineDmg * stealthBonus * (isCrit ? 2 : 1) * (isHead ? 3 : 1) * ultDmgMul * weaponLevelDmgBonus(w.id) * (state.survivorsActive ? ((1 + getSurvivorsPerkSum('dmg')) * (getSurvivorsPerkSum('berserker') > 0 && p.hp < p.maxHp * 0.5 ? (1 + Math.min(0.5, (1 - p.hp / p.maxHp))) : 1)) : 1),
      life: w.style === 'flame' ? 0.5 : (w.style === 'boomerang' ? 2.5 : 1.6),
      r: isCrit ? 5 : (w.style === 'flame' ? 6 : 4),
      color: (isCrit || isHead || cheatChozza) ? '#ffeb3b' : w.color,
      hostile: false,
      pierce: cheatPen || cheatUlt || !!w.pierce || (state.survivorsActive && getSurvivorsPerkSum('pierce') > 0),
      explosive: (w.explosive || 0) * (p.explMul || 1),
      crit: isCrit || isHead,
      _isHeadshot: isHead,  // separat flag så vi kan visa distinct HEADSHOT-popup vid hit
      style: w.style,
      weaponId: w.id, // Krävs av anti-cheese long-range allow-list (line ~9540)
      burn: w.burn || 0,
      chain: w.chain || 0,
      slow: w.slow || 0,
      knockback: (w.knockback || 0) * (p.kbMul || 1),
      pullRadius: w.pullRadius || 0,
      pullsEnemy: w.pullsEnemy || false,
      returns: w.returns || false,
      returnTimer: 0,
      origin: { x: p.x, y: p.y },
      bounced: false,
      cheatPen,
      cheatUlt,
    });
    if (_coopShots) {
      const _bul = state.bullets[state.bullets.length - 1];
      // v1.502: skicka även style + mascot så partner-bullets renderas korrekt
      // (rocket/grenade behåller distinkt look; mascot-shots blir food-projectiles).
      const _cos = getCurrentCostume();
      _coopShots.push({
        x: Math.round(_bul.x), y: Math.round(_bul.y),
        vx: Math.round(_bul.vx), vy: Math.round(_bul.vy),
        c: _bul.color, r: _bul.r, l: _bul.life,
        s: _bul.style || undefined,
        m: _cos.mascot || undefined,
      });
    }
  }
  if (_coopShots && _coopShots.length) Coop.broadcastShots(_coopShots);
  // Muzzle flash: kort kon vid mynningen. Storlek skalas med vapen-DPS-känsla.
  // Skip för melee/passiva vapen (de har egen slash-VFX).
  if (w.type === 'gun') {
    const muzzleSize = w.explosive ? 28 : (w.style === 'plasma' || w.style === 'tesla' || w.style === 'railgun') ? 24 : (w.style === 'flame' || w.style === 'minigun') ? 16 : 18;
    const mx = p.x + Math.cos(p.aimAngle) * (p.r + 4);
    const my = p.y + Math.sin(p.aimAngle) * (p.r + 4);
    spawnMuzzleFlash(mx, my, p.aimAngle, w.color || '#ffd14a', muzzleSize);
    // Större vapen kastar gnistor
    if (w.explosive || w.style === 'railgun' || w.style === 'plasma' || w.id === 'sniper') {
      spawnSparks(mx, my, w.color || '#ffd14a', 4, 180);
    }
  }
  // Server-auth: skicka sim_shoot så server fires authoritative bullet (skadar enemies).
  // Klientens lokala bullets är purely visual (för instant feedback) — server gör damage.
  // VIKTIGT: weaponLevelDmgBonus måste bakas in i dmgMul eftersom server inte har save-data.
  if (window._debugServerSim) console.log('[CLIENT] tryShoot serverSimActive=' + Coop.serverSimActive + ' ws=' + (Coop.ws && Coop.ws.readyState));
  if (Coop.serverSimActive && Coop.ws && Coop.ws.readyState === 1) {
    const wepLvlBonus = (typeof weaponLevelDmgBonus === 'function') ? weaponLevelDmgBonus(w.id) : 1;
    if (typeof _simDiag !== 'undefined') _simDiag.shotsSent++;
    Coop.ws.send(JSON.stringify({
      type: 'sim_shoot',
      weaponId: w.id,
      x: p.x, y: p.y, ang: p.aimAngle,
      dmgMul: (p.dmgMul || 1) * wepLvlBonus,
      bspeedMul: p.bspeedMul || 1,
      explMul: p.explMul || 1,
      kbMul: p.kbMul || 1,
      critChance: p.critChance || 0,
      adrenalineDmg, stealthBonus,
      perks: { headshot: hasPerk('headshot') },
      cheats: {
        chozza: isCheatActive('chozza'),
        ultimate: isCheatActive('ultimate'),
        penetrera: isCheatActive('penetrera'),
      },
    }));
  }
  spawnParticles(p.x + Math.cos(p.aimAngle)*p.r, p.y + Math.sin(p.aimAngle)*p.r, w.color, 4, 90);
}

// Per-vapen hit-particles vid bullet-träff. Ger varje vapen-typ unik visuell
// signature på träff (frost = isskärvor, flame = glöd, plasma = energi-burst, etc).
function spawnHitParticles(x, y, b) {
  const style = b && b.style;
  const color = (b && b.color) || '#ffd54a';
  if (style === 'frost') {
    // Iskärvor flygande utåt
    for (let i = 0; i < 5; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 80 + Math.random() * 60;
      state.particles.push({ x, y, vx: Math.cos(a)*sp, vy: Math.sin(a)*sp, life: 0.5, color: '#ccf6ff', r: 2 });
    }
  } else if (style === 'flame') {
    // Eldgnistor
    for (let i = 0; i < 4; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*60, vy: Math.sin(a)*60 - 30, life: 0.6, color: `rgba(255, ${100+Math.random()*100}, 30, 1)`, r: 2 + Math.random() * 2 });
    }
  } else if (style === 'plasma') {
    // Energi-ring expansion
    state.particles.push({ x, y, vx: 0, vy: 0, life: 0.3, color, r: 18, isExplosion: true });
  } else if (style === 'tesla') {
    // Lightning-sparks
    for (let i = 0; i < 6; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*120, vy: Math.sin(a)*120, life: 0.25, color: '#ffeb3b', r: 1.5 });
    }
  } else if (style === 'sonic') {
    // Sonic-ringar (3 expanderande)
    for (let i = 0; i < 2; i++) {
      state.particles.push({ x, y, vx: 0, vy: 0, life: 0.4 - i * 0.1, color: '#ff5ac4', r: 14 + i * 8, isExplosion: true });
    }
  } else if (style === 'railgun') {
    // Vit elektrisk burst
    state.particles.push({ x, y, vx: 0, vy: 0, life: 0.25, color: '#ffffff', r: 22, isExplosion: true });
    for (let i = 0; i < 4; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*150, vy: Math.sin(a)*150, life: 0.2, color: '#aabbff', r: 2 });
    }
  } else if (style === 'blackhole') {
    // Lila virvel-prickar
    for (let i = 0; i < 5; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*40, vy: Math.sin(a)*40, life: 0.5, color: '#aa3aff', r: 2 });
    }
  } else if (style === 'thrown') {
    // Knife-kast: små metall-stänk
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*70, vy: Math.sin(a)*70, life: 0.3, color: '#cccccc', r: 1.5 });
    }
  } else if (style === 'rocket' || style === 'grenade') {
    // Explosion hanteras av explode(), men icke-kill-träff på tanky-fiende behöver
    // ändå små rök-puffar så spelaren ser att skottet landade.
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*30, vy: Math.sin(a)*30 - 10, life: 0.4, color: 'rgba(160,160,160,0.7)', r: 3 + Math.random() * 2 });
    }
  } else {
    // Default: små gula gnistor (pistol/revolver/rifle/smg/shotgun/sniper/burst/minigun/bow/crossbow)
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      state.particles.push({ x, y, vx: Math.cos(a)*50, vy: Math.sin(a)*50, life: 0.25, color: color, r: 1.8 });
    }
  }
}

function damageEnemy(e, dmg, isCrit) {
  // Boss weak point — om träff i framsida (mot spelaren) inom 40% av radien = +200% dmg
  if (e.isBoss && state.player) {
    const dx = state.player.x - e.x, dy = state.player.y - e.y;
    const ang = Math.atan2(dy, dx);
    const facingDiff = Math.abs(((ang - (e.facing || 0) + Math.PI*3) % (Math.PI*2)) - Math.PI);
    if (facingDiff < 0.4) {
      dmg *= 3;
      isCrit = true;
      // weak point particles
      state.particles.push({
        x: e.x + Math.cos(ang) * e.r * 0.6,
        y: e.y + Math.sin(ang) * e.r * 0.6,
        vx: 0, vy: 0, life: 0.4, color: '#ff5a3a', r: 12, isExplosion: true,
      });
      // Lär ut weak-point en gång per save — ofta upptäcks det aldrig annars
      if (!save.tutFlags || !save.tutFlags.weakPoint) {
        save.tutFlags = save.tutFlags || {};
        save.tutFlags.weakPoint = true;
        persist();
        if (typeof showToast === 'function') showToast('🎯 FRONT-TRÄFF — 3× SKADA! Sikta på bossens framsida.', 4);
      }
    }
  }
  e.hp -= dmg;
  e.flashUntil = performance.now() + 80;
  // v1.527: SURVIVORS-RUN lifesteal — % av damage dealt blir HP till player
  if (state.survivorsActive && state.player && state.player.hp > 0) {
    const lifestealPct = getSurvivorsPerkSum('lifesteal');
    if (lifestealPct > 0) {
      state.player.hp = Math.min(state.player.maxHp, state.player.hp + dmg * lifestealPct);
    }
  }
  // v1.533: SURVIVORS-RUN synergy-perk hooks
  if (state.survivorsActive && !e.dead && e.hp > 0) {
    // EXECUTIONER — instakill om <10% HP (ej boss)
    if (!e.isBoss && getSurvivorsPerkSum('executioner') > 0 && e.maxHp > 0 && (e.hp / e.maxHp) < 0.10) {
      e.hp = 0;
    }
    // FROST — slow 60% i 1s
    const frostDur = getSurvivorsPerkSum('frost');
    if (frostDur > 0) {
      e.slowUntil = performance.now() + frostDur * 1000;
      e.slowFactor = 0.4;
      if (e._origSpeed && e.speed > e._origSpeed * 0.4) e.speed = e._origSpeed * 0.4;
    }
    // FIRE — burn DoT 3 dmg/s i 4s
    const burnDps = getSurvivorsPerkSum('fire');
    if (burnDps > 0) {
      e.burnUntil = performance.now() + 4000;
      e.burnDps = Math.max(e.burnDps || 0, burnDps);
    }
    // EXPLODING — AoE vid hit
    const explDmg = getSurvivorsPerkSum('exploding');
    if (explDmg > 0 && typeof explode === 'function') {
      explode(e.x, e.y, 60, explDmg, true);
    }
    // CHAIN LIGHTNING — studsa till närmaste enemy inom 150px med 50% dmg
    if (getSurvivorsPerkSum('chain') > 0 && state.enemies && !e._chainSource) {
      let best = null, bestD2 = 150 * 150;
      for (const e2 of state.enemies) {
        if (e2 === e || !e2 || e2.dead || e2.hp <= 0) continue;
        const dx = e2.x - e.x, dy = e2.y - e.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < bestD2) { bestD2 = d2; best = e2; }
      }
      if (best) {
        const chainDmg = dmg * 0.5;
        best.hp -= chainDmg;
        best.flashUntil = performance.now() + 80;
        best._chainSource = true; // förhindra infinity-loop
        // Visuell chain-blixt
        state.particles.push({
          x: e.x, y: e.y, vx: 0, vy: 0,
          targetX: best.x, targetY: best.y,
          life: 0.18, color: '#ffeb3b', r: 2,
          isChainLightning: true,
        });
        setTimeout(() => { if (best) best._chainSource = false; }, 100);
      }
    }
  }
  // Stagger — stora träffar staggar fienden 0.5s
  if (dmg > 50 && !e.isBoss) {
    e.staggerUntil = performance.now() + 500;
  }
  // Track max single-shot damage for 'oneshot' achievement
  if (e.isBoss && dmg > (state.maxBossDmgThisStage || 0)) {
    state.maxBossDmgThisStage = dmg;
  }
  if (isCrit) {
    Audio.hitCrit();
    state.critsThisRun = (state.critsThisRun || 0) + 1;
    save.stats.totalCrits = (save.stats.totalCrits || 0) + 1;
    triggerVibrate(30); // Hit-confirm: längre puls vid crit
  } else {
    Audio.hit();
    triggerVibrate(15); // Hit-confirm: kort puls vid vanlig träff
  }
  if (isCrit) {
    triggerHitStop(60);
    triggerShake(3, 0.1);
    state.particles.push({
      x: e.x, y: e.y - e.r - 10, vx: 0, vy: -40,
      life: 0.7, color: '#ffeb3b', r: 0, isCritText: true, text: 'CRIT!',
    });
  } else {
    // Punchy non-crit feel — varje träff staggrar bilden lite. self-clampar via Math.max.
    triggerHitStop(10);
    triggerShake(1.2, 0.05);
  }
  // Damage number (flytande över fienden)
  spawnDamageNumber(e.x, e.y - e.r, Math.round(dmg), isCrit);
  // Impact-shockwave skalas med dmg så små skott känns lätta, stora hits punchy.
  // Skip vid dmg<8 så minigun-spam inte spränger partikel-poolen.
  if (dmg >= 8) {
    const ringR = Math.min(70, (e.r || 12) + 4 + dmg * 0.4);
    spawnShockwave(e.x, e.y, (e.r || 12) * 0.5, ringR, isCrit ? '#ffeb3b' : '#fff', 0.22, 2);
  }
  // Combo-counter: konsekutiva träffar utan att tappa streak. Resetar vid 1.8s utan hit.
  const nowC = performance.now();
  if (nowC - (state.lastComboHit || 0) > 1800) state.comboHits = 0;
  state.comboHits = (state.comboHits || 0) + 1;
  state.lastComboHit = nowC;
  state.maxComboThisRun = Math.max(state.maxComboThisRun || 0, state.comboHits);
  if (e.hp <= 0) killEnemy(e);
}

function maybeChatter(e, lines) {
  const now = performance.now();
  if (e.lastChatter && now - e.lastChatter < 2000) return;
  e.lastChatter = now;
  const text = lines[Math.floor(Math.random() * lines.length)];
  state.particles.push({
    x: e.x, y: e.y - e.r - 6, vx: 0, vy: -25,
    life: 1.0, r: 0,
    color: '#ffd54a',
    isChatter: true, text, size: 11,
  });
}

// Off-screen hit-markers — visa pil-indikator vid skärmkant när jag träffar
// någon utanför viewport. Stackas i en kö som ritas i drawOffscreenHitMarkers.
const _offscreenHitMarkers = [];
function queueOffscreenHitMarker(worldX, worldY, dmg) {
  _offscreenHitMarkers.push({
    x: worldX, y: worldY, dmg,
    spawnAt: performance.now(),
    life: 1.0,                // sekunder, fade ut
  });
  // Cap till senaste 6 (gamla droppas)
  while (_offscreenHitMarkers.length > 6) _offscreenHitMarkers.shift();
}
function drawOffscreenHitMarkers() {
  if (!_offscreenHitMarkers.length || !state.player) return;
  const now = performance.now();
  // Filtrera ut gamla
  for (let i = _offscreenHitMarkers.length - 1; i >= 0; i--) {
    if (now - _offscreenHitMarkers[i].spawnAt > 1500) _offscreenHitMarkers.splice(i, 1);
  }
  const cam = state.camera;
  if (!cam) return;
  const margin = 50;
  const cx = viewW / 2, cy = viewH / 2;
  for (const m of _offscreenHitMarkers) {
    const sx = m.x - cam.x;
    const sy = m.y - cam.y;
    // Bara visa om utanför viewport
    if (sx >= 0 && sx <= viewW && sy >= 0 && sy <= viewH) continue;
    const age = (now - m.spawnAt) / 1500;
    if (age >= 1) continue;
    const alpha = 1 - age;
    // Rikta från center mot target
    const dx = sx - cx, dy = sy - cy;
    const ang = Math.atan2(dy, dx);
    // Klamp till viewport-rand med margin
    const halfW = viewW / 2 - margin;
    const halfH = viewH / 2 - margin;
    const scale = Math.min(halfW / Math.abs(Math.cos(ang) || 0.0001), halfH / Math.abs(Math.sin(ang) || 0.0001));
    const ex = cx + Math.cos(ang) * scale;
    const ey = cy + Math.sin(ang) * scale;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(ex, ey);
    ctx.rotate(ang);
    // Pil-form: triangel med damage-tal
    ctx.fillStyle = '#ff5a3a';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(18, 0);
    ctx.lineTo(-6, 10);
    ctx.lineTo(-6, -10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    // Damage-tal (oroterat)
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = '#ffd54a';
    ctx.font = 'bold 14px sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    const labelOffX = -Math.cos(ang) * 26;
    const labelOffY = -Math.sin(ang) * 26;
    ctx.fillText('-' + m.dmg, ex + labelOffX, ey + labelOffY + 4);
    ctx.restore();
  }
}

function spawnDamageNumber(x, y, dmg, isCrit) {
  // Stacka: hitta recent damage-number inom 40px — bumpa siffran istället för ny partikel.
  // Burst-vapen (shotgun 6 pellets, burstpistol 3 skott) spawnade tidigare 3-6 ovanpå
  // varandra som FIFO-cullades, så spelaren såg bara "12 / 12 / 12" innan de försvann.
  // Crits stackar inte (separat visuell payoff).
  if (!isCrit) {
    for (const pt of state.particles) {
      if (!pt.isDamageNumber || pt.isCritStack) continue;
      if (pt.life < 0.55) continue; // bara färska
      if (Math.abs(pt.x - x) < 40 && Math.abs(pt.y - y) < 40) {
        pt.stackedDmg = (pt.stackedDmg || parseInt(pt.text, 10) || 0) + dmg;
        pt.text = '' + pt.stackedDmg;
        pt.life = 0.8; // refresh så stacken inte försvinner mitt i burst
        return;
      }
    }
  }
  // Cap 10 samtidiga (var 5) — FIFO på äldsta om över cap.
  const existing = state.particles.filter(p => p.isDamageNumber);
  if (existing.length >= 10) existing[0].life = 0;
  state.particles.push({
    x: x + (Math.random() - 0.5) * 12, y, vx: (Math.random() - 0.5) * 30, vy: -60,
    life: 0.8, r: 0,
    color: isCrit ? '#ffeb3b' : '#fff',
    isDamageNumber: true,
    isCritStack: !!isCrit,
    text: isCrit ? dmg + '!' : '' + dmg,
    size: isCrit ? 18 : 13,
  });
}

function killEnemy(e) {
  e.dead = true;
  // Mini-boss-sekvens: när en miniboss dör → spawna en interlude-wave av enemies.
  // När alla enemies cleared → nästa miniboss spawnar (i updateZoneProgression).
  if (e.isMiniBoss && !e._miniBossNextSpawned) {
    e._miniBossNextSpawned = true;
    const stage = getStage(state.wave);
    const miniList = stage && (stage.miniBosses || (stage.miniBoss ? [stage.miniBoss] : []));
    if (miniList && (state.miniBossesSpawned || 0) < miniList.length) {
      // Mer minibosses kvar → starta interlude-wave så player får andas + nya enemies
      state._miniInterludeActive = true;
      state._miniInterludePending = true; // BLOCKAR clearing-flow tills enemies har spawnats
      state._miniInterludeNextIdx = state.miniBossesSpawned;
      const zones = stage.zones || [];
      const pool = (zones[Math.min(state.currentZone || 0, zones.length - 1)] || zones[0] || { pool: ['grunt'] }).pool;
      const count = 5 + Math.floor(Math.random() * 3);
      const sw = stage.worldW, sh = stage.worldH;
      const stageWaveAtSchedule = state.wave;
      if (state._interludeTimerId) clearTimeout(state._interludeTimerId);
      state._interludeTimerId = setTimeout(() => {
        state._interludeTimerId = null;
        state._miniInterludePending = false;
        if (state.mode !== 'playing') return;
        if (!state._miniInterludeActive) return;
        if (state.wave !== stageWaveAtSchedule) return;
        for (let i = 0; i < count; i++) {
          const t = pool[Math.floor(Math.random() * pool.length)];
          const angle = Math.random() * Math.PI * 2;
          const dist = 350 + Math.random() * 200;
          const ex = (state.player ? state.player.x : sw/2) + Math.cos(angle) * dist;
          const ey = (state.player ? state.player.y : sh/2) + Math.sin(angle) * dist;
          const ne = makeEnemy(t,
            Math.max(40, Math.min(sw - 40, ex)),
            Math.max(40, Math.min(sh - 40, ey)));
          state.enemies.push(ne);
        }
        if (count > 0 && typeof showToast === 'function') showToast('⚠ FÖRSTÄRKNING ANLÄNDER');
      }, 600);
    }
  }
  const p = state.player;
  const goldMul = p ? (p.goldMul || 1) : 1;
  const goldGained = Math.round(e.gold * goldMul);
  state.goldThisRun += goldGained;
  save.gold += goldGained;
  // Coop: dela gold till alla partners
  if (Coop.active && Coop.isHost && goldGained > 0) {
    Coop.broadcast({ type: 'gold_share', g: goldGained, boss: !!e.isBoss });
  }
  // Coop kill-attribution (för leaderboard)
  if (Coop.active && Coop.isHost) {
    const pid = e.lastDamagerPid;
    if (pid && Coop.players.has(pid)) {
      const pt = Coop.players.get(pid);
      pt.kills = (pt.kills || 0) + 1;
      if (e.isBoss) pt.bossKills = (pt.bossKills || 0) + 1;
      pt.gold = (pt.gold || 0) + goldGained;
    } else {
      state.hostKills = (state.hostKills || 0) + 1;
      if (e.isBoss) state.hostBossKills = (state.hostBossKills || 0) + 1;
    }
  }
  state.killsThisWave++;
  state.killsThisRun = (state.killsThisRun || 0) + 1;
  state.totalKills = (state.totalKills || 0) + 1;
  save.stats.totalKills++;
  if (killCountEl) killCountEl.textContent = state.killsThisRun;
  // Mini-boss firande
  if (e.isMiniBoss) {
    showToast('💥 ' + (e.name || 'MINI-BOSS') + ' NEDLAGD!');
    triggerShake(12, 0.5);
    spawnParticles(e.x, e.y, '#ffae3a', 30, 280);
    // Dubbel-shockwave + spark-burst
    spawnShockwave(e.x, e.y, e.r * 1.2, e.r * 5, '#ffae3a', 0.45, 3);
    setTimeout(() => spawnShockwave(e.x, e.y, e.r, e.r * 8, '#ff5a3a', 0.5, 2), 150);
    spawnSparks(e.x, e.y, '#ffae3a', 12, 300);
    // v1.577: SURVIVORS skippar bonus-pickups (inga drops, bara pengar/perks)
    if (!state.survivorsActive) {
      spawnPickup(e.x - 25, e.y, 'hp');
      spawnPickup(e.x + 25, e.y, 'ammo');
      spawnPickup(e.x, e.y + 25, 'temp_dmg');
    }
  }
  // Vapen-XP — det vapen som var equippat när fienden dog
  if (p && p.weaponId) {
    addWeaponXp(p.weaponId, e.isBoss ? 50 : (e.gold > 12 ? 3 : 1));
  }
  save.stats.totalGold = (save.stats.totalGold || 0) + goldGained;
  if (e.isBoss) save.stats.bossKills++;
  Achievements.check();
  spawnParticles(e.x, e.y, e.color, 10, 140);
  // Kill shockwave — snabb ring + gnistor så varje kill känns punchy.
  spawnShockwave(e.x, e.y, e.r * 1.2, e.r * 3.5, '#ffe9a0', 0.35, 2);
  spawnSparks(e.x, e.y, '#ffd14a', 5, 200);
  // Throttle: max ett kill-ljud per 70ms så AoE/avatar-summon-massmord inte stackar
  // 5 ljud ovanpå varandra → ljudgrums. Mini-boss/boss kringgår throttle (ovanliga).
  const _nowKill = performance.now();
  if (e.isBoss || e.isMiniBoss || _nowKill - (state._lastKillSfx || 0) > 70) {
    Audio.kill();
    state._lastKillSfx = _nowKill;
  }
  if (e.gold >= 10) Audio.goldPickup();
  // Ultimate cheat: massive explosion at kill
  if (isCheatActive('ultimate')) {
    explode(e.x, e.y, 200, 100, true);
    triggerShake(15, 0.3);
  }
  // Gold-attraction-trail (3 mynt-partiklar flyger uppåt)
  if (goldGained > 0 && getQualityMul() > 0.5) {
    for (let i = 0; i < 3; i++) {
      state.particles.push({
        x: e.x + (Math.random()-0.5)*10,
        y: e.y + (Math.random()-0.5)*10,
        vx: (Math.random()-0.5) * 80,
        vy: -120 - Math.random() * 60,
        life: 0.7,
        color: '#ffd54a', r: 2.5,
        isGoldCoin: true,
      });
    }
  }
  // Killstreak — räknar kills inom 3s av varandra
  const now = performance.now();
  if (!state.killstreak || now - state.lastKillTime > 3000) state.killstreak = 0;
  state.killstreak++;
  state.lastKillTime = now;
  // Tröskel 3 → 5: rocket/blackhole/AoE-vapen procade banner varje wave → tapet.
  if (state.killstreak >= 5) showKillstreakBanner(state.killstreak);
  if (state.killstreak >= 10) Achievements.unlock('streak10');
  if (state.killstreak >= 20) Achievements.unlock('streak20');
  // Blod-puddel som death-animation
  state.particles.push({
    x: e.x, y: e.y, vx: 0, vy: 0, life: 3.5, color: 'rgba(80,0,0,0.7)',
    r: e.r * 0.9, isBloodPool: true,
  });
  // Vampyrism perk: 3 HP/kill (nerf från 4 — 240 HP/wave trivializerade hardcore)
  if (p && hasPerk('vampire')) {
    p.hp = Math.min(p.maxHp, p.hp + 3);
  }
  // v1.579: SURVIVORS — bara HP + shield-drops (inga pengar/ammo/temp_dmg).
  // Pengar ges direkt via goldGained-counter (instant, ingen pickup).
  if (state.survivorsActive) {
    const dropChance = e.isBoss ? 1.0 : (e.gold > 15 ? 0.22 : 0.10);
    if (Math.random() < dropChance) {
      const r = Math.random();
      if (e.isBoss) {
        // Boss droppar både hp + shield
        spawnPickup(e.x - 18, e.y, 'hp');
        spawnPickup(e.x + 18, e.y, 'shield');
        spawnPickup(e.x, e.y + 18, 'hp');
      } else if (r < 0.6) {
        spawnPickup(e.x, e.y, 'hp');
      } else {
        spawnPickup(e.x, e.y, 'shield');
      }
    }
  } else {
    // Drop-chans (mer från större fiender) — STANDARD CD/story-mode
    const dropChance = e.isBoss ? 1.0 : (e.gold > 15 ? 0.18 : 0.08);
    if (Math.random() < dropChance) {
      const r = Math.random();
      let type;
      if (e.isBoss) {
        spawnPickup(e.x - 20, e.y, 'temp_dmg');
        spawnPickup(e.x + 20, e.y, 'hp');
        spawnPickup(e.x, e.y + 20, 'ammo');
      } else if (p && p.hp / p.maxHp < 0.5 && r < 0.4) {
        type = 'hp';
      } else if (r < 0.3 && p && p.weaponId !== 'fists') {
        type = 'ammo';
      } else if (r < 0.7) {
        type = 'gold';
      } else {
        type = 'temp_dmg';
      }
      if (type) spawnPickup(e.x, e.y, type);
    }
  }
  // Kraftbrand — sprid burn till närmsta fiende
  if (hasPerk('firespread') && e.burnUntil && performance.now() < e.burnUntil) {
    let best = null, bestD = 220;
    for (const other of state.enemies) {
      if (other === e || other.dead) continue;
      const d = Math.hypot(other.x - e.x, other.y - e.y);
      if (d < bestD) { bestD = d; best = other; }
    }
    if (best) {
      best.burnUntil = performance.now() + 2200;
      best.burnDps = Math.max(best.burnDps || 0, e.burnDps || 4);
      // visuell flame-spridning
      state.particles.push({
        x: e.x, y: e.y, vx: 0, vy: 0, life: 0.25, color: '#ff8a30', r: 0,
        isLightning: true, x2: best.x, y2: best.y,
      });
    }
  }
  if (e.isBoss) {
    state.bossAlive = false;
    spawnParticles(e.x, e.y, '#ffeb3b', 30, 220);
    Audio.bossDeath();
    Music.setIntensity('active'); // tysta boss-spänning
    // 25px shake @ 1.2s var orkanmessigt på 6" mobil i landscape — cap till 16px
    triggerShake(16, 1.0);
    triggerHitStop(150); // dramatisk paus
    // Trippel-shockwave + gnistor + flame-burst
    spawnShockwave(e.x, e.y, e.r, e.r * 6, '#ffeb3b', 0.5, 4);
    setTimeout(() => spawnShockwave(e.x, e.y, e.r, e.r * 9, '#ff9a3a', 0.55, 3), 120);
    setTimeout(() => spawnShockwave(e.x, e.y, e.r, e.r * 12, '#ff3a3a', 0.55, 2), 280);
    spawnSparks(e.x, e.y, '#ffd14a', 18, 380);
    // Slow-mo + zoom på boss-död
    state.bossDeathCinematic = {
      x: e.x, y: e.y, startTime: performance.now(), duration: 1500, name: e.name,
    };
    // Multipla shockwaves
    state.particles.push({ x: e.x, y: e.y, vx:0, vy:0, life: 0.6, color: '#ffeb3b', r: e.r * 4, isExplosion: true });
    setTimeout(() => state.particles && state.particles.push({ x: e.x, y: e.y, vx:0, vy:0, life: 0.5, color: '#fff', r: e.r * 6, isExplosion: true }), 200);
    setTimeout(() => state.particles && state.particles.push({ x: e.x, y: e.y, vx:0, vy:0, life: 0.4, color: '#ff5a3a', r: e.r * 8, isExplosion: true }), 400);
    // Andra bossen i sekvens?
    const stage = getStage(state.wave);
    if (stage.bossKey2 && state.bossSequenceStep === 1) {
      setTimeout(() => spawnSecondBoss(stage), 1200);
    } else {
      state.bossDefeated = true;
      if (window._debug) console.log('[GAME] Boss dead — väntar på att alla minions är döda');
    }
  }
  updateHUD();
}

// ============================================================
// STAGE EVENTS
// ============================================================
function triggerStageEvent(stage, eventType) {
  const p = state.player;
  showToast(eventNames[eventType] || '!');
  // Visuell signalering: shake + röd vinjett-pulse så spelaren känner att något händer.
  // Tidigare bara en liten text-toast — i strids-flöde missades det helt.
  triggerShake(6, 0.35);
  state.eventVignetteUntil = performance.now() + 500;
  // I serverSim-mode äger SERVERN entity-listan — skip lokal spawn (annars står
  // hundarna stilla för server vet inget om dem).
  if (Coop.serverSimActive) return;
  if (eventType === 'release_dogs') {
    // 4 hundar spawnar från sidorna
    for (let i = 0; i < 4; i++) {
      const side = i < 2 ? 60 : stage.worldW - 60;
      const y = 400 + i * 200;
      const e = makeEnemy('dog', side, y);
      state.enemies.push(e);
    }
  }
  if (eventType === 'alarm') {
    state.alarmUntil = performance.now() + 4000;
    // 3 förstärkningar spawnar nära portalen
    for (let i = 0; i < 3; i++) {
      const e = makeEnemy('shooter', stage.goalPos.x + (i-1)*60, stage.goalPos.y + 200);
      state.enemies.push(e);
    }
  }
  if (eventType === 'open_doors') {
    // Ninjor spawnar genom korridor-dörrar
    state.alarmUntil = performance.now() + 2500;
    for (let i = 0; i < 4; i++) {
      const x = i % 2 === 0 ? 250 : stage.worldW - 250;
      const y = 600 + i * 300;
      const e = makeEnemy('ninja', x, y);
      state.enemies.push(e);
    }
  }
  if (eventType === 'barracks_open') {
    // Vakter ut ur barackerna (4 hörn)
    const corners = [
      { x: 240, y: 220 }, { x: stage.worldW - 240, y: 220 },
      { x: 240, y: stage.worldH - 220 }, { x: stage.worldW - 240, y: stage.worldH - 220 },
    ];
    for (const c of corners) {
      state.enemies.push(makeEnemy('brute', c.x, c.y));
    }
  }
  if (eventType === 'fuel_blast') {
    // Bränsletruck exploderar — eldspår på golvet
    const cx = stage.worldW * 0.6, cy = stage.worldH / 2;
    explode(cx, cy, 140, 0, true); // visuell
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * Math.PI * 2;
      state.flameTrails.push({
        x: cx + Math.cos(a) * 60, y: cy + Math.sin(a) * 60,
        r: 50, life: 6, dps: 18,
      });
    }
    state.alarmUntil = performance.now() + 1500;
  }
  if (eventType === 'barrel_chain') {
    // Kedjereaktion av exploderande fat
    let delay = 0;
    for (const d of stageState.decorations) {
      if (d.kind === 'fuel_drum' && Math.random() < 0.4) {
        const dx = d.x, dy = d.y;
        setTimeout(() => {
          if (state.mode !== 'playing') return;
          explode(dx, dy, 90, 25, true);
        }, delay);
        delay += 180;
      }
    }
  }
  if (eventType === 'crane_drop') {
    // Container faller från kran — krockar med golv vid slutet
    const cx = stage.worldW / 2 + 200, cy = stage.worldH * 0.4;
    state.craneDropAnim = { x: cx, y: cy, startTime: performance.now(), duration: 1400 };
    setTimeout(() => {
      if (state.mode !== 'playing') return;
      explode(cx, cy, 140, 0, true);
      // Ny cover spawnas
      stageState.buildings.push({ x: cx - 50, y: cy - 30, w: 100, h: 60, kind: 'container' });
    }, 1400);
  }
  if (eventType === 'lights_flicker') {
    state.lightsFlickerUntil = performance.now() + 5000;
    // 4 fiender spawnar i mörkret
    for (let i = 0; i < 4; i++) {
      const e = makeEnemy('ninja', 200 + Math.random()*(stage.worldW-400), 300 + Math.random()*(stage.worldH-600));
      state.enemies.push(e);
    }
  }
  if (eventType === 'core_pulse' || eventType === 'jimmy_screens') {
    // Omega-kärnan pulserar — alla skärmar lyser rött, alarm-ljud
    state.jimmyScreensUntil = performance.now() + 8000;
    state.alarmUntil = performance.now() + 3000;
  }
}
const eventNames = {
  release_dogs: 'HUNDARNA SLÄPPS!',
  alarm: '⚠ LARMET GÅR ⚠',
  open_doors: 'NINJOR I KORRIDOREN!',
  barracks_open: 'BARACKERNA TÖMS!',
  fuel_blast: '💥 BRÄNSLETRUCK!',
  barrel_chain: '💥 KEDJEREAKTION!',
  crane_drop: '⚠ KRANEN SLÄPPER!',
  lights_flicker: '⚡ LJUSEN SLOCKNAR',
  core_pulse: '⚡ KÄRNAN PULSERAR',
  jimmy_screens: '⚡ KÄRNAN PULSERAR', // backward-compat
};

// ============================================================
// PARTIKLAR / FX
// ============================================================
function getQualityMul() {
  const q = save.quality || 'medium';
  let base = 1.0;
  if (q === 'low') base = 0.4;
  else if (q === 'high') base = 1.4;
  // Coop = ännu lägre kvalitet (mer enemies + nätverk = behöver CPU för andra saker)
  if (Coop && Coop.active && Coop.players && Coop.players.size > 0) {
    base *= 0.6;
    // Auto-drop ytterligare baserat på server-RTT så frame-budget bevaras vid laggy
    // anslutningar. Klient med 250ms+ ping har ändå "knyckig" upplevelse — vi köper
    // tillbaka stabilitet genom att sänka partikel-budget + decoration-cull.
    const rtt = Coop._serverRtt || 0;
    if (rtt > 250) base *= 0.5;
    else if (rtt > 150) base *= 0.75;
  }
  return base;
}
function spawnParticles(x, y, color, count, speed) {
  const adjusted = Math.max(1, Math.round(count * getQualityMul()));
  for (let i = 0; i < adjusted; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = speed * (0.4 + Math.random() * 0.8);
    state.particles.push({
      x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s,
      life: 0.4 + Math.random()*0.4, color,
      r: 2 + Math.random()*2,
    });
  }
}
function spawnSlash(x, y, ang, reach, color) {
  state.particles.push({
    x, y, vx:0, vy:0, life: 0.18, color,
    r: reach, isSlash: true, ang,
  });
}
function explode(x, y, radius, dmg, friendly) {
  spawnParticles(x, y, '#ffb84a', 24, 280);
  state.particles.push({ x, y, vx:0, vy:0, life: 0.35, color: '#ffb84a', r: radius, isExplosion: true });
  // Shockwave + sparks — gör att även små explosioner känns punchy
  spawnShockwave(x, y, radius * 0.4, radius * 1.6, '#ff8a3a', 0.4, 3);
  spawnSparks(x, y, '#ffd14a', Math.min(14, Math.round(radius / 12)), 280, 280);
  Audio.explosion();
  triggerShake(12, 0.4);
  if (friendly) {
    for (const e of state.enemies) {
      const d = Math.hypot(e.x - x, e.y - y);
      if (d <= radius + e.r) {
        const falloff = 1 - d / (radius + e.r);
        damageEnemy(e, dmg * Math.max(0.3, falloff));
      }
    }
  } else {
    const p = state.player;
    const d = Math.hypot(p.x - x, p.y - y);
    if (d <= radius + p.r) {
      const falloff = 1 - d / (radius + p.r);
      // Sprängskydd-perk halverar
      const safeMul = hasPerk('blastsafe') ? 0.5 : 1;
      damagePlayer(dmg * Math.max(0.3, falloff) * safeMul, 'explosion');
    }
  }
}

function damagePlayer(amount, source) {
  const p = state.player;
  if (p.invuln > 0) return;
  // Ultimate cheat = odödlig
  if (isCheatActive('ultimate')) return;
  // Spectator-mode (redan död) — ta inte mer skada
  if (p.spectating) return;
  // Mountad på turret = osårbar (bara trucken tar skada)
  if (p._mountedTurretId) return;
  // v1.608: SURVIVORS DODGE-perk — chans att helt undvika skada
  if (state.survivorsActive && typeof getSurvivorsPerkSum === 'function') {
    const dodgeChance = getSurvivorsPerkSum('dodge');
    if (dodgeChance > 0 && Math.random() < dodgeChance) {
      // Visuell feedback: vit shockwave + toast
      if (typeof spawnShockwave === 'function') {
        spawnShockwave(p.x, p.y, 4, 24, '#ffffff', 0.2, 1);
      }
      p.invuln = 0.15;
      return;
    }
    // RESIST-perk — reducera inkommande skada
    const resist = getSurvivorsPerkSum('resist');
    if (resist > 0) amount = amount * Math.max(0.2, 1 - resist);
  }
  // Track senaste damage-källa för death-feedback ("du dog från X")
  if (source) state._lastDamageSource = source;
  p.hp -= amount;
  p.flashUntil = performance.now() + 120;
  p.invuln = 0.3;
  Audio.playerHurt();
  triggerShake(8, 0.3);
  triggerVibrate(40);
  // Skärm-flash + small shockwave runt spelaren så damage känns punchy.
  state.dmgFlashUntil = performance.now() + 180;
  spawnShockwave(p.x, p.y, 8, 32, '#ff3a3a', 0.25, 2);
  if (p.hp <= 0) {
    // v1.608: SURVIVORS PHOENIX-perk — vid död explodera + revive med 50% HP
    if (state.survivorsActive && typeof getSurvivorsPerkSum === 'function'
        && getSurvivorsPerkSum('phoenix') > 0 && !state.survivorsPhoenixUsed) {
      state.survivorsPhoenixUsed = true;
      p.hp = Math.round((p.maxHp || 100) * 0.5);
      p.invuln = 3.0;
      if (typeof explode === 'function') explode(p.x, p.y, 250, 300, true);
      if (typeof triggerShake === 'function') triggerShake(20, 0.6);
      if (typeof Audio !== 'undefined' && Audio.revive) Audio.revive();
      p.flashUntil = performance.now() + 800;
      state.particles.push({
        x: p.x, y: p.y, vx: 0, vy: 0, life: 1.0, color: '#ff6a3a', r: 200, isExplosion: true,
      });
      if (typeof showToast === 'function') showToast('🔥 FENIX! — 50% HP ÅTERSTÄLLD');
      if (typeof updateHUD === 'function') updateHUD();
      return;
    }
    // v1.530: SURVIVORS-RUN "ANDRA CHANS"-perk — återupplivas med 1 HP en gång per match
    if (state.survivorsActive && typeof getSurvivorsPerkSum === 'function' && getSurvivorsPerkSum('revive') > 0 && !state.survivorsReviveUsed) {
      state.survivorsReviveUsed = true;
      p.hp = 1;
      p.invuln = 3.0;
      if (typeof Audio !== 'undefined' && Audio.revive) Audio.revive();
      p.flashUntil = performance.now() + 600;
      state.particles.push({
        x: p.x, y: p.y, vx: 0, vy: 0, life: 0.7, color: '#aa5aff', r: 100, isExplosion: true,
      });
      if (typeof showToast === 'function') showToast('✨ ANDRA CHANS — 1 HP kvar!');
      if (typeof updateHUD === 'function') updateHUD();
      return;
    }
    // Andra chans perk (story-mode upgrade)
    if (p.reviveAvailable) {
      p.reviveAvailable = false;
      p.hp = p.maxHp * 0.5;
      p.invuln = 2.5;
      Audio.revive();
      Achievements.unlock('survive');
      p.flashUntil = performance.now() + 600;
      // visuell revive-effekt
      state.particles.push({
        x: p.x, y: p.y, vx:0, vy:0, life: 0.7, color: '#aa5aff', r: 100, isExplosion: true,
      });
      showToast('ANDRA CHANS!');
      updateHUD();
      return;
    }
    // Last-laugh perk: explosion vid död
    if (hasPerk('lastlaugh')) {
      explode(p.x, p.y, 250, 200, true);
      triggerShake(20, 0.6);
    }
    p.hp = 0;
    state.hostDeaths = (state.hostDeaths || 0) + 1;
    enterDeathState();
  }
  updateHUD();
}

// DÖD-SYSTEM
function enterDeathState() {
  const p = state.player;
  if (!p) return;
  // Skapa kropp på dödsplatsen
  state.deadBody = {
    x: p.x, y: p.y, reviveTimer: 0, revivedBy: null,
    color: getCurrentCostume().shirt || '#222',
  };
  // Death-cam: slow-mo + heavy shake + radial dark vignette i 1500ms
  state.deathCamUntil = performance.now() + 1500;
  triggerHitStop(180);
  triggerShake(14, 0.6);
  // Big shockwave på death-platsen
  spawnShockwave(p.x, p.y, 12, 90, '#ff3a3a', 0.5, 3);
  spawnSparks(p.x, p.y, '#ff5a5a', 16, 280, 200);
  p.spectating = true;
  p.specTarget = null; // välj live-player att speca
  // Visa orsak om vi spårat senaste damage-källan
  const cause = state._lastDamageSource ? ' — ' + state._lastDamageSource : '';
  showToast('💀 DU DOG' + cause);
  // I coop: vänta på revive eller all-dead game-over (checkCoopAllDead sköter)
  if (Coop.active) {
    for (const [pid, partner] of Coop.players) {
      if (partner.hp > 0) { p.specTarget = pid; break; }
    }
  } else {
    // Single-player: revive-perk ger second chance, annars game over
    if (p.reviveAvailable && hasPerk('revive')) {
      p.reviveAvailable = false;
      setTimeout(() => {
        if (!state.player || !state.player.spectating) return;
        state.deadBody = null;
        state.player.spectating = false;
        state.player.hp = state.player.maxHp * 0.5;
        state.player.invuln = 2.0;
        showToast('💚 REVIVE!');
      }, 1500);
    } else {
      // Riktig solo death — visa game-over efter en kort respit så toast hinner ses
      setTimeout(() => {
        if (state.mode !== 'playing') return;
        endGame(false);
      }, 1500);
    }
  }
}

// Coop: Game over om alla spelare är döda (host kontrollerar)
function checkCoopAllDead() {
  if (!Coop.active || !Coop.isHost) return;
  if (state._coopGameOverFired) return;
  if (state.mode !== 'playing') return;
  // PvP-modes har egna match-end-villkor (mode_match_end-events). Död är bara
  // ett 3s respawn-fönster — game-over på "alla döda" ska INTE triggas där.
  if (Coop.gungameActive || Coop.tdmActive || Coop.ctfActive || Coop.siegeActive || Coop.kothActive || Coop.juggernautActive || Coop.battleroyaleActive) return;
  const hostDead = !state.player || state.player.hp <= 0 || state.player.spectating;
  if (!hostDead) return;
  let anyAlive = false;
  for (const [, partner] of Coop.players) {
    if (partner && partner.hp > 0) { anyAlive = true; break; }
  }
  if (anyAlive) return;
  // ALLA är döda — game over
  state._coopGameOverFired = true;
  Coop.broadcast({ type: 'event', event: 'game_over' });
  endGame(false);
}

function updateDeathState(dt) {
  if (!state.deadBody || !state.player) return;
  const body = state.deadBody;
  const p = state.player;
  // Update spec-camera följer specTarget i coop
  if (p.spectating && p.specTarget && Coop.players.has(p.specTarget)) {
    const target = Coop.players.get(p.specTarget);
    p.x += (target.x - p.x) * 0.1;
    p.y += (target.y - p.y) * 0.1;
  }
  // Coop: kolla om någon partner står på kroppen i 5 sek
  if (Coop.active) {
    let anyReviving = false;
    for (const [pid, partner] of Coop.players) {
      if (partner.hp <= 0) continue;
      const d = Math.hypot(partner.x - body.x, partner.y - body.y);
      if (d < 50) {
        anyReviving = true;
        body.reviveTimer += dt;
        body.revivedBy = pid;
        if (body.reviveTimer >= 5) {
          // Återuppliv!
          p.x = body.x; p.y = body.y;
          p.hp = p.maxHp * 0.5;
          p.spectating = false;
          p.specTarget = null;
          p.invuln = 2;
          state.deadBody = null;
          Audio.revive();
          showToast('💚 ÅTERUPPLIVAD');
          spawnParticles(p.x, p.y, '#5aff5a', 30, 220);
        }
        break;
      }
    }
    if (!anyReviving) body.reviveTimer = Math.max(0, body.reviveTimer - dt);
  }
}

function drawDeadBody() {
  if (!state.deadBody) return;
  const body = state.deadBody;
  const x = body.x - state.camera.x;
  const y = body.y - state.camera.y;
  const t = performance.now();
  // Liggande kropp
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.beginPath(); ctx.ellipse(x + 4, y + 8, 22, 8, 0, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = body.color;
  ctx.beginPath(); ctx.ellipse(x, y, 18, 11, 0.3, 0, Math.PI*2); ctx.fill();
  // Blod
  ctx.fillStyle = 'rgba(120,0,0,0.5)';
  ctx.beginPath(); ctx.ellipse(x - 2, y + 3, 14, 6, 0.3, 0, Math.PI*2); ctx.fill();
  // Revive-indikator
  if (body.reviveTimer > 0) {
    const frac = body.reviveTimer / 5;
    ctx.strokeStyle = '#5aff5a';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(x, y, 28, -Math.PI/2, -Math.PI/2 + frac * Math.PI*2);
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#5aff5a';
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('REVIVING ' + Math.ceil(5 - body.reviveTimer) + 's', x, y - 36);
  } else {
    // Spec-info
    ctx.fillStyle = '#ff5a3a';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    ctx.fillText('💀 DÖD', x, y - 20);
    if (Coop.active && Coop.playerCount() > 1) {
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'bold 10px sans-serif';
      ctx.fillText('Stå nära 5s för revive', x, y - 36);
    }
    ctx.shadowBlur = 0;
  }
  ctx.restore();
}

// ============================================================
// SPAWNING / NIVÅER
// ============================================================
function startWave(n) {
  // Story-coop: lås upp progressivt vapen för denna wave
  if (isCoopStoryMode()) {
    const entry = COOP_STORY_WEAPON_UNLOCKS[n];
    if (entry) {
      const list = Array.isArray(entry) ? entry : [entry];
      for (const wid of list) {
        if (!save.owned.includes(wid)) {
          save.owned.push(wid);
          const w = getWeapon(wid);
          if (typeof showToast === 'function' && w) showToast('🔓 NYTT VAPEN: ' + w.name);
          if (typeof Audio !== 'undefined' && Audio.achievement) Audio.achievement();
        }
      }
    }
  }
  loadStage(n);
}

function loadStage(n) {
  const stage = getStage(n);
  if (!stage) { endGame(true); return; }
  // Stage-transition white-flash (utöver stage 1 där det är onödigt)
  if (state.wave && n > state.wave) {
    state.stageTransitionUntil = performance.now() + 600;
  }
  state.wave = n;
  state.killsThisWave = 0;
  state.bossAlive = false;
  state.enemies = [];
  state.bullets = [];
  state.pickups = [];
  state.particles = [];
  state.gasClouds = [];
  state.flameTrails = [];

  // Zon-system
  state.currentZone = 0;
  state.zoneState = 'spawning';
  state.eventTriggered = false;
  state.bossSequenceStep = 0;
  state.bossDefeated = false;
  state._stageClearShown = false;
  state._waveCompleting = false;
  state._coopGameOverFired = false;
  // Mini-boss state — counter är single source of truth (miniBossSpawned bool
  // borttagen pga split-brain mellan flow-paths)
  state.miniBossesSpawned = 0;
  state._miniInterludeActive = false;
  state._miniInterludePending = false;
  state._miniInterludeNextIdx = 0;
  // Avbryt eventuell pending interlude-timer från föregående stage
  if (state._interludeTimerId) {
    clearTimeout(state._interludeTimerId);
    state._interludeTimerId = null;
  }
  // Truck-mode setup
  if (stage.isTruckMode) {
    setupTruck(stage);
    if (truckTurretBarEl) truckTurretBarEl.classList.remove('hidden');
  } else {
    state.truck = null;
    if (truckTurretBarEl) truckTurretBarEl.classList.add('hidden');
  }
  // Coop: clear enemy interpolation cache (gammal stage) + visual-only bullets
  if (state._enemyCache) state._enemyCache = {};
  if (Coop.active) state.bullets = (state.bullets || []).filter(b => !b._visualOnly);

  // Uppdatera världsdimensioner per stage
  WORLD.w = stage.worldW;
  WORLD.h = stage.worldH;

  // Generera per-stage layout
  buildStageLayout(stage);

  // Teleportera spelaren till stage-spawn + återställ död-state (annars fastnar man som spectator efter stage clear)
  if (state.player) {
    state.player.x = stage.spawnPos.x;
    state.player.y = stage.spawnPos.y;
    state.player.invuln = 1.0;
    state.player.shotsThisStage = 0;
    state.player.spectating = false;
    state.player.specTarget = null;
    if (state.player.hp <= 0) state.player.hp = state.player.maxHp;
  }
  state.deadBody = null;
  // Andra chans återställs INTE per stage längre — bara per RUN (i startGame)
  state.camera.x = state.player.x - viewW/2;
  state.camera.y = state.player.y - viewH/2;

  state.fadeIn = { startTime: performance.now(), duration: 500 };
  state.bossIntro = null;

  // 5s prep-countdown vid stage-start så spelaren hinner positionera. Gäller även
  // solo (var coop-only innan men då fick solo aldrig prep-tid).
  // Skip i serverSim-mode: server skickar sitt eget countdown_start.
  if (!Coop.serverSimActive) {
    state._countdownEndAt = performance.now() + 5000;
    state._countdownLabel = 'FÖRBERED';
    // v1.378: rensa stale input så user inte kan smyga in actions
    input.firing = false;
    input.fireJoyActive = false;
    if (typeof state.grenadeAim !== 'undefined') state.grenadeAim = null;
    if (Coop.active && Coop.isHost) {
      Coop.broadcast({ type: 'event', event: 'countdown_start', durationMs: 5000 });
    }
  }

  // Tracking-flags för achievements
  state.stageStartTime = performance.now();
  state.shopBoughtThisStage = 0;
  state.regenedThisStage = 0;
  state.weaponsUsedThisStage = new Set();
  state.maxBossDmgThisStage = 0;
  state.killstreak = 0;
  killstreakBanner = { text: '', timer: 0, count: 0 };
  // Sandbox: spawna 5 dummies som re-spawnar
  if (stage.sandbox) {
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * Math.PI * 2;
      const e = makeEnemy('grunt', stage.spawnPos.x + Math.cos(a) * 250, stage.spawnPos.y + Math.sin(a) * 250);
      e.hp = 99999; e.maxHp = 99999; e.dmg = 0; e.speed = 0;
      e.dummy = true;
      state.enemies.push(e);
    }
  }
  // Starta första zonen
  startZone(stage, 0);
  state.waveActive = true;
  showToast(`STAGE ${n} — ${stage.name}`);
  Audio.stageStart();
  // Starta stage-musik
  Music.startStage(stage.kind);
  Music.setIntensity('active');
  // Story-dialog innan stage (story-mode)
  showStoryDialog(n);
  updateHUD();
}

function startZone(stage, zoneIdx) {
  const zones = stage.zones || [{ count: 8, pool: ['grunt'] }];
  if (zoneIdx >= zones.length) {
    // Klart med alla zoner — spawna boss (om inte sandbox/idle)
    if (stage.sandbox) {
      // Sandbox: ingen boss, ingen progression — bara idle-state
      state.zoneState = 'idle';
      return;
    }
    spawnBoss(stage);
    return;
  }
  const z = zones[zoneIdx];
  state.currentZone = zoneIdx;
  state.zoneState = 'spawning';
  state.enemiesToSpawn = z.count;
  state.spawnTimer = 0.5;
  state.eventTriggered = false;
  state.activeZonePool = z.pool;
}

function spawnBoss(stage) {
  state.zoneState = 'boss';
  const boss = makeBoss(stage.bossKey, stage.goalPos.x, stage.goalPos.y);
  if (boss) {
    state.enemies.push(boss);
    state.bossAlive = true;
    state.bossSequenceStep = 1;
    // Korta boss-intro när spelaren redan sett denna boss (NG+, repris) — 2400→1200ms.
    const seen = save.bossesSeen && save.bossesSeen[stage.bossKey];
    const introDur = seen ? 1200 : 2400;
    state.bossIntro = { startTime: performance.now(), duration: introDur, name: boss.name, sub: boss.subtitle, entrance: getBossEntrance(boss.bossKey) };
    boss.entranceUntil = performance.now() + introDur;
    save.bossesSeen = save.bossesSeen || {};
    save.bossesSeen[stage.bossKey] = true;
    persist();
    Audio.bossSpawn();
    triggerShake(12, 1.0);
    Music.setIntensity('boss');
  }
}

function getBossEntrance(key) {
  // Nya 9 finals — entrance baserad på första power i powerSet
  const entrances = {
    witheredelder: 'fade_in',
    ironclad: 'stomp',
    mirroredone: 'cloak_drop',
    ossarius: 'stomp',
    vanguardatlas: 'pod_break',
    emberoracle: 'jetpack_drop',
    blightsovereign: 'gas_emerge',
    buriedcrown: 'shield_slam',
    lastsovereign: 'final_descent',
  };
  return entrances[key] || 'fade_in';
}

function spawnSecondBoss(stage) {
  if (!stage.bossKey2) return;
  const boss = makeBoss(stage.bossKey2, stage.goalPos.x, stage.goalPos.y);
  if (boss) {
    state.enemies.push(boss);
    state.bossAlive = true;
    state.bossSequenceStep = 2;
    state.bossIntro = { startTime: performance.now(), duration: 2200, name: boss.name, sub: boss.subtitle };
    Audio.bossSpawn();
    triggerShake(12, 1.0);
    Music.setIntensity('boss');
  }
}

function spawnEnemyAtEdge() {
  const player = state.player;
  const stage = getStage(state.wave);
  const pool = state.activeZonePool || stage.enemyPool || ['grunt'];
  const type = pool[Math.floor(Math.random() * pool.length)];

  // spawn-pos: någonstans inom stage-bounds, helst närmare goal än player,
  // ej inuti byggnad, ej för nära player
  let x = 0, y = 0, ok = false;
  for (let tries = 0; tries < 14 && !ok; tries++) {
    // bias mot goal-sidan
    const t = 0.15 + Math.random() * 0.7;
    x = stage.spawnPos.x + (stage.goalPos.x - stage.spawnPos.x) * (1 - t)
      + (Math.random() - 0.5) * stage.worldW * 0.6;
    y = stage.spawnPos.y + (stage.goalPos.y - stage.spawnPos.y) * (1 - t)
      + (Math.random() - 0.5) * stage.worldH * 0.4;
    x = Math.max(40, Math.min(stage.worldW - 40, x));
    y = Math.max(40, Math.min(stage.worldH - 40, y));
    const distFromPlayer = Math.hypot(x - player.x, y - player.y);
    if (distFromPlayer < 320) continue;
    if (isInsideAnyBuilding(x, y, 18)) continue;
    ok = true;
  }
  if (!ok) return; // skip om vi inte hittar plats

  const e = makeEnemy(type, x, y);
  // Cap @ 4× för att förhindra omöjliga waves i Endless (wave 31+ = 4× scale)
  const scale = Math.min(1 + (state.wave - 1) * 0.10, 4.0);
  const diff = getDiffMul();
  const ngpMul = getNGPMul();
  // Daily modifier
  const dailyMod = state.dailyModifier ? state.dailyModifier.id : null;
  const dailyHpMul = dailyMod === 'reduced_hp' ? 0.85 : 1;
  const dailySpeedMul = dailyMod === 'fast_enemies' ? 1.5 : 1;
  // Endless-modifier
  const stageObj = getStage(state.wave);
  const endlessMod = stageObj && stageObj.endlessMod;
  const endlessHpMul = endlessMod && endlessMod.hpMul ? endlessMod.hpMul : 1;
  const endlessSpeedMul = endlessMod && endlessMod.speedMul ? endlessMod.speedMul : 1;
  const coopMul = getCoopMultiplier();
  e.hp = Math.round(e.hp * scale * diff.enemyHp * ngpMul * dailyHpMul * endlessHpMul * coopMul);
  e.maxHp = e.hp;
  e.dmg = Math.round(e.dmg * scale * diff.enemyDmg * ngpMul * (1 + (coopMul - 1) * 0.5));
  e.speed = Math.round(e.speed * dailySpeedMul * endlessSpeedMul);
  e._origSpeed = e.speed;
  if (e.bulletDmg) e.bulletDmg = Math.round(e.bulletDmg * diff.enemyDmg * ngpMul);
  state.enemies.push(e);
}

function isStageComplete() {
  if (!state.waveActive) return false;
  if (!state.bossDefeated) return false;
  // Alla minions måste också vara döda
  if (state.enemies.length > 0) return false;
  const stage = getStage(state.wave);
  if (stage.bossKey2 && state.bossSequenceStep < 2) return false;
  return true;
}

function spawnMiniBoss(stage, idx) {
  // idx = vilken miniboss i sekvensen (0/1/2). Om miniBosses-array → använd index.
  // Bakåtkompatibilitet: gamla single miniBoss-fältet stöds fortfarande.
  let m = null;
  if (stage.miniBosses && stage.miniBosses.length > 0) {
    m = stage.miniBosses[Math.min(idx || 0, stage.miniBosses.length - 1)];
  } else {
    m = stage.miniBoss;
  }
  if (!m) return;
  // Spawn-pos: 350-500px från player (random angle), så miniboss kommer in i fight
  // istället för att stå mitt på kartan långt bort. Clampa till stage-bounds.
  const p = state.player;
  let sx, sy;
  if (p) {
    const angle = Math.random() * Math.PI * 2;
    const dist = 350 + Math.random() * 150;
    sx = Math.max(60, Math.min(stage.worldW - 60, p.x + Math.cos(angle) * dist));
    sy = Math.max(60, Math.min(stage.worldH - 60, p.y + Math.sin(angle) * dist));
  } else {
    sx = stage.worldW / 2 + (Math.random() - 0.5) * 200;
    sy = stage.worldH / 2 + (Math.random() - 0.5) * 200;
  }
  const e = makeEnemy(m.type || 'brute', sx, sy);
  const scale = Math.min(1 + (state.wave - 1) * 0.10, 4.0);
  const diff = getDiffMul();
  const ngpMul = getNGPMul();
  const coopMul = getCoopMultiplier();
  e.hp = Math.round(e.hp * (m.hpMul || 4) * scale * diff.enemyHp * ngpMul * coopMul);
  e.maxHp = e.hp;
  e.dmg = Math.round(e.dmg * (m.dmgMul || 1.5) * scale * diff.enemyDmg * ngpMul);
  if (e.bulletDmg) e.bulletDmg = Math.round(e.bulletDmg * (m.dmgMul || 1.5));
  // v1.599: mini-bossar mellan minions (16-22) och bossar (32-46) — scale 1.3
  // För brute(22)*1.3=29, ninja(12)*1.3=16 → mini-boss r ~16-30 = klart mellan storlek
  e.r = Math.round(e.r * (m.scale || 1.3));
  e.speed = Math.round(e.speed * 1.1);
  e._origSpeed = e.speed;
  e.gold = m.gold || 100;
  e.isMiniBoss = true;
  e.miniBossIdx = idx || 0;
  e.name = m.name || 'Mini-boss';
  if (m.power) e.miniPower = m.power;
  // Stage-tema-färg: använd stage.accentColor som accent + edgeColor som glow.
  // Defensiv default-set så varje miniboss alltid har konsistenta tre nyanser
  // även för custom/edge-stages som saknar fält (endless-builder etc).
  e.stageAccent = stage.accentColor || '#7a5aaa';
  e.stageEdge = stage.edgeColor || '#aaff5a';
  e.stageBg = stage.bgColor || '#3a2a44';
  // Säkerställ miniIntensity är number (defensiv mot legacy-spawn utan idx)
  e.miniIntensity = (typeof e.miniIntensity === 'number') ? e.miniIntensity : 0;
  // Index-baserad intensitet (mini1=svag glow, mini3=stark glow)
  e.miniIntensity = (idx || 0) / 2; // 0, 0.5, 1.0
  state.enemies.push(e);
  showToast('⚠ MINI-BOSS ' + e.name + ' har spawnat');
  Audio.bossSpawn && Audio.bossSpawn();
  triggerShake(8, 0.4);
}

function updateZoneProgression(stage) {
  // FAIL-SAFE: Om boss aldrig spawnat och alla zoner är klara → tvinga spawn efter 3s
  if (stage && stage.bossKey && state.bossSequenceStep === 0) {
    const zones = stage.zones || [];
    const lastZoneDone = state.currentZone >= zones.length - 1;
    const noEnemies = state.enemies.length === 0 && state.enemiesToSpawn <= 0;
    if (lastZoneDone && noEnemies) {
      state._bossFailsafeTimer = (state._bossFailsafeTimer || 0) + 1/60;
      if (state._bossFailsafeTimer > 3) {
        state._bossFailsafeTimer = 0;
        spawnBoss(stage);
        return;
      }
    } else {
      state._bossFailsafeTimer = 0;
    }
  }
  if (state.zoneState === 'spawning' && state.enemiesToSpawn <= 0) {
    state.zoneState = 'clearing';
  }
  // Interlude-clear: kör BARA om timer redan firat (pending=false). Annars
  // hoppar vi över interlude-enemies och 3 minibosses spawnar i rad.
  if (state.enemies.length === 0 && state._miniInterludeActive && !state._miniInterludePending) {
    state._miniInterludeActive = false;
    const nextIdx = state._miniInterludeNextIdx || 0;
    const miniList2 = stage.miniBosses || (stage.miniBoss ? [stage.miniBoss] : []);
    if (nextIdx < miniList2.length) {
      state.miniBossesSpawned = nextIdx + 1;
      spawnMiniBoss(stage, nextIdx);
      return;
    }
    state.zoneState = 'clearing';
  }
  if (state.zoneState === 'clearing' && state.enemies.length === 0) {
    // Första minibossen: trigga om INGEN miniboss spawnats än (oavsett currentZone)
    // — currentZone===0-villkoret skapade soft-lock om event-zone bytte zone-index
    // innan clearing-checken körs.
    const miniList = stage.miniBosses || (stage.miniBoss ? [stage.miniBoss] : []);
    if (miniList.length > 0 && (state.miniBossesSpawned || 0) === 0) {
      state.miniBossesSpawned = 1;
      spawnMiniBoss(stage, 0);
      return;
    }
    // Sequence: vänta på att alla minibosses dödats innan zone-progression
    if (miniList.length > 0 && (state.miniBossesSpawned || 0) < miniList.length) {
      return;
    }
    // Zon clear — kör event om finns, annars nästa zon
    const zones = stage.zones || [];
    const z = zones[state.currentZone];
    if (z && z.event && !state.eventTriggered) {
      state.eventTriggered = true;
      triggerStageEvent(stage, z.event);
      state.zoneState = 'event';
      state.eventTimer = 1.2; // kort paus innan nästa zon
    } else {
      // Nästa zon
      const next = state.currentZone + 1;
      if (next < zones.length) {
        startZone(stage, next);
      } else if (state.bossSequenceStep === 0) {
        // Alla vanliga zoner klara — spawna boss
        spawnBoss(stage);
      }
    }
  }
  if (state.zoneState === 'event') {
    state.eventTimer -= 1/60;
    if (state.eventTimer <= 0) {
      const next = state.currentZone + 1;
      if (next < (stage.zones || []).length) {
        startZone(stage, next);
      } else if (state.bossSequenceStep === 0) {
        spawnBoss(stage);
      }
    }
  }
}

function onWaveComplete() {
  if (state._waveCompleting) return;
  state._waveCompleting = true;
  state.waveActive = false;
  save.wave = Math.max(save.wave, state.wave + 1);
  save.highWave = Math.max(save.highWave || 1, state.wave);
  // v1.524: Mode-records för endless/bossrush/survive/speedrun/daily borttagna
  // tillsammans med modes. Save.records lämnas intakt för bakåtkompatibilitet
  // (gamla saves kan ha records.endless etc, ignoreras).
  if (!save.records) save.records = {};
  Audio.zoneClear();
  // Wave-complete fanfare — gyllene shockwaves + sparks runt spelaren så stage-clear känns belönande
  if (state.player) {
    const p = state.player;
    spawnShockwave(p.x, p.y, 16, 140, '#ffd54a', 0.55, 5);
    setTimeout(() => spawnShockwave(p.x, p.y, 16, 220, '#ffae3a', 0.6, 4), 140);
    setTimeout(() => spawnShockwave(p.x, p.y, 20, 300, '#fff', 0.55, 3), 280);
    spawnSparks(p.x, p.y, '#ffd54a', 24, 380);
    triggerShake(6, 0.4);
  }
  if (window._debug) console.log('[GAME] Stage ' + state.wave + ' complete');
  // I coop: host broadcastar event till klienter
  if (Coop.active && Coop.isHost) {
    Coop.broadcast({ type: 'event', event: 'stage_complete' });
  }
  // v1.524: Boss rush gold-bonus borttagen (mode removed). Behåll variabel
  // för code-flöde — gold = 0 så ingen påverkan.
  if (false) {
    const bonus = state.wave * 100;
    save.gold += bonus;
    state.goldThisRun += bonus;
    showToast('+' + bonus + ' GOLD');
  }
  // Achievements: stage-baserade
  const stageTime = (performance.now() - (state.stageStartTime || 0)) / 1000;
  const stage = getStage(state.wave);
  if (stageTime < 60) Achievements.unlock('speedrun');
  if (state.wave === 1 && state.weaponsUsedThisStage && state.weaponsUsedThisStage.size === 1 && state.weaponsUsedThisStage.has('fists')) {
    Achievements.unlock('pacifist');
  }
  if ((state.regenedThisStage || 0) < 1) Achievements.unlock('noheal');
  if (state.wave === 5 && (state.shopBoughtThisStage || 0) === 0 && getMode() === 'story') {
    Achievements.unlock('noshop');
  }
  // oneshot Generalen (stage 4 boss)
  if (state.wave === 4 && state.maxBossDmgThisStage >= 900) {
    Achievements.unlock('oneshot');
  }
  persist();
  // Stage rank baserat på tid + HP-kvar
  if (state.player) {
    const stageTime = (performance.now() - (state.stageStartTime || 0)) / 1000;
    const hpFrac = state.player.hp / state.player.maxHp;
    let rank = 'C', rankColor = '#888';
    if (stageTime < 60 && hpFrac > 0.8) { rank = 'S'; rankColor = '#ffd54a'; }
    else if (stageTime < 90 && hpFrac > 0.6) { rank = 'A'; rankColor = '#5aff5a'; }
    else if (stageTime < 120 && hpFrac > 0.4) { rank = 'B'; rankColor = '#5acaff'; }
    state.lastRank = { rank, rankColor };
    showAchievementPopup({ icon: rank, name: 'Stage rank: ' + rank });
  }
  if (state.wave >= getStageCount()) {
    // Story-mode vinst — höj NG+ nivå
    if (getMode() === 'story') {
      save.ngpLevel = (save.ngpLevel || 0) + 1;
    }
    state._waveCompleting = false;
    endGame(true);
  } else {
    // 5s loot-grace efter sista enemy så spelarna hinner ta pickups/dog tags innan
    // shop öppnar. Använd visuell countdown-overlay (samma som prep-countdown)
    // så spelaren ser exakt hur mycket tid som är kvar.
    const lootGraceMs = 5000;
    state._countdownEndAt = performance.now() + lootGraceMs;
    state._countdownLabel = 'LOOT';
    if (typeof showToast === 'function') showToast('🎁 LOOT-FÖNSTER', 5);
    setTimeout(() => {
      // Guard: om spelaren dog/lämnade under grace, öppna inte shop (softlock-risk
      // där shop öppnar ovanpå gameover-skärm).
      if (state.mode !== 'playing') return;
      // Coop: ingen shop — hoppa direkt till nästa stage. Alla har samma 6 vapen
      // hela tiden, inga perks/upgrades-köp tillåtna i coop.
      if (Coop.active) {
        state._waveCompleting = false;
        try { startWave(state.wave + 1); }
        catch (e) { console.error('[COOP] startWave error:', e); }
        return;
      }
      try {
        state._waveCompleting = false;
        openShop();
      } catch (e) {
        console.error('[GAME] openShop error:', e);
        // Force-fix: hoppa direkt till nästa stage
        startWave(state.wave + 1);
      }
    }, lootGraceMs);
  }
}

// Visa STAGE CLEAR-overlay med manuell FORTSÄTT-knapp
function showStageClearOverlay() {
  if (window._debug) console.log('[GAME] showStageClearOverlay called');
  state._stageClearShown = true;
  try {
    const overlay = document.getElementById('stage-clear-overlay');
    if (!overlay) {
      console.error('[GAME] stage-clear-overlay element MISSING');
      // Fallback: gå direkt vidare
      onWaveComplete();
      return;
    }
    // Räkna stats — alla med try-catch så ett fel inte stoppar resten
    const elapsed = (performance.now() - (state.stageStartTime || 0)) / 1000;
    const min = Math.floor(elapsed / 60), sec = Math.floor(elapsed % 60);
    const stage = getStage(state.wave);
    const setText = (id, txt) => {
      const el = document.getElementById(id);
      if (el) el.textContent = txt;
    };
    setText('sc-subtitle', (stage ? stage.name : '') + ' — ' + state.wave + '/' + getStageCount());
    setText('sc-time', `${min}:${sec.toString().padStart(2,'0')}`);
    setText('sc-kills', state.killsThisWave || 0);
    const rank = state.lastRank ? state.lastRank.rank : (elapsed < 60 ? 'S' : elapsed < 90 ? 'A' : elapsed < 120 ? 'B' : 'C');
    setText('sc-rank', rank);
    setText('sc-gold', '💰 ' + (save.gold || 0));
    const btn = document.getElementById('btn-stage-continue');
    const wait = document.getElementById('sc-waiting');
    if (Coop.active && !Coop.isHost) {
      if (btn) btn.classList.add('hidden');
      if (wait) wait.classList.remove('hidden');
    } else {
      if (btn) btn.classList.remove('hidden');
      if (wait) wait.classList.add('hidden');
    }
    overlay.classList.remove('hidden');
    try { Audio.victory(); } catch(e) {}
    if (window._debug) console.log('[GAME] Stage clear overlay visible');
  } catch (e) {
    console.error('[GAME] showStageClearOverlay error:', e);
    // Fallback om något går fel: hoppa direkt
    onWaveComplete();
  }
}

document.getElementById('btn-stage-continue').addEventListener('click', () => {
  Audio.uiClick();
  document.getElementById('stage-clear-overlay').classList.add('hidden');
  state._stageClearShown = false;
  // I coop som host, broadcasta till klienter
  if (Coop.active && Coop.isHost) {
    Coop.broadcast({ type: 'event', event: 'stage_complete' });
  }
  onWaveComplete();
});

// ============================================================
// SHOP
// ============================================================
const shopScreen = document.getElementById('shop-screen');
const shopItems = document.getElementById('shop-items');
const shopGoldEl = document.getElementById('shop-gold-amount');

function openShop() {
  // Coop blockerar shop hårt — alla har samma utgångsläge, inga köp tillåtna.
  // Defense-in-depth: även om en UI-väg råkar slippa Coop-check så blockas det här.
  if (Coop.active) {
    if (typeof showToast === 'function') showToast('🚫 Shop ej tillgänglig i coop');
    return;
  }
  state.mode = 'shop';
  shopScreen.classList.remove('hidden');
  setShopTab('weapons');
  renderShop();
}
function closeShop() {
  shopScreen.classList.add('hidden');
  state.mode = 'playing';
  if (state.shopFromMidGame) {
    // Mid-game shop: bara resume, inga advance
    state.shopFromMidGame = false;
    return;
  }
  // Mellan-stage shop: partial heal + nästa wave
  // Tidigare full-heal i story gjorde boss-överlevnad värdelös — du kunde dö i fel
  // och ändå vara fullt återställd nästa stage. Nu 75% heal i story så väl-spelade
  // bossar känns belönande, men ger fortfarande generös buffer.
  // Endless/Bossrush/Survive: 45% — pressar resurser hårdare.
  // v1.524: reducedHealModes (endless/bossrush/survive) borttagna med modes.
  const healFrac = 0.75;
  state.player.hp = Math.min(state.player.maxHp, state.player.hp + state.player.maxHp * healFrac);
  state.player.ammo = getWeapon(state.player.weaponId).mag || 0;
  state.player.reloading = false;
  // Server-auth: tell server att avancera till nästa stage
  if (Coop.serverSimActive && Coop.ws && Coop.ws.readyState === 1) {
    Coop.ws.send(JSON.stringify({ type: 'sim_load_stage', wave: state.wave + 1 }));
  }
  startWave(state.wave + 1);
}

let shopWeaponCat = 'all';
function renderShop() {
  sanitizeGold();
  shopGoldEl.textContent = save.gold;
  shopItems.innerHTML = '';
  // Sortera vapen efter pris (billigast först), ägda först bland samma pris
  const sortedWeapons = [...WEAPONS].sort((a, b) => {
    const aOwned = save.owned.includes(a.id) ? 0 : 1;
    const bOwned = save.owned.includes(b.id) ? 0 : 1;
    if (aOwned !== bOwned) return aOwned - bOwned;
    return (a.price || 0) - (b.price || 0);
  });
  for (const w of sortedWeapons) {
    const cat = weaponCategory(w);
    if (shopWeaponCat !== 'all' && cat !== shopWeaponCat) continue;
    const owned = save.owned.includes(w.id);
    const equipped = save.equipped === w.id;
    const div = document.createElement('div');
    div.className = 'shop-item' + (equipped ? ' equipped' : (owned ? ' owned' : ''));
    let stats = '';
    if (w.type === 'melee') {
      stats = `<div class="stat-row"><span>DMG</span><span>${w.dmg}</span></div>
               <div class="stat-row"><span>RATE</span><span>${(60000/w.rate).toFixed(1)}/s</span></div>
               <div class="stat-row"><span>RÄCKV</span><span>${w.range}</span></div>`;
    } else {
      const dps = (w.dmg * (w.pellets || 1) * (60000 / w.rate)).toFixed(0);
      stats = `<div class="stat-row"><span>DMG</span><span>${w.dmg}${w.pellets?'×'+w.pellets:''}</span></div>
               <div class="stat-row"><span>MAG</span><span>${w.mag}</span></div>
               <div class="stat-row"><span>RATE</span><span>${(60000/w.rate).toFixed(1)}/s</span></div>`;
    }
    const tags = [];
    if (w.pierce) tags.push('🎯 Pierce');
    if (w.explosive) tags.push('💥 Expl');
    if (w.burn) tags.push('🔥 Burn');
    if (w.chain) tags.push('⚡ Chain');
    if (w.slow) tags.push('❄ Slow');
    if (w.knockback) tags.push('💢 KB');
    const lvl = getWeaponLevel(w.id);
    const lvlPrice = weaponUpgradePrice(w.id);
    const lvlPips = '<div style="display:flex;gap:2px;margin-top:4px;">' +
      Array.from({length: WEAPON_UPGRADE_MAX}, (_, i) =>
        `<div style="width:14px;height:5px;background:${i < lvl ? '#ffd54a' : '#333'};border-radius:1px;"></div>`
      ).join('') + '</div>';
    div.innerHTML = `
      ${equipped ? '<div class="equipped-badge">✓</div>' : ''}
      <div class="name">${w.name}</div>
      <span class="wtype ${cat}">${cat.toUpperCase()}</span>
      <div class="stats">${stats}${tags.length ? '<div style="margin-top:4px;font-size:10px;opacity:0.7;">'+tags.join(' · ')+'</div>' : ''}</div>
      ${w.desc ? `<div class="desc" style="font-size:10px;opacity:0.6;margin:4px 0;line-height:1.3;">${w.desc}</div>` : ''}
      ${owned ? `<div style="font-size:10px;opacity:0.7;margin-top:4px;">Nivå ${lvl}/${WEAPON_UPGRADE_MAX} (+${lvl*12}% dmg)</div>${lvlPips}` : ''}
      <div class="price">${owned ? (equipped ? '✓ UTRUSTAD' : 'BÄR') : '💰 ' + w.price}</div>
      ${owned && lvlPrice !== null ? `<button class="weapon-upgrade-btn" style="width:100%;margin-top:6px;padding:6px 4px;background:linear-gradient(135deg,#3a2a10,#1a1408);color:#ffd54a;border:1px solid #ffd54a;border-radius:4px;font-size:10px;font-weight:700;cursor:pointer;">⬆ UPPGRADERA · 💰 ${lvlPrice}</button>` : ''}
      ${owned && lvlPrice === null ? `<div style="text-align:center;margin-top:6px;color:#5aff5a;font-size:10px;font-weight:700;">⭐ MAX NIVÅ</div>` : ''}
    `;
    const upgBtn = div.querySelector('.weapon-upgrade-btn');
    if (upgBtn) {
      upgBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (upgradeWeapon(w.id)) {
          renderShop();
        } else {
          flashShopItem(upgBtn);
        }
      });
    }
    div.addEventListener('click', () => {
      if (owned) { equip(w.id); renderShop(); return; }
      if (save.gold < w.price) { flashShopItem(div); return; }
      save.gold -= w.price;
      save.owned.push(w.id);
      equip(w.id);
      state.shopBoughtThisStage = (state.shopBoughtThisStage || 0) + 1;
      Audio.purchase();
      persist();
      renderShop();
    });
    shopItems.appendChild(div);
  }
}

