// Walk-cykel variants — bara benen ändras. För enkel start använder vi
// bara base sprite; lägg till L/R-frames senare för animation.

// v1.442: Professional pixel-art palette med 3-4 toner per material.
// Ljus kommer från upper-left → highlights NW, shadows SE.
function _buildPlayerPalette(cos, color) {
  const vestBase = color || cos.shirt || '#4a5a3a';
  const skinBase = cos.skin || '#c89870';
  const bandanaBase = cos.bandana || '#c83030';
  const accentBase = cos.accent || '#f0c020';
  const pantsBase = cos.pants || '#2a2418';
  return {
    'O': '#0a0a0e',                         // Outline (near-black)
    'n': '#1a0e08',                         // Deep shadow / hair under bandana
    // Skin — 4 toner för djup
    's': lighten(skinBase, 0.15),           // Skin highlight (upper)
    'S': skinBase,                          // Skin base
    'K': darken(skinBase, 0.62),            // Skin shadow
    'N': darken(skinBase, 0.40),            // Skin deep shadow (under jaw)
    // Bandana — 4 toner
    'Q': lighten(bandanaBase, 0.18),        // Bandana highlight
    'R': bandanaBase,                       // Bandana base
    'r': darken(bandanaBase, 0.65),         // Bandana shadow
    'q': darken(bandanaBase, 0.45),         // Bandana deep shadow
    'A': accentBase,                        // Accent stripe gold
    'a': darken(accentBase, 0.60),          // Accent shadow
    // Sunglasses — 3 toner
    'G': '#0a0a14',                         // Sunglasses dark
    'W': '#5070a0',                         // Sunglasses reflection (blue-grey)
    'w': '#d8e8f8',                         // Sunglasses white glint
    // Vest — 4 toner
    'F': lighten(vestBase, 0.20),           // Vest highlight (top-left)
    'V': vestBase,                          // Vest base
    'v': darken(vestBase, 0.55),            // Vest shadow
    'E': darken(vestBase, 0.35),            // Vest mid-shadow
    // Plate carrier — 3 toner
    'D': darken(vestBase, 0.75),            // Plate base (dark)
    'd': '#080806',                         // Plate deep shadow
    // Brass/metal
    'M': '#d0a838',                         // Brass mid
    'm': '#785818',                         // Brass shadow
    'I': '#f0d060',                         // Brass highlight
    // Pants
    'P': pantsBase,                         // Pants base
    'p': darken(pantsBase, 0.60),           // Pants shadow
    'f': lighten(pantsBase, 0.20),          // Pants highlight
    // Boots
    'B': '#0a0805',                         // Boot deep black
    'l': '#3a2818',                         // Boot leather mid
    'L': '#5a3820',                         // Boot leather highlight
    // Stubble + misc
    'T': '#1a0a06',                         // Stubble shadow
    'Y': accentBase,                        // Legacy compat
    'H': cos.hairColor || '#1a0a08',
    'X': '#0a0a0a',
    // v1.453: Underwear (vit) för naked sprite
    'U': '#fafafa',                         // White underwear (kallingar)
    'u': '#c8c8c8',                         // Underwear shadow
    // v1.460: ~50 colors total för rich shading av naken karaktär
    // Skin tones (8 levels)
    '0': lighten(skinBase, 0.32),           // Skin brightest highlight
    '1': darken(skinBase, 0.15),            // Skin mid-shadow
    '2': darken(skinBase, 0.32),            // Skin darker shadow
    '3': darken(skinBase, 0.55),            // Skin deep shadow
    '4': darken(skinBase, 0.78),            // Skin darkest (near outline)
    // Hair tones (5 levels)
    '5': lighten(cos.hairColor || '#1a0a08', 0.45),  // Hair brightest highlight
    '6': darken(cos.hairColor || '#1a0a08', 0.20),   // Hair mid-shadow
    '7': darken(cos.hairColor || '#1a0a08', 0.50),   // Hair deep shadow
    '8': '#000604',                                   // Hair darkest
    // Eye details
    'e': '#f0f4fa',                         // Eye sclera (white-blue)
    'i': '#3a5070',                         // Iris base (steel blue)
    '@': '#0a0a0c',                         // Pupil
    '*': '#ffffff',                         // Eye glint (bright white)
    // Lip details
    'b': '#7a3a3a',                         // Lip base
    'c': '#a85a50',                         // Lip highlight
    'g': '#3a0a0a',                         // Lip deep shadow (mouth open)
    // Underwear details (5 levels)
    '=': '#ffffff',                         // Underwear elastic highlight
    '+': '#9a9aaa',                         // Underwear shadow
    '#': '#6a6a7a',                         // Elastic dark band
    // Misc
    'o': '#1a1a22',                         // Lighter outline (for highlights edge)
  };
}

// Renderar ett pixel-sprite-array till en offscreen-canvas. Returnerar canvas.
function _renderPixelSpriteToCanvas(sprite, palette, scale, flash) {
  const rows = sprite.length;
  const cols = sprite[0].length;
  const c = document.createElement('canvas');
  c.width = cols * scale;
  c.height = rows * scale;
  const cc = c.getContext('2d');
  cc.imageSmoothingEnabled = false;
  for (let r = 0; r < rows; r++) {
    const row = sprite[r];
    for (let col = 0; col < cols; col++) {
      const ch = row[col];
      if (ch === '.' || ch === ' ') continue;
      const color = flash ? '#fff' : (palette[ch] || '#f0f');
      cc.fillStyle = color;
      cc.fillRect(col * scale, r * scale, scale, scale);
    }
  }
  return c;
}

// v1.450: Cache rendered top-down head per costume
const _topDownHeadCache = new Map();
function _getCachedTopDownHead(cos, color, flash) {
  const key = (color || '') + '|' + (cos.skin || '') + '|' + (cos.bandana || '') + '|' +
              (cos.accent || '') + '|' + (flash ? 'F' : 'N');
  let cached = _topDownHeadCache.get(key);
  if (cached) return cached;
  const palette = _buildPlayerPalette(cos, color);
  cached = _renderPixelSpriteToCanvas(HEAD_TOP_DOWN, palette, 1, flash);
  if (_topDownHeadCache.size > 60) {
    const firstKey = _topDownHeadCache.keys().next().value;
    _topDownHeadCache.delete(firstKey);
  }
  _topDownHeadCache.set(key, cached);
  return cached;
}

// v1.456: Cache rendered naked sprite at SCALE=2 så karaktären får samma storlek
// som original IDLE-spriten (original 45 rad innehåll, min naked har 24 rad — scale 2
// ger 48 rad effektiv storlek).
const _nakedSpriteCache = new Map();
function _getCachedNakedSprite(cos, color, flash) {
  const key = (color || '') + '|' + (cos.skin || '') + '|' + (cos.hairColor || '') +
              '|' + (flash ? 'F' : 'N');
  let cached = _nakedSpriteCache.get(key);
  if (cached) return cached;
  const palette = _buildPlayerPalette(cos, color);
  cached = _renderPixelSpriteToCanvas(PLAYER_SPRITE_NAKED, palette, 1, flash);
  if (_nakedSpriteCache.size > 60) {
    const firstKey = _nakedSpriteCache.keys().next().value;
    _nakedSpriteCache.delete(firstKey);
  }
  _nakedSpriteCache.set(key, cached);
  return cached;
}

// Cache så vi inte re-renderar sprite varje frame
const _pixelSpriteCache = new Map();
function _getCachedPlayerSprite(cos, color, scale, flash, spriteData) {
  // v1.440: spriteData = vilken frame (IDLE/WALK_A/WALK_B). Default = IDLE.
  const sprite = spriteData || PLAYER_SPRITE_IDLE;
  // Skapa frame-id baserat på sprite-array-reference för cache key
  let frameId = 'I';
  if (sprite === PLAYER_SPRITE_WALK_A) frameId = 'A';
  else if (sprite === PLAYER_SPRITE_WALK_B) frameId = 'B';
  const key = (color || '') + '|' + (cos.skin || '') + '|' + (cos.shirt || '') + '|' +
              (cos.bandana || '') + '|' + (cos.accent || '') + '|' + (cos.pants || '') + '|' +
              (cos.hairColor || '') + '|' + scale + '|' + (flash ? 'F' : 'N') + '|' + frameId;
  let cached = _pixelSpriteCache.get(key);
  if (cached) return cached;
  const palette = _buildPlayerPalette(cos, color);
  cached = _renderPixelSpriteToCanvas(sprite, palette, scale, flash);
  if (_pixelSpriteCache.size > 120) {
    const firstKey = _pixelSpriteCache.keys().next().value;
    _pixelSpriteCache.delete(firstKey);
  }
  _pixelSpriteCache.set(key, cached);
  return cached;
}

// Helper för att rita pixel-sprite vid (x, y) med rotation = aimAngle.
// Använder cached canvas + ctx.drawImage med rotation.
function drawPlayerPixelSprite(ctx, x, y, aimAngle, cos, color, scale, flash) {
  const spriteCanvas = _getCachedPlayerSprite(cos, color, scale, flash);
  const sw = spriteCanvas.width, sh = spriteCanvas.height;
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.translate(x, y);
  ctx.rotate(aimAngle);
  // Centrera sprite på (x, y)
  ctx.drawImage(spriteCanvas, -sw / 2, -sh / 2);
  ctx.restore();
}

// v1.443: BANDANA TAIL — animerad cloth som vajar bakom karaktären.
// Ritas FÖRE sprite så den ligger bakom. Färg från costume.
// Body-local coords: tail trails ALWAYS to -X (since mirror handles direction).
// Wave-animation baserat på now för "alive" look.
function drawBandanaTail(ctx, cos, color, now, moving, phase) {
  const bandanaColor = cos.bandana || color || '#c83030';
  const bandanaDark = darken(bandanaColor, 0.65);
  const accentColor = cos.accent || '#f0c020';
  // Anchor: back of head — sprite top is around y=-22 in 48×48 frame (centered)
  const baseX = -8;
  const baseY = -16;
  // Wave intensity boosts vid rörelse (cloth flutters mer när man springer)
  const waveAmp = moving ? 2.4 : 1.5;
  const waveT = now / 160 + (moving ? phase * 0.5 : 0);
  const segments = 10;
  const segLen = 2.2;
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  for (let i = 0; i < segments; i++) {
    const seg = i + 1;
    const segX = baseX - seg * segLen;
    // Wave: increasing amplitude along tail
    const wave = Math.sin(waveT + i * 0.55) * (waveAmp + i * 0.35);
    const segY = baseY + i * 0.3 + wave;
    const width = Math.max(1, 3 - Math.floor(i / 4));
    ctx.fillStyle = i % 2 === 0 ? bandanaColor : bandanaDark;
    ctx.fillRect(Math.round(segX), Math.round(segY), width, width + 1);
    if (i % 3 === 0 && i > 0) {
      ctx.fillStyle = accentColor;
      ctx.fillRect(Math.round(segX), Math.round(segY + 1), 1, 1);
    }
  }
  ctx.restore();
}

// v1.443: MUZZLE FLASH — bright burst at weapon tip when firing.
// Pixel-art star-burst pattern in weapon-local coords (assumes ctx is
// already rotated to aim direction). Fades out over 80ms.
function drawMuzzleFlash(ctx, weaponTipX, sinceShot, weaponType) {
  if (weaponType !== 'gun') return;
  if (sinceShot > 80) return;
  const intensity = 1 - sinceShot / 80;
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  // Core flash (white-yellow center)
  const cx = weaponTipX, cy = 0;
  // Random spike-pattern that varies per ms (looks more "alive")
  const spikeOffset = Math.floor(sinceShot / 16) % 3; // changes every 16ms
  // Outer glow (yellow)
  ctx.fillStyle = 'rgba(255,200,80,' + (0.7 * intensity) + ')';
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      const d = Math.abs(dx) + Math.abs(dy);
      if (d > 4) continue;
      if (d === 4 && (dx + dy + spikeOffset) % 2 === 0) continue;
      ctx.fillRect(cx + dx, cy + dy, 1, 1);
    }
  }
  // Mid flash (bright orange)
  ctx.fillStyle = 'rgba(255,160,40,' + intensity + ')';
  for (let dx = -2; dx <= 2; dx++) {
    for (let dy = -2; dy <= 2; dy++) {
      if (Math.abs(dx) + Math.abs(dy) > 2) continue;
      ctx.fillRect(cx + dx, cy + dy, 1, 1);
    }
  }
  // Core (white-hot)
  ctx.fillStyle = 'rgba(255,255,220,' + intensity + ')';
  ctx.fillRect(cx - 1, cy - 1, 3, 3);
  ctx.fillRect(cx, cy - 2, 1, 5);
  ctx.fillRect(cx - 2, cy, 5, 1);
  // Spark spokes (4 directions)
  ctx.fillStyle = 'rgba(255,240,180,' + (0.8 * intensity) + ')';
  const sparkLen = 4 + spikeOffset;
  ctx.fillRect(cx + 2, cy, sparkLen, 1);  // forward
  ctx.fillRect(cx - sparkLen - 1, cy, sparkLen, 1); // backward
  ctx.fillRect(cx, cy - 3, 1, 2);
  ctx.fillRect(cx, cy + 2, 1, 2);
  ctx.restore();
}

// v1.479: Cape som hänger BAKOM den upprätta kroppen. Frame är samma som
// drawNakedBody: x ~-8 till +8, y -22 till +20. Cape går från axlar (y=-4) ner.
function drawCapeOnUprightBody(ctx, style, color, flash, now, moving) {
  const wave = Math.sin((now || 0) / 350) * (moving ? 2.4 : 1.2);
  const trailDown = moving ? 22 : 19;
  const col = flash ? '#fff' : (color || '#aa1818');
  const dark = flash ? '#fff' : darken(color || '#aa1818', 0.45);
  const outline = flash ? '#fff' : '#0a0a0a';
  ctx.save();
  if (style === 'cape') {
    // Trapets-cape: smal vid axlar, bredare neråt
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(-6, -4);                              // axel-väst
    ctx.lineTo(6, -4);                                // axel-öst
    ctx.lineTo(8 + wave, trailDown);                  // hem-öst
    ctx.lineTo(-8 - wave, trailDown);                 // hem-väst
    ctx.closePath();
    ctx.fill();
    // Mitten-fold (mörk stripe)
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.moveTo(-1.5, -4);
    ctx.lineTo(1.5, -4);
    ctx.lineTo(2 + wave * 0.4, trailDown);
    ctx.lineTo(-2 - wave * 0.4, trailDown);
    ctx.closePath();
    ctx.fill();
    // Outline
    ctx.strokeStyle = outline; ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(-6, -4);
    ctx.lineTo(6, -4);
    ctx.lineTo(8 + wave, trailDown);
    ctx.lineTo(-8 - wave, trailDown);
    ctx.closePath();
    ctx.stroke();
  } else if (style === 'rainbow') {
    const colors = ['#ff3a3a', '#ff8a3a', '#ffd54a', '#5aff5a', '#3acaff', '#aa3aff'];
    const segs = colors.length;
    for (let i = 0; i < segs; i++) {
      const t0 = -6 + 12 * (i / segs);
      const t1 = -6 + 12 * ((i + 1) / segs);
      const b0 = -8 - wave + (16 + wave * 2) * (i / segs);
      const b1 = -8 - wave + (16 + wave * 2) * ((i + 1) / segs);
      ctx.fillStyle = flash ? '#fff' : colors[i];
      ctx.beginPath();
      ctx.moveTo(t0, -4);
      ctx.lineTo(t1, -4);
      ctx.lineTo(b1, trailDown);
      ctx.lineTo(b0, trailDown);
      ctx.closePath();
      ctx.fill();
    }
  } else if (style === 'flames') {
    // Jagged flame-edges
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(-6, -4);
    ctx.lineTo(6, -4);
    for (let i = 6; i >= -6; i -= 2) {
      const flick = (i % 4 === 0 ? -3 : -6) + Math.sin((now || 0) / 150 + i) * 2;
      ctx.lineTo(i + wave * 0.3, trailDown + flick);
    }
    ctx.closePath();
    ctx.fill();
    // Hot core
    ctx.fillStyle = flash ? '#fff' : '#ffae3a';
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.ellipse(0, trailDown - 5, 4, 8, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  } else if (style === 'tattered') {
    // Trasiga kanter
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(-6, -4);
    ctx.lineTo(6, -4);
    for (let i = 6; i >= -6; i -= 1.5) {
      const torn = (i % 3 === 0) ? trailDown - 4 : trailDown - (i % 4) * 1.5;
      ctx.lineTo(i + wave * 0.3, torn);
    }
    ctx.closePath();
    ctx.fill();
    // Hål
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.beginPath(); ctx.ellipse(-2, 7, 1.2, 1.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(3, 12, 1.4, 1.2, 0, 0, Math.PI * 2); ctx.fill();
  } else if (style === 'wings') {
    // Två vinge-blades på axlarna
    ctx.fillStyle = col;
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.translate(side * 5, -3);
      ctx.rotate(side * (0.25 + Math.sin((now || 0) / 400) * 0.05));
      // Vinge-blade
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(side * 9, 4, side * 12, 16);
      ctx.quadraticCurveTo(side * 6, 14, 0, 8);
      ctx.closePath();
      ctx.fill();
      // Fjäder-linjer
      ctx.strokeStyle = dark; ctx.lineWidth = 0.4;
      for (let i = 1; i < 4; i++) {
        ctx.beginPath();
        ctx.moveTo(0, i * 2);
        ctx.lineTo(side * (4 + i * 2), 5 + i * 2);
        ctx.stroke();
      }
      ctx.restore();
    }
  } else {
    // Default: trapets-cape (basic style för okända varianter)
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(-6, -4);
    ctx.lineTo(6, -4);
    ctx.lineTo(8 + wave, trailDown);
    ctx.lineTo(-8 - wave, trailDown);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

// ============================================================
// v1.487: MASCOT CHARACTERS — full custom render (Ronald, Nugget, Korv)
// ============================================================
// Ritar Ronald McDonald — clown med vit ansiktsmålning, röd mun/näsa/hår
// + gul jumpsuit med röda vertikala stripes + stora röda skor
function drawMcDonaldsCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const yellow      = flash ? '#fff' : '#ffd54a';
  const yellowDark  = flash ? '#fff' : '#cc9018';
  const red         = flash ? '#fff' : '#cc1818';
  const redDark     = flash ? '#fff' : '#8a0a0a';
  const white       = flash ? '#fff' : '#f8f8f8';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const outline     = flash ? '#fff' : '#0a0a0a';
  const skinPale    = flash ? '#fff' : '#f4d4a8';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // === HEAD shape (vit ansiktsmålning över hela ansiktet) ===
  ctx.fillStyle = white;
  ctx.beginPath();
  ctx.moveTo(-4, -19);
  ctx.quadraticCurveTo(2, -20.5, 6, -19);
  ctx.quadraticCurveTo(8, -15, 7, -11);
  ctx.quadraticCurveTo(6, -8, 4, -7);
  ctx.lineTo(2, -7);
  ctx.quadraticCurveTo(-2, -7.5, -4, -9);
  ctx.quadraticCurveTo(-6, -14, -5, -17);
  ctx.quadraticCurveTo(-5, -19, -4, -19);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 1.5;
  ctx.stroke();
  // === RED CURLY WIG (5 puffs runt huvudet) ===
  const curls = [[-2, -21, 2.5], [2.5, -22, 2.8], [5.5, -20.5, 2.4],
                 [-6, -17, 2.2], [8, -15, 2.2]];
  ctx.fillStyle = red;
  for (const [cx, cy, cr] of curls) {
    ctx.beginPath(); ctx.arc(cx, cy, cr, 0, Math.PI * 2); ctx.fill();
  }
  // Curl highlights (mer volym)
  ctx.fillStyle = flash ? '#fff' : '#ff5a5a';
  ctx.beginPath(); ctx.arc(-1, -21, 0.8, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3.5, -22, 1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(6.5, -20, 0.8, 0, Math.PI * 2); ctx.fill();
  // Curl outlines
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.6;
  for (const [cx, cy, cr] of curls) {
    ctx.beginPath(); ctx.arc(cx, cy, cr, 0, Math.PI * 2); ctx.stroke();
  }
  // === BIG CARTOON EYES ===
  ctx.fillStyle = white;
  ctx.beginPath(); ctx.ellipse(0.5, -13, 1.6, 1.1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.6; ctx.stroke();
  ctx.beginPath(); ctx.ellipse(4.5, -13, 1.6, 1.1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.stroke();
  // Iris (svart pupill)
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(0.6, -13, 0.7, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4.6, -13, 0.7, 0, Math.PI * 2); ctx.fill();
  // Eye glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(0.9, -13.4, 0.4, 0.4);
  ctx.fillRect(4.9, -13.4, 0.4, 0.4);
  // === RED CLOWN NOSE (rund röd boll) ===
  ctx.fillStyle = red;
  ctx.beginPath(); ctx.arc(2.5, -10, 1.4, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.beginPath(); ctx.arc(2.5, -10, 1.4, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = flash ? '#fff' : '#ff8a8a';
  ctx.beginPath(); ctx.arc(2.0, -10.4, 0.5, 0, Math.PI * 2); ctx.fill();
  // === BIG RED CLOWN SMILE (krets-kurva, ej platt linje) ===
  ctx.fillStyle = red;
  ctx.beginPath();
  ctx.moveTo(-1.5, -8.5);
  ctx.quadraticCurveTo(2.5, -5, 6.5, -8.5);
  ctx.quadraticCurveTo(2.5, -7, -1.5, -8.5);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-1.5, -8.5);
  ctx.quadraticCurveTo(2.5, -5, 6.5, -8.5);
  ctx.stroke();
  // Lip highlight (vit liten reflektion)
  ctx.fillStyle = '#fff';
  ctx.fillRect(0.5, -7.5, 1.5, 0.4);
  // === NECK (skin) ===
  ctx.fillStyle = skinPale;
  ctx.beginPath();
  ctx.moveTo(-3, -7); ctx.lineTo(3, -7);
  ctx.quadraticCurveTo(4, -5, 5, -4);
  ctx.lineTo(-5, -4);
  ctx.quadraticCurveTo(-4, -5, -3, -7);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1.5;
  ctx.stroke();
  // === TORSO (gul jumpsuit) ===
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(-6, -4);
  ctx.quadraticCurveTo(-8, 0, -5, 4);
  ctx.lineTo(-4, 13);
  ctx.lineTo(5, 13);
  ctx.lineTo(6, 4);
  ctx.quadraticCurveTo(8, 0, 6, -4);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  // === RED VERTICAL STRIPES på torso (klassisk clown-pattern) ===
  ctx.fillStyle = red;
  for (let i = -5; i <= 5; i += 2.5) {
    ctx.fillRect(i, -3.5, 0.9, 16);
  }
  // === BIG "M" LOGO på chest (gul mot röd stripe) ===
  ctx.strokeStyle = yellow;
  ctx.lineWidth = 1.4;
  ctx.lineJoin = 'miter';
  ctx.beginPath();
  ctx.moveTo(-1.8, 4.5); ctx.lineTo(-1.8, 0.5);
  ctx.lineTo(0.3, 2.8); ctx.lineTo(2.4, 0.5);
  ctx.lineTo(2.4, 4.5);
  ctx.stroke();
  // M outline
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.4;
  ctx.stroke();
  // === LEGS (gul + röda stripes) ===
  const bkX = -3 - legSwing;
  const bkTop = 13;
  const frX = 3 + legSwing;
  const frTop = 13;
  // Back leg
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(bkX - 2.7, bkTop);
  ctx.lineTo(bkX + 2.7, bkTop);
  ctx.quadraticCurveTo(bkX + 3, bkTop + 5, bkX + 2.2, bkTop + 8);
  ctx.quadraticCurveTo(bkX + 2.8, bkTop + 10, bkX + 2, bkTop + 12);
  ctx.lineTo(bkX + 1.5, bkTop + 13);
  ctx.lineTo(bkX - 1.5, bkTop + 13);
  ctx.quadraticCurveTo(bkX - 2.8, bkTop + 10, bkX - 2.2, bkTop + 8);
  ctx.quadraticCurveTo(bkX - 3, bkTop + 5, bkX - 2.7, bkTop);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.fillStyle = red;
  ctx.fillRect(bkX - 2, bkTop, 0.6, 13);
  ctx.fillRect(bkX, bkTop, 0.6, 13);
  ctx.fillRect(bkX + 1.4, bkTop, 0.6, 13);
  // Front leg
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(frX - 2.7, frTop);
  ctx.lineTo(frX + 2.7, frTop);
  ctx.quadraticCurveTo(frX + 3, frTop + 5, frX + 2.2, frTop + 8);
  ctx.quadraticCurveTo(frX + 2.8, frTop + 10, frX + 2, frTop + 12);
  ctx.lineTo(frX + 1.5, frTop + 13);
  ctx.lineTo(frX - 1.5, frTop + 13);
  ctx.quadraticCurveTo(frX - 2.8, frTop + 10, frX - 2.2, frTop + 8);
  ctx.quadraticCurveTo(frX - 3, frTop + 5, frX - 2.7, frTop);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = red;
  ctx.fillRect(frX - 2, frTop, 0.6, 13);
  ctx.fillRect(frX, frTop, 0.6, 13);
  ctx.fillRect(frX + 1.4, frTop, 0.6, 13);
  // === GIANT RED CLOWN SHOES (oversized, sticker ut framåt) ===
  // Back foot
  ctx.fillStyle = red;
  ctx.beginPath();
  ctx.moveTo(bkX - 2.8, bkTop + 13);
  ctx.lineTo(bkX - 2, bkTop + 17);
  ctx.quadraticCurveTo(bkX + 2, bkTop + 18, bkX + 6, bkTop + 17);
  ctx.lineTo(bkX + 6, bkTop + 14);
  ctx.lineTo(bkX + 2, bkTop + 13);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.8;
  ctx.stroke();
  // White sole stripe
  ctx.fillStyle = white;
  ctx.fillRect(bkX - 2.5, bkTop + 16.5, 8.5, 0.8);
  // Front foot
  ctx.fillStyle = red;
  ctx.beginPath();
  ctx.moveTo(frX - 2.8, frTop + 13);
  ctx.lineTo(frX - 2, frTop + 17);
  ctx.quadraticCurveTo(frX + 2, frTop + 18, frX + 7, frTop + 17);
  ctx.lineTo(frX + 7, frTop + 14);
  ctx.lineTo(frX + 2, frTop + 13);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = white;
  ctx.fillRect(frX - 2.5, frTop + 16.5, 9.5, 0.8);
  // Shoe highlight
  ctx.fillStyle = flash ? '#fff' : '#ff5a5a';
  ctx.fillRect(frX + 1, frTop + 14, 4, 0.5);
}

// Ritar en CHICKEN NUGGET — irregulär oval gyllene-brun form, bumpy outline,
// litet face, stick-arms och stick-legs som sticker ut
function drawNuggetCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const nuggetGold    = flash ? '#fff' : '#d4a04a';
  const nuggetCrust   = flash ? '#fff' : '#aa7a30';
  const nuggetShadow  = flash ? '#fff' : '#7a5a20';
  const nuggetLight   = flash ? '#fff' : '#f0c060';
  const outline       = flash ? '#fff' : '#3a2a0a';
  const blackEye      = flash ? '#fff' : '#0a0a0a';
  const stickColor    = flash ? '#fff' : '#5a3a20';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 1.5 : 0;
  // === NUGGET BODY (irregulär oval med bumpy outline) ===
  ctx.fillStyle = nuggetGold;
  ctx.beginPath();
  ctx.moveTo(-7, -13);
  ctx.quadraticCurveTo(-9, -10, -8, -6);
  ctx.lineTo(-9, -2);
  ctx.quadraticCurveTo(-8.5, 2, -8, 5);
  ctx.lineTo(-7, 8);
  ctx.quadraticCurveTo(-5, 11, -2, 12);
  ctx.lineTo(2, 12);
  ctx.quadraticCurveTo(5, 11, 7, 8);
  ctx.lineTo(8, 5);
  ctx.quadraticCurveTo(8.5, 2, 8, -2);
  ctx.lineTo(9, -6);
  ctx.quadraticCurveTo(8, -10, 7, -13);
  ctx.lineTo(4, -14);
  ctx.quadraticCurveTo(0, -15, -4, -14);
  ctx.lineTo(-7, -13);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 1.4;
  ctx.stroke();
  // === BUMPY CRUST TEXTURE (små brödsmulor över hela) ===
  ctx.fillStyle = nuggetCrust;
  const bumps = [[-5, -10], [-2, -12], [3, -11], [6, -8], [-7, -4], [4, -5],
                 [-3, -3], [2, -1], [-5, 2], [5, 3], [-2, 6], [3, 7],
                 [-6, -8], [0, -9], [7, -3], [-4, 5], [1, 9], [-1, -6],
                 [6, 5], [-3, 9]];
  for (const [bx, by] of bumps) {
    ctx.beginPath();
    ctx.ellipse(bx, by, 0.7, 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // Lighter highlights (skiner som friterad mat)
  ctx.fillStyle = nuggetLight;
  const hls = [[-4, -10], [3, -9], [-2, -2], [4, 0], [-3, 6], [5, -6]];
  for (const [hx, hy] of hls) {
    ctx.beginPath();
    ctx.ellipse(hx, hy, 0.6, 0.4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // === SHADOW under-side ===
  ctx.fillStyle = nuggetShadow;
  ctx.globalAlpha = 0.35;
  ctx.beginPath();
  ctx.moveTo(-7, 6);
  ctx.quadraticCurveTo(-5, 11, -2, 12);
  ctx.lineTo(2, 12);
  ctx.quadraticCurveTo(5, 11, 7, 8);
  ctx.lineTo(8, 5);
  ctx.quadraticCurveTo(5, 8, 0, 8.5);
  ctx.quadraticCurveTo(-5, 8, -7, 6);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // === FACE (cute kawaii face) ===
  // Big eyes
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2.2, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.2, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  // Eye highlights (gör dem kawaii)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1.9, -5.4, 0.4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -5.4, 0.4, 0, Math.PI * 2); ctx.fill();
  // Small smile (kawaii open mouth)
  ctx.strokeStyle = blackEye;
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-1.5, -1.5);
  ctx.quadraticCurveTo(0, 0, 1.5, -1.5);
  ctx.stroke();
  // Cheek blush
  ctx.fillStyle = flash ? '#fff' : '#ff9090';
  ctx.globalAlpha = 0.55;
  ctx.beginPath(); ctx.arc(-4.5, -2.5, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4.5, -2.5, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.globalAlpha = 1;
  // === STICK ARMS (skinny limbs poking out, in walk-cycle) ===
  const armSwing = isMoving ? swing * 1.5 : 0;
  ctx.strokeStyle = stickColor;
  ctx.lineWidth = 1.4;
  ctx.lineCap = 'round';
  // Left arm
  ctx.beginPath();
  ctx.moveTo(-7.5, -1);
  ctx.lineTo(-11, 2 - armSwing);
  ctx.stroke();
  // Right arm
  ctx.beginPath();
  ctx.moveTo(7.5, -1);
  ctx.lineTo(11, 2 + armSwing);
  ctx.stroke();
  // Hands (dots)
  ctx.fillStyle = stickColor;
  ctx.beginPath(); ctx.arc(-11, 2 - armSwing, 1.2, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(11, 2 + armSwing, 1.2, 0, Math.PI * 2); ctx.fill();
  // === STICK LEGS (poking out from bottom) ===
  ctx.strokeStyle = stickColor;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(-3 - legSwing, 11);
  ctx.lineTo(-3 - legSwing, 18);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3 + legSwing, 11);
  ctx.lineTo(3 + legSwing, 18);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // Small feet (black dots)
  ctx.fillStyle = stickColor;
  ctx.beginPath();
  ctx.ellipse(-3 - legSwing, 19, 1.8, 0.8, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 19, 1.8, 0.8, 0, 0, Math.PI * 2);
  ctx.fill();
}

// Ritar en KORV MED BRÖD — bun bredvid sausage + mustard + ketchup
// Sausage sticker ut top och visas i mitten av buns
function drawKorvCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const bunColor      = flash ? '#fff' : '#d4a060';
  const bunShadow     = flash ? '#fff' : '#aa7a40';
  const bunHighlight  = flash ? '#fff' : '#f0c080';
  const sausageColor  = flash ? '#fff' : '#c44830';
  const sausageDark   = flash ? '#fff' : '#8a2818';
  const sausageLight  = flash ? '#fff' : '#e85a40';
  const mustardColor  = flash ? '#fff' : '#ffd54a';
  const ketchupColor  = flash ? '#fff' : '#cc2020';
  const outline       = flash ? '#fff' : '#3a2010';
  const skinColor     = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye      = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // === SAUSAGE END (på toppen, sticker ut ovanför bun) ===
  ctx.fillStyle = sausageColor;
  ctx.beginPath();
  ctx.ellipse(1, -17, 3, 4, 0, 0, Math.PI * 2);
  ctx.fill();
  // Sausage shadow på övre delen
  ctx.fillStyle = sausageDark;
  ctx.beginPath();
  ctx.ellipse(-0.5, -17, 1.2, 3.5, 0, 0, Math.PI * 2);
  ctx.fill();
  // Sausage highlight east
  ctx.fillStyle = sausageLight;
  ctx.beginPath();
  ctx.ellipse(2.5, -17, 0.6, 3, 0, 0, Math.PI * 2);
  ctx.fill();
  // Sausage outline
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.ellipse(1, -17, 3, 4, 0, 0, Math.PI * 2);
  ctx.stroke();
  // === BUN LEFT/WEST (vänster halva av brödet) ===
  ctx.fillStyle = bunColor;
  ctx.beginPath();
  ctx.moveTo(-8, -12);
  ctx.quadraticCurveTo(-10, -7, -9, 0);
  ctx.lineTo(-8, 7);
  ctx.quadraticCurveTo(-6, 11, -3, 11);
  ctx.lineTo(-2, 8);
  ctx.lineTo(-2, -10);
  ctx.quadraticCurveTo(-5, -14, -8, -12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // Bun shadow (west sida)
  ctx.fillStyle = bunShadow;
  ctx.globalAlpha = 0.55;
  ctx.beginPath();
  ctx.moveTo(-8, -12);
  ctx.quadraticCurveTo(-10, -7, -9, 0);
  ctx.lineTo(-8, 7);
  ctx.lineTo(-7, 6);
  ctx.lineTo(-7, -3);
  ctx.lineTo(-8, -11);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // Sesame seeds på bun (small lighter dots)
  ctx.fillStyle = bunHighlight;
  ctx.beginPath(); ctx.ellipse(-5, -9, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-7, -6, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-4, -3, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-6, 2, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-5, 5, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  // === BUN RIGHT/EAST (höger halva av brödet) ===
  ctx.fillStyle = bunColor;
  ctx.beginPath();
  ctx.moveTo(8, -12);
  ctx.quadraticCurveTo(10, -7, 9, 0);
  ctx.lineTo(8, 7);
  ctx.quadraticCurveTo(6, 11, 3, 11);
  ctx.lineTo(4, 8);
  ctx.lineTo(4, -10);
  ctx.quadraticCurveTo(5, -14, 8, -12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // Bun highlight east (mot ljuset)
  ctx.fillStyle = bunHighlight;
  ctx.globalAlpha = 0.55;
  ctx.beginPath();
  ctx.moveTo(8, -12);
  ctx.lineTo(9, -7);
  ctx.lineTo(8, 4);
  ctx.lineTo(7, -3);
  ctx.lineTo(7, -11);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // Sesame seeds east
  ctx.fillStyle = flash ? '#fff' : '#ffe0a0';
  ctx.beginPath(); ctx.ellipse(6, -9, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(7, -5, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(5, -2, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(7, 3, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(6, 6, 0.5, 0.3, 0, 0, Math.PI * 2); ctx.fill();
  // === SAUSAGE (mittsektionen mellan bun halvor) ===
  ctx.fillStyle = sausageColor;
  ctx.beginPath();
  ctx.moveTo(-3, -13);
  ctx.lineTo(5, -13);
  ctx.lineTo(5, 9);
  ctx.quadraticCurveTo(1, 11, -3, 9);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.7;
  ctx.stroke();
  // Sausage shadow west
  ctx.fillStyle = sausageDark;
  ctx.globalAlpha = 0.55;
  ctx.fillRect(-3, -12, 1.5, 22);
  ctx.globalAlpha = 1;
  // Sausage highlight east
  ctx.fillStyle = sausageLight;
  ctx.fillRect(3.5, -12, 1, 22);
  // === MUSTARD ZIGZAG (gul streck på sausage) ===
  ctx.fillStyle = mustardColor;
  ctx.beginPath();
  ctx.moveTo(-2.5, -10);
  ctx.lineTo(-1, -12);
  ctx.lineTo(0, -10);
  ctx.lineTo(1.5, -12);
  ctx.lineTo(3, -10);
  ctx.lineTo(4.5, -12);
  ctx.lineTo(4.5, -8);
  ctx.lineTo(-2.5, -8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = flash ? '#fff' : '#aa8a20';
  ctx.lineWidth = 0.3;
  ctx.stroke();
  // === KETCHUP DRIZZLE (röd kurva på sausage) ===
  ctx.strokeStyle = ketchupColor;
  ctx.lineWidth = 1.2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-2, -2);
  ctx.quadraticCurveTo(0, 0, 1, -1.5);
  ctx.quadraticCurveTo(3, 2, 4, 0);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // === FACE peeking out — small eyes på sidorna av bunet ===
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-5.5, -8, 0.8, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(6.5, -8, 0.8, 0, Math.PI * 2); ctx.fill();
  // Eye glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(-5.3, -8.3, 0.3, 0.3);
  ctx.fillRect(6.7, -8.3, 0.3, 0.3);
  // Small smile på sausage mitt
  ctx.strokeStyle = flash ? '#fff' : '#5a1a08';
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(0, 4);
  ctx.quadraticCurveTo(1, 5, 2, 4);
  ctx.stroke();
  // === LEGS (skinny ben sticker ut nederifrån) ===
  // Back leg
  ctx.fillStyle = skinColor;
  ctx.fillRect(-3 - legSwing, 11, 2.2, 5.5);
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 11, 2.2, 5.5);
  // Front leg
  ctx.fillStyle = skinColor;
  ctx.fillRect(2 + legSwing, 11, 2.2, 5.5);
  ctx.strokeRect(2 + legSwing, 11, 2.2, 5.5);
  // Feet (svarta små skor)
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 17, 2.2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3.1 + legSwing, 17, 2.2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline;
  ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 17, 2.2, 1, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(3.1 + legSwing, 17, 2.2, 1, 0, 0, Math.PI * 2);
  ctx.stroke();
}

// ============================================================
// v1.489: NYA MAT-MASCOTS — Hamburgare, Pizza, Banan, Kiwi, Mango
// ============================================================

// HAMBURGARE — staplad burger: top bun + lettuce + tomato + cheese + patty + bottom bun
function drawHamburgerCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const bunTop       = flash ? '#fff' : '#d4a060';
  const bunBottom    = flash ? '#fff' : '#aa7a40';
  const bunHighlight = flash ? '#fff' : '#f0c080';
  const lettuce      = flash ? '#fff' : '#5aaa30';
  const lettuceDark  = flash ? '#fff' : '#3a7a1a';
  const tomato       = flash ? '#fff' : '#dd2818';
  const tomatoSeed   = flash ? '#fff' : '#ff8a30';
  const cheese       = flash ? '#fff' : '#ffd54a';
  const patty        = flash ? '#fff' : '#5a2818';
  const pattyDark    = flash ? '#fff' : '#3a1a08';
  const outline      = flash ? '#fff' : '#2a1a05';
  const skin         = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye     = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // TOP BUN (dome with sesame seeds)
  ctx.fillStyle = bunTop;
  ctx.beginPath();
  ctx.moveTo(-8, -10);
  ctx.quadraticCurveTo(-9, -16, -3, -18);
  ctx.quadraticCurveTo(0, -19, 3, -18);
  ctx.quadraticCurveTo(9, -16, 8, -10);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // Sesame seeds
  ctx.fillStyle = bunHighlight;
  const seeds = [[-5, -15], [-2, -16], [1, -16.5], [4, -15], [6, -13],
                 [-6, -12], [3, -13], [-3, -13.5]];
  for (const [sx, sy] of seeds) {
    ctx.beginPath();
    ctx.ellipse(sx, sy, 0.5, 0.3, 0.3, 0, Math.PI * 2);
    ctx.fill();
  }
  // Bun base shadow
  ctx.fillStyle = bunBottom;
  ctx.fillRect(-8, -11, 16, 1);
  // LETTUCE (wavy green ruffle)
  ctx.fillStyle = lettuce;
  ctx.beginPath();
  ctx.moveTo(-8, -10);
  for (let x = -8; x <= 8; x += 1) {
    const wave = Math.sin(x * 1.5) * 0.7;
    ctx.lineTo(x, -10 + wave);
  }
  ctx.lineTo(8, -7);
  ctx.lineTo(-8, -7);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = lettuceDark;
  for (const lx of [-6, -3, 0, 3, 6]) ctx.fillRect(lx, -8.5, 0.5, 1);
  // TOMATO disk
  ctx.fillStyle = tomato;
  ctx.fillRect(-7.5, -7, 15, 2);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-7.5, -7, 15, 2);
  ctx.fillStyle = tomatoSeed;
  for (const tx of [-5, 0, 4]) ctx.fillRect(tx, -6.5, 0.4, 0.4);
  // CHEESE (square hanging out at corners + drips)
  ctx.fillStyle = cheese;
  ctx.beginPath();
  ctx.moveTo(-8, -5);
  ctx.lineTo(8, -5);
  ctx.lineTo(7.5, -3);
  ctx.lineTo(-7.5, -3);
  ctx.closePath();
  ctx.fill();
  // Drips
  ctx.beginPath();
  ctx.moveTo(-7, -3); ctx.lineTo(-7.5, -1); ctx.lineTo(-6, -2); ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(7, -3); ctx.lineTo(7.5, -1); ctx.lineTo(6, -2); ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.4;
  ctx.stroke();
  // PATTY (dark brown beef with face)
  ctx.fillStyle = patty;
  ctx.fillRect(-7.5, -3, 15, 5);
  ctx.fillStyle = pattyDark;
  for (const [px, py] of [[-5, -2], [0, -1], [3, -2], [-3, 0], [4, 1], [-4, 1]]) {
    ctx.fillRect(px, py, 1, 0.5);
  }
  ctx.strokeStyle = outline; ctx.lineWidth = 0.7;
  ctx.strokeRect(-7.5, -3, 15, 5);
  // FACE on patty
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2, 0, 1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2, 0, 1, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2, 0, 0.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2, 0, 0.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(-1.7, -0.3, 0.3, 0.3);
  ctx.fillRect(2.3, -0.3, 0.3, 0.3);
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-1.5, 1.5); ctx.quadraticCurveTo(0, 2.2, 1.5, 1.5);
  ctx.stroke();
  // BOTTOM BUN
  ctx.fillStyle = bunBottom;
  ctx.beginPath();
  ctx.moveTo(-7, 2);
  ctx.quadraticCurveTo(-8, 4, -6, 8);
  ctx.lineTo(6, 8);
  ctx.quadraticCurveTo(8, 4, 7, 2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // LEGS (skin)
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2, 8);
  ctx.fillRect(2 + legSwing, 8, 2, 8);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2, 8);
  ctx.strokeRect(2 + legSwing, 8, 2, 8);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
}

// PIZZA — rund pizza-form med crust, sauce, cheese, pepperoni
function drawPizzaCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const crust       = flash ? '#fff' : '#d4a060';
  const crustDark   = flash ? '#fff' : '#aa7a40';
  const sauce       = flash ? '#fff' : '#cc2818';
  const cheese      = flash ? '#fff' : '#ffd54a';
  const cheeseLight = flash ? '#fff' : '#ffe080';
  const pepperoni   = flash ? '#fff' : '#aa1818';
  const pepperoniDark = flash ? '#fff' : '#6a0a0a';
  const outline     = flash ? '#fff' : '#3a1a05';
  const skin        = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // CRUST (outer ring)
  ctx.fillStyle = crust;
  ctx.beginPath();
  ctx.arc(0.5, -2, 9, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // SAUCE (inner red)
  ctx.fillStyle = sauce;
  ctx.beginPath();
  ctx.arc(0.5, -2, 7.5, 0, Math.PI * 2);
  ctx.fill();
  // CRUST inner edge
  ctx.strokeStyle = crustDark; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.arc(0.5, -2, 7.6, 0, Math.PI * 2);
  ctx.stroke();
  // CHEESE BLOBS scattered
  ctx.fillStyle = cheese;
  const cheeseBlobs = [
    [-3, -5, 1.8], [3, -4, 2.0], [0, -1, 2.2], [-4, 1, 1.7], [4, 2, 1.9],
    [-1, 4, 1.6], [5, -1, 1.4], [-5, -3, 1.6], [2, -5, 1.3], [-2, 2, 1.5]
  ];
  for (const [cx, cy, cr] of cheeseBlobs) {
    ctx.beginPath();
    ctx.arc(cx, cy, cr, 0, Math.PI * 2);
    ctx.fill();
  }
  // Cheese highlights
  ctx.fillStyle = cheeseLight;
  for (const [hx, hy] of [[-3, -5.5], [3, -4.5], [-1, 3.5], [4, 1.5]]) {
    ctx.beginPath();
    ctx.arc(hx, hy, 0.6, 0, Math.PI * 2);
    ctx.fill();
  }
  // PEPPERONI
  const pepperoniDots = [[-4, -3], [3, -2], [-1, 1], [5, 1], [-3, 3], [2, 4], [0, -5]];
  for (const [px, py] of pepperoniDots) {
    ctx.fillStyle = pepperoni;
    ctx.beginPath();
    ctx.arc(px, py, 1.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = pepperoniDark;
    ctx.beginPath();
    ctx.arc(px, py, 0.6, 0, Math.PI * 2);
    ctx.fill();
  }
  // FACE on pizza
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-3, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.3;
  ctx.beginPath(); ctx.arc(-3, -5, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(4, -5, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-3, -5, 0.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4, -5, 0.5, 0, Math.PI * 2); ctx.fill();
  // Big smile arc
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.arc(0.5, -2, 4, Math.PI * 0.15, Math.PI * 0.85);
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 7, 2, 8);
  ctx.fillRect(2 + legSwing, 7, 2, 8);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 7, 2, 8);
  ctx.strokeRect(2 + legSwing, 7, 2, 8);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 15, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 15, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
}

// BANAN — kurvad gul kropp med brun spets + bruna mogna prickar
function drawBananaCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const yellow      = flash ? '#fff' : '#ffd54a';
  const yellowDark  = flash ? '#fff' : '#cca828';
  const yellowLight = flash ? '#fff' : '#fff088';
  const brown       = flash ? '#fff' : '#5a3a1a';
  const tipBrown    = flash ? '#fff' : '#3a2a08';
  const outline     = flash ? '#fff' : '#2a1a05';
  const skin        = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BANANA BODY (curved C-shape)
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(-3, -18);
  ctx.quadraticCurveTo(-6, -15, -6, -10);
  ctx.quadraticCurveTo(-7, -3, -5, 4);
  ctx.quadraticCurveTo(-3, 9, 2, 10);
  ctx.quadraticCurveTo(6, 9, 7, 4);
  ctx.quadraticCurveTo(8, -3, 6, -10);
  ctx.quadraticCurveTo(5, -15, 1, -18);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1.2;
  ctx.stroke();
  // Brown tip at top
  ctx.fillStyle = tipBrown;
  ctx.beginPath();
  ctx.ellipse(-1, -18, 2.5, 1.5, 0, 0, Math.PI * 2);
  ctx.fill();
  // Brown ripe spots (fixed positions, no random)
  ctx.fillStyle = brown;
  for (const [sx, sy, sr] of [[-3, -13, 0.25], [3, -12, 0.4], [-4, -7, 0.3],
                              [4, -6, 0.2], [-2, -2, 0.5], [3, -1, 0.15],
                              [-3, 4, 0.35], [4, 4, 0.25]]) {
    ctx.beginPath();
    ctx.ellipse(sx, sy, 0.7, 0.4, sr, 0, Math.PI * 2);
    ctx.fill();
  }
  // West shadow ridge
  ctx.fillStyle = yellowDark;
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.moveTo(-5, -16);
  ctx.quadraticCurveTo(-6, -10, -6, -3);
  ctx.quadraticCurveTo(-5, 4, -3, 9);
  ctx.lineTo(-2, 9);
  ctx.quadraticCurveTo(-4, 4, -5, -3);
  ctx.quadraticCurveTo(-5, -10, -4, -16);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // East glossy highlight
  ctx.fillStyle = yellowLight;
  ctx.globalAlpha = 0.6;
  ctx.fillRect(4.5, -14, 1, 18);
  ctx.globalAlpha = 1;
  // FACE — v1.515 GOOFY/SILLY personality (excited big eyes + tongue out + blush)
  // Big bouncy eyes
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1, -7, 1.3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, -7, 1.3, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-1, -7, 1.3, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(3, -7, 1.3, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-1, -7, 0.6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, -7, 0.6, 0, Math.PI * 2); ctx.fill();
  // BIG sparkly glints (excited)
  ctx.fillStyle = '#fff';
  ctx.fillRect(-0.8, -7.4, 0.5, 0.5);
  ctx.fillRect(3.2, -7.4, 0.5, 0.5);
  ctx.fillRect(-1.4, -6.5, 0.25, 0.25);
  ctx.fillRect(2.7, -6.5, 0.25, 0.25);
  // OPEN LAUGHING MOUTH with TONGUE OUT
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath();
  ctx.ellipse(1, -3, 1.5, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  // Pink tongue sticking out below
  ctx.fillStyle = '#ff7090';
  ctx.beginPath();
  ctx.ellipse(1, -2.2, 1.0, 0.8, 0, 0, Math.PI);
  ctx.closePath(); ctx.fill();
  // Tongue line detail
  ctx.strokeStyle = '#cc4060'; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(1, -2.4); ctx.lineTo(1, -1.6);
  ctx.stroke();
  // BLUSH SPOTS (pink cheeks)
  ctx.fillStyle = '#ff8aaa';
  ctx.globalAlpha = 0.55;
  ctx.beginPath();
  ctx.ellipse(-2.5, -5, 0.9, 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(4.5, -5, 0.9, 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-2 - legSwing, 10, 2, 7);
  ctx.fillRect(2 + legSwing, 10, 2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-2 - legSwing, 10, 2, 7);
  ctx.strokeRect(2 + legSwing, 10, 2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1 - legSwing, 17, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 17, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
}

// KIWI — rund tvärsnitt med fuzzy brun yttre + grön flesh + svarta seeds
function drawKiwiCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const brown      = flash ? '#fff' : '#8a5a3a';
  const brownDark  = flash ? '#fff' : '#5a3a20';
  const green      = flash ? '#fff' : '#7aaa3a';
  const greenLight = flash ? '#fff' : '#aaca5a';
  const white      = flash ? '#fff' : '#f4f4e0';
  const seedBlack  = flash ? '#fff' : '#1a1a0a';
  const outline    = flash ? '#fff' : '#3a2a08';
  const skin       = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye   = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // OUTER FUZZY BROWN
  ctx.fillStyle = brown;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8.5, 11, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // Fuzzy texture (radial hatches)
  ctx.strokeStyle = brownDark; ctx.lineWidth = 0.3;
  for (let ang = 0; ang < Math.PI * 2; ang += 0.32) {
    const x1 = Math.cos(ang) * 8;
    const y1 = -3 + Math.sin(ang) * 10.5;
    const x2 = Math.cos(ang) * 8.4;
    const y2 = -3 + Math.sin(ang) * 10.8;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }
  // INNER GREEN FLESH
  ctx.fillStyle = green;
  ctx.beginPath();
  ctx.ellipse(0, -3, 7, 9.5, 0, 0, Math.PI * 2);
  ctx.fill();
  // Lighter green inner
  ctx.fillStyle = greenLight;
  ctx.beginPath();
  ctx.ellipse(0, -3, 5.5, 7.5, 0, 0, Math.PI * 2);
  ctx.fill();
  // WHITE CENTER STAR (10-point star)
  ctx.fillStyle = white;
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    const ang = -Math.PI / 2 + (i / 10) * Math.PI * 2;
    const r = i % 2 === 0 ? 1.5 : 0.6;
    const x = Math.cos(ang) * r;
    const y = -3 + Math.sin(ang) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();
  // BLACK SEEDS (oval pattern)
  ctx.fillStyle = seedBlack;
  for (let i = 0; i < 14; i++) {
    const ang = (i / 14) * Math.PI * 2;
    const rx = Math.cos(ang) * 3.5;
    const ry = -3 + Math.sin(ang) * 4.5;
    ctx.beginPath();
    ctx.ellipse(rx, ry, 0.35, 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // FACE — v1.515 SURPRISED/CURIOUS (BIG round amazed eyes + O-mouth + raised brows)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2, -7, 1.4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2, -7, 1.4, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.4;
  ctx.beginPath(); ctx.arc(-2, -7, 1.4, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2, -7, 1.4, 0, Math.PI * 2); ctx.stroke();
  // Small pupils (creates amazed wide-eyed look)
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2, -7, 0.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2, -7, 0.5, 0, Math.PI * 2); ctx.fill();
  // Eye sparkles
  ctx.fillStyle = '#fff';
  ctx.fillRect(-1.7, -7.3, 0.4, 0.4);
  ctx.fillRect(2.3, -7.3, 0.4, 0.4);
  // Raised eyebrows (high up, surprised)
  ctx.fillStyle = blackEye;
  ctx.fillRect(-3, -9.5, 2, 0.5);
  ctx.fillRect(1, -9.5, 2, 0.5);
  // O-shape MOUTH (oh!)
  ctx.fillStyle = '#3a0a08';
  ctx.beginPath();
  ctx.arc(0, -2, 0.9, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.4;
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2, 8);
  ctx.fillRect(2 + legSwing, 8, 2, 8);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2, 8);
  ctx.strokeRect(2 + legSwing, 8, 2, 8);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
}

// MANGO — oval orange-gul kropp med röd blush + grön stem + leaf
function drawMangoCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const orange     = flash ? '#fff' : '#ff9020';
  const yellow     = flash ? '#fff' : '#ffd54a';
  const red        = flash ? '#fff' : '#dd4020';
  const orangeDark = flash ? '#fff' : '#aa5010';
  const yellowHi   = flash ? '#fff' : '#ffe070';
  const green      = flash ? '#fff' : '#3a8a3a';
  const greenDark  = flash ? '#fff' : '#1a5a1a';
  const outline    = flash ? '#fff' : '#5a3a08';
  const skin       = flash ? '#fff' : (cos.skin || '#d4a574');
  const blackEye   = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BASE oval (yellow under)
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.ellipse(0, -2, 7, 10.5, 0.1, 0, Math.PI * 2);
  ctx.fill();
  // ORANGE main
  ctx.fillStyle = orange;
  ctx.beginPath();
  ctx.ellipse(0, -3, 6.8, 9.5, 0.1, 0, Math.PI * 2);
  ctx.fill();
  // RED blush top
  ctx.fillStyle = red;
  ctx.beginPath();
  ctx.ellipse(1, -10, 4.5, 3.5, 0.2, 0, Math.PI * 2);
  ctx.fill();
  // Blend orange over red edges
  ctx.fillStyle = orange;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.ellipse(1, -8, 4, 3.5, 0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // OUTLINE
  ctx.strokeStyle = outline; ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(0, -3, 7, 10.5, 0.1, 0, Math.PI * 2);
  ctx.stroke();
  // Shadow west
  ctx.fillStyle = orangeDark;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.ellipse(-3, -3, 2.5, 8, 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // Highlight east
  ctx.fillStyle = yellowHi;
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.ellipse(4, -2, 1.3, 6.5, 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // STEM (green)
  ctx.fillStyle = green;
  ctx.fillRect(-0.5, -15, 1, 3);
  // LEAF
  ctx.fillStyle = green;
  ctx.beginPath();
  ctx.moveTo(0, -14);
  ctx.quadraticCurveTo(3.5, -15.5, 4.5, -12);
  ctx.quadraticCurveTo(2.5, -13, 0, -13);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = greenDark; ctx.lineWidth = 0.4;
  ctx.stroke();
  // Leaf vein
  ctx.strokeStyle = greenDark; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(0.5, -13.5); ctx.lineTo(3.5, -12.8);
  ctx.stroke();
  // FACE — v1.515 LAID-BACK/CHILL (half-closed eyes + lopsided smile + tropical vibe)
  // Eye whites
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2, -5, 1.2, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -5, 1.2, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.3;
  ctx.beginPath(); ctx.arc(-2, -5, 1.2, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -5, 1.2, 0, Math.PI * 2); ctx.stroke();
  // Half-closed bottom-eyelids (chill/relaxed look)
  ctx.fillStyle = orangeDark || '#cc5a10';
  ctx.beginPath();
  ctx.arc(-2, -5, 1.2, 0, Math.PI);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.arc(2.5, -5, 1.2, 0, Math.PI);
  ctx.closePath(); ctx.fill();
  // Heavy lower eyelid lines
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-3, -5); ctx.lineTo(-1, -5);
  ctx.moveTo(1.5, -5); ctx.lineTo(3.5, -5);
  ctx.stroke();
  // Small upper pupils visible (just dots above lid line)
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2, -5.3, 0.35, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -5.3, 0.35, 0, Math.PI * 2); ctx.fill();
  // LOPSIDED CHILL SMILE (one corner up, one slight)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-1, -0.5);
  ctx.quadraticCurveTo(0.5, 1, 2.5, -0.8);
  ctx.stroke();
  // Tiny tongue-tip showing (relaxed)
  ctx.fillStyle = '#ff7090';
  ctx.fillRect(0.8, -0.1, 0.5, 0.4);
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2, 8);
  ctx.fillRect(2 + legSwing, 8, 2, 8);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2, 8);
  ctx.strokeRect(2 + legSwing, 8, 2, 8);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(3 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2);
  ctx.fill();
}

// ============================================================
// v1.496: PENCIL/BROCCOLI/CARROT/CASHEW — 4 nya mat/objekt-mascots
// ============================================================

// PENCIL (Blyertspenna) — gul hexagonal kropp + rosa rubber + sharpened tip
function drawPencilCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const yellow      = flash ? '#fff' : '#ffd54a';
  const yellowDark  = flash ? '#fff' : '#cca828';
  const yellowLight = flash ? '#fff' : '#fff088';
  const pink        = flash ? '#fff' : '#ff8a9a';
  const pinkDark    = flash ? '#fff' : '#cc5070';
  const silver      = flash ? '#fff' : '#aaaaaa';
  const silverDark  = flash ? '#fff' : '#5a5a5a';
  const wood        = flash ? '#fff' : '#cca878';
  const woodDark    = flash ? '#fff' : '#7a5a30';
  const graphite    = flash ? '#fff' : '#2a2a2a';
  const outline     = flash ? '#fff' : '#3a2a08';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const stickColor  = flash ? '#fff' : '#5a3a20';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 1.2 : 0;
  // ERASER (rosa cap)
  ctx.fillStyle = pink;
  ctx.beginPath();
  ctx.moveTo(-2.3, -16);
  ctx.quadraticCurveTo(-2.5, -18.5, -0.5, -18.8);
  ctx.lineTo(0.5, -18.8);
  ctx.quadraticCurveTo(2.5, -18.5, 2.3, -16);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.8;
  ctx.stroke();
  // Eraser shadow (under-side)
  ctx.fillStyle = pinkDark;
  ctx.fillRect(-2.3, -16.5, 4.6, 0.5);
  // Eraser highlight
  ctx.fillStyle = flash ? '#fff' : '#ffb5c0';
  ctx.fillRect(-1.5, -18.3, 1, 1.5);
  // METAL BAND (silver ferrule)
  ctx.fillStyle = silver;
  ctx.fillRect(-2.4, -16, 4.8, 1.5);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.6;
  ctx.strokeRect(-2.4, -16, 4.8, 1.5);
  // Rivets/lines on ferrule
  ctx.fillStyle = silverDark;
  ctx.fillRect(-2.4, -15.5, 4.8, 0.2);
  ctx.fillRect(-2.4, -15.0, 4.8, 0.2);
  // YELLOW HEXAGONAL BODY
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(-2.4, -14.5);
  ctx.lineTo(2.4, -14.5);
  ctx.lineTo(2.4, 5);
  ctx.lineTo(-2.4, 5);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.8;
  ctx.stroke();
  // Hexagonal edges (vertical lines on body)
  ctx.strokeStyle = yellowDark; ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.moveTo(-1.5, -14.5); ctx.lineTo(-1.5, 5);
  ctx.moveTo(0, -14.5); ctx.lineTo(0, 5);
  ctx.moveTo(1.5, -14.5); ctx.lineTo(1.5, 5);
  ctx.stroke();
  // East-side highlight
  ctx.fillStyle = yellowLight;
  ctx.fillRect(1.8, -14, 0.5, 18);
  // FACE on body
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1, -4, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1, -4, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-1, -4, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1, -4, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(-0.7, -4.3, 0.3, 0.3);
  ctx.fillRect(1.3, -4.3, 0.3, 0.3);
  // Smile
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-0.7, -2); ctx.quadraticCurveTo(0, -1, 0.7, -2);
  ctx.stroke();
  // WOOD CONE (lower body taper)
  ctx.fillStyle = wood;
  ctx.beginPath();
  ctx.moveTo(-2.4, 5);
  ctx.lineTo(2.4, 5);
  ctx.lineTo(0.7, 9);
  ctx.lineTo(-0.7, 9);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.6;
  ctx.stroke();
  // Wood grain lines
  ctx.strokeStyle = woodDark; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(-1.5, 6); ctx.lineTo(-0.5, 8.5);
  ctx.moveTo(0, 6); ctx.lineTo(0, 8.5);
  ctx.moveTo(1.5, 6); ctx.lineTo(0.5, 8.5);
  ctx.stroke();
  // GRAPHITE TIP (sharp point)
  ctx.fillStyle = graphite;
  ctx.beginPath();
  ctx.moveTo(-0.7, 9);
  ctx.lineTo(0.7, 9);
  ctx.lineTo(0, 11.5);
  ctx.closePath();
  ctx.fill();
  // Tip highlight
  ctx.strokeStyle = silver; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(-0.3, 9.5); ctx.lineTo(0, 11);
  ctx.stroke();
  // STICK ARMS (sticker ut från sidor)
  const armSwing = isMoving ? swing * 1.5 : 0;
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.3; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-2.4, -2);
  ctx.lineTo(-5.5, 1 - armSwing);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(2.4, -2);
  ctx.lineTo(5.5, 1 + armSwing);
  ctx.stroke();
  // Hands
  ctx.fillStyle = stickColor;
  ctx.beginPath(); ctx.arc(-5.5, 1 - armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(5.5, 1 + armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  // STICK LEGS — pencil-tipen är där fötterna går (men vi har riktiga ben på sidor)
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-2 - legSwing, 11.5);
  ctx.lineTo(-2 - legSwing, 16);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(2 + legSwing, 11.5);
  ctx.lineTo(2 + legSwing, 16);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // Feet
  ctx.fillStyle = stickColor;
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 17, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(2 + legSwing, 17, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
}

// BROCCOLI — grön flower head + light green stalk
function drawBroccoliCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const greenDark   = flash ? '#fff' : '#3a7a1a';
  const greenMid    = flash ? '#fff' : '#5aaa3a';
  const greenLight  = flash ? '#fff' : '#7aca5a';
  const stalkGreen  = flash ? '#fff' : '#aaca7a';
  const stalkDark   = flash ? '#fff' : '#7aaa4a';
  const outline     = flash ? '#fff' : '#2a4a08';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const stickColor  = flash ? '#fff' : '#5a3a20';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 1.5 : 0;
  // FLOWER HEAD — multiple cloudy bumps (broccoli florets)
  // Main base
  ctx.fillStyle = greenMid;
  ctx.beginPath();
  ctx.ellipse(0, -11, 8, 6, 0, 0, Math.PI * 2);
  ctx.fill();
  // Florets (multiple bumps)
  const florets = [
    [-6, -13, 2.5], [-3, -16, 3.0], [0, -17, 3.2],
    [3, -16, 2.8], [6, -13.5, 2.6],
    [-5, -10, 2.4], [-1, -10, 2.5], [3.5, -10, 2.4],
    [5.5, -8, 2.0], [-5.5, -8, 2.0]
  ];
  ctx.fillStyle = greenMid;
  for (const [fx, fy, fr] of florets) {
    ctx.beginPath();
    ctx.arc(fx, fy, fr, 0, Math.PI * 2);
    ctx.fill();
  }
  // Texture variation (lighter bumps)
  ctx.fillStyle = greenLight;
  for (const [hx, hy, hr] of [[-2, -17, 1.0], [2, -16, 0.8], [-4, -12, 0.7],
                              [4, -12, 0.7], [0, -13, 0.8]]) {
    ctx.beginPath();
    ctx.arc(hx, hy, hr, 0, Math.PI * 2);
    ctx.fill();
  }
  // Darker shadow bumps (depth)
  ctx.fillStyle = greenDark;
  for (const [dx, dy] of [[-4, -10], [3, -10], [-1, -8], [4, -8]]) {
    ctx.beginPath();
    ctx.arc(dx, dy, 0.7, 0, Math.PI * 2);
    ctx.fill();
  }
  // Outline runt flower
  ctx.strokeStyle = outline; ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.ellipse(0, -11, 8, 6, 0, 0, Math.PI * 2);
  ctx.stroke();
  // STALK (light green column)
  ctx.fillStyle = stalkGreen;
  ctx.beginPath();
  ctx.moveTo(-2.5, -6);
  ctx.lineTo(2.5, -6);
  ctx.lineTo(2.5, 10);
  ctx.quadraticCurveTo(0, 11, -2.5, 10);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 0.7;
  ctx.stroke();
  // Stalk ridges (vertical detail)
  ctx.fillStyle = stalkDark;
  ctx.fillRect(-2, -5, 0.4, 14);
  ctx.fillRect(-0.2, -5, 0.4, 14);
  ctx.fillRect(1.6, -5, 0.4, 14);
  // FACE on stalk
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1, 0, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1, 0, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-1, 0, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1, 0, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(-0.7, -0.3, 0.3, 0.3);
  ctx.fillRect(1.3, -0.3, 0.3, 0.3);
  // Smile
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-1, 2.5); ctx.quadraticCurveTo(0, 3.5, 1, 2.5);
  ctx.stroke();
  // STICK LEGS
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.4; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-1.5 - legSwing, 10.5);
  ctx.lineTo(-1.5 - legSwing, 16);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(1.5 + legSwing, 10.5);
  ctx.lineTo(1.5 + legSwing, 16);
  ctx.stroke();
  ctx.lineCap = 'butt';
  ctx.fillStyle = stickColor;
  ctx.beginPath();
  ctx.ellipse(-1.5 - legSwing, 17, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.5 + legSwing, 17, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
}

// CARROT — orange tapered cone + green leafy top
function drawCarrotCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const orange      = flash ? '#fff' : '#ff8a30';
  const orangeDark  = flash ? '#fff' : '#cc5810';
  const orangeLight = flash ? '#fff' : '#ffb060';
  const greenDark   = flash ? '#fff' : '#3a7a1a';
  const greenLight  = flash ? '#fff' : '#5aaa3a';
  const outline     = flash ? '#fff' : '#5a3008';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const stickColor  = flash ? '#fff' : '#5a3a20';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 1.5 : 0;
  // LEAFY TOP — 5 långa pointed leaves
  ctx.fillStyle = greenDark;
  const leaves = [
    [-3, -10, -4.5, -18, -2, -16],     // far west leaf
    [-1.5, -10, -1, -19, 0, -17],      // west-center
    [0.5, -10, 1, -20, 2.5, -18],      // center-east
    [2.5, -10, 4, -18.5, 3.5, -16.5],  // east-center
    [4, -10, 5.5, -17, 5, -15]         // far east
  ];
  for (const [bx, by, tx, ty, mx, my] of leaves) {
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.quadraticCurveTo(mx, my, tx, ty);
    ctx.quadraticCurveTo(mx + 1, my + 1, bx + 1, by);
    ctx.closePath();
    ctx.fill();
  }
  // Leaf highlights (lighter green on tops)
  ctx.fillStyle = greenLight;
  for (const [tx, ty] of [[-4.5, -18], [-1, -19], [1, -20], [4, -18.5], [5.5, -17]]) {
    ctx.beginPath();
    ctx.arc(tx, ty, 0.5, 0, Math.PI * 2);
    ctx.fill();
  }
  // CARROT BODY — orange tapered cone (top wide, bottom point)
  ctx.fillStyle = orange;
  ctx.beginPath();
  ctx.moveTo(-5, -10);
  ctx.lineTo(5, -10);
  ctx.lineTo(2, 4);                  // narrowing
  ctx.lineTo(0.5, 9);                // tip-narrow
  ctx.lineTo(-0.5, 11);              // pointed tip
  ctx.lineTo(-2, 4);                 // narrowing west
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1.0;
  ctx.stroke();
  // HORIZONTAL RIDGES (carrot texture)
  ctx.strokeStyle = orangeDark; ctx.lineWidth = 0.4;
  for (const ry of [-7, -4, -1, 2, 5, 7]) {
    const ratio = (ry - (-10)) / (11 - (-10)); // 0 at top, 1 at bottom
    const halfW = 5 * (1 - ratio * 0.85);
    ctx.beginPath();
    ctx.moveTo(-halfW, ry);
    ctx.quadraticCurveTo(0, ry + 0.4, halfW, ry);
    ctx.stroke();
  }
  // East-side highlight (sheen)
  ctx.fillStyle = orangeLight;
  ctx.beginPath();
  ctx.moveTo(3, -9);
  ctx.lineTo(4, -9);
  ctx.lineTo(1.5, 3);
  ctx.lineTo(0.8, 3);
  ctx.closePath();
  ctx.fill();
  // FACE on body
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1.5, -5, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1.5, -5, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-1.5, -5, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1.5, -5, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(-1.2, -5.3, 0.3, 0.3);
  ctx.fillRect(1.8, -5.3, 0.3, 0.3);
  // Smile
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-1, -2); ctx.quadraticCurveTo(0, -1, 1, -2);
  ctx.stroke();
  // STICK ARMS
  const armSwing = isMoving ? swing * 1.5 : 0;
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.3; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-4, -6);
  ctx.lineTo(-6.5, -3 - armSwing);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(4, -6);
  ctx.lineTo(6.5, -3 + armSwing);
  ctx.stroke();
  ctx.fillStyle = stickColor;
  ctx.beginPath(); ctx.arc(-6.5, -3 - armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(6.5, -3 + armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  ctx.lineCap = 'butt';
  // Carrot tip serves as bottom — no separate legs needed.
  // But for walk-cycle illusion, add subtle leg-stubs.
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-1 - legSwing * 0.5, 11.5);
  ctx.lineTo(-1.5 - legSwing * 0.5, 14);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0.5 + legSwing * 0.5, 11.5);
  ctx.lineTo(1 + legSwing * 0.5, 14);
  ctx.stroke();
  // Feet
  ctx.fillStyle = stickColor;
  ctx.beginPath();
  ctx.ellipse(-1.5 - legSwing * 0.5, 14.5, 1.4, 0.7, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1 + legSwing * 0.5, 14.5, 1.4, 0.7, 0, 0, Math.PI * 2); ctx.fill();
}

// CASHEW — kidney/C-curved shape, beige nut with face
function drawCashewCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const beige       = flash ? '#fff' : '#d4c090';
  const beigeDark   = flash ? '#fff' : '#a08a60';
  const beigeLight  = flash ? '#fff' : '#f0e0b8';
  const outline     = flash ? '#fff' : '#5a4020';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const stickColor  = flash ? '#fff' : '#5a3a20';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 1.5 : 0;
  // CASHEW BODY — C-curve / kidney bean shape, facing east
  ctx.fillStyle = beige;
  ctx.beginPath();
  // Outer curve (east side, convex)
  ctx.moveTo(-2, -10);
  ctx.quadraticCurveTo(4, -10, 6, -5);
  ctx.quadraticCurveTo(7, 0, 6, 5);
  ctx.quadraticCurveTo(4, 10, -2, 10);
  // Inner curve (west side, concave — the kidney indent)
  ctx.quadraticCurveTo(-6, 8, -7, 5);
  ctx.quadraticCurveTo(-5, 3, -4, 0);          // pinch inward
  ctx.quadraticCurveTo(-5, -3, -7, -5);
  ctx.quadraticCurveTo(-6, -8, -2, -10);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1.0;
  ctx.stroke();
  // East-side highlight (mot ljuset)
  ctx.fillStyle = beigeLight;
  ctx.beginPath();
  ctx.moveTo(4, -7);
  ctx.quadraticCurveTo(6, -4, 6, 3);
  ctx.lineTo(5, 3);
  ctx.quadraticCurveTo(5, -3, 3.5, -6);
  ctx.closePath();
  ctx.fill();
  // West indent shadow (gör kidney-shape tydlig)
  ctx.fillStyle = beigeDark;
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.moveTo(-7, -3);
  ctx.quadraticCurveTo(-5, 0, -7, 3);
  ctx.lineTo(-6, 3);
  ctx.quadraticCurveTo(-4, 0, -6, -3);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // Subtle surface texture (small lighter spots)
  ctx.fillStyle = beigeLight;
  for (const [tx, ty] of [[2, -5], [4, 2], [1, 6], [-3, -7], [-1, 8]]) {
    ctx.beginPath();
    ctx.ellipse(tx, ty, 0.5, 0.3, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // FACE on east-side (visible portion of cashew)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(0, -3, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, -3, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(0, -3, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, -3, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(0.3, -3.3, 0.3, 0.3);
  ctx.fillRect(3.3, -3.3, 0.3, 0.3);
  // Smile
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(0.5, 0); ctx.quadraticCurveTo(1.5, 1, 2.5, 0);
  ctx.stroke();
  // Tiny blush cheeks
  ctx.fillStyle = flash ? '#fff' : '#ff9090';
  ctx.globalAlpha = 0.55;
  ctx.beginPath(); ctx.arc(-2, -1, 0.6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(5, -1, 0.6, 0, Math.PI * 2); ctx.fill();
  ctx.globalAlpha = 1;
  // STICK ARMS
  const armSwing = isMoving ? swing * 1.5 : 0;
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.3; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-6, 1);
  ctx.lineTo(-9, 4 - armSwing);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(6, 0);
  ctx.lineTo(9, 3 + armSwing);
  ctx.stroke();
  ctx.fillStyle = stickColor;
  ctx.beginPath(); ctx.arc(-9, 4 - armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(9, 3 + armSwing, 1.0, 0, Math.PI * 2); ctx.fill();
  // STICK LEGS
  ctx.strokeStyle = stickColor; ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-2 - legSwing, 10);
  ctx.lineTo(-2 - legSwing, 15);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(2 + legSwing, 10);
  ctx.lineTo(2 + legSwing, 15);
  ctx.stroke();
  ctx.lineCap = 'butt';
  ctx.fillStyle = stickColor;
  ctx.beginPath();
  ctx.ellipse(-2 - legSwing, 16, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(2 + legSwing, 16, 1.8, 0.8, 0, 0, Math.PI * 2); ctx.fill();
}

// ============================================================
// v1.513: 8 NYA EXOTISKA FRUKT-MASCOTS
// Design: pineapple (taggig krona), dragonfruit (alien-look), durian (taggig+stink-lines),
// coconut (hårig+ögon-hål), pomegranate (kalkblad+frön), starfruit (5-stjärna),
// pricklypear (taggig outsider), olive (klassisk med pimento)
// Alla i 35-unit coord-system (top y~-19, feet y=16) — skalas 1.4x av drawNakedBody.
// ============================================================

// ANANAS — v1.515 REDESIGN: layered crown, pineapple-tapered body, discrete
// diamond pattern (ej crosshatch), regal/proud face (half-lidded + mustache lines)
function drawPineappleCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const yellow      = flash ? '#fff' : '#ffd54a';
  const yellowDark  = flash ? '#fff' : '#cc9818';
  const yellowLite  = flash ? '#fff' : '#fff088';
  const brownPat    = flash ? '#fff' : '#aa6a18';
  const brownDk     = flash ? '#fff' : '#7a4a08';
  const green       = flash ? '#fff' : '#3a8a3a';
  const greenDark   = flash ? '#fff' : '#1a5a1a';
  const greenLite   = flash ? '#fff' : '#5aaa3a';
  const skin        = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline     = flash ? '#fff' : '#3a1a05';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const eyebrowCol  = flash ? '#fff' : '#7a4a08';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // === LAYERED LEAFY CROWN — 9 leaves med curves + veins ===
  // BACK layer (mörkast green, outermost leaves)
  ctx.fillStyle = greenDark;
  for (const [bx, by, tx, ty, w] of [
    [-5, -10, -7.5, -16, 1.2],
    [5, -10, 7.5, -16, 1.2],
    [-4, -10, -6, -19, 1.3],
    [4, -10, 6, -19, 1.3],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx - w, by);
    ctx.quadraticCurveTo(bx + (tx - bx) * 0.4, by - 4, tx, ty);
    ctx.quadraticCurveTo(bx + (tx - bx) * 0.6 + 0.3, by - 4, bx + w, by);
    ctx.closePath();
    ctx.fill();
  }
  // MID layer (medium green)
  ctx.fillStyle = green;
  for (const [bx, by, tx, ty, w] of [
    [-2.5, -10.5, -3.5, -20, 1.4],
    [2.5, -10.5, 3.5, -20, 1.4],
    [-1, -11, -1.8, -21.5, 1.3],
    [1, -11, 1.8, -21.5, 1.3],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx - w, by);
    ctx.quadraticCurveTo(bx + (tx - bx) * 0.4, by - 5, tx, ty);
    ctx.quadraticCurveTo(bx + (tx - bx) * 0.6 + 0.3, by - 5, bx + w, by);
    ctx.closePath();
    ctx.fill();
  }
  // TOP leaf (tallest center, ljusast)
  ctx.fillStyle = greenLite;
  ctx.beginPath();
  ctx.moveTo(-1.3, -11);
  ctx.quadraticCurveTo(-0.5, -18, 0, -22.5);
  ctx.quadraticCurveTo(0.5, -18, 1.3, -11);
  ctx.closePath();
  ctx.fill();
  // Leaf veins (centerlines)
  ctx.strokeStyle = greenDark; ctx.lineWidth = 0.3;
  for (const [bx, by, tx, ty] of [
    [-5, -10, -7.5, -16], [5, -10, 7.5, -16],
    [-4, -10, -6, -19], [4, -10, 6, -19],
    [-2.5, -10.5, -3.5, -20], [2.5, -10.5, 3.5, -20],
    [-1, -11, -1.8, -21.5], [1, -11, 1.8, -21.5],
    [0, -11, 0, -22.5],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(tx, ty);
    ctx.stroke();
  }
  // === BODY — pineapple-shaped (wider top, slightly tapered) ===
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.moveTo(-8, -8);
  ctx.quadraticCurveTo(-9.5, -3, -8.5, 2);
  ctx.quadraticCurveTo(-7.5, 7, -4, 8);
  ctx.lineTo(4, 8);
  ctx.quadraticCurveTo(7.5, 7, 8.5, 2);
  ctx.quadraticCurveTo(9.5, -3, 8, -8);
  ctx.quadraticCurveTo(0, -10, -8, -8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // === DISCRETE DIAMOND PATTERN (NOT crosshatch — proper pineapple texture) ===
  ctx.strokeStyle = brownPat; ctx.lineWidth = 0.35;
  // Rows of diamonds, alternating offset per row
  const diamondRows = [
    { y: -6, offset: 0 },
    { y: -3, offset: 1.5 },
    { y: 0, offset: 0 },
    { y: 3, offset: 1.5 },
    { y: 6, offset: 0 },
  ];
  for (const row of diamondRows) {
    for (let col = -2; col <= 2; col++) {
      const x = col * 3 + row.offset - 0.7;
      // Skip diamonds outside body silhouette (rough check)
      const maxXForY = 7.5 - Math.abs(row.y) * 0.25;
      if (Math.abs(x) > maxXForY) continue;
      // Diamond outline
      ctx.beginPath();
      ctx.moveTo(x, row.y - 1.1);
      ctx.lineTo(x + 1.4, row.y);
      ctx.lineTo(x, row.y + 1.1);
      ctx.lineTo(x - 1.4, row.y);
      ctx.closePath();
      ctx.stroke();
      // Small dark bump in center (signature pineapple eye)
      ctx.fillStyle = brownDk;
      ctx.beginPath();
      ctx.arc(x, row.y, 0.35, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // East-side body highlight (sheen)
  ctx.fillStyle = yellowLite;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.ellipse(4.5, -1, 1.5, 5, -0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // === FACE — REGAL/PROUD personality ===
  // White sclera
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2.5, -3, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -3, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-2.5, -3, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -3, 1.1, 0, Math.PI * 2); ctx.stroke();
  // HALF-LIDDED EYELIDS (top half covered = haughty look)
  ctx.fillStyle = yellow;
  ctx.beginPath();
  ctx.arc(-2.5, -3, 1.1, Math.PI, 0);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.arc(2.5, -3, 1.1, Math.PI, 0);
  ctx.closePath(); ctx.fill();
  // Eyelid line (heavy lash line)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.moveTo(-3.6, -3); ctx.lineTo(-1.4, -3);
  ctx.moveTo(1.4, -3); ctx.lineTo(3.6, -3);
  ctx.stroke();
  // Pupils (only lower half visible)
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2.3, -2.6, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.7, -2.6, 0.45, 0, Math.PI * 2); ctx.fill();
  // Glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(-2.1, -2.8, 0.25, 0.25);
  ctx.fillRect(2.9, -2.8, 0.25, 0.25);
  // RAISED EYEBROWS (proud, arched, brown)
  ctx.fillStyle = eyebrowCol;
  ctx.beginPath();
  ctx.moveTo(-3.8, -4.5);
  ctx.quadraticCurveTo(-2.5, -5.2, -1.2, -4.8);
  ctx.lineTo(-1.2, -4.3);
  ctx.quadraticCurveTo(-2.5, -4.7, -3.8, -4.0);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(3.8, -4.5);
  ctx.quadraticCurveTo(2.5, -5.2, 1.2, -4.8);
  ctx.lineTo(1.2, -4.3);
  ctx.quadraticCurveTo(2.5, -4.7, 3.8, -4.0);
  ctx.closePath(); ctx.fill();
  // SMUG SMALL SMILE (closed mouth, slight upturn)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.65;
  ctx.beginPath();
  ctx.moveTo(-1.4, -0.2);
  ctx.quadraticCurveTo(0, 0.3, 1.4, -0.2);
  ctx.stroke();
  // TINY MUSTACHE-LIKE LINES (regal touch)
  ctx.strokeStyle = brownPat; ctx.lineWidth = 0.35;
  ctx.beginPath();
  ctx.moveTo(-1.2, -0.8); ctx.lineTo(-0.5, -1);
  ctx.moveTo(1.2, -0.8); ctx.lineTo(0.5, -1);
  ctx.stroke();
  // === LEGS ===
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  // FEET
  ctx.fillStyle = flash ? '#fff' : '#3a2010';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// DRAKFRUKT — pink/red oval med green pointed scales sticker ut, alien-look
function drawDragonfruitCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const pink       = flash ? '#fff' : '#ff5aaa';
  const pinkDark   = flash ? '#fff' : '#cc2a7a';
  const pinkLite   = flash ? '#fff' : '#ff8aca';
  const green      = flash ? '#fff' : '#5aaa3a';
  const greenLite  = flash ? '#fff' : '#7aca5a';
  const white      = flash ? '#fff' : '#f4f0e0';
  const blackSeed  = flash ? '#fff' : '#0a0a0a';
  const skin       = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline    = flash ? '#fff' : '#3a0a2a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (pink/magenta oval)
  ctx.fillStyle = pink;
  ctx.beginPath();
  ctx.ellipse(0, -4, 8, 12, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // GREEN POINTED SCALES sticking out (alien dragon-look)
  ctx.fillStyle = green;
  for (const [bx, by, tx, ty] of [
    [-7, -8, -10, -10],
    [-7, 0, -10, -1],
    [-6, 5, -9, 6],
    [7, -8, 10, -10],
    [7, 0, 10, -1],
    [6, 5, 9, 6],
    [-3, -15, -4, -19],
    [3, -15, 4, -19],
    [-1, -16, -1, -20],
    [1, -16, 1, -20.5],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx, by - 1.5);
    ctx.lineTo(tx, ty);
    ctx.lineTo(bx, by + 1.5);
    ctx.closePath();
    ctx.fill();
  }
  // Scale shadows (mörkare baksidan)
  ctx.fillStyle = pinkDark;
  for (const [bx, by] of [[-7, -8], [-7, 0], [-6, 5], [7, -8], [7, 0], [6, 5]]) {
    ctx.beginPath();
    ctx.ellipse(bx, by, 1, 1.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // Pink highlight (east side)
  ctx.fillStyle = pinkLite;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.ellipse(3, -5, 2, 5, -0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // WHITE INTERIOR PATCH visible (showing flesh — alien vibe)
  ctx.fillStyle = white;
  ctx.beginPath();
  ctx.ellipse(0, 1, 4, 5, 0, 0, Math.PI * 2);
  ctx.fill();
  // BLACK SEEDS scattered in white area
  ctx.fillStyle = blackSeed;
  for (const [sx, sy] of [[-2, -1], [1, -1], [-1, 1], [2, 1], [-2, 3], [1, 3], [0, 0], [-3, 0], [3, 0]]) {
    ctx.beginPath();
    ctx.arc(sx, sy, 0.35, 0, Math.PI * 2);
    ctx.fill();
  }
  // FACE — v1.515 ALIEN STARE (HUGE round eyes + tiny dot pupils + mini-O mouth + 3rd eye)
  // Huge alien eyes (much bigger än standard)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2.5, -8, 1.7, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -8, 1.7, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -8, 1.7, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackSeed; ctx.lineWidth = 0.4;
  ctx.beginPath(); ctx.arc(-2.5, -8, 1.7, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -8, 1.7, 0, Math.PI * 2); ctx.stroke();
  // TINY pupil dots (creates wide alien stare)
  ctx.fillStyle = blackSeed;
  ctx.beginPath(); ctx.arc(-2.3, -8, 0.3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.7, -8, 0.3, 0, Math.PI * 2); ctx.fill();
  // Big eye sparkles (otherworldly shine)
  ctx.fillStyle = '#fff';
  ctx.fillRect(-3, -8.8, 0.6, 0.6);
  ctx.fillRect(2, -8.8, 0.6, 0.6);
  // THIRD EYE dot on forehead (alien vibe)
  ctx.fillStyle = pinkDark;
  ctx.beginPath(); ctx.arc(0, -10.5, 0.4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.fillRect(-0.1, -10.7, 0.2, 0.2);
  // TINY O mouth (mystified)
  ctx.fillStyle = '#3a0a2a';
  ctx.beginPath();
  ctx.arc(0, -5.5, 0.55, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = blackSeed; ctx.lineWidth = 0.3;
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 9, 2.2, 6);
  ctx.fillRect(0.8 + legSwing, 9, 2.2, 6);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 9, 2.2, 6);
  ctx.strokeRect(0.8 + legSwing, 9, 2.2, 6);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// DURIAN — spiky greenish-yellow body med stink-lines (comedy gold)
function drawDurianCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const durianBody = flash ? '#fff' : '#caa820';
  const durianDark = flash ? '#fff' : '#8a7818';
  const durianLite = flash ? '#fff' : '#eac848';
  const spikeColor = flash ? '#fff' : '#5a4a08';
  const stinkColor = flash ? '#fff' : 'rgba(120, 180, 100, 0.55)';
  const skin       = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline    = flash ? '#fff' : '#2a1808';
  const blackEye   = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (round/oval with thorny silhouette)
  ctx.fillStyle = durianBody;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8, 10, 0, 0, Math.PI * 2);
  ctx.fill();
  // MANY SPIKES sticking out i alla riktningar (durians iconic spikar)
  ctx.fillStyle = durianBody;
  ctx.strokeStyle = spikeColor; ctx.lineWidth = 0.3;
  const spikes = [];
  for (let i = 0; i < 20; i++) {
    const ang = (i / 20) * Math.PI * 2;
    const bx = Math.cos(ang) * 7;
    const by = -3 + Math.sin(ang) * 9;
    const tx = Math.cos(ang) * 9.5;
    const ty = -3 + Math.sin(ang) * 11.5;
    spikes.push([bx, by, tx, ty, ang]);
  }
  for (const [bx, by, tx, ty, ang] of spikes) {
    const perp1x = -Math.sin(ang) * 1.0;
    const perp1y = Math.cos(ang) * 1.0;
    ctx.beginPath();
    ctx.moveTo(bx - perp1x, by - perp1y);
    ctx.lineTo(tx, ty);
    ctx.lineTo(bx + perp1x, by + perp1y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
  // Body outline
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8, 10, 0, 0, Math.PI * 2);
  ctx.stroke();
  // Texture (cross-hatch shading)
  ctx.strokeStyle = durianDark; ctx.lineWidth = 0.25;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(-5 + i, -8); ctx.lineTo(-1 + i, 4);
    ctx.stroke();
  }
  // STINK LINES (comedy waves rising up from durian)
  ctx.strokeStyle = stinkColor; ctx.lineWidth = 1.2;
  for (const [sx, baseY] of [[-3.5, -14], [0.5, -15], [4, -14]]) {
    ctx.beginPath();
    ctx.moveTo(sx, baseY);
    ctx.quadraticCurveTo(sx + 1, baseY - 1, sx, baseY - 2.5);
    ctx.quadraticCurveTo(sx - 1, baseY - 4, sx, baseY - 5.5);
    ctx.stroke();
  }
  // Stink "lines" small detail dots
  ctx.fillStyle = stinkColor;
  ctx.beginPath(); ctx.arc(-3.5, -19, 0.4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0.5, -20, 0.4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4, -19, 0.4, 0, Math.PI * 2); ctx.fill();
  // FACE (between spikes — exhausted/pained expression for comedy)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2.5, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-2.5, -5, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -5, 1.1, 0, Math.PI * 2); ctx.stroke();
  // X-eyes (v1.515 ENHANCED — passed out + tongue + sweat drops för stink-comedy)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-3.3, -5.8); ctx.lineTo(-1.7, -4.2);
  ctx.moveTo(-3.3, -4.2); ctx.lineTo(-1.7, -5.8);
  ctx.moveTo(1.7, -5.8); ctx.lineTo(3.3, -4.2);
  ctx.moveTo(1.7, -4.2); ctx.lineTo(3.3, -5.8);
  ctx.stroke();
  // Open mouth med PINK TONGUE STICKING OUT (queasy)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.arc(0, -2, 1.0, 0, Math.PI);
  ctx.closePath();
  ctx.fillStyle = '#3a0a08';
  ctx.fill();
  ctx.stroke();
  // Tongue hanging out
  ctx.fillStyle = '#ff7090';
  ctx.beginPath();
  ctx.moveTo(-0.7, -1.5);
  ctx.quadraticCurveTo(0, 0.5, 0.7, -1.5);
  ctx.quadraticCurveTo(0.3, -0.8, 0, -1);
  ctx.quadraticCurveTo(-0.3, -0.8, -0.7, -1.5);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#cc4060'; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(0, -1.2); ctx.lineTo(0, 0.2);
  ctx.stroke();
  // SWEAT DROPS (3 around head - signature stink comedy)
  ctx.fillStyle = '#7accea';
  ctx.shadowColor = '#5aaaca'; ctx.shadowBlur = 2;
  // Sweat drop 1 (above east temple)
  ctx.beginPath();
  ctx.moveTo(7, -10);
  ctx.quadraticCurveTo(6.5, -8.5, 7, -7.5);
  ctx.quadraticCurveTo(7.5, -8.5, 7, -10);
  ctx.closePath(); ctx.fill();
  // Sweat drop 2 (above west temple)
  ctx.beginPath();
  ctx.moveTo(-7, -10);
  ctx.quadraticCurveTo(-7.5, -8.5, -7, -7.5);
  ctx.quadraticCurveTo(-6.5, -8.5, -7, -10);
  ctx.closePath(); ctx.fill();
  // Small sweat splash
  ctx.beginPath();
  ctx.arc(0, -13, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.shadowBlur = 0;
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// KOKOSNÖT — brun hårig oval med 3 "ögon"-hål (coconuts naturliga marks)
function drawCoconutCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const brown      = flash ? '#fff' : '#7a4a20';
  const brownDark  = flash ? '#fff' : '#4a2810';
  const brownLite  = flash ? '#fff' : '#9a6a40';
  const brownHair  = flash ? '#fff' : '#3a1a08';
  const whiteFlesh = flash ? '#fff' : '#f0e8d0';
  const skin       = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline    = flash ? '#fff' : '#1a0a04';
  const blackEye   = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (round/oval brown)
  ctx.fillStyle = brown;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8, 10, 0, 0, Math.PI * 2);
  ctx.fill();
  // HAIRY TEXTURE — many small fiber-lines
  ctx.strokeStyle = brownHair; ctx.lineWidth = 0.3;
  for (let i = 0; i < 40; i++) {
    const ang = (i / 40) * Math.PI * 2;
    const r1 = 6.5 + (i % 3) * 0.3;
    const r2 = 7.8 + (i % 4) * 0.4;
    const x1 = Math.cos(ang) * r1;
    const y1 = -3 + Math.sin(ang) * r1 * (10/8);
    const x2 = Math.cos(ang) * r2;
    const y2 = -3 + Math.sin(ang) * r2 * (10/8);
    ctx.beginPath();
    ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.stroke();
  }
  // Body outline
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8, 10, 0, 0, Math.PI * 2);
  ctx.stroke();
  // East-side highlight (sheen)
  ctx.fillStyle = brownLite;
  ctx.globalAlpha = 0.35;
  ctx.beginPath();
  ctx.ellipse(3, -5, 2, 5, -0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // 3 COCONUT "EYES" (naturliga circular spots on coconut top)
  ctx.fillStyle = brownDark;
  ctx.beginPath(); ctx.arc(-3, -9, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(0, -10, 0.9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, -9, 0.9, 0, Math.PI * 2); ctx.fill();
  // CRACK med white flesh visible
  ctx.strokeStyle = brownDark; ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-4, 2);
  ctx.lineTo(-2.5, 3);
  ctx.lineTo(-1, 1.5);
  ctx.lineTo(1.5, 3.5);
  ctx.lineTo(4, 2);
  ctx.stroke();
  // White flesh sliver showing
  ctx.fillStyle = whiteFlesh;
  ctx.beginPath();
  ctx.moveTo(-2.5, 3);
  ctx.lineTo(-1, 1.5);
  ctx.lineTo(1.5, 3.5);
  ctx.lineTo(0, 4.5);
  ctx.closePath();
  ctx.fill();
  // FACE — v1.515 TOUGH/GRUFF (slit narrow eyes + angry V-brows + grimace med teeth)
  // Narrow slit eyes (squinty/tough)
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.ellipse(-2.5, -5, 1.1, 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(2.5, -5, 1.1, 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.ellipse(-2.5, -5, 1.1, 0.4, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(2.5, -5, 1.1, 0.4, 0, 0, Math.PI * 2);
  ctx.stroke();
  // Small intense pupils
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2.5, -5, 0.35, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -5, 0.35, 0, Math.PI * 2); ctx.fill();
  // ANGRY V-EYEBROWS (thick, dramatic angle - inner LOW outer HIGH)
  ctx.fillStyle = brownDark;
  ctx.beginPath();
  ctx.moveTo(-3.8, -7);
  ctx.lineTo(-1.0, -5.7);
  ctx.lineTo(-1.0, -5.2);
  ctx.lineTo(-3.8, -6.5);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(3.8, -7);
  ctx.lineTo(1.0, -5.7);
  ctx.lineTo(1.0, -5.2);
  ctx.lineTo(3.8, -6.5);
  ctx.closePath(); ctx.fill();
  // GRIMACE mouth (downturned med clenched teeth visible)
  ctx.fillStyle = '#3a0a08';
  ctx.beginPath();
  ctx.moveTo(-2, -1.5);
  ctx.quadraticCurveTo(0, -0.3, 2, -1.5);
  ctx.lineTo(2, -1);
  ctx.quadraticCurveTo(0, 0.2, -2, -1);
  ctx.closePath(); ctx.fill();
  // Clenched teeth (white lines)
  ctx.fillStyle = '#fff';
  for (const tx of [-1.3, -0.5, 0.3, 1.1]) {
    ctx.fillRect(tx, -1.3, 0.5, 0.5);
  }
  // Outline lips
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.moveTo(-2, -1.5);
  ctx.quadraticCurveTo(0, -0.3, 2, -1.5);
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// GRANATÄPPLE — röd round body med crown calyx + section visning av frön
function drawPomegranateCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const red       = flash ? '#fff' : '#aa1828';
  const redDark   = flash ? '#fff' : '#6a0818';
  const redLite   = flash ? '#fff' : '#dd4848';
  const seedRed   = flash ? '#fff' : '#cc1010';
  const seedHi    = flash ? '#fff' : '#ff5050';
  const calyx     = flash ? '#fff' : '#4a2a08';
  const skin      = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline   = flash ? '#fff' : '#2a0408';
  const blackEye  = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (red round)
  ctx.fillStyle = red;
  ctx.beginPath();
  ctx.ellipse(0, -3, 8, 10, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // Dark shading (vertical streaks)
  ctx.strokeStyle = redDark; ctx.lineWidth = 0.5;
  for (const lx of [-5, -3, 3, 5]) {
    ctx.beginPath();
    ctx.moveTo(lx, -10);
    ctx.lineTo(lx + 0.5, 6);
    ctx.stroke();
  }
  // East-side highlight
  ctx.fillStyle = redLite;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.ellipse(3, -5, 2, 5, -0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // CROWN CALYX (5 spikes on top — pomegranates iconic feature)
  ctx.fillStyle = calyx;
  for (const [bx, by, tx, ty] of [
    [-3, -11, -3.5, -14],
    [-1, -11.5, -1.2, -15],
    [1, -11.5, 1.2, -15],
    [3, -11, 3.5, -14],
    [0, -12, 0, -16],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx - 0.7, by);
    ctx.lineTo(tx, ty);
    ctx.lineTo(bx + 0.7, by);
    ctx.closePath();
    ctx.fill();
  }
  ctx.strokeStyle = outline; ctx.lineWidth = 0.4;
  for (const [bx, by, tx, ty] of [
    [-3, -11, -3.5, -14],
    [0, -12, 0, -16],
    [3, -11, 3.5, -14],
  ]) {
    ctx.beginPath();
    ctx.moveTo(bx - 0.7, by);
    ctx.lineTo(tx, ty);
    ctx.lineTo(bx + 0.7, by);
    ctx.stroke();
  }
  // SECTION CUT visande seeds (revealed interior)
  ctx.fillStyle = '#f0e0c0';  // membrane
  ctx.beginPath();
  ctx.moveTo(-4.5, 1);
  ctx.quadraticCurveTo(0, 4, 4.5, 1);
  ctx.lineTo(4, 5);
  ctx.quadraticCurveTo(0, 7, -4, 5);
  ctx.closePath();
  ctx.fill();
  // SEEDS (red drops) scattered in section
  ctx.fillStyle = seedRed;
  for (const [sx, sy] of [[-3, 2], [-1.5, 2.5], [0, 2.3], [1.5, 2.5], [3, 2],
                          [-2, 3.5], [0, 3.8], [2, 3.5], [-1, 5], [1, 5]]) {
    ctx.beginPath();
    ctx.arc(sx, sy, 0.65, 0, Math.PI * 2);
    ctx.fill();
  }
  // Seed highlights
  ctx.fillStyle = seedHi;
  for (const [sx, sy] of [[-3, 2], [0, 2.3], [3, 2], [0, 3.8]]) {
    ctx.beginPath();
    ctx.arc(sx - 0.2, sy - 0.2, 0.2, 0, Math.PI * 2);
    ctx.fill();
  }
  // FACE — v1.515 WISE/REGAL (half-closed elegant eyes + arched thin brows + subtle smile + beauty mark)
  // Sclera
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2.5, -6, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -6, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-2.5, -6, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -6, 1.1, 0, Math.PI * 2); ctx.stroke();
  // Wise half-closed eyelids (top half covered, elegant gaze)
  ctx.fillStyle = redDark;
  ctx.beginPath(); ctx.arc(-2.5, -6, 1.1, Math.PI, Math.PI * 1.85);
  ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.arc(2.5, -6, 1.1, Math.PI * 1.15, 0);
  ctx.closePath(); ctx.fill();
  // Pupils (visible only in lower portion)
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2.3, -5.7, 0.45, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2.7, -5.7, 0.45, 0, Math.PI * 2); ctx.fill();
  // Tiny refined glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(-2.1, -5.9, 0.2, 0.2);
  ctx.fillRect(2.9, -5.9, 0.2, 0.2);
  // Arched thin elegant eyebrows
  ctx.strokeStyle = redDark; ctx.lineWidth = 0.5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-3.7, -7.7);
  ctx.quadraticCurveTo(-2.5, -8.4, -1.4, -7.6);
  ctx.moveTo(1.4, -7.6);
  ctx.quadraticCurveTo(2.5, -8.4, 3.7, -7.7);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // BEAUTY MARK (small dark dot near west eye - aristocratic touch)
  ctx.fillStyle = redDark;
  ctx.beginPath();
  ctx.arc(-3.8, -4.2, 0.25, 0, Math.PI * 2);
  ctx.fill();
  // Subtle warm refined smile
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.moveTo(-1.3, -3); ctx.quadraticCurveTo(0, -2.4, 1.3, -3.2);
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// STJÄRNFRUKT — 5-point star body, yellow-green
function drawStarfruitCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const starColor   = flash ? '#fff' : '#caea30';
  const starDark    = flash ? '#fff' : '#8aaa10';
  const starLite    = flash ? '#fff' : '#eaffa0';
  const skin        = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline     = flash ? '#fff' : '#3a4a08';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // STAR BODY (5-point star)
  ctx.fillStyle = starColor;
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    const ang = -Math.PI / 2 + (i / 10) * Math.PI * 2;
    const r = (i % 2 === 0) ? 10 : 4;
    const sx = Math.cos(ang) * r;
    const sy = -3 + Math.sin(ang) * r;
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // Inner star outline (showing 5-segments)
  ctx.strokeStyle = starDark; ctx.lineWidth = 0.5;
  for (let i = 0; i < 5; i++) {
    const ang = -Math.PI / 2 + (i / 5) * Math.PI * 2;
    const x = Math.cos(ang) * 9.5;
    const y = -3 + Math.sin(ang) * 9.5;
    ctx.beginPath();
    ctx.moveTo(0, -3); ctx.lineTo(x, y);
    ctx.stroke();
  }
  // Center pentagon highlight
  ctx.fillStyle = starLite;
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const ang = -Math.PI / 2 + (i / 5) * Math.PI * 2 + Math.PI / 5;
    const sx = Math.cos(ang) * 3;
    const sy = -3 + Math.sin(ang) * 3;
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  // FACE — v1.515 SHOWBIZ STAR (★-shaped pupils + huge laughing mouth + raised excited brows)
  // Eye whites
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-1.8, -3.5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1.8, -3.5, 1.1, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-1.8, -3.5, 1.1, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(1.8, -3.5, 1.1, 0, Math.PI * 2); ctx.stroke();
  // ★-SHAPED PUPILS (5-point star — showbiz signature!)
  ctx.fillStyle = blackEye;
  for (const cx of [-1.8, 1.8]) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + (i / 10) * Math.PI * 2;
      const rad = (i % 2 === 0) ? 0.6 : 0.25;
      const sx = cx + Math.cos(ang) * rad;
      const sy = -3.5 + Math.sin(ang) * rad;
      if (i === 0) ctx.moveTo(sx, sy);
      else ctx.lineTo(sx, sy);
    }
    ctx.closePath();
    ctx.fill();
  }
  // Bright eye glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(-1.5, -3.9, 0.3, 0.3);
  ctx.fillRect(2.1, -3.9, 0.3, 0.3);
  // Raised excited eyebrows (high up, V-down-pointing for excitement)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-3, -5.5);
  ctx.lineTo(-1, -5);
  ctx.moveTo(1, -5);
  ctx.lineTo(3, -5.5);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // HUGE LAUGHING MOUTH (showbiz smile med tongue)
  ctx.fillStyle = '#3a0a08';
  ctx.beginPath();
  ctx.moveTo(-2.3, -1.7);
  ctx.quadraticCurveTo(0, 1, 2.3, -1.7);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.5;
  ctx.stroke();
  // White teeth row (top)
  ctx.fillStyle = '#fff';
  for (const tx of [-1.7, -1.0, -0.3, 0.4, 1.1]) {
    ctx.fillRect(tx, -1.6, 0.5, 0.5);
  }
  // Pink tongue at bottom
  ctx.fillStyle = '#ff7090';
  ctx.beginPath();
  ctx.ellipse(0, 0.2, 1.2, 0.5, 0, 0, Math.PI);
  ctx.closePath(); ctx.fill();
  // Sparkles around star (extra shine)
  ctx.fillStyle = starLite;
  ctx.shadowColor = '#ffff80'; ctx.shadowBlur = 3;
  for (const [sx, sy] of [[-7, -10], [7, -10], [-8, 3], [8, 3]]) {
    ctx.beginPath();
    ctx.arc(sx, sy, 0.4, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.shadowBlur = 0;
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 7, 2.2, 8);
  ctx.fillRect(0.8 + legSwing, 7, 2.2, 8);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 7, 2.2, 8);
  ctx.strokeRect(0.8 + legSwing, 7, 2.2, 8);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// KAKTUSFIKON — pink-red oval body med many tiny spines (taggig outsider)
function drawPricklypearCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const pinkRed   = flash ? '#fff' : '#ff5a70';
  const pinkDark  = flash ? '#fff' : '#cc2030';
  const pinkLite  = flash ? '#fff' : '#ff8aa0';
  const spineCol  = flash ? '#fff' : '#3a1018';
  const green     = flash ? '#fff' : '#3a7a3a';
  const skin      = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline   = flash ? '#fff' : '#3a0a18';
  const blackEye  = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (pink-red oval, slightly elongated)
  ctx.fillStyle = pinkRed;
  ctx.beginPath();
  ctx.ellipse(0, -3, 7, 11, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // East-side highlight
  ctx.fillStyle = pinkLite;
  ctx.globalAlpha = 0.35;
  ctx.beginPath();
  ctx.ellipse(2.5, -5, 1.8, 5, -0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // Pink shadow lines (subtle vertical streaks)
  ctx.strokeStyle = pinkDark; ctx.lineWidth = 0.3;
  for (const lx of [-4, -2, 2, 4]) {
    ctx.beginPath();
    ctx.moveTo(lx, -10);
    ctx.lineTo(lx + 0.5, 6);
    ctx.stroke();
  }
  // MANY TINY SPINES all over body (signature feature)
  ctx.fillStyle = spineCol;
  ctx.strokeStyle = spineCol; ctx.lineWidth = 0.25;
  for (let i = 0; i < 30; i++) {
    const angle = (i / 30) * Math.PI * 2 + (i % 3) * 0.2;
    const dist = 4 + (i % 4);
    const sx = Math.cos(angle) * dist;
    const sy = -3 + Math.sin(angle) * dist * 1.4;
    // Small star-burst cluster
    ctx.beginPath();
    ctx.moveTo(sx - 0.25, sy); ctx.lineTo(sx + 0.25, sy);
    ctx.moveTo(sx, sy - 0.25); ctx.lineTo(sx, sy + 0.25);
    ctx.moveTo(sx - 0.18, sy - 0.18); ctx.lineTo(sx + 0.18, sy + 0.18);
    ctx.moveTo(sx - 0.18, sy + 0.18); ctx.lineTo(sx + 0.18, sy - 0.18);
    ctx.stroke();
  }
  // Green flower-tuft on top
  ctx.fillStyle = green;
  ctx.beginPath();
  ctx.ellipse(0, -13, 1.5, 0.8, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = pinkDark;
  ctx.beginPath();
  ctx.arc(0, -13, 0.5, 0, Math.PI * 2);
  ctx.fill();
  // FACE — v1.515 SMUG REBEL (asymmetric eyes + ONE raised brow + smirk + scar)
  // Eye whites — east eye SLIGHTLY LARGER (raised-brow effect)
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-2.5, -6, 0.9, 0, Math.PI * 2); ctx.fill();    // west smaller
  ctx.beginPath(); ctx.arc(2.5, -6, 1.2, 0, Math.PI * 2); ctx.fill();     // east bigger
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.35;
  ctx.beginPath(); ctx.arc(-2.5, -6, 0.9, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(2.5, -6, 1.2, 0, Math.PI * 2); ctx.stroke();
  // Pupils — west looking sideways, east staring
  ctx.fillStyle = blackEye;
  ctx.beginPath(); ctx.arc(-2.1, -5.9, 0.4, 0, Math.PI * 2); ctx.fill();   // looking east
  ctx.beginPath(); ctx.arc(2.6, -6, 0.55, 0, Math.PI * 2); ctx.fill();
  // Glints
  ctx.fillStyle = '#fff';
  ctx.fillRect(-1.9, -6.1, 0.25, 0.25);
  ctx.fillRect(2.9, -6.3, 0.3, 0.3);
  // ASYMMETRIC EYEBROWS — west flat, east HIGH (raised = skeptical/cocky)
  ctx.fillStyle = blackEye;
  ctx.fillRect(-3.4, -7.2, 1.7, 0.4);  // west: flat low
  ctx.beginPath();                       // east: raised + arched
  ctx.moveTo(1.5, -8.2);
  ctx.quadraticCurveTo(2.7, -8.7, 3.7, -7.8);
  ctx.lineTo(3.5, -7.5);
  ctx.quadraticCurveTo(2.7, -8.3, 1.7, -7.8);
  ctx.closePath(); ctx.fill();
  // SCAR through west eyebrow (tough rebel touch)
  ctx.strokeStyle = '#aa5050'; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-3.6, -7.8);
  ctx.lineTo(-2.4, -6.4);
  ctx.stroke();
  // Scar highlight
  ctx.strokeStyle = '#ddaaaa'; ctx.lineWidth = 0.25;
  ctx.beginPath();
  ctx.moveTo(-3.55, -7.75);
  ctx.lineTo(-2.35, -6.35);
  ctx.stroke();
  // SMUG SMIRK (asymmetric — east higher)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.65;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-1.5, -3);
  ctx.quadraticCurveTo(0, -2.3, 1.5, -3.5);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // Small dimple at east mouth corner
  ctx.fillStyle = pinkDark;
  ctx.beginPath();
  ctx.arc(1.7, -3.3, 0.2, 0, Math.PI * 2);
  ctx.fill();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// OLIV — grön oval body med tiny leaf + red pimento (classic look)
function drawOliveCharacter(ctx, cos, flash, walkPhase, isMoving) {
  const oliveGreen  = flash ? '#fff' : '#5a7a2a';
  const oliveDark   = flash ? '#fff' : '#3a5a1a';
  const oliveLite   = flash ? '#fff' : '#8aaa4a';
  const leafGreen   = flash ? '#fff' : '#7aca3a';
  const pimento     = flash ? '#fff' : '#dd2818';
  const pimentoDark = flash ? '#fff' : '#aa1010';
  const skin        = flash ? '#fff' : (cos.skin || '#d4a574');
  const outline     = flash ? '#fff' : '#1a3008';
  const blackEye    = flash ? '#fff' : '#0a0a0a';
  const swing = Math.sin(walkPhase);
  const legSwing = isMoving ? swing * 2 : 0;
  // BODY (olive oval)
  ctx.fillStyle = oliveGreen;
  ctx.beginPath();
  ctx.ellipse(0, -3, 7, 11, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = outline; ctx.lineWidth = 1;
  ctx.stroke();
  // East-side highlight (olive sheen)
  ctx.fillStyle = oliveLite;
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  ctx.ellipse(2.5, -5, 1.8, 5, -0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // Subtle vertical shading
  ctx.strokeStyle = oliveDark; ctx.lineWidth = 0.4;
  ctx.beginPath();
  ctx.moveTo(-4, -10); ctx.lineTo(-4, 5);
  ctx.moveTo(4, -10); ctx.lineTo(4, 5);
  ctx.stroke();
  // TINY LEAF + STEM on top
  ctx.fillStyle = '#3a2008';
  ctx.fillRect(-0.3, -14, 0.6, 1.5);
  // Leaf
  ctx.fillStyle = leafGreen;
  ctx.beginPath();
  ctx.ellipse(1.5, -15, 1.5, 0.6, 0.4, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = oliveDark; ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(0, -14.5); ctx.lineTo(3, -15.5);
  ctx.stroke();
  // RED PIMENTO (classic stuffed olive look) — visible på top-front
  ctx.fillStyle = pimento;
  ctx.beginPath();
  ctx.ellipse(0, -10.5, 2, 1.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = pimentoDark; ctx.lineWidth = 0.3;
  ctx.stroke();
  // Pimento highlight
  ctx.fillStyle = '#ff5a30';
  ctx.fillRect(-0.5, -11, 1, 0.4);
  // FACE — v1.515 REFINED GENTLEMAN (closed ^_^ happy squint + cheek dots + tiny mustache)
  // CLOSED HAPPY-SQUINT EYES (^_^ shape — Mediterranean refined vibe)
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.55;
  ctx.lineCap = 'round';
  ctx.beginPath();
  // West eye (^)
  ctx.moveTo(-3.4, -5.8);
  ctx.quadraticCurveTo(-2.5, -6.5, -1.6, -5.8);
  // East eye (^)
  ctx.moveTo(1.6, -5.8);
  ctx.quadraticCurveTo(2.5, -6.5, 3.4, -5.8);
  ctx.stroke();
  // Small eyelashes (sweet detail)
  ctx.lineWidth = 0.3;
  ctx.beginPath();
  ctx.moveTo(-3.5, -6.0); ctx.lineTo(-3.7, -6.3);
  ctx.moveTo(-1.5, -6.0); ctx.lineTo(-1.3, -6.3);
  ctx.moveTo(1.5, -6.0); ctx.lineTo(1.3, -6.3);
  ctx.moveTo(3.5, -6.0); ctx.lineTo(3.7, -6.3);
  ctx.stroke();
  ctx.lineCap = 'butt';
  // CHEEK BLUSH DOTS (sweet rosy cheeks)
  ctx.fillStyle = '#ff9a8a';
  ctx.globalAlpha = 0.55;
  ctx.beginPath();
  ctx.ellipse(-4, -4.5, 0.7, 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(4, -4.5, 0.7, 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  // ELEGANT SMILE med teeth-line
  ctx.strokeStyle = blackEye; ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-1.5, -2.8);
  ctx.quadraticCurveTo(0, -1.4, 1.5, -2.8);
  ctx.stroke();
  // Tiny mouth-corner dimples
  ctx.fillStyle = oliveDark;
  ctx.beginPath(); ctx.arc(-1.5, -2.7, 0.15, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(1.5, -2.7, 0.15, 0, Math.PI * 2); ctx.fill();
  // TINY HANDLEBAR MUSTACHE under the pimento (gentleman touch)
  ctx.strokeStyle = '#3a2008'; ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(-2, -3.5);
  ctx.quadraticCurveTo(0, -3.8, 2, -3.5);
  ctx.stroke();
  // Tiny mustache curls at ends
  ctx.beginPath();
  ctx.arc(-2.2, -3.5, 0.3, Math.PI * 0.2, Math.PI * 1.2);
  ctx.moveTo(2.2, -3.5);
  ctx.arc(2.2, -3.5, 0.3, Math.PI * 1.8, Math.PI * 0.8);
  ctx.stroke();
  // LEGS
  ctx.fillStyle = skin;
  ctx.fillRect(-3 - legSwing, 8, 2.2, 7);
  ctx.fillRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.strokeStyle = outline; ctx.lineWidth = 0.5;
  ctx.strokeRect(-3 - legSwing, 8, 2.2, 7);
  ctx.strokeRect(0.8 + legSwing, 8, 2.2, 7);
  ctx.fillStyle = flash ? '#fff' : '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(-1.9 - legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.ellipse(1.9 + legSwing, 16, 2, 1, 0, 0, Math.PI * 2); ctx.fill();
}

// ============================================================
// v1.514: 15 NYA PUBLIC-DOMAIN / FOLKTALE-KARAKTÄRER
// Alla baserade på ORIGINAL PD-källor (ej Disney/film-adaptioner)
