    const _aBase = _mStyle ? _mStyle.base : (cos.skin || '#c08860');
    const _aLight = flash ? '#fff' : (_mStyle ? _mStyle.light : lighten(_aBase, 0.22));
    const _aSkin = flash ? '#fff' : _aBase;
